INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0001', '3/4 sit-up', 'waist', 'waist', 'body weight', '{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Metti le mani dietro la testa con i gomiti rivolti verso l''esterno.","Coinvolgendo gli addominali, solleva lentamente la parte superiore del corpo da terra, piegandoti in avanti finché il busto non forma un angolo di 45 gradi.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Ellerinizi başınızın arkasına, dirsekleriniz dışarı bakacak şekilde yerleştirin.","Karın kaslarınızı devreye sokarak üst bedeninizi yavaşça yerden kaldırın ve gövdeniz 45 derecelik bir açıya gelene kadar öne doğru kıvrılın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.","Umieść dłonie za głową, kierując łokcie na zewnątrz.","Angażując mięśnie brzucha, powoli unieś górną część ciała nad podłogę, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 누워 무릎을 구부리고 발을 바닥에 붙입니다.","손을 머리 뒤에 깍지껴 팔꿈치가 바깥쪽을 향하도록 합니다.","복근을 사용하여 천천히 윗몸을 들어 올려 몸통이 45도 각도가 될 때까지 앞쪽으로 구부립니다.","맨 위에서 잠깐 멈췄다가 천천히 윗몸을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors","lower back"]', 'abs', 'images/0001-2gPfomN.jpg', 'videos/0001-2gPfomN.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0002', '45° side bend', 'waist', 'waist', 'body weight', '{"en":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e le braccia distese lungo i fianchi.","Mantenendo la schiena dritta e il core impegnato, piega lentamente il busto da un lato, abbassando la mano verso il ginocchio.","Fermati per un momento in basso, quindi torna lentamente alla posizione di partenza.","Ripeti dall''altra parte.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve kollarınız yanlarınızda düz bir şekilde uzatılmış şekilde ayakta durun.","Sırtınızı düz ve merkez bölgenizi meşgul tutarak gövdenizi yavaşça bir tarafa doğru eğin ve elinizi dizinize doğru indirin.","Altta bir an duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","Diğer tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia abajo a los lados.","Manteniendo la espalda recta y el core activado, flexiona lentamente el torso hacia un lado, bajando la mano hacia la rodilla.","Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч и вытянув руки по бокам.","Удерживая спину прямой и напрягая корпус, медленно наклоните туловище в сторону, опуская руку к колену.","Задержитесь на мгновение внизу, затем медленно вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，双臂在身体两侧笔直向下伸展。","保持背部挺直，核心肌群参与，慢慢将躯干向一侧弯曲，将手向膝盖方向放低。","在底部停顿片刻，然后慢慢回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपकी भुजाएं आपके बगल में सीधी नीचे की ओर फैली हुई हों।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, धीरे-धीरे अपने धड़ को एक तरफ झुकाएं, अपने हाथ को अपने घुटने की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań w rozkroku na szerokość barków, ramiona wyprostowane wzdłuż tułowia.","Utrzymując proste plecy i napięty brzuch, powoli pochyl tułów w bok, opuszczając dłoń w kierunku kolana.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie powoli wróć do pozycji wyjściowej.","Powtórz po drugiej stronie.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["발을 어깨 넓이로 벌리고 팔을 양쪽에 내려 펼칩니다.","등을 곧게 펴고 복근을 긴장시킨 상태에서 천천히 몸통을 한쪽으로 구부려 손을 무릎 쪽으로 내립니다.","맨 아래에서 잠깐 멈췄다가 천천히 시작 자세로 돌아옵니다.","반대쪽에서 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/0002-Hy9D21L.jpg', 'videos/0002-Hy9D21L.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0003', 'air bike', 'waist', 'waist', 'body weight', '{"en":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le mani dietro la testa.","Solleva le gambe da terra e piega le ginocchia con un angolo di 90 gradi.","Porta il gomito destro verso il ginocchio sinistro mentre contemporaneamente raddrizzi la gamba destra.","Ritorna alla posizione di partenza e ripeti il ​​movimento dal lato opposto, portando il gomito sinistro verso il ginocchio destro mentre raddrizzi la gamba sinistra.","Continua ad alternare i lati con un movimento di pedalata per il numero di ripetizioni desiderato."],"tr":["Elleriniz başınızın arkasında olacak şekilde sırt üstü uzanın.","Bacaklarınızı yerden kaldırın ve dizlerinizi 90 derecelik bir açıyla bükün.","Sağ bacağınızı düzleştirirken aynı anda sağ dirseğinizi sol dizinize doğru getirin.","Başlangıç ​​pozisyonuna dönün ve sol bacağınızı düzleştirirken sol dirseğinizi sağ dizinize doğru getirerek hareketi diğer tarafta tekrarlayın.","İstenilen sayıda tekrarlama için pedal çevirme hareketinde alternatif tarafları kullanmaya devam edin."],"es":["Túmbate sobre tu espalda con las manos colocadas detrás de la cabeza.","Levanta las piernas del suelo y flexiona las rodillas formando un ángulo de 90 grados.","Lleva el codo derecho hacia la rodilla izquierda mientras simultáneamente estiras la pierna derecha.","Regresa a la posición inicial y repite el movimiento del lado opuesto, llevando el codo izquierdo hacia la rodilla derecha mientras estiras la pierna izquierda.","Continúa alternando lados con un movimiento de pedaleo durante el número de repeticiones deseado."],"ru":["Лягте на спину, положив руки за голову.","Поднимите ноги от земли и согните колени под углом 90 градусов.","Поднесите правый локоть к левому колену, одновременно выпрямляя правую ногу.","Вернитесь в исходное положение и повторите движение в противоположную сторону, приближая левый локоть к правому колену и выпрямляя левую ногу.","Продолжайте чередовать стороны, вращая педали, необходимое количество повторений."],"zh":["平躺，双手放在脑后。","将双腿抬离地面，并以 90 度角弯曲膝盖。","将右肘靠近左膝盖，同时伸直右腿。","返回起始位置，在另一侧重复该动作，将左肘拉向右膝盖，同时伸直左腿。","继续交替进行蹬踏动作，达到所需的重复次数。"],"hi":["अपने हाथों को अपने सिर के पीछे रखते हुए अपनी पीठ के बल सीधे लेट जाएँ।","अपने पैरों को ज़मीन से ऊपर उठाएं और अपने घुटनों को 90 डिग्री के कोण पर मोड़ें।","अपने दाहिने पैर को सीधा करते हुए अपनी दाहिनी कोहनी को अपने बाएँ घुटने की ओर लाएँ।","प्रारंभिक स्थिति पर लौटें और अपने बाएं पैर को सीधा करते हुए अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाते हुए, विपरीत दिशा में आंदोलन को दोहराएं।","पुनरावृत्ति की वांछित संख्या के लिए पैडल गति में पक्षों को बदलना जारी रखें।"],"pl":["Połóż się płasko na plecach, dłonie umieść za głową.","Unieś nogi nad podłogę i ugnij kolana pod kątem 90 stopni.","Przyciągnij prawy łokieć w kierunku lewego kolana, jednocześnie prostując prawą nogę.","Wróć do pozycji wyjściowej i powtórz ruch po przeciwnej stronie, przyciągając lewy łokieć do prawego kolana i prostując lewą nogę.","Kontynuuj naprzemienny ruch przypominający pedałowanie przez zalecaną liczbę powtórzeń."],"ko":["등을 바닥에 누워 손을 머리 뒤에 깍지껴 올립니다.","다리를 바닥에서 들어 올려 무릎을 90도 각도로 구부립니다.","오른쪽 팔꿈치를 왼쪽 무릎으로 가져오면서 동시에 오른쪽 다리를 펼칩니다.","시작 자세로 돌아와 반대쪽을 반복하며 왼쪽 팔꿈치를 오른쪽 무릎으로 가져오면서 왼쪽 다리를 펼칩니다.","자전거 페달을 밟는 동작으로 양쪽을 번갈아가며 원하는 반복 횟수만큼 계속합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/0003-1ZFqTDN.jpg', 'videos/0003-1ZFqTDN.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1512', 'all fours squad stretch', 'upper legs', 'upper legs', 'body weight', '{"en":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."],"it":["Inizia a quattro zampe con le mani direttamente sotto le spalle e le ginocchia direttamente sotto i fianchi.","Estendi una gamba all''indietro, mantenendo il ginocchio piegato e il piede flesso.","Abbassa lentamente i fianchi verso terra, avvertendo l''allungamento dei quadricipiti.","Mantieni questa posizione per 20-30 secondi.","Cambia gamba e ripeti l''allungamento sull''altro lato."],"tr":["Elleriniz doğrudan omuzlarınızın altında ve dizleriniz doğrudan kalçalarınızın altında olacak şekilde dört ayak üzerinde başlayın.","Dizinizi bükülmüş ve ayağınızı bükülmüş halde tutarak bir bacağınızı geriye doğru uzatın.","Kalçalarınızı yavaşça yere doğru indirin, dörtlü kaslarınızda bir gerginlik hissedin.","Bu pozisyonu 20-30 saniye basılı tutun.","Bacaklarınızı değiştirin ve diğer taraftaki esnemeyi tekrarlayın."],"es":["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.","Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.","Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.","Mantén esta posición durante 20-30 segundos.","Cambia de pierna y repite el estiramiento del otro lado."],"ru":["Встаньте на четвереньки, положив руки прямо под плечи и колени прямо под бедрами.","Вытяните одну ногу прямо назад, сохраняя колено согнутым и ступню согнутой.","Медленно опустите бедра к земле, чувствуя растяжение квадрицепсов.","Удерживайте это положение 20–30 секунд.","Поменяйте ноги и повторите растяжку с другой стороны."],"zh":["从四肢着地开始，双手直接放在肩膀下方，膝盖直接放在臀部下方。","将一条腿向后伸直，保持膝盖弯曲和脚弯曲。","慢慢地将臀部降低到地面，感觉股四头肌的伸展。","保持这个姿势20-30秒。","换腿并在另一侧重复拉伸。"],"hi":["अपने हाथों को सीधे अपने कंधों के नीचे और अपने घुटनों को सीधे अपने कूल्हों के नीचे रखकर चारों तरफ से शुरुआत करें।","अपने एक पैर को सीधा पीछे की ओर फैलाएँ, अपने घुटने को मोड़ें और अपने पैर को मोड़ें।","धीरे-धीरे अपने कूल्हों को ज़मीन की ओर नीचे लाएँ, अपने क्वाड्स में खिंचाव महसूस करें।","इस स्थिति में 20-30 सेकंड तक रुकें।","पैरों को बदलें और दूसरी तरफ भी खिंचाव दोहराएं।"],"pl":["Ustaw się w podporze na czworakach, dłonie dokładnie pod barkami, a kolana pod biodrami.","Wyciągnij jedną nogę prosto do tyłu, utrzymując kolano ugięte i stopę zgiętą grzbietowo.","Powoli opuszczaj biodra w kierunku podłogi, odczuwając rozciąganie w mięśniach czworogłowych uda.","Utrzymaj tę pozycję przez 20-30 sekund.","Zmień nogę i powtórz rozciąganie po drugiej stronie."],"ko":["네 발을 모두 대고 손이 어깨 아래에, 무릎이 엉덩이 아래에 오도록 시작합니다.","한쪽 다리를 곧게 펼쳐 뒤로 뻗되 무릎을 구부린 상태로 발을 펼칩니다.","천천히 엉덩이를 바닥으로 내려 대퇴사두근이 늘어나는 것을 느낍니다.","이 자세를 20~30초간 유지합니다.","다리를 바꿔 반대쪽도 같은 방법으로 스트레칭합니다."]}', 'hamstrings', '["hamstrings","glutes"]', 'quads', 'images/1512-qBcKorM.jpg', 'videos/1512-qBcKorM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0006', 'alternate heel touchers', 'waist', 'waist', 'body weight', '{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Estendi le braccia verso i lati, parallele al suolo.","Coinvolgendo gli addominali, solleva le spalle da terra e allunga la mano destra verso il tallone destro.","Ritorna alla posizione iniziale e ripeti sul lato sinistro, portando la mano sinistra verso il tallone sinistro.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Kollarınızı yere paralel olarak yanlara doğru uzatın.","Karın kaslarınızı devreye sokarak omuzlarınızı yerden kaldırın ve sağ elinizi sağ topuğunuza doğru uzatın.","Başlangıç ​​pozisyonuna dönün ve sol elinizi sol topuğunuza doğru uzatarak sol tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos hacia los lados, paralelos al suelo.","Activando el abdomen, levanta los hombros del suelo y lleva la mano derecha hacia el talón derecho.","Regresa a la posición inicial y repite del lado izquierdo, llevando la mano izquierda hacia el talón izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки прямо в стороны, параллельно земле.","Включив пресс, оторвите плечи от земли и протяните правую руку к правой пятке.","Вернитесь в исходное положение и повторите то же самое с левой стороны, потянув левую руку к левой пятке.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["平躺，膝盖弯曲，双脚平放在地上。","将双臂伸直至两侧，与地面平行。","收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。","返回起始位置并在左侧重复，将左手伸向左脚跟。","继续交替进行所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को ज़मीन के समानांतर, भुजाओं तक सीधा फैलाएँ।","अपने एब्स को शामिल करते हुए, अपने कंधों को ज़मीन से ऊपर उठाएं और अपने दाहिने हाथ को अपनी दाहिनी एड़ी की ओर ले जाएं।","प्रारंभिक स्थिति पर लौटें और बाईं ओर दोहराएं, अपने बाएं हाथ को अपनी बाईं एड़ी तक पहुंचाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.","Wyciągnij ramiona na boki, równolegle do podłogi.","Angażując mięśnie brzucha, unieś barki nad podłogę i sięgnij prawą dłonią w kierunku prawej pięty.","Wróć do pozycji wyjściowej i powtórz po lewej stronie, sięgając lewą dłonią do lewej pięty.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["등을 바닥에 누워 무릎을 구부리고 발을 바닥에 붙입니다.","팔을 옆으로 쭉 펼쳐 바닥과 평행하게 합니다.","복근을 사용하여 어깨를 바닥에서 들어 올리고 오른쪽 손으로 오른쪽 발뒤꿈치를 터치합니다.","시작 자세로 돌아와 왼쪽 손으로 왼쪽 발뒤꿈치를 터치하는 것을 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/0006-qaZVsGk.jpg', 'videos/0006-qaZVsGk.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0007', 'alternate lateral pulldown', 'back', 'back', 'cable', '{"en":["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti sulla macchina via cavo con la schiena dritta e i piedi appoggiati a terra.","Afferrare le maniglie con una presa prona, leggermente più larga della larghezza delle spalle.","Appoggiati leggermente all''indietro e tira le maniglie verso il petto, stringendo insieme le scapole.","Fermati per un momento al culmine del movimento, quindi rilascia lentamente le maniglie nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Kablo makinesinin üzerine sırtınız düz ve ayaklarınız yere düz basacak şekilde oturun.","Tutamaçları omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Hafifçe geriye yaslanın ve kürek kemiklerinizi birbirine doğru sıkıştırarak kolları göğsünüze doğru çekin.","Hareketin zirvesinde bir an duraklayın, ardından kolları yavaşça başlangıç ​​pozisyonuna bırakın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en la máquina de cable con la espalda recta y los pies apoyados en el suelo.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Inclínate ligeramente hacia atrás y lleva las agarraderas hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на канатный тренажер, выпрямив спину и поставив ноги на землю.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Слегка откиньтесь назад и потяните ручки к груди, сжимая лопатки вместе.","Задержитесь на мгновение на пике движения, затем медленно отпустите ручки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在缆绳机上，背部挺直，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके केबल मशीन पर बैठें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","थोड़ा पीछे झुकें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, हैंडल को अपनी छाती की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na maszynie linkowej z prostymi plecami i stopami płasko na podłodze.","Chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.","Odchyl się lekko do tyłu i przyciągnij uchwyty w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę w szczytowej fazie ruchu, a następnie powoli uwolnij uchwyty do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["케이블 머신에 앉아 등을 곧게 펴고 발을 바닥에 붙입니다.","손으로 손잡이를 잡되 손바닥이 위를 향하고 어깨 넓이보다 약간 넓게 잡습니다.","약간 뒤로 기울인 상태에서 손잡이를 가슴 쪽으로 당기며 어깨뼈를 모읍니다.","동작의 최고 지점에서 잠깐 멈췄다가 천천히 손잡이를 시작 자세로 놓습니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","rhomboids"]', 'lats', 'images/0007-4IKbhHV.jpg', 'videos/0007-4IKbhHV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1368', 'ankle circles', 'lower legs', 'lower legs', 'body weight', '{"en":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."],"it":["Siediti a terra con le gambe distese davanti a te.","Solleva una gamba da terra e ruota la caviglia con un movimento circolare.","Esegui il numero desiderato di cerchi in una direzione, quindi passa all''altra direzione.","Ripeti con l''altra gamba."],"tr":["Bacaklarınız önünüzde uzatılmış halde yere oturun.","Bir bacağınızı yerden kaldırın ve bileğinizi dairesel bir hareketle döndürün.","İstediğiniz sayıda daireyi bir yönde gerçekleştirin, ardından diğer yöne geçin.","Diğer bacakla tekrarlayın."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti.","Levanta una pierna del suelo y rota el tobillo con un movimiento circular.","Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.","Repite con la otra pierna."],"ru":["Сядьте на пол, вытянув ноги перед собой.","Поднимите одну ногу с земли и сделайте круговые движения лодыжкой.","Выполните нужное количество кругов в одну сторону, затем переключитесь на другую сторону.","Повторите с другой ногой."],"zh":["坐在地上，双腿在身前伸展。","将一条腿抬离地面，并以圆周运动旋转脚踝。","在一个方向上转所需的圈数，然后切换到另一个方向。","换另一条腿重复上述步骤。"],"hi":["अपने पैरों को सामने फैलाकर जमीन पर बैठें।","एक पैर को जमीन से ऊपर उठाएं और अपने टखने को गोलाकार गति में घुमाएं।","एक दिशा में वांछित संख्या में वृत्त बनाएं, फिर दूसरी दिशा में स्विच करें।","दूसरे पैर से दोहराएँ।"],"pl":["Usiądź na podłodze z nogami wyciągniętymi przed sobą.","Unieś jedną nogę nad podłogę i wykonuj okrężny ruch kostką.","Wykonaj zalecaną liczbę okrążeń w jednym kierunku, a następnie zmień kierunek.","Powtórz drugą nogą."],"ko":["바닥에 앉아 다리를 앞으로 펼칩니다.","한쪽 다리를 바닥에서 들어 발목을 원형으로 회전시킵니다.","원하는 횟수만큼 한 방향으로 회전한 다음 반대 방향으로 회전합니다.","반대쪽 다리로 같은 동작을 반복합니다."]}', 'ankle stabilizers', '["ankle stabilizers"]', 'calves', 'images/1368-uL9CsKm.jpg', 'videos/1368-uL9CsKm.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3293', 'archer pull up', 'back', 'back', 'body weight', '{"en":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."],"it":["Inizia appendendoti a una barra per trazioni con una presa prona, leggermente più larga della larghezza delle spalle.","Coinvolgi il tuo core e tira le scapole verso il basso e all''indietro.","Mentre ti tiri su, piega un braccio e porta il gomito verso il fianco, mantenendo l''altro braccio dritto.","Continua a tirare finché il mento non è sopra la barra e il braccio piegato è completamente flesso.","Abbassati di nuovo con controllo, raddrizzando il braccio piegato e ripetendo il movimento dall''altro lato.","Lati alternativi ad ogni ripetizione."],"tr":["Omuz genişliğinden biraz daha geniş, üstten tutuşla bir barfiks barına asılarak başlayın.","Merkez bölgenizi devreye sokun ve kürek kemiklerinizi aşağı ve geriye doğru çekin.","Kendinizi yukarı çekerken bir kolunuzu bükün ve dirseğinizi yanınıza doğru getirin, diğer kolunuzu ise düz tutun.","Çeneniz çubuğun üzerine gelinceye ve bükülmüş kolunuz tamamen bükülünceye kadar çekmeye devam edin.","Bükülmüş kolu düzleştirerek kendinizi kontrollü bir şekilde geriye doğru indirin ve hareketi diğer tarafta tekrarlayın.","Her tekrarda tarafları değiştirin."],"es":["Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto.","Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado.","Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado.","Alterna los lados en cada repetición."],"ru":["Начните с подвешивания на перекладине хватом сверху, на расстоянии чуть шире плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Подтягиваясь, согните одну руку и отведите локоть в сторону, сохраняя при этом другую руку прямой.","Продолжайте тянуть до тех пор, пока подбородок не окажется над перекладиной, а согнутая рука полностью не согнется.","Контролируемое опускание вниз, выпрямляя согнутую руку и повторяя движение на другую сторону.","Меняйте стороны при каждом повторении."],"zh":["首先，用正手握法悬挂在引体向上杆上，握距略宽于肩宽。","启动你的核心并将肩胛骨向下拉和向后拉。","当你站起来时，弯曲一只手臂并将肘部移向身体一侧，同时保持另一只手臂伸直。","继续拉，直到下巴位于杠铃上方并且弯曲的手臂完全弯曲。","有控制地放低自己，伸直弯曲的手臂并在另一侧重复该动作。","每次重复时交替进行。"],"hi":["ओवरहैंड ग्रिप के साथ कंधे की चौड़ाई से थोड़ा अधिक चौड़े पुल-अप बार से लटककर शुरुआत करें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","जैसे ही आप अपने आप को ऊपर खींचते हैं, एक हाथ को मोड़ें और अपनी कोहनी को अपनी तरफ लाएं, जबकि दूसरे हाथ को सीधा रखें।","तब तक खींचते रहें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए और आपकी मुड़ी हुई भुजा पूरी तरह से मुड़ न जाए।","अपने आप को नियंत्रण के साथ वापस नीचे लाएँ, मुड़ी हुई भुजा को सीधा करें और दूसरी ओर से भी यही क्रिया दोहराएँ।","प्रत्येक पुनरावृत्ति के साथ वैकल्पिक पक्ष।"],"pl":["Zacznij, zwisając na drążku do podciągania nachwytem, nieco szerzej niż na szerokość barków.","Napnij mięśnie brzucha i ściągnij łopatki w dół i do tyłu.","Podciągając się, ugnij jedną rękę i przyciągnij łokieć w kierunku boku ciała, utrzymując drugą rękę prostą.","Kontynuuj podciąganie, aż broda znajdzie się nad drążkiem, a ugięta ręka będzie w pełni zgięta.","Opuść się z powrotem w kontrolowany sposób, prostując zgiętą rękę, i powtórz ruch po drugiej stronie.","Zmieniaj strony przy każdym powtórzeniu."],"ko":["턱걸이 바에 손을 어깨 넓이보다 약간 넓게 손바닥이 앞을 향하도록 매달립니다.","복근을 긴장시키고 어깨뼈를 아래로 당겨 뒤로 젖힙니다.","몸을 올리면서 한쪽 팔의 팔꿈치를 구부려 옆으로 가져오되 다른 쪽 팔은 펴진 상태로 유지합니다.","턱이 바 위로 올라가고 구부린 팔이 완전히 굽혀질 때까지 계속 당깁니다.","제어된 속도로 몸을 내리면서 구부린 팔을 펼치고 반대쪽에서 같은 동작을 반복합니다.","매 반복마다 좌우를 번갈아가며 합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/3293-72BC5Za.jpg', 'videos/3293-72BC5Za.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3294', 'archer push up', 'chest', 'chest', 'body weight', '{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."],"it":["Inizia in una posizione push-up con le mani leggermente più larghe della larghezza delle spalle.","Estendi un braccio di lato, parallelo al suolo.","Abbassa il corpo piegando i gomiti, mantenendo la schiena dritta e il core impegnato.","Spingi indietro fino alla posizione di partenza.","Ripeti dall''altro lato, estendendo il braccio opposto lateralmente.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Elleriniz omuz genişliğinden biraz daha geniş olacak şekilde şınav pozisyonuna başlayın.","Bir kolunuzu yere paralel olarak yana doğru uzatın.","Dirseklerinizi bükerek, sırtınızı düz ve göbek bölgenizi meşgul tutarak vücudunuzu indirin.","Başlangıç ​​pozisyonuna kadar geriye doğru itin.","Karşı kolu yana doğru uzatarak diğer tarafta da tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Comienza en posición de flexión de brazos con las manos un poco más separadas que el ancho de los hombros.","Extiende un brazo hacia el lado, paralelo al suelo.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el core activado.","Empuja hacia arriba para volver a la posición inicial.","Repite del otro lado, extendiendo el brazo opuesto hacia el lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Начните с позиции отжимания, поставив руки чуть шире ширины плеч.","Вытяните одну руку прямо в сторону, параллельно земле.","Опустите тело, согнув локти, сохраняя спину прямой и напряженным корпусом.","Вернитесь в исходное положение.","Повторите то же самое с другой стороны, вытягивая противоположную руку в сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["从俯卧撑位置开始，双手分开略宽于肩宽。","将一只手臂伸直至一侧，与地面平行。","弯曲肘部降低身体，保持背部挺直，核心参与。","推回到起始位置。","在另一侧重复上述步骤，将另一只手臂伸出到一侧。","继续交替进行所需的重复次数。"],"hi":["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखते हुए पुश-अप स्थिति से शुरुआत करें।","एक हाथ को ज़मीन के समानांतर बगल की ओर सीधा फैलाएँ।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और कोर को व्यस्त रखते हुए अपने शरीर को नीचे लाएँ।","प्रारंभिक स्थिति में वापस पुश करें।","दूसरी ओर दोहराएं, विपरीत भुजा को बगल की ओर फैलाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Ustaw się w pozycji pompki z dłońmi nieco szerzej niż na szerokość barków.","Wyciągnij jedną rękę prosto w bok, równolegle do podłogi.","Opuść ciało, uginając łokcie, utrzymując proste plecy i napięty brzuch.","Odepchnij się z powrotem do pozycji wyjściowej.","Powtórz po drugiej stronie, wyciągając drugą rękę w bok.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["팔굽혀펴기 자세로 시작하되 손이 어깨 넓이보다 약간 넓게 벌어집니다.","한쪽 팔을 곧게 펴 바닥과 평행하게 옆으로 뻗습니다.","팔꿈치를 구부려 몸을 내리되 등을 곧게 펴고 복근을 긴장시킵니다.","시작 자세로 밀어 올립니다.","반대쪽 팔을 옆으로 펴 같은 동작을 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'triceps', '["triceps","shoulders","core"]', 'pectorals', 'images/3294-A9qxk2F.jpg', 'videos/3294-A9qxk2F.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2355', 'arm slingers hanging bent knee legs', 'waist', 'waist', 'body weight', '{"en":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Appendere a una barra per trazioni con le braccia completamente distese e le ginocchia piegate con un angolo di 90 gradi.","Coinvolgi il tuo core e solleva le ginocchia verso il petto, portandole il più vicino possibile ai gomiti.","Abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Kollarınız tamamen uzatılmış ve dizleriniz 90 derecelik bir açıyla bükülmüş haldeyken barfiks barına asın.","Merkez bölgenizi devreye sokun ve dizlerinizi göğsünüze doğru kaldırın, onları mümkün olduğunca dirseklerinize yaklaştırın.","Bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las rodillas flexionadas formando un ángulo de 90 grados.","Activa el core y levanta las rodillas hacia el pecho, acercándolas lo más posible a los codos.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Повисните на перекладине, полностью выпрямив руки и согнув колени под углом 90 градусов.","Напрягите корпус и поднимите колени к груди, приближая их как можно ближе к локтям.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["悬挂在引体向上杆上，双臂完全伸展，膝盖弯曲成 90 度角。","收紧核心并将膝盖抬向胸部，尽可能靠近肘部。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"],"hi":["अपनी बाहों को पूरी तरह फैलाकर और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने घुटनों को अपनी छाती की ओर उठाएं, उन्हें जितना संभव हो सके अपनी कोहनी के करीब लाएं।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i kolanami ugiętymi pod kątem 90 stopni.","Napnij mięśnie brzucha i unieś kolana w kierunku klatki piersiowej, przybliżając je jak najbardziej do łokci.","Powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["턱걸이 바에 팔을 완전히 펴 매달립니다.","무릎을 90도 각도로 구부립니다.","복근을 긴장시키고 무릎을 가슴 쪽으로 올리되 팔꿈치에 최대한 가깝게 가져옵니다.","천천히 다리를 시작 자세로 내립니다."]}', 'shoulders', '["shoulders","back"]', 'abs', 'images/2355-uWpxD4v.jpg', 'videos/2355-uWpxD4v.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2333', 'arm slingers hanging straight legs', 'waist', 'waist', 'body weight', '{"en":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Appenditi a una barra per trazioni con le braccia completamente distese e le gambe dritte verso il basso.","Coinvolgi il tuo core e solleva le gambe davanti a te finché non sono parallele al suolo.","Mantieni la posizione in alto per un momento, quindi abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Kollarınız tamamen uzatılmış ve bacaklarınız düz bir şekilde aşağıya doğru bir barfiks barına asın.","Merkez bölgenizi devreye sokun ve bacaklarınızı yere paralel olana kadar önünüze doğru kaldırın.","Üstte bir süre bekleyin, ardından bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las piernas estiradas hacia abajo.","Activa el core y levanta las piernas hacia adelante hasta que queden paralelas al suelo.","Mantén un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Повисните на перекладине, полностью вытянув руки и опустив ноги вниз.","Напрягите корпус и поднимите ноги перед собой, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["悬挂在引体向上杆上，双臂完全伸展，双腿伸直向下。","启动你的核心并将双腿抬起到你面前，直到它们与地面平行。","在顶部保持片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"hi":["अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को सीधा नीचे करके पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","एक क्षण के लिए शीर्ष पर रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i nogami prostymi w dół.","Napnij mięśnie brzucha i unieś nogi przed sobą, aż będą równoległe do podłogi.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["턱걸이 바에 팔을 완전히 펴 매달리되 다리를 곧게 내립니다.","복근을 긴장시키고 다리를 앞으로 올려 바닥과 평행하게 만듭니다.","맨 위에서 잠깐 멈췄다가 천천히 다리를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","back"]', 'abs', 'images/2333-PXTIwgu.jpg', 'videos/2333-PXTIwgu.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3214', 'arms apart circular toe touch (male)', 'upper legs', 'upper legs', 'body weight', '{"en":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e le braccia distese ai lati.","Tenendo le gambe dritte, piegati in avanti all''altezza della vita e allunga la mano destra verso le punte dei piedi.","Mentre ti abbassi, solleva contemporaneamente la gamba sinistra dietro di te, mantenendo l''equilibrio.","Ritorna alla posizione di partenza e ripeti il ​​movimento con la mano sinistra protesa verso le dita dei piedi e la gamba destra sollevata dietro di te.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve kollarınız yanlara doğru uzatılmış şekilde ayakta durun.","Bacaklarınızı düz tutarak belinizden öne doğru eğilin ve sağ elinizle ayak parmaklarınıza doğru uzanın.","Aşağı uzandığınızda, dengenizi koruyarak aynı anda sol bacağınızı düz bir şekilde arkanıza kaldırın.","Başlangıç ​​pozisyonuna dönün ve sol eliniz ayak parmaklarınıza uzanıp sağ bacağınızı arkanıza doğru kaldıracak şekilde hareketi tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados.","Manteniendo las piernas rectas, flexiona el torso hacia adelante desde la cintura y lleva la mano derecha hacia los dedos de los pies.","Mientras bajas, levanta simultáneamente la pierna izquierda recta detrás de ti, manteniendo el equilibrio.","Regresa a la posición inicial y repite el movimiento llevando la mano izquierda hacia los dedos de los pies y levantando la pierna derecha detrás de ti.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, руки вытянуты в стороны.","Держа ноги прямыми, наклонитесь вперед в талии и дотянитесь правой рукой до пальцев ног.","Наклоняясь вниз, одновременно поднимите левую ногу прямо позади себя, сохраняя равновесие.","Вернитесь в исходное положение и повторите движение, потянув левую руку к пальцам ног и подняв правую ногу позади себя.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，双臂向两侧伸展。","保持双腿伸直，腰部向前弯曲，右手向下伸向脚趾。","当你向下伸展时，同时将左腿在身后伸直，保持平衡。","返回起始位置，重复该动作，左手伸向脚趾，右腿在身后抬起。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और हाथों को बगल तक फैलाकर खड़े हो जाएं।","अपने पैरों को सीधा रखते हुए, कमर के बल आगे की ओर झुकें और अपने दाहिने हाथ से अपने पैर की उंगलियों तक पहुंचें।","जैसे ही आप नीचे पहुँचते हैं, साथ ही संतुलन बनाए रखते हुए अपने बाएँ पैर को अपने पीछे सीधा ऊपर उठाएँ।","प्रारंभिक स्थिति पर लौटें और अपने बाएं हाथ को अपने पैर की उंगलियों तक पहुंचाते हुए और अपने दाहिने पैर को अपने पीछे ऊपर उठाते हुए इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań w rozkroku na szerokość barków z ramionami wyciągniętymi na boki.","Utrzymując proste nogi, pochyl się do przodu w biodrach i sięgnij prawą dłonią w kierunku palców stóp.","Sięgając w dół, jednocześnie unieś lewą nogę prosto w górę za siebie, zachowując równowagę.","Wróć do pozycji wyjściowej i powtórz ruch, sięgając lewą dłonią do palców stóp i unosząc prawą nogę za siebie.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["발을 어깨 넓이로 벌리고 팔을 옆으로 펼칩니다.","다리를 곧게 펴고 허리를 앞으로 구부려 오른쪽 손으로 발끝을 터치합니다.","손을 내릴 때 동시에 왼쪽 다리를 곧게 펴 뒤로 들어 올려 균형을 유지합니다.","시작 자세로 돌아와 왼쪽 손으로 발끝을 터치하면서 오른쪽 다리를 곧게 펴 뒤로 들어 올리는 동작을 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'hamstrings', '["hamstrings","quadriceps","calves"]', 'glutes', 'images/3214-RtyAsy1.jpg', 'videos/3214-RtyAsy1.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3204', 'arms overhead full sit-up (male)', 'waist', 'waist', 'body weight', '{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Estendi le braccia sopra la testa, mantenendole dritte.","Coinvolgendo gli addominali, solleva lentamente la parte superiore del corpo da terra, piegandoti in avanti finché il busto non è in posizione verticale.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Kollarınızı düz tutarak yukarı doğru uzatın.","Karın kaslarınızı devreye sokarak üst bedeninizi yavaşça yerden kaldırın, gövdeniz dik olana kadar öne doğru kıvrılın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Extiende los brazos por encima de la cabeza, manteniéndolos rectos.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que el torso quede erguido.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Вытяните руки над головой, сохраняя их прямыми.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется в вертикальном положении.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，膝盖弯曲，双脚平放在地上。","将手臂伸过头顶，保持伸直。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲直到躯干直立。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी भुजाओं को सीधा रखते हुए ऊपर की ओर फैलाएँ।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ सीधा न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.","Wyciągnij ramiona nad głowę, utrzymując je proste.","Angażując mięśnie brzucha, powoli unieś górną część ciała nad podłogę, zwijając się do przodu, aż tułów znajdzie się w pozycji pionowej.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 누워 무릎을 구부리고 발을 바닥에 붙입니다.","팔을 머리 위로 곧게 펼칩니다.","복근을 사용하여 천천히 윗몸을 들어 올려 몸통이 수직이 될 때까지 앞쪽으로 구부립니다.","맨 위에서 잠깐 멈췄다가 천천히 윗몸을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors","lower back"]', 'abs', 'images/3204-NAkmgdx.jpg', 'videos/3204-NAkmgdx.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0009', 'assisted chest dip (kneeling)', 'chest', 'chest', 'leverage machine', '{"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina all''altezza desiderata e fissa le ginocchia sul cuscinetto.","Afferrare le maniglie con i palmi rivolti verso il basso e le braccia completamente distese.","Abbassa il corpo piegando i gomiti finché la parte superiore delle braccia non è parallela al pavimento.","Fai una pausa per un momento, quindi ritorna alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz yüksekliğe ayarlayın ve dizlerinizi yastığa sabitleyin.","Avuç içleriniz aşağıya bakacak ve kollarınız tamamen uzatılmış halde tutacakları kavrayın.","Üst kollarınız yere paralel oluncaya kadar dirseklerinizi bükerek vücudunuzu indirin.","Bir an duraklayın ve ardından kendinizi başlangıç ​​pozisyonuna doğru itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Отрегулируйте машину на желаемую высоту и зафиксируйте колени на подставке.","Возьмитесь за ручки ладонями вниз и полностью выпрямите руки.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","手掌朝下，抓住手柄，双臂完全伸展。","弯曲肘部降低身体，直到上臂与地板平行。","暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपनी इच्छित ऊंचाई पर समायोजित करें और अपने घुटनों को पैड पर सुरक्षित करें।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर हैंडल को पकड़ें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiednią wysokość i oprzyj kolana na poduszce.","Chwyć uchwyty dłońmi skierowanymi w dół, ramiona w pełni wyprostowane.","Opuść ciało, uginając łokcie, aż ramiona będą równoległe do podłogi.","Zatrzymaj się na chwilę, a następnie wypchnij się z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 높이로 조절하고 무릎을 패드에 고정합니다.","손으로 손잡이를 손바닥이 아래를 향하도록 잡고 팔을 완전히 펼칩니다.","팔꿈치를 구부려 몸을 내리되 팔뚝이 바닥과 평행하게 될 때까지 내립니다.","잠깐 멈췄다가 몸을 시작 자세로 밀어 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/0009-PAgTVaK.jpg', 'videos/0009-PAgTVaK.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0011', 'assisted hanging knee raise', 'waist', 'waist', 'assisted', '{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Appendi a una barra per trazioni con le braccia completamente distese e i palmi rivolti lontano da te.","Coinvolgi i muscoli centrali e solleva le ginocchia verso il petto, piegando i fianchi e le ginocchia.","Fai una pausa per un momento nella parte superiore del movimento, contraendo gli addominali.","Abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Kollarınız tamamen uzatılmış ve avuçlarınız sizden uzağa bakacak şekilde barfiks barına asın.","Çekirdek kaslarınızı çalıştırın ve dizlerinizi göğsünüze doğru kaldırın, kalçalarınızı ve dizlerinizi bükün.","Hareketin zirvesinde bir anlığına durun ve karın kaslarınızı sıkın.","Bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, flexionando las caderas y las rodillas.","Haz una pausa por un momento en la parte superior del movimiento, apretando el abdomen.","Baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Задействуйте мышцы корпуса и поднимите колени к груди, сгибая бедра и колени.","Задержитесь на мгновение в верхней точке движения, напрягая пресс.","Медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","调动你的核心肌肉，将膝盖抬向胸部，弯曲臀部和膝盖。","在动作的最高点暂停片刻，挤压腹肌。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"],"hi":["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपनी मुख्य मांसपेशियों को संलग्न करें और अपने घुटनों को अपनी छाती की ओर उठाएं, कूल्हों और घुटनों पर झुकें।","अपने पेट को सिकोड़ते हुए गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i dłońmi skierowanymi od siebie.","Napnij mięśnie brzucha i unieś kolana w kierunku klatki piersiowej, uginając biodra i kolana.","Zatrzymaj się na chwilę w górnej fazie ruchu, ściskając mięśnie brzucha.","Powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["턱걸이 바에 팔을 완전히 펴고 손바닥이 앞을 향하도록 매달립니다.","복근을 긴장시키고 무릎을 가슴 쪽으로 올리되 엉덩이와 무릎에서 구부립니다.","동작의 맨 위에서 잠깐 멈춰 복근을 조입니다.","천천히 다리를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/0011-03lzqwk.jpg', 'videos/0011-03lzqwk.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0010', 'assisted hanging knee raise with throw down', 'waist', 'waist', 'assisted', '{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."],"it":["Appendi a una barra per trazioni con le braccia completamente distese e i palmi rivolti lontano da te.","Coinvolgi il core e solleva le ginocchia verso il petto, mantenendo le gambe unite.","Una volta che le ginocchia sono all''altezza del petto, lancia in modo esplosivo le gambe verso terra, estendendole completamente.","Consenti alle gambe di oscillare nuovamente verso l''alto e ripeti il ​​movimento per il numero di ripetizioni desiderato."],"tr":["Kollarınız tamamen uzatılmış ve avuçlarınız sizden uzağa bakacak şekilde barfiks barına asın.","Merkez bölgenizi devreye sokun ve bacaklarınızı bir arada tutarak dizlerinizi göğsünüze doğru kaldırın.","Dizleriniz göğüs hizasına geldiğinde bacaklarınızı patlayıcı bir şekilde yere doğru atın ve tamamen uzatın.","Bacaklarınızın geriye doğru sallanmasına izin verin ve hareketi istenen sayıda tekrarla tekrarlayın."],"es":["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera.","Activa el core y levanta las rodillas hacia el pecho, manteniendo las piernas juntas.","Una vez que las rodillas estén a la altura del pecho, lanza las piernas explosivamente hacia el suelo, extendiéndolas por completo.","Deja que las piernas se balanceen de vuelta hacia arriba y repite el movimiento el número de repeticiones deseado."],"ru":["Повисните на перекладине, полностью вытянув руки и повернув ладони от себя.","Напрягите корпус и поднимите колени к груди, держа ноги вместе.","Как только ваши колени окажутся на уровне груди, резко бросьте ноги вниз к земле, полностью выпрямляя их.","Позвольте ногам подняться и повторите движение желаемое количество повторений."],"zh":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","收紧核心并将膝盖抬向胸部，保持双腿并拢。","一旦你的膝盖与胸部齐平，爆发性地将你的双腿向地面扔去，将它们完全伸展。","让双腿向后摆动并重复该动作达到所需的重复次数。"],"hi":["अपनी बाहों को पूरी तरह फैलाकर और अपनी हथेलियों को आपसे दूर की ओर रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने पैरों को एक साथ रखते हुए, अपने घुटनों को अपनी छाती की ओर उठाएं।","एक बार जब आपके घुटने छाती के स्तर पर हों, तो अपने पैरों को पूरी तरह फैलाते हुए जमीन की ओर नीचे फेंकें।","अपने पैरों को वापस ऊपर की ओर झुकने दें और वांछित संख्या में दोहराव के लिए इस क्रिया को दोहराएं।"],"pl":["Zwiśnij na drążku do podciągania z rękami w pełni wyprostowanymi i dłońmi skierowanymi od siebie.","Napnij mięśnie brzucha i unieś kolana w kierunku klatki piersiowej, trzymając nogi razem.","Gdy kolana znajdą się na wysokości klatki piersiowej, gwałtownie wyrzuć nogi w dół, w pełni je prostując.","Pozwól nogom wrócić w górę wahadłowym ruchem i powtórz zalecaną liczbę razy."],"ko":["턱걸이 바에 팔을 완전히 펴고 손바닥이 앞을 향하도록 매달립니다.","복근을 긴장시키고 무릎을 가슴 쪽으로 올리되 다리를 모은 상태로 유지합니다.","무릎이 가슴 높이에 도달하면 폭발적으로 다리를 바닥 쪽으로 던지며 완전히 펼칩니다.","다리가 자연스럽게 위로 흔들려 올라오게 하고 동작을 반복합니다."]}', 'hip flexors', '["hip flexors","lower back"]', 'abs', 'images/0010-8K0w2yA.jpg', 'videos/0010-8K0w2yA.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1708', 'assisted lying calves stretch', 'lower legs', 'lower legs', 'assisted', '{"en":["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."],"it":["Sdraiati sulla schiena con le gambe distese.","Piega un ginocchio e appoggia il piede a terra.","Usando le mani o un asciugamano, tira delicatamente le dita dei piedi verso il corpo, avvertendo un allungamento nel polpaccio.","Mantieni l''allungamento per 20-30 secondi.","Rilascia l''allungamento e ripeti sull''altra gamba."],"tr":["Bacaklarınız uzatılmış halde sırt üstü yatın.","Bir dizinizi bükün ve ayağınızı düz bir şekilde yere koyun.","Ellerinizi veya bir havluyu kullanarak ayak parmaklarınızı yavaşça vücudunuza doğru çekin, baldırınızda bir gerginlik hissedin.","Uzatmayı 20-30 saniye kadar tutun.","Germeyi bırakın ve diğer bacakta tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona una rodilla y coloca el pie plano sobre el suelo.","Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite con la otra pierna."],"ru":["Лягте на спину, вытянув ноги.","Согните одно колено и поставьте стопу на землю.","Руками или полотенцем осторожно потяните пальцы ног к телу, чувствуя растяжение в икрах.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите на другую ногу."],"zh":["仰卧，双腿伸展。","弯曲一侧膝盖，将脚平放在地上。","用手或毛巾轻轻地将脚趾拉向身体，感受小腿的拉伸。","保持拉伸 20-30 秒。","松开拉伸并在另一条腿上重复。"],"hi":["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","एक घुटने को मोड़ें और अपने पैर को ज़मीन पर सपाट रखें।","अपने हाथों या तौलिये का उपयोग करके, अपनी पिंडली में खिंचाव महसूस करते हुए, धीरे से अपने पैर की उंगलियों को अपने शरीर की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरे पैर पर दोहराएं।"],"pl":["Połóż się na plecach z wyciągniętymi nogami.","Ugnij jedną nogę i oprzyj stopę płasko na podłodze.","Za pomocą rąk lub ręcznika delikatnie przyciągnij palce stopy w kierunku ciała, odczuwając rozciąganie w łydce.","Utrzymaj rozciąganie przez 20-30 sekund.","Zwolnij rozciąganie i powtórz drugą nogą."],"ko":["등을 바닥에 누워 다리를 펼칩니다.","한쪽 무릎을 구부려 발을 바닥에 붙입니다.","손이나 수건을 사용하여 발가락을 천천히 몸 쪽으로 당겨 종아리가 늘어나는 것을 느낍니다.","스트레칭을 20~30초간 유지합니다.","스트레칭을 풀고 반대쪽 다리로 반복합니다."]}', 'hamstrings', '["hamstrings"]', 'calves', 'images/1708-GxDwDX0.jpg', 'videos/1708-GxDwDX0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1709', 'assisted lying glutes stretch', 'upper legs', 'upper legs', 'assisted', '{"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"it":["Sdraiati sulla schiena con le gambe distese.","Piega il ginocchio destro e posiziona la caviglia destra sulla coscia sinistra, appena sopra il ginocchio.","Afferrare la coscia sinistra con entrambe le mani e tirarla delicatamente verso il petto.","Mantieni l''allungamento per 20-30 secondi.","Rilascia e ripeti dall''altra parte."],"tr":["Bacaklarınız uzatılmış halde sırt üstü yatın.","Sağ dizinizi bükün ve sağ ayak bileğinizi sol uyluğunuzun üzerine, dizin hemen üstüne yerleştirin.","Sol uyluğunuzu iki elinizle kavrayın ve yavaşça göğsünüze doğru çekin.","Uzatmayı 20-30 saniye kadar tutun.","Serbest bırakın ve diğer tarafta tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."],"ru":["Лягте на спину, вытянув ноги.","Согните правое колено и положите правую лодыжку на левое бедро, чуть выше колена.","Возьмите левое бедро обеими руками и осторожно потяните его к груди.","Удерживайте растяжку 20–30 секунд.","Отпустите и повторите с другой стороны."],"zh":["仰卧，双腿伸展。","弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。","用双手抓住左大腿，轻轻地将其拉向胸部。","保持拉伸 20-30 秒。","松开并在另一侧重复。"],"hi":["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने टखने को अपनी बाईं जांघ पर रखें, घुटने के ठीक ऊपर।","अपनी बायीं जांघ को दोनों हाथों से पकड़ें और धीरे से अपनी छाती की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","छोड़ें और दूसरी तरफ दोहराएं।"],"pl":["Połóż się na plecach z wyciągniętymi nogami.","Ugnij prawe kolano i umieść prawą kostkę na lewym udzie, tuż nad kolanem.","Chwyć lewe udo obiema rękami i delikatnie przyciągnij je w kierunku klatki piersiowej.","Utrzymaj rozciąganie przez 20-30 sekund.","Zwolnij i powtórz po drugiej stronie."],"ko":["등을 바닥에 누워 다리를 펼칩니다.","오른쪽 무릎을 구부려 오른쪽 발목을 왼쪽 넓적다리 위에 놓되 무릎 바로 위에 올립니다.","양손으로 왼쪽 넓적다리를 잡고 천천히 가슴 쪽으로 당깁니다.","스트레칭을 20~30초간 유지합니다.","스트레칭을 풀고 반대쪽에서 반복합니다."]}', 'hamstrings', '["hamstrings"]', 'glutes', 'images/1709-yn0LjwL.jpg', 'videos/1709-yn0LjwL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1710', 'assisted lying gluteus and piriformis stretch', 'upper legs', 'upper legs', 'assisted', '{"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."],"it":["Sdraiati sulla schiena con le gambe distese.","Piega il ginocchio destro e posiziona la caviglia destra sulla coscia sinistra, appena sopra il ginocchio.","Afferrare la coscia sinistra con entrambe le mani e tirarla delicatamente verso il petto.","Mantieni l''allungamento per 20-30 secondi.","Rilascia l''allungamento e ripeti dall''altro lato."],"tr":["Bacaklarınız uzatılmış halde sırt üstü yatın.","Sağ dizinizi bükün ve sağ ayak bileğinizi sol uyluğunuzun üzerine, dizin hemen üstüne yerleştirin.","Sol uyluğunuzu iki elinizle kavrayın ve yavaşça göğsünüze doğru çekin.","Uzatmayı 20-30 saniye kadar tutun.","Uzatmayı bırakın ve diğer tarafta tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas extendidas.","Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.","Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta el estiramiento y repite del otro lado."],"ru":["Лягте на спину, вытянув ноги.","Согните правое колено и положите правую лодыжку на левое бедро, чуть выше колена.","Возьмите левое бедро обеими руками и осторожно потяните его к груди.","Удерживайте растяжку 20–30 секунд.","Освободите растяжку и повторите с другой стороны."],"zh":["仰卧，双腿伸展。","弯曲右膝盖，将右脚踝放在左大腿上，就在膝盖上方。","用双手抓住左大腿，轻轻地将其拉向胸部。","保持拉伸 20-30 秒。","松开拉伸并在另一侧重复。"],"hi":["अपने पैरों को फैलाकर अपनी पीठ के बल लेटें।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने टखने को अपनी बाईं जांघ पर रखें, घुटने के ठीक ऊपर।","अपनी बायीं जांघ को दोनों हाथों से पकड़ें और धीरे से अपनी छाती की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","खिंचाव छोड़ें और दूसरी तरफ दोहराएं।"],"pl":["Połóż się na plecach z wyciągniętymi nogami.","Ugnij prawe kolano i umieść prawą kostkę na lewym udzie, tuż nad kolanem.","Chwyć lewe udo obiema rękami i delikatnie przyciągnij je w kierunku klatki piersiowej.","Utrzymaj rozciąganie przez 20-30 sekund.","Zwolnij rozciąganie i powtórz po drugiej stronie."],"ko":["등을 바닥에 누워 다리를 펼칩니다.","오른쪽 무릎을 구부려 오른쪽 발목을 왼쪽 넓적다리 위에 놓되 무릎 바로 위에 올립니다.","양손으로 왼쪽 넓적다리를 잡고 천천히 가슴 쪽으로 당깁니다.","스트레칭을 20~30초간 유지합니다.","스트레칭을 풀고 반대쪽에서 반복합니다."]}', 'hamstrings', '["hamstrings"]', 'glutes', 'images/1710-RQNVT10.jpg', 'videos/1710-RQNVT10.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0012', 'assisted lying leg raise with lateral throw down', 'waist', 'waist', 'assisted', '{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe distese e le braccia lungo i fianchi.","Metti le mani sotto i glutei per supporto.","Coinvolgi gli addominali e solleva le gambe da terra, mantenendole dritte.","Tenendo le gambe unite, abbassale da un lato finché non si trovano a pochi centimetri dal suolo.","Fai una pausa per un momento, quindi riporta le gambe nella posizione di partenza.","Ripeti il ​​movimento dall''altro lato.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız uzatılmış ve kollarınız yanlarınızda olacak şekilde sırt üstü yatın.","Destek için ellerinizi kalça kaslarınızın altına yerleştirin.","Karın kaslarınızı devreye sokun ve bacaklarınızı düz tutarak yerden kaldırın.","Bacaklarınızı bir arada tutarken yerden birkaç santim yüksekte olana kadar onları bir tarafa indirin.","Bir an duraklayın ve bacaklarınızı tekrar başlangıç ​​pozisyonuna kaldırın.","Hareketi diğer tarafa doğru tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el abdomen y levanta las piernas del suelo, manteniéndolas rectas.","Manteniendo las piernas juntas, bájalas hacia un lado hasta que queden a pocos centímetros del suelo.","Haz una pausa por un momento, luego levanta las piernas de vuelta a la posición inicial.","Repite el movimiento hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите пресс и поднимите ноги от земли, сохраняя их прямыми.","Держа ноги вместе, опустите их в сторону, пока они не окажутся на несколько дюймов над землей.","Сделайте паузу на мгновение, затем поднимите ноги обратно в исходное положение.","Повторите движение в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["平躺，双腿伸展，双臂放在身体两侧。","将双手放在臀部下方以获得支撑。","收紧腹肌，将双腿抬离地面，保持伸直。","双腿并拢的同时，将它们降低到一侧，直到离地几英寸。","暂停片刻，然后抬起双腿回到起始位置。","到另一侧重复该动作。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने पेट को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपने पैरों को एक साथ रखते हुए, उन्हें एक तरफ नीचे करें जब तक कि वे जमीन से कुछ इंच ऊपर न हो जाएं।","एक पल के लिए रुकें, फिर अपने पैरों को वापस प्रारंभिक स्थिति में उठाएं।","इस क्रिया को दूसरी ओर भी दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Połóż się płasko na plecach z wyciągniętymi nogami i ramionami wzdłuż tułowia.","Umieść dłonie pod pośladkami dla wsparcia.","Napnij mięśnie brzucha i unieś nogi nad podłogę, utrzymując je proste.","Trzymając nogi razem, opuść je na bok, aż znajdą się kilka centymetrów nad podłogą.","Zatrzymaj się na chwilę, a następnie unieś nogi z powrotem do pozycji wyjściowej.","Powtórz ruch po drugiej stronie.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["등을 바닥에 누워 다리를 펼치고 팔을 양쪽에 내립니다.","손을 둔부 아래에 받쳐 놓습니다.","복근을 긴장시키고 다리를 바닥에서 들어 곧게 펼친 상태로 유지합니다.","다리를 모은 상태로 한쪽으로 내려 바닥에서 몇 센티 정도 떨어진 위치까지 내립니다.","잠깐 멈춰 다리를 시작 자세로 올립니다.","반대쪽으로도 같은 동작을 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'hip flexors', '["hip flexors","obliques"]', 'abs', 'images/0012-UGhRD1A.jpg', 'videos/0012-UGhRD1A.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0013', 'assisted lying leg raise with throw down', 'waist', 'waist', 'assisted', '{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe distese e le braccia lungo i fianchi.","Metti le mani sotto i glutei per supporto.","Coinvolgi il tuo core e solleva le gambe da terra, mantenendole dritte.","Alza le gambe finché non sono perpendicolari al suolo.","Abbassa le gambe nella posizione di partenza.","Allo stesso tempo, getta le gambe verso terra, mantenendole dritte.","Solleva le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız uzatılmış ve kollarınız yanlarınızda olacak şekilde sırt üstü yatın.","Destek için ellerinizi kalça kaslarınızın altına yerleştirin.","Merkez bölgenizi devreye sokun ve bacaklarınızı düz tutarak yerden kaldırın.","Bacaklarınızı yere dik olana kadar kaldırın.","Bacaklarınızı tekrar başlangıç ​​pozisyonuna indirin.","Eş zamanlı olarak bacaklarınızı düz tutarak yere doğru indirin.","Bacaklarınızı tekrar başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.","Coloca las manos debajo de los glúteos como apoyo.","Activa el core y levanta las piernas del suelo, manteniéndolas rectas.","Eleva las piernas hasta que queden perpendiculares al suelo.","Baja las piernas de vuelta a la posición inicial.","Simultáneamente, lanza las piernas hacia el suelo, manteniéndolas rectas.","Eleva las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, вытянув ноги и положив руки по бокам.","Положите руки под ягодицы для поддержки.","Напрягите корпус и поднимите ноги от земли, сохраняя их прямыми.","Поднимайте ноги до тех пор, пока они не станут перпендикулярно земле.","Опустите ноги обратно в исходное положение.","Одновременно опустите ноги на землю, сохраняя их прямыми.","Поднимите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，双腿伸展，双臂放在身体两侧。","将双手放在臀部下方以获得支撑。","启动你的核心并将双腿抬离地面，保持伸直。","抬起双腿，直到它们垂直于地面。","将双腿放低回到起始位置。","同时，将双腿向地面放下，保持伸直。","将双腿抬回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर अपनी पीठ के बल सीधे लेट जाएँ।","समर्थन के लिए अपने हाथों को अपने ग्लूट्स के नीचे रखें।","अपने कोर को संलग्न करें और अपने पैरों को सीधा रखते हुए जमीन से ऊपर उठाएं।","अपने पैरों को तब तक उठाएं जब तक वे जमीन से लंबवत न हो जाएं।","अपने पैरों को वापस नीचे प्रारंभिक स्थिति में ले आएँ।","इसके साथ ही अपने पैरों को सीधा रखते हुए नीचे जमीन की ओर फेंकें।","अपने पैरों को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach z wyciągniętymi nogami i ramionami wzdłuż tułowia.","Umieść dłonie pod pośladkami dla wsparcia.","Napnij mięśnie brzucha i unieś nogi nad podłogę, utrzymując je proste.","Unieś nogi, aż będą prostopadłe do podłogi.","Opuść nogi z powrotem do pozycji wyjściowej.","Jednocześnie wyrzuć nogi w dół w kierunku podłogi, utrzymując je proste.","Unieś nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 누워 다리를 펼치고 팔을 양쪽에 내립니다.","손을 둔부 아래에 받쳐 놓습니다.","복근을 긴장시키고 다리를 바닥에서 들어 곧게 펼친 상태로 유지합니다.","다리를 바닥과 수직이 될 때까지 올립니다.","다리를 다시 바닥 쪽으로 내립니다.","동시에 다리를 바닥을 향해 폭발적으로 던지며 곧게 펼친 상태로 유지합니다.","다리를 다시 시작 자세로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors","quadriceps"]', 'abs', 'images/0013-VX5YKR5.jpg', 'videos/0013-VX5YKR5.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0014', 'assisted motion russian twist', 'waist', 'waist', 'medicine ball', '{"en":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."],"it":["Sedersi a terra con le ginocchia piegate e i piedi appoggiati sul pavimento.","Tieni la palla medica con entrambe le mani davanti al petto.","Appoggiati leggermente all''indietro, contraendo gli addominali e mantenendo la schiena dritta.","Ruota lentamente il busto verso destra, portando la palla medica verso il lato destro del corpo.","Fai una pausa per un momento, quindi ruota il busto verso sinistra, portando la palla medica verso il lato sinistro del corpo.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde yere oturun.","Sağlık topunu iki elinizle göğsünüzün önünde tutun.","Hafifçe geriye yaslanın, karın kaslarınızı çalıştırın ve sırtınızı düz tutun.","Sağlık topunu vücudunuzun sağ tarafına doğru getirerek gövdenizi yavaşça sağa doğru çevirin.","Bir an duraklayın, ardından gövdenizi sola doğru döndürerek sağlık topunu vücudunuzun sol tarafına getirin.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén el balón medicinal con ambas manos frente al pecho.","Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta.","Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo.","Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Сядьте на пол, согните колени и поставьте ступни на пол.","Держите медицинский мяч обеими руками перед грудью.","Слегка откиньтесь назад, напрягая пресс и держа спину прямо.","Медленно поверните туловище вправо, направляя медицинский мяч к правой стороне тела.","Сделайте паузу на мгновение, затем поверните туловище влево, направляя медицинский мяч к левой стороне тела.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["坐在地上，膝盖弯曲，双脚平放在地板上。","双手将健身球放在胸前。","稍微向后倾斜，收紧腹肌并保持背部挺直。","慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。","暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。","继续交替进行所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट करके जमीन पर बैठें।","मेडिसिन बॉल को दोनों हाथों से अपनी छाती के सामने पकड़ें।","अपने पेट को जोड़ते हुए और अपनी पीठ को सीधा रखते हुए थोड़ा पीछे झुकें।","धीरे-धीरे अपने धड़ को दाईं ओर मोड़ें, दवा की गेंद को अपने शरीर के दाईं ओर लाएं।","एक पल के लिए रुकें, फिर अपने धड़ को बाईं ओर मोड़ें, दवा की गेंद को अपने शरीर के बाईं ओर लाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Usiądź na podłodze z ugiętymi kolanami i stopami płasko na podłodze.","Trzymaj piłkę lekarską obiema rękami przed klatką piersiową.","Odchyl się lekko do tyłu, napinając mięśnie brzucha i utrzymując proste plecy.","Powoli skręć tułów w prawo, przenosząc piłkę lekarską w kierunku prawej strony ciała.","Zatrzymaj się na chwilę, a następnie skręć tułów w lewo, przenosząc piłkę lekarską w kierunku lewej strony ciała.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["바닥에 앉아 무릎을 구부리고 발을 바닥에 붙입니다.","메디신볼을 양손으로 가슴 앞에 들어 올립니다.","약간 뒤로 기울인 상태에서 복근을 긴장시키고 등을 곧게 펴 유지합니다.","천천히 몸통을 오른쪽으로 트위스트하여 메디신볼을 몸의 오른쪽으로 가져옵니다.","잠깐 멈춘 다음 몸통을 왼쪽으로 트위스트하며 메디신볼을 몸의 왼쪽으로 가져옵니다.","원하는 반복 횟수만큼 좌우를 번갈아가며 계속합니다."]}', 'obliques', '["obliques","lower back"]', 'abs', 'images/0014-r7cT9YD.jpg', 'videos/0014-r7cT9YD.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0015', 'assisted parallel close grip pull-up', 'back', 'back', 'leverage machine', '{"en":["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina in base al peso e all''altezza desiderati.","Posiziona le mani sulle barre parallele con una presa salda, i palmi rivolti l''uno verso l''altro.","Appendi alle sbarre con le braccia completamente distese e i piedi sollevati da terra.","Coinvolgi i muscoli della schiena e solleva il corpo verso le sbarre, mantenendo i gomiti vicini al corpo.","Continua a tirare finché il mento non è sopra le sbarre.","Fai una pausa per un momento in alto, quindi abbassa lentamente il corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz ağırlığa ve yüksekliğe ayarlayın.","Ellerinizi paralel çubukların üzerine, avuç içleriniz birbirine bakacak şekilde yakın bir tutuşla yerleştirin.","Kollarınız tamamen uzatılmış ve ayaklarınız yerden yukarıda olacak şekilde barlardan sarkın.","Sırt kaslarınızı çalıştırın ve dirseklerinizi vücudunuza yakın tutarak vücudunuzu barlara doğru yukarı çekin.","Çeneniz barların üstüne çıkana kadar çekmeye devam edin.","Tepe noktasında bir an duraklayın, ardından vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina al peso y la altura deseados.","Coloca las manos en las barras paralelas con un agarre cerrado, con las palmas mirándose entre sí.","Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las barras, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las barras.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Настройте машину на желаемый вес и рост.","Положите руки на параллельные брусья узким хватом, ладонями друг к другу.","Повисните на перекладинах, полностью вытянув руки и оторвав ноги от земли.","Напрягите мышцы спины и подтяните тело к перекладинам, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над перекладинами.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整到您想要的重量和高度。","将双手紧紧握在双杠上，手掌相对。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。","继续拉，直到下巴高于杠铃。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपने इच्छित वजन और ऊंचाई के अनुसार समायोजित करें।","अपने हाथों को समानान्तर पट्टियों पर कसकर पकड़ के रखें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखते हुए सलाखों से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को सलाखों की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी सलाखों से ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiedni ciężar i wysokość.","Umieść dłonie na równoległych poręczach wąskim chwytem, dłońmi zwróconymi do siebie.","Zwiśnij na poręczach z rękami w pełni wyprostowanymi i stopami uniesionymi nad podłogę.","Napnij mięśnie pleców i podciągnij ciało w kierunku poręczy, trzymając łokcie blisko ciała.","Kontynuuj podciąganie, aż broda znajdzie się nad poręczami.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 무게와 높이로 조절합니다.","평행봉에 손을 좁게 올려 손바닥이 서로 마주보도록 합니다.","팔을 완전히 펴고 발을 바닥에서 들어 봉에 매달립니다.","등 근육을 긴장시키고 몸을 봉 쪽으로 위로 당기되 팔꿈치는 몸 쪽으로 가깝게 유지합니다.","턱이 봉 위로 올라갈 때까지 계속 당깁니다.","맨 위에서 잠깐 멈췄다가 천천히 몸을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/0015-vrhHa6D.jpg', 'videos/0015-vrhHa6D.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0016', 'assisted prone hamstring', 'upper legs', 'upper legs', 'assisted', '{"en":["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati a faccia in giù su un tappetino o una panca con le gambe completamente distese.","Avere un partner o utilizzare una fascia di resistenza per fissare le caviglie.","Coinvolgi i muscoli posteriori della coscia e solleva le gambe verso i glutei, mantenendo le ginocchia dritte.","Fai una pausa per un momento in alto, quindi abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız tamamen uzatılmış halde, bir minder veya bankın üzerine yüzüstü uzanın.","Bir partneriniz olsun veya ayak bileklerinizi sabitlemek için bir direnç bandı kullanın.","Hamstringlerinizi devreye sokun ve dizlerinizi düz tutarak bacaklarınızı kalça kaslarınıza doğru kaldırın.","Tepe noktasında bir an duraklayın, ardından bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.","Pide a un compañero o usa una banda elástica para sujetar tus tobillos.","Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте лицом вниз на коврик или скамью, полностью вытянув ноги.","Попросите партнера или используйте эспандер, чтобы зафиксировать лодыжки.","Напрягите мышцы задней поверхности бедра и поднимите ноги к ягодицам, держа колени прямо.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["脸朝下躺在垫子或长凳上，双腿完全伸展。","找一个伙伴或使用阻力带来固定脚踝。","收紧腿筋，将双腿抬向臀肌，保持膝盖伸直。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को पूरी तरह फैलाकर किसी चटाई या बेंच पर मुंह करके लेट जाएं।","अपनी एड़ियों को सुरक्षित करने के लिए एक साथी रखें या प्रतिरोध बैंड का उपयोग करें।","अपने हैमस्ट्रिंग को संलग्न करें और अपने घुटनों को सीधा रखते हुए अपने पैरों को अपने ग्लूट्स की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na brzuchu na macie lub ławce z nogami w pełni wyprostowanymi.","Poproś partnera lub użyj taśmy oporowej, aby zabezpieczyć kostki.","Napnij mięśnie dwugłowe uda i unieś nogi w kierunku pośladków, utrzymując proste kolana.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["매트나 벤치 위에 엎드려 다리를 완전히 펼칩니다.","파트너에게 도움을 받거나 저항 밴드를 사용하여 발목을 고정합니다.","햄스트링을 긴장시키고 무릎을 곧게 펼친 상태로 다리를 둔부 쪽으로 올립니다.","맨 위에서 잠깐 멈췄다가 천천히 다리를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'glutes', '["glutes","lower back"]', 'hamstrings', 'images/0016-VedGSby.jpg', 'videos/0016-VedGSby.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1713', 'assisted prone lying quads stretch', 'upper legs', 'upper legs', 'assisted', '{"en":["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."],"it":["Sdraiati a faccia in giù con le gambe distese.","Piega il ginocchio sinistro e allunga la mano sinistra indietro per afferrare il piede o la caviglia sinistra.","Tira delicatamente il piede sinistro verso i glutei, avvertendo un allungamento nel quadricipite sinistro.","Mantieni la posizione per 20-30 secondi, quindi rilascia.","Ripeti con la gamba destra."],"tr":["Bacaklarınız uzatılmış halde yüzüstü yere yatın.","Sol dizinizi bükün ve sol ayağınızı veya ayak bileğinizi tutmak için sol elinizle geriye doğru uzanın.","Sol ayağınızı yavaşça kalça kaslarınıza doğru çekin, sol kuadrisepsinizde bir gerginlik hissedin.","Gerdirmeyi 20-30 saniye kadar tutun, sonra bırakın.","Sağ bacağınızla tekrarlayın."],"es":["Túmbate boca abajo en el suelo con las piernas extendidas.","Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.","Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.","Mantén el estiramiento durante 20-30 segundos, luego suelta.","Repite con la pierna derecha."],"ru":["Лягте лицом вниз на землю, вытянув ноги.","Согните левое колено и потянитесь левой рукой назад, чтобы схватить левую ступню или лодыжку.","Аккуратно подтяните левую ногу к ягодицам, чувствуя растяжение в левом квадрицепсе.","Удерживайте растяжку 20–30 секунд, затем расслабьтесь.","Повторите с правой ногой."],"zh":["脸朝下躺在地上，双腿伸直。","弯曲左膝，用左手向后抓住左脚或脚踝。","轻轻地将左脚拉向臀肌，感受左股四头肌的拉伸。","保持拉伸 20-30 秒，然后放松。","右腿重复上述动作。"],"hi":["अपने पैरों को फैलाकर जमीन पर मुंह करके लेट जाएं।","अपने बाएँ घुटने को मोड़ें और अपने बाएँ हाथ को पीछे ले जाकर अपने बाएँ पैर या टखने को पकड़ें।","अपने बाएँ पैर को धीरे से अपने ग्लूट्स की ओर खींचें, अपने बाएँ क्वाड में खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","अपने दाहिने पैर से दोहराएँ।"],"pl":["Połóż się na brzuchu na podłodze z wyciągniętymi nogami.","Ugnij lewe kolano i sięgnij lewą ręką do tyłu, aby chwycić lewą stopę lub kostkę.","Delikatnie przyciągnij lewą stopę w kierunku pośladków, odczuwając rozciąganie w lewym mięśniu czworogłowym uda.","Utrzymaj rozciąganie przez 20-30 sekund, a następnie zwolnij.","Powtórz prawą nogą."],"ko":["바닥에 엎드려 다리를 펼칩니다.","왼쪽 무릎을 구부리고 왼쪽 손으로 뒤로 뻗어 발이나 발목을 잡습니다.","왼쪽 발을 둔부 쪽으로 천천히 당겨 왼쪽 대퇴사두근이 늘어나는 것을 느낍니다.","스트레칭을 20~30초간 유지한 다음 풉니다.","오른쪽 다리로 반복합니다."]}', 'hamstrings', '["hamstrings","glutes"]', 'quads', 'images/1713-YUYAMEj.jpg', 'videos/1713-YUYAMEj.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1714', 'assisted prone rectus femoris stretch', 'waist', 'waist', 'assisted', '{"en":["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."],"it":["Sdraiati a faccia in giù con le gambe dritte.","Piega il ginocchio destro e allunga la mano destra indietro per afferrare il piede o la caviglia destra.","Tira delicatamente il piede destro o la caviglia verso i glutei, avvertendo un allungamento nella parte anteriore della coscia destra.","Mantieni l''allungamento per 20-30 secondi.","Rilascia e ripeti dall''altra parte."],"tr":["Bacaklarınız düz olacak şekilde yüz üstü yere yatın.","Sağ dizinizi bükün ve sağ ayağınızı veya ayak bileğinizi tutmak için sağ elinizle geriye doğru uzanın.","Sağ uyluğunuzun ön kısmında bir gerginlik hissederek sağ ayağınızı veya ayak bileğinizi yavaşça kalçalarınıza doğru çekin.","Uzatmayı 20-30 saniye kadar tutun.","Serbest bırakın ve diğer tarafta tekrarlayın."],"es":["Túmbate boca abajo en el suelo con las piernas rectas.","Flexiona la rodilla derecha y lleva la mano derecha hacia atrás para agarrar el pie o el tobillo derecho.","Jala suavemente el pie o el tobillo derecho hacia los glúteos, sintiendo un estiramiento en la parte frontal del muslo derecho.","Mantén el estiramiento durante 20-30 segundos.","Suelta y repite del otro lado."],"ru":["Лягте лицом вниз на землю, выпрямив ноги.","Согните правое колено и протяните правую руку назад, чтобы схватить правую ступню или лодыжку.","Аккуратно потяните правую ступню или лодыжку к ягодицам, ощущая растяжение в передней части правого бедра.","Удерживайте растяжку 20–30 секунд.","Отпустите и повторите с другой стороны."],"zh":["脸朝下躺在地上，双腿伸直。","弯曲右膝，用右手向后伸抓住右脚或脚踝。","轻轻地将右脚或脚踝拉向臀部，感受右大腿前部的拉伸。","保持拉伸 20-30 秒。","松开并在另一侧重复。"],"hi":["अपने पैरों को सीधा करके जमीन पर मुंह करके लेट जाएं।","अपने दाहिने घुटने को मोड़ें और अपने दाहिने पैर या टखने को पकड़ने के लिए अपने दाहिने हाथ से पीछे जाएँ।","अपनी दाहिनी जांघ के सामने खिंचाव महसूस करते हुए धीरे से अपने दाहिने पैर या टखने को अपने ग्लूट्स की ओर खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें।","छोड़ें और दूसरी तरफ दोहराएं।"],"pl":["Połóż się na brzuchu na podłodze z prostymi nogami.","Ugnij prawe kolano i sięgnij prawą ręką do tyłu, aby chwycić prawą stopę lub kostkę.","Delikatnie przyciągnij prawą stopę lub kostkę w kierunku pośladków, odczuwając rozciąganie z przodu prawego uda.","Utrzymaj rozciąganie przez 20-30 sekund.","Zwolnij i powtórz po drugiej stronie."],"ko":["바닥에 엎드린 상태로 누워 두 다리를 곧게 펼칩니다.","오른쪽 무릎을 구부리고 오른손으로 뒤로 뻗어 오른발이나 발목을 잡습니다.","오른발이나 발목을 엉덩이 쪽으로 천천히 당겨 오른쪽 허벅지 앞부분에 스트레칭을 느낍니다.","20~30초 동안 스트레칭을 유지합니다.","반대쪽도 같은 방식으로 반복합니다."]}', 'quadriceps', '["quadriceps"]', 'abs', 'images/1714-2Ryn564.jpg', 'videos/1714-2Ryn564.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0017', 'assisted pull-up', 'back', 'back', 'leverage machine', '{"en":["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina in base alle impostazioni di peso e altezza desiderate.","Afferrare le maniglie con una presa prona, leggermente più larga della larghezza delle spalle.","Appendere con le braccia completamente distese e i piedi sollevati da terra.","Coinvolgi i muscoli della schiena e solleva il corpo verso le maniglie, mantenendo i gomiti vicini al corpo.","Continua a tirare finché il mento non è sopra le maniglie.","Fai una pausa per un momento in alto, quindi abbassa lentamente il corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz ağırlık ve boy ayarlarına ayarlayın.","Tutamaçları omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Kollarınız tamamen uzatılmış ve ayaklarınız yerden yukarıda olacak şekilde asın.","Sırt kaslarınızı çalıştırın ve dirseklerinizi vücudunuza yakın tutarak vücudunuzu tutamaçlara doğru yukarı çekin.","Çeneniz tutamakların üzerine gelene kadar çekmeye devam edin.","Tepe noktasında bir an duraklayın, ardından vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina a los valores de peso y altura deseados.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos y los pies sin tocar el suelo.","Activa los músculos de la espalda y lleva el cuerpo hacia arriba hacia las agarraderas, manteniendo los codos cerca del cuerpo.","Continúa subiendo hasta que la barbilla quede por encima de las agarraderas.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Настройте машину на желаемые параметры веса и роста.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Висите, полностью вытянув руки и оторвав ноги от земли.","Задействуйте мышцы спины и подтяните тело к ручкам, держа локти близко к телу.","Продолжайте тянуть, пока подбородок не окажется над ручками.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整至您所需的体重和高度设置。","正手握住手柄，握距略宽于肩宽。","双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपनी वांछित वजन और ऊंचाई सेटिंग्स के अनुसार समायोजित करें।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखकर लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपने शरीर को हैंडल की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी हैंडल के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiedni ciężar i wysokość.","Chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.","Zwiśnij z rękami w pełni wyprostowanymi i stopami uniesionymi nad podłogę.","Napnij mięśnie pleców i podciągnij ciało w kierunku uchwytów, trzymając łokcie blisko ciała.","Kontynuuj podciąganie, aż broda znajdzie się nad uchwytami.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 무게와 높이 설정으로 조정합니다.","손바닥이 앞을 향하도록 손잡이를 어깨너비보다 약간 넓게 잡습니다.","팔을 완전히 펼친 상태로 발이 바닥에서 떨어져 매달립니다.","등 근육을 활성화하고 팔꿈치를 몸 옆에 붙이며 몸을 위로 당겨 손잡이 방향으로 올립니다.","턱이 손잡이 위로 올라올 때까지 계속 당깁니다.","맨 위에서 잠깐 멈춘 후 천천히 시작 위치로 몸을 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/0017-kiJ4Z2K.jpg', 'videos/0017-kiJ4Z2K.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1716', 'assisted seated pectoralis major stretch with stability ball', 'chest', 'chest', 'assisted', '{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una palla stabilizzata con i piedi appoggiati a terra e la schiena dritta.","Tieni una palla stabilizzante con entrambe le mani ed estendi le braccia davanti a te.","Abbassa lentamente la sfera di stabilità verso il petto, avvertendo un allungamento dei muscoli pettorali.","Mantieni la posizione per alcuni secondi, quindi torna lentamente alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir stabilite topunun üzerine oturun.","Denge topunu iki elinizle tutun ve kollarınızı düz bir şekilde önünüze doğru uzatın.","Göğüs kaslarınızın gerildiğini hissederek stabilite topunu yavaşça göğsünüze doğru indirin.","Gerdirmeyi birkaç saniye basılı tutun, ardından yavaşça başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.","Sostén un balón de estabilidad con ambas manos y extiende los brazos rectos frente a ti.","Baja lentamente el balón de estabilidad hacia el pecho, sintiendo un estiramiento en los pectorales.","Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на мяч, поставив ноги на землю и выпрямив спину.","Возьмите мяч для стабилизации обеими руками и вытяните руки прямо перед собой.","Медленно опустите мяч-стабилизатор к груди, чувствуя растяжение грудных мышц.","Удерживайте растяжку несколько секунд, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在稳定球上，双脚平放在地面上，背部挺直。","双手握住稳定球，并将双臂伸直至身前。","慢慢地将稳定球降低到胸部，感受胸肌的拉伸。","保持伸展几秒钟，然后慢慢回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक स्टेबिलिटी बॉल पर बैठें।","दोनों हाथों से एक स्टेबिलिटी बॉल पकड़ें और अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपनी पेक्टोरल मांसपेशियों में खिंचाव महसूस करते हुए धीरे-धीरे स्टेबिलिटी बॉल को अपनी छाती की ओर नीचे लाएँ।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na piłce stabilizacyjnej ze stopami płasko na podłodze i prostymi plecami.","Trzymaj piłkę stabilizacyjną obiema rękami i wyciągnij ramiona prosto przed siebie.","Powoli opuść piłkę w kierunku klatki piersiowej, odczuwając rozciąganie w mięśniach piersiowych.","Utrzymaj rozciąganie przez kilka sekund, a następnie powoli wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["짐볼에 앉아 발을 바닥에 평평하게 놓고 등을 펴서 바른 자세를 유지합니다.","짐볼을 양손으로 잡고 팔을 앞으로 곧게 펼칩니다.","짐볼을 가슴 쪽으로 천천히 내려 가슴 근육에서 스트레칭을 느낍니다.","몇 초 동안 스트레칭을 유지한 후 천천히 시작 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","triceps"]', 'pectorals', 'images/1716-RoV1Rfa.jpg', 'videos/1716-RoV1Rfa.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1712', 'assisted side lying adductor stretch', 'upper legs', 'upper legs', 'assisted', '{"en":["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."],"it":["Sdraiati su un fianco con le gambe dritte e impilate una sopra l''altra.","Piega leggermente la parte inferiore della gamba per stabilità.","Posiziona il piede superiore su una superficie stabile, come una panca o un gradino.","Mantenendo la gamba superiore dritta, abbassala lentamente verso terra, avvertendo un allungamento nella parte interna della coscia.","Mantieni l''allungamento per 20-30 secondi.","Ritorna alla posizione di partenza e ripeti dall''altro lato."],"tr":["Bacaklarınız düz ve üst üste gelecek şekilde yan tarafınıza uzanın.","Denge için alt bacağınızı hafifçe bükün.","Üstteki ayağınızı bank veya basamak gibi sabit bir yüzeye yerleştirin.","Üst bacağınızı düz tutarak yavaşça yere doğru indirin, uyluğunuzun iç kısmında bir gerginlik hissedin.","Uzatmayı 20-30 saniye kadar tutun.","Başlangıç ​​pozisyonuna dönün ve diğer tarafta tekrarlayın."],"es":["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.","Flexiona ligeramente la pierna de abajo para mayor estabilidad.","Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.","Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.","Mantén el estiramiento durante 20-30 segundos.","Regresa a la posición inicial y repite del otro lado."],"ru":["Лягте на бок, выпрямив ноги и положив их друг на друга.","Слегка согните нижнюю ногу для устойчивости.","Поставьте верхнюю ногу на устойчивую поверхность, например на скамью или ступеньку.","Удерживая верхнюю ногу прямой, медленно опустите ее к земле, чувствуя растяжение внутренней части бедра.","Удерживайте растяжку 20–30 секунд.","Вернитесь в исходное положение и повторите то же самое в другую сторону."],"zh":["侧躺，双腿伸直并叠放在一起。","稍微弯曲下面的腿以保持稳定。","将上脚放在稳定的表面上，例如长凳或台阶上。","保持上腿伸直，慢慢将其降低到地面，感觉大腿内侧有拉伸感。","保持拉伸 20-30 秒。","返回起始位置并在另一侧重复。"],"hi":["अपने पैरों को सीधा और एक दूसरे के ऊपर रखकर करवट से लेटें।","स्थिरता के लिए अपने निचले पैर को थोड़ा मोड़ें।","अपने ऊपरी पैर को किसी स्थिर सतह, जैसे बेंच या सीढ़ी पर रखें।","अपने ऊपरी पैर को सीधा रखते हुए, अपनी आंतरिक जांघ में खिंचाव महसूस करते हुए इसे धीरे-धीरे जमीन की ओर नीचे लाएं।","20-30 सेकंड तक खिंचाव बनाए रखें।","प्रारंभिक स्थिति पर लौटें और दूसरी तरफ दोहराएं।"],"pl":["Połóż się na boku z prostymi nogami ułożonymi jedna na drugiej.","Ugnij lekko dolną nogę dla stabilności.","Oprzyj górną stopę na stabilnej powierzchni, takiej jak ławka lub stopień.","Utrzymując górną nogę prostą, powoli opuszczaj ją w kierunku podłogi, odczuwając rozciąganie w wewnętrznej części uda.","Utrzymaj rozciąganie przez 20-30 sekund.","Wróć do pozycji wyjściowej i powtórz po drugiej stronie."],"ko":["옆으로 누운 자세에서 다리를 곧게 펼쳐 위아래로 정렬시킵니다.","안정성을 위해 아래쪽 다리를 약간 구부립니다.","위쪽 발을 벤치나 스텝 같은 안정적인 표면에 올립니다.","위쪽 다리를 곧게 펼친 상태로 천천히 아래로 내려 안쪽 허벅지에서 스트레칭을 느낍니다.","20~30초 동안 스트레칭을 유지합니다.","시작 위치로 돌아간 후 반대쪽도 반복합니다."]}', 'hamstrings', '["hamstrings","glutes"]', 'adductors', 'images/1712-hC6oYY5.jpg', 'videos/1712-hC6oYY5.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1758', 'assisted sit-up', 'waist', 'waist', 'assisted', '{"en":["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti sul bordo di una panchina o chiedi a qualcuno di tenerti i piedi abbassati.","Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Metti le mani dietro la testa con i gomiti rivolti verso l''esterno.","Coinvolgendo gli addominali, solleva lentamente la parte superiore del corpo da terra, piegandoti in avanti finché il busto non forma un angolo di 45 gradi.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bir bankın kenarına oturun veya birisinin ayaklarınızı aşağıda tutmasını sağlayın.","Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Ellerinizi başınızın arkasına, dirsekleriniz dışarı bakacak şekilde yerleştirin.","Karın kaslarınızı devreye sokarak üst bedeninizi yavaşça yerden kaldırın ve gövdeniz 45 derecelik bir açıya gelene kadar öne doğru kıvrılın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en el borde de un banco o pide a alguien que te sujete los pies.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на край скамьи или попросите кого-нибудь держать вас за ноги.","Лягте на спину, согните колени и поставьте ступни на землю.","Положите руки за голову локтями наружу.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳边缘或让某人按住你的脚。","平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["किसी बेंच के किनारे पर बैठें या किसी से अपने पैर नीचे रखने को कहें।","अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na brzegu ławki lub poproś kogoś, aby przytrzymał ci stopy.","Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.","Umieść dłonie za głową, kierując łokcie na zewnątrz.","Angażując mięśnie brzucha, powoli unieś górną część ciała nad podłogę, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["벤치 끝에 앉거나 누군가가 발을 눌러 고정합니다.","무릎을 구부리고 발을 바닥에 평평하게 놓은 상태로 등을 바닥에 펼쳐 누웁니다.","양손을 머리 뒤에 놓고 팔꿈치가 바깥쪽을 향하도록 합니다.","복근을 활성화하여 상체를 천천히 들어올려 45도 각도가 될 때까지 앞으로 구부립니다.","맨 위에서 잠깐 멈춘 후 천천히 상체를 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/1758-aumB2IV.jpg', 'videos/1758-aumB2IV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1431', 'assisted standing chin-up', 'back', 'back', 'leverage machine', '{"en":["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina al livello di assistenza desiderato.","Stare sulla pedana e afferrare le maniglie con una presa prona, leggermente più larghe della larghezza delle spalle.","Tieni il petto in alto e le spalle indietro, contrai il core e piega leggermente le ginocchia.","Solleva il corpo flettendo i gomiti e portandoli verso i fianchi.","Continua a tirare finché il mento non è sopra la barra.","Fai una pausa per un momento in alto, quindi abbassa lentamente il corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz yardım seviyesine ayarlayın.","Ayak platformunun üzerinde durun ve kolları omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak tutun.","Göğsünüzü yukarıda, omuzlarınızı geride tutun, merkez bölgenizi devreye sokun ve dizlerinizi hafifçe bükün.","Dirseklerinizi bükerek ve dirseklerinizi yanlarınıza doğru indirerek vücudunuzu yukarı çekin.","Çeneniz çubuğun üstüne çıkana kadar çekmeye devam edin.","Tepe noktasında bir an duraklayın, ardından vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina al nivel de asistencia deseado.","Sube a la plataforma para los pies y agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Mantén el pecho arriba y los hombros atrás, activa el core y flexiona ligeramente las rodillas.","Levanta el cuerpo flexionando los codos y llevándolos hacia abajo, en dirección a los costados.","Continúa subiendo hasta que la barbilla quede por encima de la barra.","Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Настройте машину на желаемый уровень помощи.","Встаньте на платформу для ног и возьмитесь за рукоятки хватом сверху, на расстоянии чуть шире плеч.","Держите грудь поднятой, а плечи отведенными назад, задействуйте корпус и слегка согните колени.","Поднимите тело вверх, сгибая локти и направляя локти вниз в стороны.","Продолжайте тянуть, пока подбородок не окажется над перекладиной.","Задержитесь на мгновение в верхней точке, затем медленно опустите тело обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整至您所需的辅助级别。","站在脚踏板上，正手握住手柄，握距略宽于肩宽。","保持挺胸、肩膀向后，收紧核心肌群，并稍微弯曲膝盖。","弯曲肘部并将肘部向身体两侧压低，将身体向上拉。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपने इच्छित सहायता स्तर पर समायोजित करें।","फुट प्लेटफॉर्म पर खड़े हो जाएं और हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी छाती को ऊपर और कंधों को पीछे रखें, अपने कोर को संलग्न करें और अपने घुटनों को थोड़ा मोड़ें।","अपनी कोहनियों को मोड़कर और अपनी कोहनियों को अपनी तरफ नीचे की ओर ले जाकर अपने शरीर को ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiedni poziom wspomagania.","Stań na platformie i chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.","Utrzymuj wypiętą klatkę piersiową i ściągnięte barki, napnij mięśnie brzucha i ugnij lekko kolana.","Podciągnij ciało, uginając łokcie i kierując je w dół w stronę boków.","Kontynuuj podciąganie, aż broda znajdzie się nad drążkiem.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 보조 수준으로 조정합니다.","발판에 서서 손바닥이 앞을 향하도록 손잡이를 어깨너비보다 약간 넓게 잡습니다.","가슴을 펴고 어깨를 뒤로 젖히며 코어를 활성화하고 무릎을 약간 구부립니다.","팔꿈치를 구부려 몸을 들어올리면서 팔꿈치를 옆으로 아래로 밀어냅니다.","턱이 바 위로 올라올 때까지 계속 당깁니다.","맨 위에서 잠깐 멈춘 후 천천히 몸을 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/1431-7OeHptV.jpg', 'videos/1431-7OeHptV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1432', 'assisted standing pull-up', 'back', 'back', 'leverage machine', '{"en":["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina in base alle impostazioni di peso e altezza desiderate.","Mettiti di fronte alla macchina con i piedi alla larghezza delle spalle.","Afferrare le maniglie con una presa prona, leggermente più larga della larghezza delle spalle.","Coinvolgi i dorsali e i bicipiti e sollevati verso le maniglie.","Fermati un attimo in alto, contraendo i muscoli della schiena.","Abbassati lentamente fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz ağırlık ve boy ayarlarına ayarlayın.","Ayaklarınız omuz genişliğinde açık olacak şekilde makineye dönük durun.","Tutamaçları omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Lats ve bicepslerinizi devreye sokun ve kendinizi tutamaçlara doğru yukarı çekin.","Sırt kaslarınızı sıkarak tepede bir an duraklayın.","Kendinizi yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina a los valores de peso y altura deseados.","Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.","Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.","Activa los dorsales y los bíceps, y levántate hacia las agarraderas.","Haz una pausa por un momento en la parte superior, apretando los músculos de la espalda.","Bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Настройте машину на желаемые параметры веса и роста.","Встаньте лицом к тренажеру, поставив ноги на ширине плеч.","Возьмитесь за ручки хватом сверху, на расстоянии чуть шире плеч.","Задействуйте широчайшие и бицепсы и подтяните себя к ручкам.","Задержитесь на мгновение в верхней точке, напрягая мышцы спины.","Медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整至您所需的体重和高度设置。","面向机器站立，双脚分开与肩同宽。","正手握住手柄，握距略宽于肩宽。","启动你的背阔肌和二头肌，并将自己拉向手柄。","在顶部暂停片刻，挤压背部肌肉。","慢慢地将自己放回到起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपनी वांछित वजन और ऊंचाई सेटिंग्स के अनुसार समायोजित करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपने लैट्स और बाइसेप्स को संलग्न करें, और अपने आप को हैंडल की ओर ऊपर खींचें।","अपनी पीठ की मांसपेशियों को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiedni ciężar i wysokość.","Stań przodem do maszyny, stopy w rozkroku na szerokość barków.","Chwyć uchwyty nachwytem, nieco szerzej niż na szerokość barków.","Napnij mięśnie najszersze grzbietu i bicepsy, i podciągnij się w kierunku uchwytów.","Zatrzymaj się na chwilę w górnej pozycji, ściskając mięśnie pleców.","Powoli wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 무게와 높이 설정으로 조정합니다.","머신을 마주보고 서서 발을 어깨너비로 벌립니다.","손바닥이 앞을 향하도록 손잡이를 어깨너비보다 약간 넓게 잡습니다.","광배근과 이두근을 활성화하여 손잡이 방향으로 몸을 당겨 올립니다.","맨 위에서 잠깐 멈춰 등 근육을 꽉 조입니다.","천천히 몸을 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/1432-f4xtKBj.jpg', 'videos/1432-f4xtKBj.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0018', 'assisted standing triceps extension (with towel)', 'upper arms', 'upper arms', 'assisted', '{"en":["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere un asciugamano con entrambe le mani dietro la testa.","Tieni i gomiti vicino alle orecchie e la parte superiore delle braccia ferma.","Estendi lentamente gli avambracci verso l''alto, contraendo i tricipiti nella parte superiore.","Fai una pausa per un momento, quindi abbassa lentamente l''asciugamano nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve iki elinizle başınızın arkasında bir havlu tutun.","Dirseklerinizi kulaklarınıza yakın tutun ve üst kollarınızı sabit tutun.","Ön kollarınızı yavaşça yukarıya doğru uzatın, üst kısımda trisepsinizi sıkın.","Bir an duraklayın, ardından havluyu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.","Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.","Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.","Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, держите полотенце обеими руками за головой.","Держите локти близко к ушам, а плечи неподвижно.","Медленно вытяните предплечья вверх, сжимая трицепсы вверху.","Сделайте паузу на мгновение, затем медленно опустите полотенце обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，双手握住毛巾放在脑后。","保持肘部靠近耳朵，上臂保持静止。","慢慢向上伸展前臂，在顶部挤压三头肌。","暂停片刻，然后慢慢将毛巾放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों को अपने सिर के पीछे रखकर एक तौलिया पकड़ लें।","अपनी कोहनियों को अपने कानों के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","धीरे-धीरे अपने अग्रबाहुओं को ऊपर की ओर बढ़ाएं, अपने ट्राइसेप्स को शीर्ष पर दबाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे तौलिये को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj ręcznik obiema rękami za głową.","Trzymaj łokcie blisko uszu, a ramiona nieruchome.","Powoli prostuj przedramiona w górę, ściskając triceps w górnej fazie ruchu.","Zatrzymaj się na chwilę, a następnie powoli opuść ręcznik z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 서서 수건을 양손으로 머리 뒤에 잡습니다.","팔꿈치를 귀 쪽에 가깝게 유지하고 위팔을 고정시킵니다.","팔뚝을 천천히 위로 펼치면서 삼두근을 꽉 조입니다.","잠깐 멈춘 후 천천히 수건을 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0018-7HcfMBP.jpg', 'videos/0018-7HcfMBP.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0019', 'assisted triceps dip (kneeling)', 'upper arms', 'upper arms', 'leverage machine', '{"en":["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Regola la macchina in base al peso e all''altezza desiderati.","Inginocchiarsi sul tappetino di fronte alla macchina, con le mani che afferrano le maniglie.","Abbassa il corpo piegando i gomiti, mantenendo la schiena dritta e vicina alla macchina.","Fai una pausa per un momento in basso, quindi spingiti indietro fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz ağırlığa ve yüksekliğe ayarlayın.","Elleriniz tutamaçları kavrayarak, makineye bakan ped üzerinde diz çökün.","Dirseklerinizi bükerek, sırtınızı düz ve makineye yakın tutarak vücudunuzu indirin.","Altta bir an duraklayın, ardından kendinizi başlangıç ​​pozisyonuna doğru itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina al peso y la altura deseados.","Arrodíllate sobre la almohadilla frente a la máquina, con las manos sujetando las agarraderas.","Baja el cuerpo flexionando los codos, manteniendo la espalda recta y cerca de la máquina.","Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Настройте машину на желаемый вес и рост.","Встаньте на колени лицом к тренажеру, взявшись руками за ручки.","Опустите тело, согнув локти, держа спину прямо и близко к тренажеру.","Задержитесь на мгновение в нижней точке, затем вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将机器调整到您想要的重量和高度。","跪在面向机器的垫子上，双手握住手柄。","弯曲肘部降低身体，保持背部挺直并靠近机器。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपने इच्छित वजन और ऊंचाई के अनुसार समायोजित करें।","मशीन के सामने पैड पर घुटने टेकें, अपने हाथों से हैंडल को पकड़ें।","अपनी कोहनियों को मोड़कर, अपनी पीठ को सीधा और मशीन के पास रखते हुए अपने शरीर को नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiedni ciężar i wysokość.","Uklęknij na poduszce przodem do maszyny, trzymając uchwyty dłońmi.","Opuść ciało, uginając łokcie, utrzymując proste plecy blisko maszyny.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie wypchnij się z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 무게와 높이로 조정합니다.","머신을 마주보고 패드에 무릎을 꿇고 손잡이를 잡습니다.","팔꿈치를 구부려 몸을 내려가며 등을 펴서 머신에 가깝게 유지합니다.","맨 아래에서 잠깐 멈춘 후 팔을 펴서 시작 위치로 자신을 들어올립니다.","원하는 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0019-J60bN17.jpg', 'videos/0019-J60bN17.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2364', 'assisted wide-grip chest dip (kneeling)', 'chest', 'chest', 'leverage machine', '{"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"it":["Regola la macchina all''altezza desiderata e fissa le ginocchia sul cuscinetto.","Afferrare le maniglie con una presa ampia e tenere i gomiti leggermente piegati.","Abbassa il corpo piegando i gomiti finché la parte superiore delle braccia non è parallela al pavimento.","Spingiti indietro fino alla posizione di partenza estendendo le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Makineyi istediğiniz yüksekliğe ayarlayın ve dizlerinizi yastığa sabitleyin.","Tutma yerlerini geniş bir tutuşla kavrayın ve dirseklerinizi hafifçe bükülü tutun.","Üst kollarınız yere paralel oluncaya kadar dirseklerinizi bükerek vücudunuzu indirin.","Kollarınızı uzatarak kendinizi başlangıç ​​pozisyonuna doğru itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ajusta la máquina a la altura deseada y asegura las rodillas sobre la almohadilla.","Agarra las agarraderas con un agarre amplio y mantén los codos ligeramente flexionados.","Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.","Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"ru":["Отрегулируйте машину на желаемую высоту и зафиксируйте колени на подставке.","Возьмитесь за рукоятки широким хватом и держите локти слегка согнутыми.","Опустите тело, сгибая локти, пока плечи не станут параллельны полу.","Вернитесь в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"zh":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","宽握手柄并保持肘部稍微弯曲。","弯曲肘部降低身体，直到上臂与地板平行。","伸展双臂，将自己推回到起始位置。","重复所需的重复次数。"],"hi":["मशीन को अपनी इच्छित ऊंचाई पर समायोजित करें और अपने घुटनों को पैड पर सुरक्षित करें।","हैंडल को चौड़ी पकड़ से पकड़ें और अपनी कोहनियों को थोड़ा मोड़कर रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपकी ऊपरी भुजाएँ फर्श के समानांतर न हो जाएँ।","अपनी भुजाओं को फैलाकर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw maszynę na odpowiednią wysokość i oprzyj kolana na poduszce.","Chwyć uchwyty szerokim chwytem, utrzymując łokcie lekko ugięte.","Opuść ciało, uginając łokcie, aż ramiona będą równoległe do podłogi.","Wypchnij się z powrotem do pozycji wyjściowej, prostując ramiona.","Powtórz zalecaną liczbę razy."],"ko":["머신을 원하는 높이로 조정하고 무릎을 패드에 고정시킵니다.","넓은 그립으로 손잡이를 잡고 팔꿈치를 약간 구부린 상태로 유지합니다.","팔꿈치를 구부려 몸을 내려가 위팔이 바닥과 평행이 될 때까지 내립니다.","팔을 펴서 시작 위치로 자신을 들어올립니다.","원하는 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/2364-PnZJIrk.jpg', 'videos/2364-PnZJIrk.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3220', 'astride jumps (male)', 'cardio', 'cardio', 'body weight', '{"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle.","Piega le ginocchia e abbassa il corpo in una posizione tozza.","Salta in modo esplosivo verso l''alto, estendendo le gambe e le braccia.","Mentre sei in aria, allarga le gambe e porta le braccia ai lati.","Atterra dolcemente con i piedi alla larghezza delle spalle, piegando le ginocchia per assorbire l''impatto.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun.","Dizlerinizi bükün ve vücudunuzu çömelme pozisyonuna indirin.","Bacaklarınızı ve kollarınızı uzatarak patlayıcı bir şekilde yukarı doğru zıplayın.","Havadayken bacaklarınızı iki yana açın ve kollarınızı yanlara doğru açın.","Ayaklarınız omuz genişliğinde açık olacak şekilde yumuşak bir şekilde yere inin ve darbeyi absorbe etmek için dizlerinizi bükün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.","Salta explosivamente hacia arriba, extendiendo las piernas y los brazos.","Mientras estás en el aire, separa las piernas y lleva los brazos hacia los lados.","Aterriza suavemente con los pies separados a la altura de los hombros, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч.","Согните колени и опустите тело в присед.","Резко прыгните вверх, вытягивая ноги и руки.","Находясь в воздухе, разведите ноги в стороны и разведите руки в стороны.","Мягко приземлитесь, поставив ноги на ширине плеч, согнув колени, чтобы поглотить удар.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立。","弯曲膝盖并将身体降低至蹲姿。","爆发性向上跳跃，伸展双腿和手臂。","在空中时，将双腿分开，并将双臂向两侧伸出。","双脚分开与肩同宽，轻轻落地，弯曲膝盖以吸收冲击力。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","अपने पैरों और भुजाओं को फैलाते हुए तेजी से ऊपर की ओर कूदें।","हवा में रहते हुए, अपने पैरों को फैलाएं और अपनी भुजाओं को बगल की ओर लाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए, प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, धीरे से जमीन पर उतरें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków.","Ugnij kolana i opuść ciało do pozycji przysiadu.","Wyskocz gwałtownie w górę, prostując nogi i ramiona.","Będąc w powietrzu, rozłóż nogi na boki i wyprostuj ramiona na boki.","Wyląduj miękko, stopy w rozkroku na szerokość barków, uginając kolana, aby zamortyzować lądowanie.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 섭니다.","무릎을 구부려 스쿼트 자세로 몸을 내립니다.","다리와 팔을 펼치며 폭발적으로 위로 점프합니다.","공중에서 다리를 벌리고 팔을 양옆으로 펼칩니다.","발을 어깨너비로 벌리고 착지하면서 무릎을 구부려 충격을 흡수합니다.","원하는 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'cardiovascular system', 'images/3220-f9lVSSI.jpg', 'videos/3220-f9lVSSI.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3672', 'back and forth step', 'cardio', 'cardio', 'body weight', '{"en":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle.","Fai un passo avanti con il piede destro, piegando il ginocchio e abbassando il corpo in una posizione di affondo.","Spingi con il piede destro e torna alla posizione di partenza.","Ripeti il ​​movimento con il piede sinistro, alternando le gambe ad ogni passo.","Continua a fare passi avanti e indietro, mantenendo un ritmo costante.","Ripetere per la durata o il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun.","Sağ ayağınızla öne doğru bir adım atın, dizinizi bükün ve vücudunuzu hamle pozisyonuna indirin.","Sağ ayağınızla itin ve başlangıç ​​pozisyonuna geri dönün.","Hareketi her adımda bacak değiştirerek sol ayağınızla tekrarlayın.","Sabit bir tempoyu koruyarak ileri geri adım atmaya devam edin.","İstenilen süre veya tekrar sayısı kadar tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Da un paso adelante con el pie derecho, flexionando la rodilla y bajando el cuerpo hacia una posición de zancada.","Empuja con el pie derecho y da un paso atrás para regresar a la posición inicial.","Repite el movimiento con el pie izquierdo, alternando las piernas en cada paso.","Continúa dando pasos hacia adelante y hacia atrás, manteniendo un ritmo constante.","Repite durante la duración o el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч.","Сделайте шаг вперед правой ногой, согнув колено и опустив тело в положение выпада.","Оттолкнитесь правой ногой и вернитесь в исходное положение.","Повторите движение левой ногой, чередуя ноги при каждом шаге.","Продолжайте шагать вперед и назад, сохраняя устойчивый темп.","Повторяйте желаемую продолжительность или количество повторений."],"zh":["双脚分开与肩同宽站立。","右脚向前迈出一步，弯曲膝盖，将身体降低到弓步位置。","用右脚蹬地，然后回到起始位置。","用左脚重复该动作，每一步交替双腿。","继续来回走动，保持稳定的步伐。","重复所需的持续时间或重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने दाहिने पैर के साथ आगे बढ़ें, अपने घुटने को मोड़ें और अपने शरीर को एक लंज स्थिति में नीचे लाएँ।","अपने दाहिने पैर से धक्का दें और प्रारंभिक स्थिति में वापस आ जाएँ।","प्रत्येक चरण के साथ पैरों को बारी-बारी से अपने बाएं पैर से दोहराएं।","स्थिर गति बनाए रखते हुए आगे-पीछे कदम बढ़ाते रहें।","वांछित अवधि या दोहराव की संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków.","Zrób krok do przodu prawą stopą, uginając kolano i opuszczając ciało do pozycji wykroku.","Odepchnij się prawą stopą i wróć krokiem do pozycji wyjściowej.","Powtórz ruch lewą stopą, zmieniając nogi przy każdym kroku.","Kontynuuj wykonywanie kroków do przodu i do tyłu, utrzymując stałe tempo.","Powtórz przez zalecany czas lub liczbę powtórzeń."],"ko":["발을 어깨너비로 벌리고 섭니다.","오른쪽 발을 앞으로 내딛고 무릎을 구부려 런지 자세로 내려갑니다.","오른쪽 발로 밀어내 시작 위치로 돌아옵니다.","왼쪽 발로 같은 동작을 반복하면서 다리를 번갈아가며 스텝합니다.","꾸준한 속도를 유지하며 앞뒤로 스텝을 계속합니다.","원하는 시간 또는 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]', 'cardiovascular system', 'images/3672-fNGumX0.jpg', 'videos/3672-fNGumX0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1314', 'back extension on exercise ball', 'back', 'back', 'stability ball', '{"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Posiziona la palla di stabilità a terra e sdraiati a faccia in giù sopra di essa, con i fianchi appoggiati sulla palla e i piedi contro un muro o un''altra superficie stabile.","Posiziona le mani dietro la testa o incrociate sul petto.","Coinvolgi il core e solleva lentamente la parte superiore del corpo dalla palla, estendendo la schiena finché il corpo non forma una linea retta dalla testa ai talloni.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Denge topunu yere koyun ve kalçalarınız topun üzerinde ve ayaklarınız bir duvara veya başka bir sabit yüzeye dayanacak şekilde yüzü aşağı bakacak şekilde topun üzerine yatın.","Ellerinizi başınızın arkasında konumlandırın veya göğsünüzün üzerinde çaprazlayın.","Merkez bölgenizi devreye sokun ve üst bedeninizi yavaşça topun üzerinden kaldırın, vücudunuz başınızdan topuklarınıza kadar düz bir çizgi oluşturana kadar sırtınızı uzatın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca el balón de estabilidad en el suelo y túmbate boca abajo sobre él, con las caderas apoyadas en el balón y los pies contra una pared u otra superficie estable.","Coloca las manos detrás de la cabeza o cruzadas sobre el pecho.","Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta desde la cabeza hasta los talones.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Положите мяч на землю и лягте на него лицом вниз, положив бедра на мяч, а ступни упираясь в стену или другую устойчивую поверхность.","Положите руки за голову или скрестите на груди.","Напрягите корпус и медленно поднимите верхнюю часть тела с мяча, вытягивая спину до тех пор, пока тело не образует прямую линию от головы до пяток.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将稳定球放在地面上，面朝下躺在上面，臀部放在球上，双脚靠在墙壁或其他稳定的表面上。","将双手放在脑后或交叉在胸前。","启动你的核心，慢慢地将你的上半身抬离球，伸展你的背部，直到你的身体从头部到脚后跟形成一条直线。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["स्टेबिलिटी बॉल को जमीन पर रखें और उसके ऊपर मुंह करके लेट जाएं, अपने कूल्हों को बॉल पर और अपने पैरों को दीवार या अन्य स्थिर सतह पर टिकाएं।","अपने हाथों को अपने सिर के पीछे रखें या अपनी छाती के ऊपर रखें।","अपने कोर को संलग्न करें और धीरे-धीरे अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपनी पीठ को तब तक फैलाएं जब तक कि आपका शरीर आपके सिर से आपकी एड़ी तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Umieść piłkę stabilizacyjną na podłodze i połóż się na niej na brzuchu, opierając biodra na piłce, a stopy o ścianę lub inną stabilną powierzchnię.","Umieść dłonie za głową lub skrzyżuj je na klatce piersiowej.","Napnij mięśnie brzucha i powoli unieś górną część ciała nad piłkę, prostując plecy, aż ciało utworzy prostą linię od głowy do pięt.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["짐볼을 바닥에 놓고 그 위에 엎드려 누워 골반이 볼에 얹혀 있고 발이 벽이나 다른 안정적인 표면에 대합니다.","양손을 머리 뒤에 놓거나 가슴에 교차시킵니다.","코어를 활성화하고 상체를 천천히 들어올려 머리에서 발까지 몸이 일직선을 이룰 때까지 등을 펴냅니다.","맨 위에서 잠깐 멈춘 후 상체를 천천히 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'glutes', '["glutes","hamstrings"]', 'spine', 'images/1314-qLpO4vV.jpg', 'videos/1314-qLpO4vV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3297', 'back lever', 'back', 'back', 'body weight', '{"en":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia appendendoti a una barra per trazioni con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Coinvolgi il tuo core e tira le scapole verso il basso e all''indietro.","Piega le ginocchia e portale verso il petto.","Solleva lentamente le gambe, mantenendole dritte, finché il tuo corpo non è parallelo al suolo.","Mantieni questa posizione per alcuni secondi, quindi abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Eller omuz genişliğinden biraz daha geniş olacak şekilde, üstten tutuşla bir barfiks barına asılarak başlayın.","Merkez bölgenizi devreye sokun ve kürek kemiklerinizi aşağı ve geriye doğru çekin.","Dizlerinizi bükün ve göğsünüze doğru çekin.","Vücudunuz yere paralel oluncaya kadar bacaklarınızı düz tutarak yavaşça yukarı kaldırın.","Bu pozisyonu birkaç saniye basılı tutun, ardından bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Comienza colgándote de una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.","Activa el core y lleva los omóplatos hacia abajo y atrás.","Flexiona las rodillas y llévalas hacia el pecho.","Levanta lentamente las piernas, manteniéndolas rectas, hasta que el cuerpo quede paralelo al suelo.","Mantén esta posición durante unos segundos, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с подвешивания на перекладине хватом сверху, руки чуть шире плеч.","Напрягите корпус и потяните лопатки вниз и назад.","Согните колени и подтяните их к груди.","Медленно поднимите ноги вверх, удерживая их прямыми, пока тело не станет параллельно земле.","Удерживайте это положение несколько секунд, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先，用正手握法悬挂在引体向上杆上，双手分开的距离略大于肩宽。","启动你的核心并将肩胛骨向下拉和向后拉。","弯曲膝盖并将其向胸部靠拢。","慢慢抬起双腿，保持伸直，直到身体与地面平行。","保持这个姿势几秒钟，然后慢慢地将双腿放回起始位置。","重复所需的重复次数。"],"hi":["ओवरहैंड पकड़ के साथ पुल-अप बार से लटकने से शुरुआत करें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को नीचे और पीछे खींचें।","अपने घुटनों को मोड़ें और उन्हें अपनी छाती की ओर मोड़ें।","धीरे-धीरे अपने पैरों को ऊपर उठाएं, उन्हें सीधा रखें, जब तक कि आपका शरीर जमीन के समानांतर न हो जाए।","कुछ सेकंड के लिए इस स्थिति में रहें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Zacznij, zwisając na drążku do podciągania nachwytem, dłonie nieco szerzej niż na szerokość barków.","Napnij mięśnie brzucha i ściągnij łopatki w dół i do tyłu.","Ugnij kolana i przyciągnij je w kierunku klatki piersiowej.","Powoli unieś nogi, utrzymując je proste, aż ciało znajdzie się równolegle do podłogi.","Utrzymaj tę pozycję przez kilka sekund, a następnie powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["풀업 바에 손바닥이 앞을 향하도록 매달리되 손을 어깨너비보다 약간 넓게 잡습니다.","코어를 활성화하고 어깨뼈를 아래로 당기며 뒤로 젖힙니다.","무릎을 구부려 가슴 쪽으로 당깁니다.","다리를 곧게 펼친 상태로 천천히 들어올려 몸이 바닥과 평행이 될 때까지 올립니다.","몇 초 동안 이 자세를 유지한 후 다리를 천천히 시작 위치로 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms","core"]', 'upper back', 'images/3297-GaSzzuh.jpg', 'videos/3297-GaSzzuh.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1405', 'back pec stretch', 'back', 'back', 'body weight', '{"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."],"it":["Stai in piedi con i piedi alla larghezza delle spalle.","Estendi le braccia davanti a te, parallele al suolo.","Incrocia le braccia davanti al corpo, con il braccio destro sopra il braccio sinistro.","Intreccia le dita e ruota i palmi delle mani lontano dal corpo.","Alza lentamente le braccia in alto e lontano dal corpo, avvertendo un allungamento nella schiena e nel petto.","Mantieni la posizione per 15-30 secondi, quindi rilascia.","Ripeti sul lato opposto."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde dik durun.","Kollarınızı yere paralel olarak önünüze doğru uzatın.","Kollarınızı vücudunuzun önünde çaprazlayın, sağ kolunuz sol kolunuzun üzerinde olsun.","Parmaklarınızı birbirine kenetleyin ve avuçlarınızı vücudunuzdan uzağa doğru çevirin.","Kollarınızı yavaşça yukarı ve vücudunuzdan uzağa kaldırın, sırtınızda ve göğsünüzde bir gerginlik hissedin.","Gerdirmeyi 15-30 saniye kadar tutun, sonra bırakın.","Karşı tarafta tekrarlayın."],"es":["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.","Extiende los brazos rectos frente a ti, paralelos al suelo.","Cruza los brazos frente al cuerpo, con el brazo derecho sobre el brazo izquierdo.","Entrelaza los dedos y gira las palmas alejándolas del cuerpo.","Levanta lentamente los brazos hacia arriba y alejándolos del cuerpo, sintiendo un estiramiento en la espalda y el pecho.","Mantén el estiramiento durante 15-30 segundos, luego suelta.","Repite del lado opuesto."],"ru":["Встаньте прямо, ноги на ширине плеч.","Вытяните руки прямо перед собой, параллельно земле.","Скрестите руки перед телом, положив правую руку на левую.","Сцепите пальцы и поверните ладони от тела.","Медленно поднимите руки вверх и от тела, чувствуя растяжение в спине и груди.","Удерживайте растяжку 15–30 секунд, затем расслабьтесь.","Повторите на противоположной стороне."],"zh":["站直，双脚分开与肩同宽。","将双臂伸直在身前，与地面平行。","双臂交叉在身体前方，右臂放在左臂上方。","手指交叉，手掌旋转远离身体。","慢慢抬起手臂并远离身体，感觉背部和胸部有拉伸感。","保持拉伸 15-30 秒，然后放松。","在另一侧重复。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपनी भुजाओं को ज़मीन के समानांतर, अपने सामने सीधा फैलाएँ।","अपनी भुजाओं को अपने शरीर के सामने क्रॉस करें, अपनी दायीं भुजा को अपनी बायीं भुजा के ऊपर रखें।","अपनी उंगलियों को आपस में फंसा लें और अपनी हथेलियों को अपने शरीर से दूर घुमाएं।","अपनी पीठ और छाती में खिंचाव महसूस करते हुए धीरे-धीरे अपनी बाहों को ऊपर और अपने शरीर से दूर उठाएं।","15-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","विपरीत दिशा में दोहराएँ."],"pl":["Stań prosto, stopy w rozkroku na szerokość barków.","Wyciągnij ramiona prosto przed siebie, równolegle do podłogi.","Skrzyżuj ramiona przed ciałem, prawe ramię nad lewym.","Spleć palce i obróć dłonie od ciała.","Powoli unieś ramiona w górę i od ciała, odczuwając rozciąganie w plecach i klatce piersiowej.","Utrzymaj rozciąganie przez 15-30 sekund, a następnie zwolnij.","Powtórz po przeciwnej stronie."],"ko":["발을 어깨너비로 벌리고 펴고 섭니다.","팔을 앞으로 곧게 펼쳐 바닥과 평행하게 합니다.","팔을 앞으로 교차시켜 오른팔이 왼팔 위에 오도록 합니다.","손가락을 끼워 손바닥이 몸에서 멀어지도록 합니다.","팔을 천천히 위로 들어올리며 몸에서 멀어지게 하여 등과 가슴에서 스트레칭을 느낍니다.","15~30초 동안 스트레칭을 유지합니다.","반대쪽도 반복합니다."]}', 'shoulders', '["shoulders","chest"]', 'lats', 'images/1405-chfnQnM.jpg', 'videos/1405-chfnQnM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1473', 'backward jump', 'upper legs', 'upper legs', 'body weight', '{"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle.","Piega leggermente le ginocchia e salta all''indietro, spingendoti con entrambi i piedi.","Atterra dolcemente sulle punte dei piedi, piegando le ginocchia per assorbire l''impatto.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun.","Dizlerinizi hafifçe bükün ve her iki ayağınızla iterek geriye doğru atlayın.","Darbeyi absorbe etmek için dizlerinizi bükerek ayak parmaklarınızın üzerine yumuşak bir şekilde inin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros.","Flexiona ligeramente las rodillas y salta hacia atrás, impulsándote con ambos pies.","Aterriza suavemente sobre la punta de los pies, flexionando las rodillas para absorber el impacto.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч.","Слегка согните колени и подпрыгните назад, отталкиваясь обеими ногами.","Мягко приземлитесь на подушечки стоп, согнув колени, чтобы поглотить удар.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立。","稍微弯曲膝盖，向后跳跃，用双脚蹬地。","脚掌轻轻着地，弯曲膝盖以吸收冲击力。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और दोनों पैरों से धक्का देते हुए पीछे की ओर कूदें।","प्रभाव को अवशोषित करने के लिए अपने घुटनों को मोड़ते हुए, अपने पैरों की उंगलियों पर धीरे से उतरें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków.","Ugnij lekko kolana i wyskocz do tyłu, odbijając się obiema stopami.","Wyląduj miękko na palcach stóp, uginając kolana, aby zamortyzować lądowanie.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 섭니다.","무릎을 약간 구부리고 양발로 밀어내 뒤로 점프합니다.","발의 앞부분으로 부드럽게 착지하면서 무릎을 구부려 충격을 흡수합니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","glutes","calves"]', 'quads', 'images/1473-SaDOwk7.jpg', 'videos/1473-SaDOwk7.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0020', 'balance board', 'upper legs', 'upper legs', 'body weight', '{"en":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."],"it":["Posizionare la tavola di equilibrio su una superficie piana.","Sali sulla tavola di equilibrio con un piede, assicurandoti che sia centrato.","Sposta lentamente il peso sul piede sulla bilancia, mantenendo il core impegnato.","Mantieni l''equilibrio e la stabilità mentre mantieni la posizione per il periodo di tempo desiderato.","Ripeti l''esercizio con l''altro piede."],"tr":["Denge tahtasını düz bir yüzeye yerleştirin.","Ortalandığından emin olarak tek ayağınızla denge tahtasının üzerine çıkın.","Ağırlığınızı yavaşça denge tahtasındaki ayağınıza verin ve merkez bölgenizi meşgul tutun.","Pozisyonu istediğiniz süre boyunca korurken dengenizi ve istikrarınızı koruyun.","Egzersizi diğer ayağınızla tekrarlayın."],"es":["Coloca la tabla de equilibrio sobre una superficie plana.","Sube a la tabla de equilibrio con un pie, asegurándote de que esté centrado.","Desplaza lentamente tu peso hacia el pie que está sobre la tabla de equilibrio, manteniendo el core activado.","Mantén el equilibrio y la estabilidad mientras sostienes la posición durante el tiempo deseado.","Repite el ejercicio con el otro pie."],"ru":["Поместите балансборд на ровную поверхность.","Встаньте на балансборд одной ногой, убедившись, что он находится по центру.","Медленно перенесите вес тела на ногу на балансборде, сохраняя при этом корпус напряженным.","Сохраняйте баланс и стабильность, удерживая позицию в течение желаемого периода времени.","Повторите упражнение другой ногой."],"zh":["将平衡板放在平坦的表面上。","用一只脚踩在平衡板上，确保其居中。","慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。","在保持该姿势所需的时间内保持平衡和稳定。","用另一只脚重复该练习。"],"hi":["बैलेंस बोर्ड को समतल सतह पर रखें।","एक पैर से बैलेंस बोर्ड पर कदम रखें, यह सुनिश्चित करते हुए कि यह बीच में है।","अपने कोर को व्यस्त रखते हुए धीरे-धीरे अपना वजन बैलेंस बोर्ड पर पैर पर डालें।","वांछित समय तक पद पर रहते हुए अपना संतुलन और स्थिरता बनाए रखें।","दूसरे पैर से भी व्यायाम दोहराएं।"],"pl":["Umieść deskę równoważną na płaskiej powierzchni.","Wejdź na deskę jedną stopą, upewniając się, że jest wyśrodkowana.","Powoli przenieś ciężar ciała na stopę stojącą na desce, napinając mięśnie brzucha.","Utrzymuj równowagę i stabilność, trzymając pozycję przez zalecany czas.","Powtórz ćwiczenie drugą stopą."],"ko":["밸런스 보드를 평평한 표면에 놓습니다.","한쪽 발을 밸런스 보드에 올려 중심을 잡습니다.","무게를 밸런스 보드 위의 발로 천천히 옮기면서 코어를 활성화합니다.","균형을 유지하며 원하는 시간만큼 자세를 유지합니다.","반대쪽 발로도 같은 운동을 반복합니다."]}', 'calves', '["calves","hamstrings","glutes"]', 'quads', 'images/0020-xAySMB0.jpg', 'videos/0020-xAySMB0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0968', 'band alternating biceps curl', 'upper arms', 'upper arms', 'band', '{"en":["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere la fascia con una presa subdola, con i palmi rivolti verso l''alto.","Tieni i gomiti vicini ai fianchi e piega lentamente un braccio verso la spalla, contraendo i bicipiti nella parte superiore.","Abbassare nuovamente il braccio nella posizione iniziale e ripetere con l''altro braccio.","Continua ad alternare le braccia per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı avuçlarınız yukarı bakacak şekilde alttan kavrayarak tutun.","Dirseklerinizi yanlarınıza yakın tutun ve bir kolunuzu yavaşça omzunuza doğru kıvırarak pazılarınızı üst kısımda sıkıştırın.","Kolunuzu tekrar başlangıç ​​pozisyonuna indirin ve hareketi diğer kolla tekrarlayın.","İstenilen sayıda tekrar için kolları değiştirerek devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba.","Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior.","Baja el brazo de vuelta a la posición inicial y repite con el otro brazo.","Continúa alternando los brazos durante el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за ленту обратным хватом ладонями вверх.","Держите локти близко к бокам и медленно поднимите одну руку к плечу, сжимая бицепс вверху.","Опустите руку обратно в исходное положение и повторите то же самое с другой рукой.","Продолжайте чередовать руки желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，反手握住弹力带，手掌朝上。","保持肘部靠近身体两侧，慢慢地将一只手臂向肩膀弯曲，在顶部挤压二头肌。","将手臂放回起始位置，然后用另一只手臂重复此动作。","继续交替手臂进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को हाथ से पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी कोहनियों को अपने किनारों के पास रखें और धीरे-धीरे एक हाथ को अपने कंधे की ओर मोड़ें, अपने बाइसेप्स को ऊपर की ओर दबाएं।","हाथ को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj taśmę oporową podchwytem, dłońmi skierowanymi do góry.","Trzymaj łokcie blisko boków ciała i powoli uginaj jedno ramię w kierunku barku, ściskając biceps w górnej fazie ruchu.","Opuść ramię z powrotem do pozycji wyjściowej i powtórz drugim ramieniem.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["발을 어깨너비로 벌리고 서서 밴드를 손바닥이 위를 향하도록 언더핸드 그립으로 잡습니다.","팔꿈치를 몸 옆에 붙이고 한쪽 팔을 천천히 어깨 방향으로 구부리면서 이두근을 꽉 조입니다.","팔을 시작 위치로 내린 후 반대쪽 팔로 반복합니다.","원하는 횟수만큼 팔을 교대로 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0968-3omWx6P.jpg', 'videos/0968-3omWx6P.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0969', 'band alternating v-up', 'waist', 'waist', 'band', '{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe dritte e le braccia distese sopra la testa, tenendo la fascia.","Coinvolgi gli addominali e solleva contemporaneamente le gambe e la parte superiore del corpo da terra, portando le mani verso le dita dei piedi.","Mentre abbassi le gambe e la parte superiore del corpo, cambia la posizione delle gambe, incrociandole l''una sull''altra.","Ripeti il ​​movimento, alternando la posizione delle gambe ad ogni ripetizione.","Continuare per il numero di ripetizioni desiderato."],"tr":["Bandı tutarak bacaklarınız düz ve kollarınız yukarı doğru uzatılmış şekilde sırt üstü uzanın.","Karın kaslarınızı devreye sokun ve bacaklarınızı ve vücudunuzun üst kısmını aynı anda yerden kaldırın, ellerinizi ayak parmaklarınıza doğru uzatın.","Bacaklarınızı ve vücudunuzun üst kısmını geriye doğru indirirken, bacaklarınızın konumunu değiştirin ve üst üste geçin.","Her tekrarda bacaklarınızın pozisyonunu değiştirerek hareketi tekrarlayın.","İstenilen tekrar sayısı kadar devam edin."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Mientras bajas las piernas y la parte superior del cuerpo de nuevo, cambia la posición de las piernas, cruzando una sobre la otra.","Repite el movimiento, alternando la posición de las piernas en cada repetición.","Continúa durante el número de repeticiones deseado."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Напрягите пресс и одновременно поднимите ноги и верхнюю часть тела от земли, дотягиваясь руками до пальцев ног.","Опуская ноги и верхнюю часть тела обратно вниз, поменяйте положение ног, скрещивая одну над другой.","Повторите движение, меняя положение ног при каждом повторении.","Продолжайте необходимое количество повторений."],"zh":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时将双腿和上半身抬离地面，将双手伸向脚趾。","当你降低双腿和上半身时，交换双腿的位置，将一条腿交叉在另一条腿上。","重复该动作，每次重复时交替变换双腿的位置。","继续进行所需的重复次数。"],"hi":["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को संलग्न करें और अपने पैरों और शरीर के ऊपरी हिस्से को एक साथ जमीन से ऊपर उठाएं, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","जैसे ही आप अपने पैरों और ऊपरी शरीर को वापस नीचे लाते हैं, एक को दूसरे के ऊपर रखते हुए अपने पैरों की स्थिति बदलें।","प्रत्येक पुनरावृत्ति के साथ अपने पैरों की स्थिति को बदलते हुए, आंदोलन को दोहराएं।","दोहराव की वांछित संख्या के लिए जारी रखें।"],"pl":["Połóż się płasko na plecach z prostymi nogami i ramionami wyciągniętymi nad głową, trzymając taśmę oporową.","Napnij mięśnie brzucha i jednocześnie unieś nogi oraz górną część ciała nad podłogę, sięgając dłońmi w kierunku palców stóp.","Opuszczając nogi i górną część ciała, zmień ułożenie nóg, krzyżując jedną nad drugą.","Powtórz ruch, zmieniając ułożenie nóg przy każdym powtórzeniu.","Kontynuuj przez zalecaną liczbę powtórzeń."],"ko":["등을 바닥에 펴고 누워 다리를 곧게 펼치고 팔을 머리 위로 펼쳐 밴드를 잡습니다.","복근을 활성화하여 다리와 상체를 동시에 들어올려 손을 발 방향으로 뻗습니다.","다리와 상체를 내리면서 다리의 위치를 바꿔 한쪽 다리가 다른 쪽 위에 교차되도록 합니다.","같은 동작을 반복하면서 매번 다리의 위치를 교대로 바꿉니다.","원하는 횟수만큼 계속 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/0969-ztAa1RK.jpg', 'videos/0969-ztAa1RK.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0970', 'band assisted pull-up', 'back', 'back', 'band', '{"en":["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a una barra per trazioni o a un punto di ancoraggio robusto.","Sali sulla fascia e afferra la barra con i palmi rivolti lontano da te, le mani leggermente più larghe della larghezza delle spalle.","Appendere con le braccia completamente distese, mantenendo il core impegnato e le spalle in basso e all''indietro.","Tira il corpo verso la sbarra stringendo insieme le scapole e spingendo i gomiti verso i fianchi.","Continua a tirare finché il mento non è sopra la barra, quindi abbassati lentamente fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı bir çekme çubuğuna veya sağlam bir bağlantı noktasına takın.","Grubun üzerine çıkın ve avuçlarınız sizden uzağa bakacak şekilde, eller omuz genişliğinden biraz daha açık olacak şekilde çubuğu kavrayın.","Kollarınızı tamamen uzatarak asın, merkez bölgenizi meşgul ve omuzlarınızı aşağıda ve geride tutun.","Kürek kemiklerinizi birbirine sıkıştırıp dirseklerinizi kalçalarınıza doğru iterek vücudunuzu bara doğru yukarı çekin.","Çeneniz çubuğun üstüne çıkana kadar çekmeye devam edin, ardından yavaşça kendinizi başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a una barra de dominadas o a un punto de anclaje resistente.","Pisa la banda y agarra la barra con las palmas mirando hacia afuera, con las manos un poco más separadas que el ancho de los hombros.","Cuélgate con los brazos completamente extendidos, manteniendo el core activado y los hombros abajo y atrás.","Sube el cuerpo hacia la barra juntando los omóplatos y llevando los codos hacia abajo, en dirección a las caderas.","Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ленту к перекладине или прочной точке крепления.","Встаньте на ленту и возьмитесь за перекладину ладонями от себя, руки расставлены чуть шире плеч.","Висите, полностью вытянув руки, удерживая корпус напряженным, а плечи опущенными и отведенными назад.","Подтяните тело к перекладине, сжимая лопатки вместе и направляя локти вниз к бедрам.","Продолжайте тянуть, пока подбородок не окажется над перекладиной, затем медленно опуститесь обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将弹力带固定在上拉杆或坚固的锚点上。","踏上弹力带，手掌背向自己，握住杠铃，双手之间的距离略宽于肩宽。","双臂完全伸展，保持核心收紧，肩膀向下并向后倾斜。","将肩胛骨挤压在一起并将肘部向下推向臀部，将身体向上拉向杠铃杆。","继续拉，直到下巴高于杠铃，然后慢慢降低回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को पुल-अप बार या मजबूत एंकर पॉइंट से जोड़ें।","बैंड पर कदम रखें और अपनी हथेलियों को अपने से दूर रखते हुए बार को पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी बाहों को पूरी तरह फैलाकर लटकें, अपने कोर को व्यस्त रखें और अपने कंधों को नीचे और पीछे रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़कर और अपनी कोहनियों को अपने कूल्हों की ओर ले जाकर अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक कि आपकी ठुड्डी बार के ऊपर न आ जाए, फिर धीरे-धीरे अपने आप को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę oporową do drążka do podciągania lub stabilnego punktu zaczepienia.","Wejdź na taśmę i chwyć drążek dłońmi skierowanymi od siebie, ręce nieco szerzej niż na szerokość barków.","Zwiśnij z rękami w pełni wyprostowanymi, napinając mięśnie brzucha i utrzymując barki w dół i do tyłu.","Podciągnij ciało w kierunku drążka, ściskając łopatki i kierując łokcie w dół w stronę bioder.","Kontynuuj podciąganie, aż broda znajdzie się nad drążkiem, a następnie powoli opuść ciało z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 풀업 바나 견고한 지점에 고정시킵니다.","밴드에 발을 올리고 손바닥이 몸에서 멀어지도록 바를 어깨너비보다 약간 넓게 잡습니다.","팔을 완전히 펼친 상태로 매달리면서 코어를 활성화하고 어깨를 아래로 뒤로 젖힙니다.","어깨뼈를 함께 조이면서 몸을 바 방향으로 당기되 팔꿈치를 골반 방향으로 아래로 밀어냅니다.","턱이 바 위로 올라올 때까지 계속 당긴 후 천천히 시작 위치로 자신을 내려갑니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/0970-r1XNRYB.jpg', 'videos/0970-r1XNRYB.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0971', 'band assisted wheel rollerout', 'waist', 'waist', 'band', '{"en":["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Inginocchiarsi sul pavimento e tenere le maniglie della fascia con entrambe le mani, con i palmi rivolti verso il basso.","Posiziona la fascia a terra davanti a te e posiziona le mani alla larghezza delle spalle.","Coinvolgi il tuo core e fai rotolare lentamente la ruota in avanti, estendendo il corpo il più lontano possibile mantenendo il controllo.","Fermati un attimo nel punto più lontano, quindi ruota lentamente la ruota verso le ginocchia per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Yere diz çökün ve bandın saplarını iki elinizle, avuçlarınız aşağıya bakacak şekilde tutun.","Bandı önünüzde yere koyun ve ellerinizi omuz genişliğinde açın.","Merkez bölgenizi devreye sokun ve tekerleği yavaşça ileri doğru yuvarlayın, kontrolü korurken vücudunuzu mümkün olduğu kadar uzatın.","En uzak noktada bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için tekerleği yavaşça dizlerinize doğru döndürün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Arrodíllate en el suelo y sostén las agarraderas de la banda con ambas manos, con las palmas hacia abajo.","Coloca la banda en el suelo frente a ti y posiciona las manos separadas a la altura de los hombros.","Activa el core y rueda lentamente la rueda hacia adelante, extendiendo el cuerpo lo más que puedas mientras mantienes el control.","Haz una pausa por un momento en el punto más lejano, luego rueda lentamente la rueda de vuelta hacia las rodillas para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте на колени и возьмитесь за ручки ремня обеими руками ладонями вниз.","Положите ленту на пол перед собой и поставьте руки на ширине плеч.","Включите корпус и медленно катите колесо вперед, вытягивая тело как можно дальше, сохраняя при этом контроль.","Сделайте паузу на мгновение в самой дальней точке, затем медленно перекатите колесо обратно к коленям, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["跪在地板上，双手握住弹力带的手柄，手掌朝下。","将弹力带放在您面前的地面上，双手分开与肩同宽。","启动你的核心并缓慢地向前滚动轮子，在保持控制的同时尽可能地伸展你的身体。","在最远点暂停片刻，然后慢慢地将轮子向膝盖方向滚动，回到起始位置。","重复所需的重复次数。"],"hi":["फर्श पर घुटने टेकें और बैंड के हैंडल को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों।","बैंड को अपने सामने ज़मीन पर रखें और अपने हाथों को कंधे की चौड़ाई से अलग रखें।","अपने कोर को संलग्न करें और धीरे-धीरे पहिया को आगे की ओर घुमाएं, नियंत्रण बनाए रखते हुए अपने शरीर को जितना हो सके उतना फैलाएं।","सबसे दूर वाले बिंदु पर एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए धीरे-धीरे पहिये को अपने घुटनों की ओर घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Uklęknij na podłodze i chwyć uchwyty taśmy obiema rękami, dłońmi skierowanymi w dół.","Umieść taśmę na podłodze przed sobą i ustaw dłonie na szerokość barków.","Napnij mięśnie brzucha i powoli wypychaj koło do przodu, wyciągając ciało tak daleko, jak to możliwe, zachowując kontrolę.","Zatrzymaj się na chwilę w najdalszym punkcie, a następnie powoli przyciągnij koło z powrotem w kierunku kolan, wracając do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["바닥에 무릎을 꿇고 밴드의 손잡이를 양손으로 잡아 손바닥이 아래를 향하게 합니다.","밴드를 앞에 놓고 손을 어깨너비로 벌립니다.","코어를 활성화하고 휠을 천천히 앞으로 굴리면서 통제를 유지하며 몸을 최대한 펼칩니다.","가장 먼 지점에서 잠깐 멈춘 후 휠을 천천히 무릎 방향으로 굴려 시작 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'lower back', '["lower back"]', 'abs', 'images/0971-zhF9lW4.jpg', 'videos/0971-zhF9lW4.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1254', 'band bench press', 'chest', 'chest', 'band', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare le maniglie della fascia con una presa prona, leggermente più larghe della larghezza delle spalle.","Estendi completamente le braccia, allontanando le fasce dal petto.","Abbassa lentamente le fasce fino al petto, mantenendo i gomiti ad un angolo di 90 gradi.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Bandın saplarını omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Bantları göğsünüzden uzağa doğru iterek kollarınızı tamamen uzatın.","Dirseklerinizi 90 derecelik bir açıda tutarak bantları yavaşça göğsünüze doğru indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.","Extiende los brazos por completo, empujando las bandas alejándolas del pecho.","Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмитесь за рукоятки ленты верхним хватом, на расстоянии чуть шире плеч.","Полностью выпрямите руки, отталкивая ленты от груди.","Медленно опустите ленты обратно к груди, держа локти под углом 90 градусов.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住带子手柄，间距略宽于肩宽。","充分伸展双臂，将弹力带推离胸部。","慢慢将弹力带放回到胸部，保持肘部呈 90 度角。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बैंड के हैंडल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","अपनी बाहों को पूरी तरह फैलाएं, बैंड को अपनी छाती से दूर धकेलें।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, बैंड को धीरे-धीरे वापस अपनी छाती तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy płasko na podłodze, a plecy oparte o ławkę.","Chwyć uchwyty taśmy nachwytem, nieco szerzej niż na szerokość barków.","Wyprostuj ramiona w pełni, wypychając taśmę od klatki piersiowej.","Powoli opuść taśmę z powrotem do klatki piersiowej, utrzymując łokcie pod kątem 90 stopni.","Powtórz zalecaną liczbę razy."],"ko":["벤치에 누워 발을 바닥에 평평하게 놓고 등을 벤치에 붙입니다.","손바닥이 앞을 향하도록 밴드 손잡이를 어깨너비보다 약간 넓게 잡습니다.","팔을 완전히 펼쳐 밴드를 가슴에서 멀어지게 밀어냅니다.","밴드를 천천히 다시 가슴으로 내려 팔꿈치가 90도 각도가 되도록 합니다.","원하는 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/1254-khlHMqs.jpg', 'videos/1254-khlHMqs.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0980', 'band bent-over hip extension', 'upper legs', 'upper legs', 'band', '{"en":["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."],"it":["Attaccare la fascia a un punto di ancoraggio robusto all''altezza della caviglia.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Fai un passo indietro per creare tensione nella fascia, mantenendo le ginocchia leggermente piegate.","Piegati sui fianchi e inclinati in avanti, mantenendo la colonna vertebrale neutra.","Estendi la gamba destra all''indietro, contraendo i glutei in alto.","Abbassa di nuovo la gamba destra e ripeti con la gamba sinistra.","Continua ad alternare le gambe per il numero di ripetizioni desiderato."],"tr":["Bandı ayak bileği yüksekliğinde sağlam bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde, bağlantı noktasından uzağa bakacak şekilde durun.","Dizlerinizi hafifçe bükerek bantta gerginlik yaratmak için geri adım atın.","Kalçalarınızı menteşeleyin ve nötr bir omurgayı koruyarak öne doğru eğin.","Sağ bacağınızı düz bir şekilde geriye doğru uzatın ve üst kısımda kalça kaslarınızı sıkıştırın.","Sağ bacağınızı geriye doğru indirin ve hareketi sol bacakla tekrarlayın.","İstenilen sayıda tekrar için bacakları değiştirerek devam edin."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura del tobillo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas e inclínate hacia adelante, manteniendo la columna en posición neutral.","Extiende la pierna derecha recta hacia atrás, apretando los glúteos en la parte superior.","Baja la pierna derecha de vuelta y repite con la pierna izquierda.","Continúa alternando las piernas durante el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте лодыжки.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Сделайте шаг назад, чтобы создать напряжение в ленте, держа колени слегка согнутыми.","Наклонитесь вперед и наклонитесь вперед, сохраняя нейтральное положение позвоночника.","Вытяните правую ногу прямо назад, сжимая ягодицы вверху.","Опустите правую ногу обратно и повторите то же самое с левой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"zh":["将带子固定在脚踝高度的坚固锚点上。","背对锚点站立，双脚与肩同宽。","向后退一步，在弹力带上产生张力，保持膝盖稍微弯曲。","铰接臀部并向前倾斜，保持脊柱中立。","将右腿向后伸直，在顶部挤压臀部。","将右腿放回原位，然后换左腿重复此动作。","继续交替双腿达到所需的重复次数。"],"hi":["बैंड को टखने की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","बैंड में तनाव पैदा करने के लिए अपने घुटनों को थोड़ा मोड़कर पीछे हटें।","कूल्हों पर टिकाएं और तटस्थ रीढ़ बनाए रखते हुए आगे की ओर झुकें।","अपने दाहिने पैर को सीधा पीछे की ओर फैलाएँ, अपने ग्लूट्स को ऊपर की ओर दबाएँ।","अपने दाहिने पैर को वापस नीचे लाएँ और बाएँ पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości kostki.","Stań tyłem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Zrób krok do tyłu, aby wytworzyć napięcie w taśmie, utrzymując kolana lekko ugięte.","Pochyl się w biodrach do przodu, utrzymując neutralną pozycję kręgosłupa.","Wyprostuj prawą nogę prosto do tyłu, ściskając pośladki w górnej fazie ruchu.","Opuść prawą nogę i powtórz lewą nogą.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["밴드를 발목 높이의 견고한 지점에 고정시킵니다.","지점에서 멀어지는 방향을 향하고 발을 어깨너비로 벌리고 섭니다.","뒤로 물러나 밴드에 장력을 만들되 무릎을 약간 구부립니다.","엉덩이에서 힌지하고 중립 척추를 유지하며 앞으로 숙입니다.","오른쪽 다리를 곧게 뒤로 펼치면서 엉덩이를 꽉 조입니다.","오른쪽 다리를 내린 후 왼쪽 다리로 반복합니다.","원하는 횟수만큼 다리를 교대로 계속합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0980-wSScovH.jpg', 'videos/0980-wSScovH.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0972', 'band bicycle crunch', 'waist', 'waist', 'band', '{"en":["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le mani dietro la testa e le ginocchia piegate.","Solleva i piedi da terra e porta il ginocchio destro verso il petto mentre contemporaneamente ruota il busto per portare il gomito sinistro verso il ginocchio destro.","Raddrizza la gamba destra portando il ginocchio sinistro verso il petto e ruotando il busto per portare il gomito destro verso il ginocchio sinistro.","Continua ad alternare il movimento di torsione, come se stessi pedalando su una bicicletta, mantenendo il core impegnato durante tutto il movimento.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Elleriniz başınızın arkasında ve dizleriniz bükülü olacak şekilde sırt üstü yatın.","Ayaklarınızı yerden kaldırın ve sağ dizinizi göğsünüze doğru getirin, aynı anda gövdenizi bükerek sol dirseğinizi sağ dizinize doğru getirin.","Sol dizinizi göğsünüze doğru getirirken sağ bacağınızı düzleştirin ve sağ dirseğinizi sol dizinize doğru getirmek için gövdenizi bükün.","Hareket boyunca merkez bölgenizi meşgul ederken, bisiklet pedalı çeviriyormuş gibi bükme hareketini dönüşümlü olarak yapmaya devam edin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las manos detrás de la cabeza y las rodillas flexionadas.","Levanta los pies del suelo y lleva la rodilla derecha hacia el pecho mientras simultáneamente giras el torso para llevar el codo izquierdo hacia la rodilla derecha.","Estira la pierna derecha mientras llevas la rodilla izquierda hacia el pecho y giras el torso para llevar el codo derecho hacia la rodilla izquierda.","Continúa alternando el movimiento de giro, como si estuvieras pedaleando una bicicleta, manteniendo el core activado durante todo el movimiento.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, заведите руки за голову и согните колени.","Поднимите ноги от земли и поднесите правое колено к груди, одновременно поворачивая туловище, чтобы поднести левый локоть к правому колену.","Выпрямите правую ногу, одновременно подтягивая левое колено к груди и поворачивая туловище так, чтобы правый локоть приблизился к левому колену.","Продолжайте чередовать скручивающие движения, как если бы вы крутили педали на велосипеде, сохраняя при этом корпус задействованным на протяжении всего движения.","Повторите необходимое количество повторений."],"zh":["平躺，双手放在脑后，膝盖弯曲。","将脚抬离地面，将右膝盖靠近胸部，同时扭转躯干，将左肘靠近右膝盖。","伸直右腿，同时将左膝靠近胸部，并扭转躯干，使右肘靠近左膝。","继续交替扭转运动，就像踩自行车一样，同时在整个运动过程中保持核心参与。","重复所需的重复次数。"],"hi":["अपने हाथों को अपने सिर के पीछे रखते हुए और अपने घुटनों को मोड़कर अपनी पीठ के बल सीधे लेट जाएँ।","अपने पैरों को जमीन से ऊपर उठाएं और अपने दाहिने घुटने को अपनी छाती की ओर लाएं, साथ ही अपने धड़ को मोड़कर अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाएं।","अपने बाएं घुटने को अपनी छाती की ओर लाते हुए अपने दाहिने पैर को सीधा करें और अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाने के लिए अपने धड़ को मोड़ें।","घुमाव की गति को बारी-बारी से जारी रखें, जैसे कि आप साइकिल को पैडल चला रहे हों, जबकि पूरे आंदोलन के दौरान अपने कोर को व्यस्त रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach, dłonie za głową, kolana ugięte.","Unieś stopy nad podłogę i przyciągnij prawe kolano w kierunku klatki piersiowej, jednocześnie skręcając tułów, aby przyciągnąć lewy łokieć do prawego kolana.","Wyprostuj prawą nogę, przyciągając lewe kolano w kierunku klatki piersiowej i skręcając tułów, aby przyciągnąć prawy łokieć do lewego kolana.","Kontynuuj naprzemienny ruch skrętny, przypominający pedałowanie na rowerze, utrzymując napięty brzuch przez cały czas trwania ćwiczenia.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 펴고 누워 양손을 머리 뒤에 놓고 무릎을 구부립니다.","발을 바닥에서 들어올리고 오른쪽 무릎을 가슴 방향으로 당기면서 동시에 몸을 비틀어 왼쪽 팔꿈치가 오른쪽 무릎을 향하게 합니다.","오른쪽 다리를 펼치면서 왼쪽 무릎을 가슴 방향으로 당기고 동시에 몸을 비틀어 오른쪽 팔꿈치가 왼쪽 무릎을 향하게 합니다.","자전거를 타는 것처럼 비틀는 동작을 계속하면서 전체 운동 동안 코어를 활성화합니다.","원하는 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors","obliques"]', 'abs', 'images/0972-tZkGYZ9.jpg', 'videos/0972-tZkGYZ9.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0974', 'band close-grip pulldown', 'back', 'back', 'band', '{"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio alto, come una barra per trazioni o una trave robusta.","Mettiti di fronte al punto di ancoraggio e afferra la fascia con una presa subdola, con le mani alla larghezza delle spalle.","Fai un passo indietro per creare tensione nella fascia, mantenendo i piedi alla larghezza dei fianchi.","Coinvolgi il tuo core e mantieni la schiena dritta mentre tiri la fascia verso il petto, stringendo insieme le scapole.","Fermati per un momento alla fine del movimento, quindi rilascia lentamente la fascia nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı, çekme çubuğu veya sağlam kiriş gibi yüksek bir bağlantı noktasına takın.","Bağlantı noktasına dönük durun ve bandı alttan kavrayarak, eller omuz genişliğinde açık olacak şekilde tutun.","Ayaklarınızı kalça genişliğinde açık tutarak bantta gerginlik yaratmak için geri adım atın.","Bandı göğsünüze doğru çekerken merkez bölgenizi devreye sokun ve sırtınızı düz tutun, kürek kemiklerinizi birbirine sıkıştırın.","Hareketin alt noktasında bir an duraklayın, ardından bandı yavaşça başlangıç ​​pozisyonuna geri bırakın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje y agarra la banda con un agarre supino, con las manos separadas a la altura de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los pies separados a la altura de las caderas.","Activa el core y mantén la espalda recta mientras tiras de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ленту к высокой точке крепления, например к перекладине или прочной балке.","Встаньте лицом к точке крепления и возьмитесь за ленту хватом снизу, руки на ширине плеч.","Сделайте шаг назад, чтобы создать натяжение ленты, держа ноги на ширине плеч.","Напрягите корпус и держите спину прямо, тянув ленту к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно отпустите ленту обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，用反手抓住弹力带，双手与肩同宽。","后退一步，在弹力带上产生张力，双脚分开与臀部同宽。","当你将弹力带向下拉向胸部时，收紧你的核心并保持背部挺直，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को किसी ऊंचे एंकर बिंदु, जैसे पुल-अप बार या मजबूत बीम से जोड़ें।","एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं और हाथों को कंधे की चौड़ाई से अलग रखते हुए बैंड को अंडरहैंड ग्रिप से पकड़ें।","अपने पैरों को कूल्हे की चौड़ाई से अलग रखते हुए, बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखें क्योंकि आप बैंड को अपनी छाती की ओर खींचते हैं, अपने कंधे के ब्लेड को एक साथ निचोड़ते हैं।","आंदोलन के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do wysokiego punktu zaczepienia, takiego jak drążek do podciągania lub stabilna belka.","Stań przodem do punktu zaczepienia i chwyć taśmę podchwytem, dłonie na szerokość barków.","Zrób krok do tyłu, aby wytworzyć napięcie w taśmie, utrzymując stopy w rozkroku na szerokość bioder.","Napnij mięśnie brzucha i utrzymuj proste plecy, ściągając taśmę w dół w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę w dolnej fazie ruchu, a następnie powoli uwolnij taśmę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 풀업 바나 견고한 들보 같은 높은 지점에 고정시킵니다.","고정 지점을 마주보고 선 후 손바닥이 몸을 향하도록 밴드를 어깨너비로 언더핸드 그립으로 잡습니다.","발 너비를 엉덩이너비로 벌리고 뒤로 물러나 밴드에 장력을 만듭니다.","코어를 활성화하고 등을 펴며 밴드를 가슴 방향으로 아래로 당기면서 어깨뼈를 함께 조입니다.","동작의 맨 아래에서 잠깐 멈춘 후 천천히 밴드를 시작 위치로 놓습니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/0974-DptumMx.jpg', 'videos/0974-DptumMx.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0975', 'band close-grip push-up', 'upper arms', 'upper arms', 'band', '{"en":["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."],"it":["Posiziona una fascia attorno alla parte superiore delle braccia, appena sopra i gomiti.","Assumi una posizione di push-up con le mani direttamente sotto le spalle e il corpo in linea retta dalla testa ai talloni.","Piega i gomiti e abbassa il petto verso terra, mantenendo i gomiti vicini ai fianchi.","Spingi attraverso i palmi delle mani per estendere le braccia e tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Üst kollarınızın etrafına, dirseklerin hemen üstüne bir bant yerleştirin.","Elleriniz doğrudan omuzlarınızın altında ve vücudunuz baştan topuklara kadar düz bir çizgide olacak şekilde şınav pozisyonu alın.","Dirseklerinizi bükün ve göğsünüzü yere doğru indirin, dirseklerinizi yanlarınıza yakın tutun.","Kollarınızı uzatmak ve başlangıç ​​pozisyonuna dönmek için avuçlarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.","Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.","Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.","Empuja con las palmas para extender los brazos y regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Наденьте ленту на плечи чуть выше локтей.","Примите позу для отжимания, положив руки прямо под плечи, а тело образуя прямую линию от головы до пяток.","Согните локти и опустите грудь к земле, держа локти близко к бокам.","Оттолкнитесь ладонями, чтобы вытянуть руки и вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["将一条带子绕在你的上臂上，就在肘部上方。","采取俯卧撑姿势，双手直接放在肩膀下方，身体从头到脚跟呈一条直线。","弯曲肘部，将胸部降低到地面，保持肘部靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"],"hi":["अपनी ऊपरी भुजाओं के चारों ओर, कोहनियों के ठीक ऊपर एक बैंड रखें।","अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को सिर से एड़ी तक एक सीधी रेखा में रखते हुए पुश-अप स्थिति लें।","अपनी कोहनियों को मोड़ें और अपनी छाती को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Umieść taśmę na ramionach, tuż nad łokciami.","Ustaw się w pozycji pompki, dłonie dokładnie pod barkami, a ciało tworzy prostą linię od głowy do pięt.","Ugnij łokcie i opuść klatkę piersiową w kierunku podłogi, trzymając łokcie blisko boków ciała.","Odepchnij się dłońmi, prostując ramiona i wracając do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["팔 위쪽, 팔꿈치 바로 위에 밴드를 감습니다.","손이 어깨 바로 아래에 있고 머리에서 발까지 일직선을 이루도록 푸시업 자세를 취합니다.","팔꿈치를 구부리고 가슴을 지면을 향해 내리되 팔꿈치를 몸 옆에 가깝게 유지합니다.","손바닥으로 밀어 팔을 펴고 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0975-ufaxB52.jpg', 'videos/0975-ufaxB52.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0976', 'band concentration curl', 'upper arms', 'upper arms', 'band', '{"en":["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"it":["Siediti su una panca o una sedia con le gambe divaricate e i piedi appoggiati a terra.","Tieni un''estremità della fascia in mano e cammina sull''altra estremità con il piede sullo stesso lato.","Piegati leggermente in avanti e appoggia il gomito all''interno della coscia, appena sopra il ginocchio.","Con il palmo rivolto verso l''alto, piega lentamente la mano verso la spalla, mantenendo ferma la parte superiore del braccio.","Fermati per un momento in alto, quindi abbassa lentamente la mano nella posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi cambia lato."],"tr":["Bacaklarınız iki yana açık ve ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun.","Bandın bir ucunu elinizde tutun ve ayağınız aynı tarafta olacak şekilde diğer ucuna basın.","Hafifçe öne doğru eğilin ve dirseğinizi uyluğunuzun iç kısmına, dizin hemen üstüne koyun.","Avucunuz yukarı bakacak şekilde, üst kolunuzu sabit tutarak elinizi yavaşça omzunuza doğru kıvırın.","Tepe noktasında bir an duraklayın, ardından elinizi yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Siéntate en un banco o silla con las piernas separadas y los pies apoyados en el suelo.","Sostén un extremo de la banda en la mano y pisa el otro extremo con el pie del mismo lado.","Inclínate ligeramente hacia adelante y apoya el codo en la parte interna del muslo, justo encima de la rodilla.","Con la palma hacia arriba, flexiona lentamente la mano hacia el hombro, manteniendo quieta la parte superior del brazo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la mano de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Сядьте на скамью или стул, раздвинув ноги и поставив ступни на землю.","Возьмите один конец ленты в руку и наступите на другой конец ногой с той же стороны.","Слегка наклонитесь вперед и положите локоть на внутреннюю часть бедра, чуть выше колена.","Повернув ладонь вверх, медленно согните руку к плечу, сохраняя плечо неподвижным.","Задержитесь на мгновение в верхней точке, затем медленно опустите руку обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["坐在长凳或椅子上，双腿分开，双脚平放在地上。","用手握住带子的一端，用脚踩在另一端上，同时将脚放在同一侧。","稍微向前倾，将肘部放在大腿内侧，膝盖上方。","手掌朝上，慢慢地将手向肩膀弯曲，保持上臂静止。","在顶部暂停片刻，然后慢慢将手放回起始位置。","重复所需的重复次数，然后换边。"],"hi":["अपने पैरों को फैलाकर एक बेंच या कुर्सी पर बैठें और आपके पैर जमीन पर सपाट हों।","बैंड के एक सिरे को अपने हाथ में पकड़ें और अपने पैर को उसी तरफ रखते हुए दूसरे सिरे पर कदम रखें।","थोड़ा आगे झुकें और अपनी कोहनी को घुटने के ठीक ऊपर, अपनी जांघ के अंदर पर टिकाएं।","अपनी हथेली को ऊपर की ओर रखते हुए, धीरे-धीरे अपने हाथ को अपने कंधे की ओर मोड़ें, अपनी ऊपरी भुजा को स्थिर रखें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Usiądź na ławce lub krześle z nogami rozstawionymi i stopami płasko na podłodze.","Trzymaj jeden koniec taśmy w dłoni i stań stopą po tej samej stronie na drugim końcu.","Pochyl się lekko do przodu i oprzyj łokieć na wewnętrznej stronie uda, tuż nad kolanem.","Dłonią skierowaną do góry powoli uginaj rękę w kierunku barku, utrzymując ramię nieruchome.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść rękę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień stronę."],"ko":["벤치나 의자에 앉아 다리를 벌리고 발을 바닥에 붙입니다.","밴드의 한쪽 끝을 손으로 잡고 다른 쪽 끝을 같은 쪽 발로 밟습니다.","살짝 앞으로 기울이고 팔꿈치를 무릎 바로 위 넓적다리 안쪽에 놓습니다.","손바닥이 위를 향하게 하여 천천히 손을 어깨 쪽으로 말아올리되 위팔은 고정한 상태를 유지합니다.","꼭짓점에서 잠깐 멈춘 후 천천히 손을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복한 후 반대쪽으로 바꿉니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0976-kmVVAfu.jpg', 'videos/0976-kmVVAfu.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3117', 'band fixed back close grip pulldown', 'back', 'back', 'band', '{"en":["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto fisso sopra di te, come una barra per trazioni o una trave robusta.","Siediti su una panca o una sedia di fronte alla fascia, con i piedi appoggiati a terra e le ginocchia piegate.","Afferra la fascia con una presa salda, i palmi rivolti verso di te.","Tieni la schiena dritta e coinvolgi il core.","Tirare la fascia verso il petto, stringendo insieme le scapole.","Fermati per un momento alla fine del movimento, sentendo la contrazione dei dorsali.","Rilascia lentamente la fascia nella posizione iniziale, mantenendo il controllo durante tutto il movimento.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı, çekme çubuğu veya sağlam kiriş gibi üstünüzdeki sabit bir noktaya takın.","Ayaklarınız yere düz basacak ve dizleriniz bükülü olacak şekilde banda dönük bir bank veya sandalyeye oturun.","Bandı, avuçlarınız size doğru bakacak şekilde sıkı bir kavrama ile kavrayın.","Sırtınızı düz tutun ve çekirdeğinizi meşgul edin.","Bandı göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Hareketin alt noktasında bir anlığına duraklayın ve latlarınızdaki kasılmayı hissedin.","Hareket boyunca kontrolü koruyarak bandı yavaşça başlangıç ​​pozisyonuna geri bırakın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto fijo por encima de ti, como una barra de dominadas o una viga resistente.","Siéntate en un banco o silla frente a la banda, con los pies apoyados en el suelo y las rodillas flexionadas.","Agarra la banda con un agarre cerrado, con las palmas hacia ti.","Mantén la espalda recta y activa el core.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la banda de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ленту к фиксированной точке над вами, например, к перекладине или прочной балке.","Сядьте на скамью или стул лицом к ленте, поставьте ступни на землю и согните колени.","Возьмитесь за ленту крепким хватом ладонями к себе.","Держите спину прямо и задействуйте корпус.","Потяните ленту вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно отпустите ленту обратно в исходное положение, сохраняя контроль на протяжении всего движения.","Повторите необходимое количество повторений."],"zh":["将弹力带固定在您上方的固定点上，例如上拉杆或坚固的横梁。","坐在面向乐队的长凳或椅子上，双脚平放在地上，膝盖弯曲。","紧紧握住弹力带，手掌朝向您。","保持背部挺直并启动核心肌群。","将弹力带向下拉向胸部，将肩胛骨挤压在一起。","在动作的底部暂停片刻，感受背阔肌的收缩。","慢慢地将弹力带释放回起始位置，在整个运动过程中保持控制。","重复所需的重复次数。"],"hi":["बैंड को अपने ऊपर एक निश्चित बिंदु पर संलग्न करें, जैसे कि पुल-अप बार या मजबूत बीम।","बैंड के सामने एक बेंच या कुर्सी पर बैठें, आपके पैर ज़मीन पर सपाट हों और आपके घुटने मुड़े हुए हों।","बैंड को ज़ोर से पकड़ें, हथेलियाँ आपकी ओर हों।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, बैंड को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग में एक पल के लिए रुकें, अपने लैट्स में संकुचन महसूस करें।","पूरे आंदोलन पर नियंत्रण बनाए रखते हुए, बैंड को धीरे-धीरे प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do stałego punktu nad sobą, takiego jak drążek do podciągania lub stabilna belka.","Usiądź na ławce lub krześle przodem do taśmy, stopy płasko na podłodze, a kolana ugięte.","Chwyć taśmę wąskim chwytem, dłońmi skierowanymi do siebie.","Utrzymuj proste plecy i napnij mięśnie brzucha.","Ściągnij taśmę w dół w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę w dolnej fazie ruchu, odczuwając napięcie w mięśniach najszerszych grzbietu.","Powoli uwolnij taśmę z powrotem do pozycji wyjściowej, zachowując kontrolę przez cały ruch.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 풀업바나 견고한 빔과 같이 머리 위의 고정된 지점에 부착합니다.","벤치나 의자에 앉아 밴드를 마주보고 발을 바닥에 붙이며 무릎을 구부립니다.","밴드를 좁은 손거리로 잡되 손바닥이 자신을 향하게 합니다.","등을 곧게 펼치고 복부에 힘을 줍니다.","밴드를 가슴 쪽으로 당기며 견갑골을 함께 짜냅니다.","동작의 아래쪽에서 잠깐 멈춰 등 근육의 수축을 느낍니다.","천천히 밴드를 시작 자세로 돌려놓되 전체 동작을 통해 제어를 유지합니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/3117-4LoWllp.jpg', 'videos/3117-4LoWllp.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3116', 'band fixed back underhand pulldown', 'back', 'back', 'band', '{"en":["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio robusto sopra la testa.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Afferrare la fascia con una presa subdola, con le mani leggermente più larghe della larghezza delle spalle.","Fai un passo indietro per creare tensione nella fascia, mantenendo le braccia completamente distese.","Coinvolgi il tuo core e stringi insieme le scapole.","Tirare la fascia verso il petto, portandola con i gomiti.","Fermati per un momento alla fine del movimento, sentendo la contrazione dei dorsali.","Rilascia lentamente la tensione della fascia e torna alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı başınızın üzerindeki sağlam bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde bağlantı noktasına bakacak şekilde durun.","Bandı alttan kavrayın, eller omuz genişliğinden biraz daha açık olsun.","Kollarınızı tamamen uzatarak bantta gerginlik yaratmak için geri adım atın.","Merkez bölgenizi devreye sokun ve kürek kemiklerinizi birbirine doğru sıkın.","Bandı dirseklerinizle birlikte göğsünüze doğru çekin.","Hareketin alt noktasında bir anlığına duraklayın ve latlarınızdaki kasılmayı hissedin.","Banttaki gerilimi yavaşça bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Da un paso atrás para generar tensión en la banda, manteniendo los brazos completamente extendidos.","Activa el core y junta los omóplatos.","Tira de la banda hacia el pecho, guiando el movimiento con los codos.","Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales.","Suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления над головой.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Возьмите ленту обратным хватом снизу, руки на расстоянии чуть шире плеч.","Сделайте шаг назад, чтобы создать напряжение в ленте, держа руки полностью выпрямленными.","Напрягите корпус и сведите лопатки вместе.","Потяните ленту вниз к груди, ведя локтями.","Сделайте паузу на мгновение в нижней части движения, чувствуя сокращение широчайших мышц.","Медленно ослабьте натяжение ленты и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将带子固定在头顶上方坚固的锚点上。","面向锚点站立，双脚分开与肩同宽。","反手握住弹力带，双手间距略宽于肩宽。","后退一步，在弹力带上产生张力，保持手臂完全伸展。","启动你的核心并将肩胛骨挤压在一起。","将弹力带向下拉向胸部，用肘部引导。","在动作的底部暂停片刻，感受背阔肌的收缩。","慢慢释放带子的张力并返回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को अपने सिर के ऊपर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी बाहों को पूरी तरह फैलाए रखते हुए बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने कोर को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ें।","बैंड को अपनी कोहनियों से आगे बढ़ाते हुए अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग में एक पल के लिए रुकें, अपने लैट्स में संकुचन महसूस करें।","धीरे-धीरे बैंड में तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia nad głową.","Stań przodem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Chwyć taśmę podchwytem, dłonie nieco szerzej niż na szerokość barków.","Zrób krok do tyłu, aby wytworzyć napięcie w taśmie, utrzymując ramiona w pełni wyprostowane.","Napnij mięśnie brzucha i ściśnij łopatki razem.","Ściągnij taśmę w dół w kierunku klatki piersiowej, prowadząc ruch łokciami.","Zatrzymaj się na chwilę w dolnej fazie ruchu, odczuwając napięcie w mięśniach najszerszych grzbietu.","Powoli zwolnij napięcie taśmy i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 머리 위의 견고한 고정점에 부착합니다.","고정점을 향해 서되 발을 어깨너비로 벌립니다.","밴드를 역손 그립으로 잡되 손이 어깨너비보다 조금 넓게 떨어져 있습니다.","뒤로 물러나 밴드에 긴장을 만들되 팔은 완전히 펼친 상태를 유지합니다.","복부에 힘을 주고 견갑골을 함께 짜냅니다.","팔꿈치를 앞으로 내밀며 밴드를 가슴 쪽으로 당깁니다.","동작의 아래쪽에서 잠깐 멈춰 등 근육의 수축을 느낍니다.","천천히 밴드의 긴장을 풀고 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","rhomboids","rear deltoids"]', 'lats', 'images/3116-ZH68exZ.jpg', 'videos/3116-ZH68exZ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0977', 'band front lateral raise', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere la fascia davanti alle cosce con i palmi rivolti verso il basso.","Tieni le braccia tese e solleva la fascia davanti a te finché le braccia non sono parallele al suolo.","Fai una pausa per un momento in alto, quindi abbassa lentamente la fascia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı avuçlarınız aşağıya bakacak şekilde uyluklarınızın önünde tutun.","Kollarınızı düz tutun ve kollarınız yere paralel oluncaya kadar bandı önünüze doğru kaldırın.","Üst noktada bir an duraklayın, ardından bandı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, держите ленту перед бедрами ладонями вниз.","Держите руки прямо и поднимите ленту перед собой, пока руки не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите ленту обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。","保持双臂伸直，将弹力带举到身前，直到双臂与地面平行。","在顶部暂停片刻，然后慢慢将弹力带放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को नीचे की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और बैंड को अपने सामने तब तक ऊपर उठाएं जब तक कि आपकी भुजाएं जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj taśmę przed udami, dłońmi skierowanymi w dół.","Utrzymuj ramiona proste i unieś taśmę przed sobą, aż ramiona będą równoległe do podłogi.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść taśmę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 서서 밴드를 넓적다리 앞에 들되 손바닥이 아래를 향하게 합니다.","팔을 곧게 펼친 상태로 밴드를 앞으로 들어올려 팔이 지면과 평행하게 만듭니다.","꼭짓점에서 잠깐 멈춘 후 천천히 밴드를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'traps', '["traps","upper back"]', 'delts', 'images/0977-sTg7iys.jpg', 'videos/0977-sTg7iys.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0978', 'band front raise', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere la fascia davanti alle cosce con i palmi rivolti verso il basso.","Tieni le braccia tese e sollevale lentamente in avanti finché non sono parallele al suolo.","Fai una pausa per un momento in alto, quindi abbassa lentamente le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı avuçlarınız aşağıya bakacak şekilde uyluklarınızın önünde tutun.","Kollarınızı düz tutun ve yere paralel oluncaya kadar yavaşça öne doğru kaldırın.","Tepe noktasında bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.","Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, держите ленту перед бедрами ладонями вниз.","Держите руки прямо и медленно поднимите их вперед, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝下。","保持手臂伸直，慢慢向前举起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को नीचे की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और धीरे-धीरे उन्हें आगे की ओर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj taśmę przed udami, dłońmi skierowanymi w dół.","Utrzymuj ramiona proste i powoli unoś je do przodu, aż będą równoległe do podłogi.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść ramiona z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 서서 밴드를 넓적다리 앞에 들되 손바닥이 아래를 향하게 합니다.","팔을 곧게 펼친 상태로 천천히 팔을 앞으로 올려 지면과 평행하게 만듭니다.","꼭짓점에서 잠깐 멈춘 후 천천히 팔을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/0978-TFA88iB.jpg', 'videos/0978-TFA88iB.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1408', 'band hip lift', 'upper legs', 'upper legs', 'band', '{"en":["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Posiziona una fascia di resistenza appena sopra le ginocchia.","Coinvolgi i tuoi glutei e i muscoli centrali.","Premi i talloni a terra e solleva i fianchi dal pavimento, contraendo i glutei nella parte superiore.","Fai una pausa per un momento in alto, quindi abbassa lentamente i fianchi fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Dizlerinizin hemen üstüne bir direnç bandı yerleştirin.","Kalçalarınızı ve göbek kaslarınızı çalıştırın.","Topuklarınızı yere bastırın ve kalçalarınızı yerden kaldırın, üst kısımda kalça kaslarınızı sıkın.","Tepe noktasında bir an duraklayın, ardından kalçalarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Coloca una banda elástica justo por encima de las rodillas.","Activa los glúteos y los músculos del core.","Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, согните колени и поставьте ступни на землю.","Поместите ленту сопротивления чуть выше колен.","Задействуйте ягодицы и мышцы корпуса.","Прижмите пятки к земле и поднимите бедра от пола, сжимая ягодицы в верхней части.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["仰卧，膝盖弯曲，双脚平放在地上。","将阻力带放在膝盖上方。","调动你的臀肌和核心肌肉。","将脚后跟压入地面，将臀部抬离地板，在顶部挤压臀部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेटें।","अपने घुटनों के ठीक ऊपर एक प्रतिरोध बैंड रखें।","अपने ग्लूट्स और कोर मांसपेशियों को संलग्न करें।","अपनी एड़ियों को ज़मीन पर दबाएँ और अपने कूल्हों को ज़मीन से ऊपर उठाएँ, अपने ग्लूट्स को ऊपर की ओर दबाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na plecach z ugiętymi kolanami i stopami płasko na podłodze.","Umieść taśmę oporową tuż nad kolanami.","Napnij pośladki i mięśnie brzucha.","Wciśnij pięty w podłogę i unieś biodra nad podłogę, ściskając pośladki w górnej fazie ruchu.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść biodra z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 대고 누워 무릎을 구부리고 발을 바닥에 붙입니다.","저항 밴드를 무릎 바로 위에 놓습니다.","엉덩이와 복부 근육에 힘을 줍니다.","발뒤꿈치를 바닥에 눌러 엉덩이를 떨어뜨려 올리되 꼭짓점에서 엉덩이 근육을 짜냅니다.","꼭짓점에서 잠깐 멈춘 후 천천히 엉덩이를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","quadriceps"]', 'glutes', 'images/1408-E4R8Hz1.jpg', 'videos/1408-E4R8Hz1.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0979', 'band horizontal pallof press', 'waist', 'waist', 'band', '{"en":["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio robusto all''altezza della vita.","Stai perpendicolare al punto di ancoraggio con i piedi alla larghezza delle spalle.","Afferrare la maniglia della fascia con entrambe le mani e allontanarsi dal punto di ancoraggio per creare tensione nella fascia.","Porta le mani al petto, mantenendo i gomiti piegati e vicini al corpo.","Coinvolgi il tuo core e mantieni una posizione stabile.","Estendi le braccia davanti a te, allontanando la fascia dal corpo.","Mantieni la posizione estesa per alcuni secondi, concentrandoti sul mantenimento della tensione nel core.","Riporta lentamente le mani al petto, resistendo alla trazione della fascia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı bel yüksekliğinde sağlam bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde bağlantı noktasına dik durun.","Bandın sapını iki elinizle kavrayın ve bantta gerginlik yaratmak için bağlantı noktasından uzaklaşın.","Ellerinizi göğsünüze getirin, dirseklerinizi bükülü ve vücudunuza yakın tutun.","Merkez bölgenizi harekete geçirin ve istikrarlı bir duruş sergileyin.","Kollarınızı düz bir şekilde önünüze doğru uzatın ve bandı vücudunuzdan uzaklaştırın.","Merkez bölgenizdeki gerilimi korumaya odaklanarak uzatılmış pozisyonu birkaç saniye basılı tutun.","Bandın çekilmesine direnerek ellerinizi yavaşça göğsünüze getirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie perpendicular al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la agarradera de la banda con ambas manos y aléjate del punto de anclaje para generar tensión en la banda.","Lleva las manos hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el core y mantén una postura estable.","Extiende los brazos rectos frente a ti, empujando la banda alejándola del cuerpo.","Mantén la posición extendida durante unos segundos, enfocándote en mantener la tensión en el core.","Lleva lentamente las manos de vuelta al pecho, resistiendo el tirón de la banda.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте перпендикулярно точке крепления, поставив ноги на ширине плеч.","Возьмитесь за ручку ленты обеими руками и отойдите от точки крепления, чтобы создать натяжение ленты.","Поднесите руки к груди, держа локти согнутыми и близко к телу.","напрягите мышцы кора ​​и сохраняйте устойчивую позицию.","Вытяните руки прямо перед собой, отталкивая ленту от тела.","Удерживайте вытянутое положение в течение нескольких секунд, сосредотачиваясь на поддержании напряжения в корпусе.","Медленно верните руки к груди, сопротивляясь натяжению ленты.","Повторите необходимое количество повторений."],"zh":["将带子固定在腰部高度的坚固锚点上。","垂直于锚点站立，双脚分开与肩同宽。","用双手抓住带子手柄并远离锚点以在带子中产生张力。","将双手放在胸前，保持肘部弯曲并靠近身体。","调动你的核心并保持稳定的姿势。","将手臂伸直至前方，将弹力带推离身体。","保持伸展姿势几秒钟，专注于保持核心紧张。","慢慢地将双手放回胸前，抵抗弹力带的拉力。","重复所需的重复次数。"],"hi":["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए लंगर बिंदु पर लंबवत खड़े रहें।","बैंड के हैंडल को दोनों हाथों से पकड़ें और बैंड में तनाव पैदा करने के लिए एंकर पॉइंट से दूर हट जाएं।","अपने हाथों को अपनी छाती के पास लाएँ, अपनी कोहनियाँ मुड़ी हुई और अपने शरीर के पास रखें।","अपने मूल को संलग्न करें और स्थिर रुख बनाए रखें।","अपनी बाहों को अपने सामने सीधा फैलाएं, बैंड को अपने शरीर से दूर धकेलें।","अपने कोर में तनाव बनाए रखने पर ध्यान केंद्रित करते हुए, कुछ सेकंड के लिए विस्तारित स्थिति में रहें।","बैंड के खिंचाव का विरोध करते हुए धीरे-धीरे अपने हाथों को अपनी छाती पर वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości talii.","Stań prostopadle do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Chwyć uchwyt taśmy obiema rękami i odejdź od punktu zaczepienia, aby wytworzyć napięcie w taśmie.","Przyciągnij dłonie do klatki piersiowej, trzymając łokcie ugięte i blisko ciała.","Napnij mięśnie brzucha i utrzymuj stabilną postawę.","Wyprostuj ramiona prosto przed sobą, wypychając taśmę od ciała.","Utrzymaj wyprostowaną pozycję przez kilka sekund, skupiając się na utrzymaniu napięcia w mięśniach brzucha.","Powoli przyciągnij dłonie z powrotem do klatki piersiowej, opierając się naciągowi taśmy.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 허리 높이의 견고한 고정점에 부착합니다.","고정점에 수직으로 서되 발을 어깨너비로 벌립니다.","밴드 손잡이를 양손으로 잡고 고정점에서 멀리 물러나 밴드에 긴장을 만듭니다.","손을 가슴 쪽으로 가져오되 팔꿈치를 구부리고 몸 옆에 가깝게 유지합니다.","복부에 힘을 주고 안정적인 자세를 유지합니다.","팔을 몸 앞으로 곧게 펼쳐 밴드를 앞으로 밀어냅니다.","펼친 자세를 몇 초간 유지하며 복부의 긴장에 집중합니다.","천천히 손을 가슴 쪽으로 가져오되 밴드의 당김에 저항합니다.","원하는 반복 횟수만큼 반복합니다."]}', 'obliques', '["obliques","glutes"]', 'abs', 'images/0979-9pa4H5m.jpg', 'videos/0979-9pa4H5m.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0981', 'band jack knife sit-up', 'waist', 'waist', 'band', '{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe dritte e le braccia distese sopra la testa, tenendo la fascia.","Coinvolgi gli addominali e solleva contemporaneamente le gambe e la parte superiore del corpo, portando le mani verso i piedi.","Fermati per un momento in alto, quindi abbassa lentamente le gambe e la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı tutarak bacaklarınız düz ve kollarınız yukarı doğru uzatılmış şekilde sırt üstü uzanın.","Karın kaslarınızı devreye sokun ve ellerinizi ayaklarınıza doğru getirerek bacaklarınızı ve vücudunuzun üst kısmını aynı anda kaldırın.","Tepe noktasında bir an duraklayın, ardından bacaklarınızı ve üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activa el abdomen y levanta las piernas y la parte superior del cuerpo simultáneamente, llevando las manos hacia los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Напрягите пресс и одновременно поднимите ноги и верхнюю часть тела, поднеся руки к ногам.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时抬起双腿和上半身，将双手移向脚部。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को संलग्न करें और अपने पैरों और ऊपरी शरीर को एक साथ उठाएं, अपने हाथों को अपने पैरों की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और शरीर के ऊपरी हिस्से को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach z prostymi nogami i ramionami wyciągniętymi nad głową, trzymając taśmę.","Napnij mięśnie brzucha i unieś nogi oraz górną część ciała jednocześnie, przyciągając dłonie w kierunku stóp.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi i górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 대고 누워 다리는 곧게 펼치고 팔은 머리 위로 뻗어 밴드를 들고 있습니다.","복부에 힘을 주고 다리와 상체를 동시에 들어올려 손을 발 쪽으로 가져옵니다.","꼭짓점에서 잠깐 멈춘 후 천천히 다리와 상체를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/0981-KCBKjma.jpg', 'videos/0981-KCBKjma.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0983', 'band kneeling one arm pulldown', 'back', 'back', 'band', '{"en":["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"it":["Attacca la fascia a un punto di ancoraggio robusto sopra la testa.","Inginocchiarsi e tenere la fascia con una mano, con il palmo rivolto verso il basso.","Estendi il braccio completamente sopra la testa, mantenendo il gomito leggermente piegato.","Coinvolgi i muscoli dorsali e abbassa la fascia verso il tuo fianco, portando il gomito verso la cassa toracica.","Fare una pausa per un momento in fondo, quindi rilasciare lentamente la tensione e tornare alla posizione di partenza.","Ripeti per il numero di ripetizioni desiderato, quindi cambia lato."],"tr":["Bandı başınızın üzerindeki sağlam bir bağlantı noktasına takın.","Diz çökün ve bandı bir elinizle, avuç içi aşağı bakacak şekilde tutun.","Dirseğinizi hafifçe bükerek kolunuzu tamamen yukarı doğru uzatın.","Enlem kaslarınızı devreye sokun ve bandı yanınıza doğru çekin, dirseğinizi göğüs kafenize doğru getirin.","Altta bir an duraklayın, ardından yavaşça gerilimi bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Sujeta la banda a un punto de anclaje resistente por encima de tu cabeza.","Arrodíllate y sostén la banda con una mano, con la palma hacia abajo.","Extiende el brazo por completo por encima de la cabeza, manteniendo el codo ligeramente flexionado.","Activa los dorsales y tira de la banda hacia el costado, llevando el codo hacia las costillas.","Haz una pausa por un momento en la parte inferior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Прикрепите ремешок к прочной точке крепления над головой.","Встаньте на колени и возьмите ленту одной рукой ладонью вниз.","Вытяните руку полностью над головой, слегка согнув локоть.","Задействуйте широчайшие мышцы и потяните ленту вниз в сторону, приближая локоть к грудной клетке.","Задержитесь на мгновение в нижней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["将带子固定在头顶上方坚固的锚点上。","跪下，用一只手握住弹力带，手掌朝下。","将手臂完全伸过头顶，保持肘部稍微弯曲。","调动你的背阔肌，将弹力带拉向你的一侧，使你的肘部靠近你的胸腔。","在底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数，然后换边。"],"hi":["बैंड को अपने सिर के ऊपर एक मजबूत एंकर पॉइंट से जोड़ें।","घुटने टेकें और बैंड को एक हाथ से पकड़ें, हथेली नीचे की ओर।","अपनी बांह को पूरी तरह ऊपर की ओर फैलाएं, अपनी कोहनी को थोड़ा मोड़कर रखें।","अपनी अंडकोश की मांसपेशियों को संलग्न करें और बैंड को अपनी तरफ नीचे खींचें, अपनी कोहनी को अपनी पसली की ओर लाएं।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia nad głową.","Uklęknij i trzymaj taśmę jedną ręką, dłonią skierowaną w dół.","Wyprostuj ramię w pełni nad głową, utrzymując łokieć lekko ugięty.","Napnij mięśnie najszersze grzbietu i ściągnij taśmę w dół w kierunku boku ciała, przyciągając łokieć w stronę klatki piersiowej.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie powoli zwolnij napięcie i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień stronę."],"ko":["밴드를 머리 위의 견고한 고정점에 부착합니다.","무릎을 꿇고 한손으로 밴드를 잡되 손바닥이 아래를 향하게 합니다.","팔을 머리 위로 완전히 펼치되 팔꿈치는 약간 구부립니다.","등 근육에 힘을 주고 밴드를 옆으로 당겨 팔꿈치를 갈비뼈 쪽으로 가져옵니다.","아래쪽에서 잠깐 멈춘 후 천천히 긴장을 풀고 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복한 후 반대쪽으로 바꿉니다."]}', 'biceps', '["biceps","rhomboids"]', 'lats', 'images/0983-pmnrOp0.jpg', 'videos/0983-pmnrOp0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0985', 'band kneeling twisting crunch', 'waist', 'waist', 'band', '{"en":["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio robusto all''altezza della vita.","Inginocchiati con la faccia opposta al punto di ancoraggio e tieni la fascia con entrambe le mani, mantenendo i gomiti piegati e vicini ai fianchi.","Coinvolgi gli addominali e ruota lentamente il busto da un lato, portando le mani verso il fianco opposto.","Fai una pausa per un momento, quindi torna lentamente alla posizione di partenza.","Ripeti dall''altra parte.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Bandı bel yüksekliğinde sağlam bir bağlantı noktasına takın.","Bağlantı noktasından uzağa bakacak şekilde diz çökün ve bandı iki elinizle tutun, dirseklerinizi bükülü ve yanlarınıza yakın tutun.","Karın kaslarınızı devreye sokun ve gövdenizi yavaşça bir tarafa doğru çevirin, ellerinizi karşı kalçanıza doğru getirin.","Bir an duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","Diğer tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Arrodíllate de espaldas al punto de anclaje y sostén la banda con ambas manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira lentamente el torso hacia un lado, llevando las manos hacia la cadera opuesta.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте на колени лицом от точки крепления и возьмитесь за ленту обеими руками, держа локти согнутыми и прижатыми к бокам.","Напрягите пресс и медленно поверните туловище в одну сторону, приближая руки к противоположному бедру.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["将带子固定在腰部高度的坚固锚点上。","面向远离锚点的方向跪下，用双手握住弹力带，保持肘部弯曲并靠近身体两侧。","收紧腹肌，慢慢地将躯干扭向一侧，将双手移向另一侧的臀部。","暂停片刻，然后慢慢回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"],"hi":["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","एंकर बिंदु से दूर की ओर मुंह करके घुटने टेकें और दोनों हाथों से बैंड को पकड़ें, अपनी कोहनियों को मोड़कर अपनी भुजाओं के करीब रखें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को एक तरफ मोड़ें, अपने हाथों को अपने विपरीत कूल्हे की ओर लाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości talii.","Uklęknij tyłem do punktu zaczepienia i trzymaj taśmę obiema rękami, utrzymując łokcie ugięte i blisko boków ciała.","Napnij mięśnie brzucha i powoli skręć tułów w jedną stronę, przyciągając dłonie w kierunku przeciwległego biodra.","Zatrzymaj się na chwilę, a następnie powoli wróć do pozycji wyjściowej.","Powtórz po drugiej stronie.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["밴드를 허리 높이의 견고한 고정점에 부착합니다.","고정점을 등지고 무릎을 꿇되 양손으로 밴드를 잡고 팔꿈치를 구부려 몸 옆에 가깝게 유지합니다.","복부에 힘을 주고 천천히 상체를 한쪽으로 비틀며 손을 반대쪽 엉덩이 쪽으로 가져옵니다.","잠깐 멈춘 후 천천히 시작 자세로 돌아갑니다.","반대쪽으로 반복합니다.","계속 양쪽을 번갈아 원하는 반복 횟수만큼 반복합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/0985-225x2Vd.jpg', 'videos/0985-225x2Vd.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0984', 'band lying hip internal rotation', 'upper legs', 'upper legs', 'band', '{"en":["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe dritte e una fascia di resistenza avvolta attorno ai piedi.","Piega le ginocchia e portale verso il petto, tenendo i piedi uniti.","Ruota lentamente le ginocchia verso l''esterno, allontanandole l''una dall''altra, mantenendo i piedi uniti.","Fare una pausa per un momento alla fine della rotazione, quindi tornare lentamente alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız düz ve ayaklarınızın etrafına bir direnç bandı sarılmış şekilde sırt üstü yatın.","Dizlerinizi bükün ve ayaklarınızı bir arada tutarak göğsünüze doğru getirin.","Ayaklarınızı bir arada tutarken dizlerinizi yavaşça birbirinden uzağa doğru döndürün.","Dönüşün sonunda bir süre duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas rectas y una banda elástica enrollada alrededor de los pies.","Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies juntos.","Rota lentamente las rodillas hacia afuera, separándolas entre sí, mientras mantienes los pies juntos.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, выпрямите ноги и обвяжите ступни эластичной лентой.","Согните колени и подтяните их к груди, держа стопы вместе.","Медленно разверните колени наружу, друг от друга, сохраняя при этом стопы вместе.","Сделайте небольшую паузу в конце вращения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["仰卧，双腿伸直，将阻力带绕在脚上。","弯曲膝盖并将其靠近胸部，双脚并拢。","慢慢向外旋转膝盖，使膝盖彼此远离，同时保持双脚并拢。","旋转结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को सीधा करके अपनी पीठ के बल लेटें और आपके पैरों के चारों ओर एक प्रतिरोध बैंड बंधा हुआ हो।","अपने घुटनों को मोड़ें और अपने पैरों को एक साथ रखते हुए उन्हें अपनी छाती की ओर लाएँ।","अपने पैरों को एक साथ रखते हुए धीरे-धीरे अपने घुटनों को एक-दूसरे से दूर बाहर की ओर घुमाएं।","घूर्णन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na plecach z prostymi nogami i taśmą oporową owiniętą wokół stóp.","Ugnij kolana i przyciągnij je w kierunku klatki piersiowej, trzymając stopy razem.","Powoli rozsuwaj kolana na zewnątrz, od siebie, utrzymując stopy razem.","Zatrzymaj się na chwilę na końcu ruchu obrotowego, a następnie powoli wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 대고 누워 다리는 곧게 펼치고 발에 저항 밴드를 감습니다.","무릎을 구부려 가슴 쪽으로 가져오되 발은 함께 유지합니다.","천천히 무릎을 바깥쪽으로 회전시키되 발은 함께 유지합니다.","회전의 끝에서 잠깐 멈춘 후 천천히 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","quadriceps"]', 'glutes', 'images/0984-vIICElP.jpg', 'videos/0984-vIICElP.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1002', 'band lying straight leg raise', 'waist', 'waist', 'band', '{"en":["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe dritte e i piedi uniti.","Posiziona la fascia attorno all''arco dei piedi e tieni le estremità della fascia con le mani.","Coinvolgendo gli addominali, solleva entrambe le gambe da terra finché non sono perpendicolari al pavimento.","Fai una pausa per un momento in alto, quindi abbassa lentamente le gambe fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız düz ve ayaklarınız bitişik olacak şekilde sırt üstü uzanın.","Bandı ayak kavislerinizin etrafına yerleştirin ve bandın uçlarını ellerinizle tutun.","Karın kaslarınızı devreye sokarak her iki bacağınızı da yere dik olana kadar yerden kaldırın.","Tepe noktasında bir an duraklayın, ardından bacaklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas rectas y los pies juntos.","Coloca la banda alrededor de los arcos de los pies y sostén los extremos de la banda con las manos.","Activando el abdomen, levanta ambas piernas del suelo hasta que queden perpendiculares al suelo.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, ноги прямые, ступни вместе.","Оберните ленту вокруг сводов стоп и возьмитесь за концы ленты руками.","Включив пресс, поднимите обе ноги от земли, пока они не станут перпендикулярны полу.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，双腿伸直，双脚并拢。","将带子放在脚弓周围，并用手握住带子的末端。","收紧腹肌，将双腿抬离地面，直到它们垂直于地板。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ के बल लेट जाएं और अपने पैरों को सीधा रखें और पैरों को एक साथ रखें।","बैंड को अपने पैरों के आर्च के चारों ओर रखें और बैंड के सिरों को अपने हाथों से पकड़ें।","अपने पेट को संलग्न करते हुए, दोनों पैरों को जमीन से ऊपर उठाएं जब तक कि वे फर्श से लंबवत न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach z prostymi nogami i stopami razem.","Umieść taśmę wokół podeszw stóp i trzymaj końce taśmy dłońmi.","Angażując mięśnie brzucha, unieś obie nogi nad podłogę, aż będą prostopadłe do podłogi.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 바닥에 대고 누워 다리는 곧게 펼치고 발을 함께 모읍니다.","발의 아치 부분에 밴드를 감고 양손으로 밴드의 끝을 잡습니다.","복부에 힘을 주고 양다리를 바닥에서 들어올려 바닥과 수직이 되게 합니다.","꼭짓점에서 잠깐 멈춘 후 천천히 다리를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/1002-bbLR7fB.jpg', 'videos/1002-bbLR7fB.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0986', 'band one arm overhead biceps curl', 'upper arms', 'upper arms', 'band', '{"en":["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona un''estremità della fascia sotto il piede.","Tieni l''altra estremità della fascia con il braccio completamente esteso sopra la testa, con il palmo rivolto in avanti.","Mantenendo ferma la parte superiore del braccio, piega l''avambraccio verso la spalla, contraendo i bicipiti.","Fai una pausa per un momento in alto, quindi abbassa lentamente l''avambraccio nella posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi cambia braccio."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandın bir ucunu ayağınızın altına yerleştirin.","Bandın diğer ucunu kolunuz tamamen uzatılmış, avuç içi öne bakacak şekilde tutun.","Üst kolunuzu sabit tutarak ön kolunuzu omzunuza doğru kıvırın ve bicepslerinizi sıkın.","Tepe noktasında bir an duraklayın, ardından ön kolunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.","Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.","Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.","Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"ru":["Встаньте, ноги на ширине плеч, и поместите один конец ленты под ногу.","Держите другой конец ленты, полностью вытянув руку над головой ладонью вперед.","Удерживая плечо неподвижно, согните предплечье к плечу, сжимая бицепс.","Задержитесь на мгновение в верхней точке, затем медленно опустите предплечье обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"zh":["双脚分开与肩同宽站立，将弹力带的一端放在脚下。","握住弹力带的另一端，手臂完全伸过头顶，手掌朝前。","保持上臂静止，将前臂向肩膀弯曲，挤压二头肌。","在顶部停顿片刻，然后慢慢将前臂放回起始位置。","重复所需的重复次数，然后换臂。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड के एक सिरे को अपने पैर के नीचे रखें।","बैंड के दूसरे सिरे को अपने हाथ से पूरी तरह ऊपर की ओर फैलाकर पकड़ें, हथेली आगे की ओर हो।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपने अग्रबाहु को अपने कंधे की ओर मोड़ें, अपने बाइसेप्स को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"],"pl":["Stań w rozkroku na szerokość barków i umieść jeden koniec taśmy pod stopą.","Trzymaj drugi koniec taśmy ramieniem w pełni wyprostowanym nad głową, dłonią skierowaną do przodu.","Utrzymując ramię nieruchome, uginaj przedramię w kierunku barku, ściskając biceps.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść przedramię z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień ramię."],"ko":["발을 어깨너비로 벌리고 서서 밴드의 한쪽 끝을 발 아래 놓습니다.","밴드의 다른 쪽 끝을 팔을 머리 위로 완전히 펼친 상태로 들되 손바닥이 앞을 향하게 합니다.","위팔을 고정한 상태로 전완을 어깨 쪽으로 말아올려 이두근을 짜냅니다.","꼭짓점에서 잠깐 멈춘 후 천천히 전완을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복한 후 팔을 바꿉니다."]}', 'forearms', '["forearms","shoulders"]', 'biceps', 'images/0986-UNAB8ak.jpg', 'videos/0986-UNAB8ak.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0987', 'band one arm single leg split squat', 'upper legs', 'upper legs', 'band', '{"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"it":["Stare con i piedi alla larghezza dei fianchi e posizionare una fascia di resistenza attorno alle caviglie.","Estendi una gamba in avanti e appoggia la parte superiore del piede su una panca o fai un passo dietro di te.","Tenersi su un supporto con una mano per mantenere l''equilibrio.","Piega la gamba in piedi e abbassa il corpo in posizione tozza, mantenendo il ginocchio in linea con le dita dei piedi.","Spingi attraverso il tallone per tornare alla posizione di partenza.","Ripeti per il numero di ripetizioni desiderato, quindi cambia gamba."],"tr":["Ayaklarınızı kalça genişliğinde açın ve ayak bileklerinizin etrafına bir direnç bandı yerleştirin.","Bir bacağınızı öne doğru uzatın ve ayağınızın üst kısmını bir bankın üzerine koyun veya arkanıza bir adım atın.","Dengeyi sağlamak için bir elinizle bir desteğe tutunun.","Ayakta duran bacağınızı bükün ve dizinizi ayak parmaklarınızla aynı hizada tutarak vücudunuzu çömelme pozisyonuna indirin.","Başlangıç ​​pozisyonuna dönmek için topuğunuzu itin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından bacakları değiştirin."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Extiende una pierna hacia adelante y apoya la parte superior del pie sobre un banco o escalón detrás de ti.","Sujétate de un apoyo con una mano para mantener el equilibrio.","Flexiona la pierna de apoyo y baja el cuerpo hacia una posición de sentadilla, manteniendo la rodilla alineada con los dedos del pie.","Empuja con el talón para regresar a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"ru":["Встаньте, ноги на ширине плеч, и наденьте эластичную ленту на лодыжки.","Вытяните одну ногу вперед и положите верхнюю часть стопы на скамью или сделайте шаг позади себя.","Держитесь за опору одной рукой для равновесия.","Согните стоящую ногу и опустите тело в положение приседа, удерживая колено на одной линии с пальцами ног.","Оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"zh":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","向前伸出一条腿，将脚尖放在长凳上或身后的一步上。","用一只手握住支撑物以保持平衡。","弯曲站立的腿，将身体降低到蹲姿，保持膝盖与脚趾在一条直线上。","推动脚后跟返回到起始位置。","重复所需的重复次数，然后换腿。"],"hi":["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और अपनी एड़ियों के चारों ओर एक प्रतिरोध बैंड लगाएं।","एक पैर को आगे बढ़ाएं और अपने पैर के ऊपरी हिस्से को अपने पीछे एक बेंच या स्टेप पर रखें।","संतुलन के लिए एक हाथ से किसी सहारे को पकड़ें।","अपने खड़े पैर को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपने घुटने को अपने पैर की उंगलियों के अनुरूप रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"],"pl":["Stań w rozkroku na szerokość bioder i umieść taśmę oporową wokół kostek.","Wyciągnij jedną nogę do przodu i oprzyj czubek stopy na ławce lub stopniu za sobą.","Chwyć podporę jedną ręką dla równowagi.","Ugnij nogę stojącą i opuść ciało do pozycji przysiadu, utrzymując kolano w linii z palcami stóp.","Odepchnij się piętą, aby wrócić do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień nogę."],"ko":["발을 엉덩이너비로 벌리고 서서 발목 주변에 저항 밴드를 감습니다.","한쪽 다리를 앞으로 펼치고 발 등을 뒤의 벤치나 발판에 놓습니다.","균형을 위해 한손으로 지지대를 잡습니다.","서 있는 다리를 구부려 스쿼트 자세로 내리되 무릎이 발가락과 일직선이 되게 합니다.","발뒤꿈치를 통해 밀어 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복한 후 다리를 바꿉니다."]}', 'glutes', '["glutes","hamstrings"]', 'quads', 'images/0987-arsYEd3.jpg', 'videos/0987-arsYEd3.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0988', 'band one arm standing low row', 'back', 'back', 'band', '{"en":["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"it":["Attaccare la fascia a un punto di ancoraggio stabile all''altezza della vita.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Tieni la fascia con una mano, con il palmo rivolto verso l''interno, e fai un passo indietro per creare tensione nella fascia.","Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta.","Tira la fascia verso la vita, stringendo insieme le scapole.","Fai una pausa per un momento nella parte superiore del movimento, quindi rilascia lentamente la fascia nella posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi cambia lato."],"tr":["Bandı bel yüksekliğinde sabit bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde bağlantı noktasına bakacak şekilde durun.","Bandı bir elinizle avuç içi içe bakacak şekilde tutun ve bantta gerginlik yaratmak için geri adım atın.","Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin.","Bandı belinize doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Hareketin en üst noktasında bir an duraklayın, ardından bandı yavaşça başlangıç ​​pozisyonuna geri bırakın.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Sujeta la banda a un punto de anclaje estable a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con una mano, con la palma hacia adentro, y da un paso atrás para generar tensión en la banda.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia la cintura, juntando los omóplatos.","Haz una pausa por un momento en la parte superior del movimiento, luego suelta lentamente la banda de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Прикрепите ремешок к устойчивой точке крепления на высоте талии.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Держите ленту одной рукой ладонью внутрь и отступите назад, чтобы создать натяжение ленты.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Потяните ленту к талии, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения, затем медленно отпустите ленту обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["将带子固定在腰部高度的稳定锚点上。","面向锚点站立，双脚分开与肩同宽。","用一只手握住弹力带，手掌朝内，然后后退以在弹力带中产生张力。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将带子拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开弹力带回到起始位置。","重复所需的重复次数，然后换边。"],"hi":["बैंड को कमर की ऊंचाई पर एक स्थिर लंगर बिंदु पर संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को एक हाथ से पकड़ें, हथेली अंदर की ओर रखें और बैंड में तनाव पैदा करने के लिए पीछे हटें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड को अपनी कमर की ओर खींचें।","आंदोलन के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości talii.","Stań przodem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Trzymaj taśmę jedną ręką, dłonią skierowaną do wewnątrz, i zrób krok do tyłu, aby wytworzyć napięcie w taśmie.","Ugnij lekko kolana i pochyl się do przodu w biodrach, utrzymując proste plecy.","Przyciągnij taśmę w kierunku talii, ściskając łopatki.","Zatrzymaj się na chwilę w górnej fazie ruchu, a następnie powoli uwolnij taśmę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień stronę."],"ko":["밴드를 허리 높이의 안정적인 고정점에 부착합니다.","고정점을 마주보고 서되 발을 어깨너비로 벌립니다.","한손으로 밴드를 잡고 손바닥이 안을 향하게 하여 뒤로 물러나 밴드에 긴장을 만듭니다.","무릎을 약간 구부리고 엉덩이 쪽으로 구부려 등을 곧게 펼칩니다.","밴드를 허리 쪽으로 당기며 견갑골을 함께 짜냅니다.","동작의 꼭짓점에서 잠깐 멈춘 후 천천히 밴드를 시작 자세로 풀어줍니다.","원하는 반복 횟수만큼 반복한 후 반대쪽으로 바꿉니다."]}', 'biceps', '["biceps","shoulders"]', 'upper back', 'images/0988-km0sQC0.jpg', 'videos/0988-km0sQC0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0989', 'band one arm twisting chest press', 'chest', 'chest', 'band', '{"en":["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."],"it":["Attaccare la fascia a un punto di ancoraggio robusto all''altezza del petto.","Stai con il fianco rivolto verso il punto di ancoraggio e afferra la fascia con una mano.","Allontanati dal punto di ancoraggio per creare tensione nella fascia.","Posiziona i piedi alla larghezza delle spalle e piega leggermente le ginocchia.","Porta la mano che tiene la fascia lungo il corpo, verso la spalla opposta.","Mantenendo la tensione nella fascia, spingi la mano in avanti e lontano dal corpo, estendendo il braccio.","Ritorna lentamente alla posizione iniziale e ripeti per il numero di ripetizioni desiderato.","Cambia lato e ripeti l''esercizio con l''altra mano."],"tr":["Bandı göğüs yüksekliğinde sağlam bir bağlantı noktasına takın.","Yan tarafınız bağlantı noktasına bakacak şekilde durun ve bandı bir elinizle tutun.","Bantta gerginlik yaratmak için bağlantı noktasından uzaklaşın.","Ayaklarınızı omuz genişliğinde açın ve dizlerinizi hafifçe bükün.","Bandı tutan elinizi vücudunuzun üzerinden karşı omzunuza doğru getirin.","Bandın gerginliğini korurken, kolunuzu uzatarak elinizi ileri ve vücudunuzdan uzağa doğru itin.","Yavaşça başlangıç ​​pozisyonuna dönün ve istenilen sayıda tekrar yapın.","Taraf değiştirin ve egzersizi diğer elinizle tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura del pecho.","Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.","Aléjate del punto de anclaje para generar tensión en la banda.","Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.","Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.","Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.","Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.","Cambia de lado y repite el ejercicio con la otra mano."],"ru":["Прикрепите ремешок к прочной точке крепления на уровне груди.","Встаньте боком к точке крепления и возьмитесь за ленту одной рукой.","Отойдите от точки крепления, чтобы создать напряжение в ленте.","Поставьте ноги на ширине плеч и слегка согните колени.","Проведите руку, удерживающую ленту, через тело к противоположному плечу.","Сохраняя натяжение ленты, толкните руку вперед и в сторону от тела, вытягивая руку.","Медленно вернитесь в исходное положение и повторите необходимое количество повторений.","Поменяйте сторону и повторите упражнение другой рукой."],"zh":["将带子固定在胸部高度的坚固锚点上。","站立，一侧面向锚点，用一只手抓住带子。","远离锚点以在带子中产生张力。","将双脚分开与肩同宽，并稍微弯曲膝盖。","将握住弹力带的手穿过身体，朝向对侧的肩膀。","在保持弹力带张力的同时，将手向前推离身体，伸展手臂。","慢慢回到起始位置并重复所需的重复次数。","换边并用另一只手重复练习。"],"hi":["बैंड को छाती की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","एंकर प्वाइंट की ओर मुंह करके खड़े हो जाएं और एक हाथ से बैंड को पकड़ लें।","बैंड में तनाव पैदा करने के लिए एंकर बिंदु से दूर हट जाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखें और अपने घुटनों को थोड़ा मोड़ लें।","बैंड को पकड़ने वाले अपने हाथ को अपने शरीर के पार, विपरीत कंधे की ओर लाएँ।","बैंड में तनाव बनाए रखते हुए, अपने हाथ को आगे बढ़ाते हुए अपने हाथ को अपने शरीर से दूर और आगे की ओर धकेलें।","धीरे-धीरे प्रारंभिक स्थिति में लौटें और वांछित संख्या में दोहराव के लिए दोहराएं।","करवट बदलें और दूसरे हाथ से व्यायाम दोहराएं।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości klatki piersiowej.","Stań bokiem do punktu zaczepienia i chwyć taśmę jedną ręką.","Odejdź od punktu zaczepienia, aby wytworzyć napięcie w taśmie.","Ustaw stopy w rozkroku na szerokość barków i ugnij lekko kolana.","Przyciągnij dłoń trzymającą taśmę w poprzek ciała, w kierunku przeciwległego barku.","Utrzymując napięcie w taśmie, wypchnij dłoń do przodu i od ciała, prostując ramię.","Powoli wróć do pozycji wyjściowej i powtórz zalecaną liczbę razy.","Zmień stronę i powtórz ćwiczenie drugą ręką."],"ko":["밴드를 가슴 높이의 견고한 고정점에 부착합니다.","옆으로 서서 고정점을 향하고 한손으로 밴드를 잡습니다.","고정점에서 멀리 물러나 밴드에 긴장을 만듭니다.","발을 어깨너비로 벌리고 무릎을 약간 구부립니다.","밴드를 들고 있는 손을 몸 안쪽을 가로질러 반대쪽 어깨 쪽으로 가져옵니다.","밴드의 긴장을 유지하면서 손을 앞으로 밀어내며 팔을 펼칩니다.","천천히 시작 자세로 돌아오고 원하는 반복 횟수만큼 반복합니다.","반대쪽으로 바꾸어 반대 손으로 운동을 반복합니다."]}', 'shoulders', '["shoulders","triceps"]', 'pectorals', 'images/0989-c16nYGA.jpg', 'videos/0989-c16nYGA.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0990', 'band one arm twisting seated row', 'back', 'back', 'band', '{"en":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."],"it":["Siediti su una panca o una sedia con i piedi appoggiati a terra e la schiena dritta.","Tieni la fascia con una mano ed estendi completamente il braccio davanti a te.","Tenendo la schiena dritta, tira la fascia verso il corpo piegando il gomito e stringendo insieme le scapole.","Allo stesso tempo, ruota il busto verso il lato del braccio che tira.","Fare una pausa per un momento in alto, quindi rilasciare lentamente la tensione nella fascia e tornare alla posizione di partenza.","Ripeti per il numero di ripetizioni desiderato, quindi passa all''altro braccio."],"tr":["Ayaklarınız yere düz basacak ve sırtınız düz olacak şekilde bir bankta veya sandalyede oturun.","Bandı bir elinizle tutun ve kolunuzu tamamen önünüze doğru uzatın.","Sırtınızı dik tutarak, dirseğinizi bükerek ve kürek kemiklerinizi birbirine doğru sıkıştırarak bandı vücudunuza doğru çekin.","Aynı zamanda gövdenizi çekme kolunun yan tarafına doğru çevirin.","Tepe noktasında bir an duraklayın, ardından banttaki gerilimi yavaşça bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.","Sostén la banda con una mano y extiende el brazo completamente frente a ti.","Manteniendo la espalda recta, tira de la banda hacia el cuerpo flexionando el codo y juntando los omóplatos.","Al mismo tiempo, gira el torso hacia el lado del brazo que tira.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión de la banda y regresa a la posición inicial.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"ru":["Сядьте на скамью или стул, поставив ноги на землю и выпрямив спину.","Держите ленту одной рукой и вытяните руку полностью перед собой.","Сохраняя спину прямой, потяните ленту к себе, сгибая локоть и сводя лопатки вместе.","В то же время поверните туловище в сторону тянущей руки.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте натяжение ленты и вернитесь в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"zh":["坐在长凳或椅子上，双脚平放在地上，背部挺直。","用一只手握住弹力带，并将手臂完全伸到身前。","保持背部挺直，弯曲肘部并将肩胛骨挤压在一起，将弹力带拉向身体。","同时，将躯干向拉动手臂的一侧扭转。","在顶部暂停片刻，然后慢慢释放弹力带的张力并返回到起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके और अपनी पीठ सीधी करके एक बेंच या कुर्सी पर बैठें।","बैंड को एक हाथ से पकड़ें और अपना हाथ पूरी तरह अपने सामने फैलाएँ।","अपनी पीठ को सीधा रखते हुए, अपनी कोहनी को मोड़कर और अपने कंधे के ब्लेड को एक साथ दबाकर बैंड को अपने शरीर की ओर खींचें।","साथ ही, अपने धड़ को खींचने वाले हाथ की तरफ मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड में तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"],"pl":["Usiądź na ławce lub krześle, stopy płasko na podłodze, plecy proste.","Trzymaj taśmę jedną ręką i wyprostuj ramię w pełni przed sobą.","Utrzymując proste plecy, przyciągnij taśmę w kierunku ciała, uginając łokieć i ściskając łopatki.","Jednocześnie skręć tułów w stronę ręki wykonującej ruch.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli zwolnij napięcie taśmy i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień rękę."],"ko":["벤치나 의자에 앉아 발을 바닥에 붙이고 등을 곧게 펼칩니다.","한손으로 밴드를 잡고 팔을 앞으로 완전히 펼칩니다.","등을 곧게 펼친 상태로 팔꿈치를 구부려 밴드를 몸 쪽으로 당기며 견갑골을 함께 짜냅니다.","동시에 당기는 팔 쪽으로 상체를 비틉니다.","꼭짓점에서 잠깐 멈춘 후 천천히 밴드의 긴장을 풀고 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복한 후 다른 팔로 바꿉니다."]}', 'biceps', '["biceps","shoulders"]', 'upper back', 'images/0990-DKBwJrL.jpg', 'videos/0990-DKBwJrL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0991', 'band pull through', 'upper legs', 'upper legs', 'band', '{"en":["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca una fascia di resistenza a un punto di ancoraggio robusto a livello del suolo.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Fai un passo avanti per creare tensione nella fascia, mantenendo le ginocchia leggermente piegate.","Fai perno sui fianchi e spingi indietro i glutei, mantenendo una leggera piegatura delle ginocchia.","Abbassa il busto finché non è parallelo al suolo, avvertendo un allungamento nei muscoli posteriori della coscia.","Spingi i fianchi in avanti e contrai i glutei per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Zemin seviyesindeki sağlam bir bağlantı noktasına bir direnç bandı takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde, bağlantı noktasından uzağa bakacak şekilde durun.","Dizlerinizi hafifçe bükerek bantta gerginlik yaratmak için öne doğru bir adım atın.","Kalçalarınızdan menteşe alın ve dizlerinizi hafif bir şekilde bükerek kalçalarınızı geriye doğru itin.","Diz arkası kirişlerinizde bir gerginlik hissederek gövdenizi yere paralel hale gelinceye kadar indirin.","Kalçalarınızı öne doğru itin ve başlangıç ​​pozisyonuna dönmek için kalça kaslarınızı sıkın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta una banda elástica a un punto de anclaje resistente a nivel del suelo.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Da un paso adelante para generar tensión en la banda, manteniendo las rodillas ligeramente flexionadas.","Flexiona las caderas y lleva los glúteos hacia atrás, manteniendo una ligera flexión en las rodillas.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Empuja las caderas hacia adelante y aprieta los glúteos para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ленту сопротивления к прочной точке крепления на уровне земли.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Сделайте шаг вперед, чтобы создать напряжение в ленте, держа колени слегка согнутыми.","Наклонитесь в бедрах и отведите ягодицы назад, сохраняя небольшой изгиб в коленях.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Поднимите бедра вперед и сожмите ягодицы, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["将阻力带连接到地面上坚固的锚点上。","背对锚点站立，双脚与肩同宽。","向前迈一步，在弹力带中产生张力，保持膝盖稍微弯曲。","铰接臀部并将臀部向后推，保持膝盖轻微弯曲。","降低躯干直到与地面平行，感觉腿筋被拉伸。","向前推动臀部并挤压臀部以返回起始位置。","重复所需的重复次数。"],"hi":["जमीनी स्तर पर एक मजबूत लंगर बिंदु पर एक प्रतिरोध बैंड संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को थोड़ा मुड़ा हुआ रखते हुए, बैंड में तनाव पैदा करने के लिए आगे बढ़ें।","कूल्हों पर झुकें और अपने घुटनों को हल्का सा मोड़ते हुए अपने ग्लूट्स को पीछे धकेलें।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","अपने कूल्हों को आगे की ओर ले जाएँ और प्रारंभिक स्थिति में लौटने के लिए अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę oporową do stabilnego punktu zaczepienia przy podłodze.","Stań tyłem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Zrób krok do przodu, aby wytworzyć napięcie w taśmie, utrzymując kolana lekko ugięte.","Pochyl się w biodrach, wypychając pośladki do tyłu, zachowując lekkie ugięcie kolan.","Opuść tułów, aż będzie równoległy do podłogi, odczuwając rozciąganie w mięśniach dwugłowych uda.","Wypchnij biodra do przodu i ściśnij pośladki, aby wrócić do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["저항 밴드를 지면 높이의 견고한 고정점에 부착합니다.","고정점을 등지고 서되 발을 어깨너비로 벌립니다.","앞으로 물러나 밴드에 긴장을 만들되 무릎을 약간 구부린 상태를 유지합니다.","엉덩이를 뒤로 밀며 엉덩이 부분에서 구부려 무릎을 약간 구부린 상태를 유지합니다.","상체가 지면과 평행할 때까지 내려가며 넓적다리 뒤쪽의 스트레치를 느낍니다.","엉덩이를 앞으로 밀어내며 엉덩이 근육을 짜내 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0991-VtTbiP3.jpg', 'videos/0991-VtTbiP3.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0992', 'band push sit-up', 'waist', 'waist', 'band', '{"en":["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Fissare saldamente il cinturino a un punto di ancoraggio stabile.","Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.","Tieni la fascia con entrambe le mani ed estendi le braccia verso il soffitto.","Coinvolgendo gli addominali, solleva lentamente la parte superiore del corpo da terra, piegandoti in avanti finché il busto non forma un angolo di 45 gradi.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı sağlam bir bağlantı noktasına güvenli bir şekilde takın.","Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde sırt üstü yatın.","Bandı iki elinizle tutun ve kollarınızı tavana doğru düz bir şekilde uzatın.","Karın kaslarınızı devreye sokarak üst bedeninizi yavaşça yerden kaldırın ve gövdeniz 45 derecelik bir açıya gelene kadar öne doğru kıvrılın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda de forma segura a un punto de anclaje estable.","Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.","Sostén la banda con ambas manos y extiende los brazos rectos hacia el techo.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Надежно прикрепите ремешок к устойчивой точке крепления.","Лягте на спину, согните колени и поставьте ступни на землю.","Возьмите ленту обеими руками и вытяните руки прямо вверх к потолку.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将带子牢固地固定在稳定的锚点上。","平躺，膝盖弯曲，双脚平放在地上。","用双手握住弹力带，并将双臂伸向天花板。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["बैंड को एक स्थिर एंकर बिंदु पर सुरक्षित रूप से संलग्न करें।","अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","बैंड को दोनों हाथों से पकड़ें और अपनी बाहों को छत की ओर सीधा ऊपर उठाएं।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę pewnie do stabilnego punktu zaczepienia.","Połóż się płasko na plecach, ugnij kolana i oprzyj stopy płasko na podłodze.","Trzymaj taśmę obiema rękami i wyciągnij ramiona prosto w górę w kierunku sufitu.","Angażując mięśnie brzucha, powoli unieś górną część ciała nad podłogę, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 안정적인 고정점에 안전하게 부착합니다.","등을 바닥에 대고 누워 무릎을 구부리고 발을 바닥에 붙입니다.","양손으로 밴드를 잡고 팔을 천장을 향해 곧게 펼칩니다.","복부에 힘을 주고 천천히 상체를 바닥에서 들어올려 상체가 45도 각도가 될 때까지 앞으로 말아올립니다.","꼭짓점에서 잠깐 멈춘 후 천천히 상체를 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","chest"]', 'abs', 'images/0992-zFzbBfL.jpg', 'videos/0992-zFzbBfL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0993', 'band reverse fly', 'shoulders', 'shoulders', 'band', '{"en":["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."],"it":["Attaccare la fascia a un oggetto fermo all''altezza del petto.","Stai con i piedi alla larghezza delle spalle e tieni la fascia con entrambe le mani davanti a te.","Tieni le braccia tese e sollevale lateralmente finché non sono parallele al suolo.","Stringi le scapole insieme nella parte superiore del movimento.","Abbassa lentamente le braccia nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı göğüs yüksekliğinde sabit bir nesneye takın.","Ayaklarınızı omuz genişliğinde açın ve bandı iki elinizle önünüzde tutun.","Kollarınızı düz tutun ve yere paralel oluncaya kadar yanlara doğru kaldırın.","Hareketin üst noktasında kürek kemiklerinizi birbirine doğru sıkın.","Kollarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un objeto fijo a la altura del pecho.","Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.","Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ремешок к неподвижному объекту на уровне груди.","Встаньте, ноги на ширине плеч, держите ленту обеими руками перед собой.","Держите руки прямо и поднимите их в стороны, пока они не станут параллельны земле.","В верхней точке движения сведите лопатки вместе.","Медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将带子固定在胸部高度的固定物体上。","双脚分开与肩同宽站立，双手握住弹力带放在身前。","保持手臂伸直并将其向两侧抬起，直到与地面平行。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"],"hi":["बैंड को छाती की ऊंचाई पर किसी स्थिर वस्तु से जोड़ें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बैंड को अपने सामने पकड़ लें।","अपनी भुजाओं को सीधा रखें और उन्हें बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे अपनी भुजाओं को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do nieruchomego obiektu na wysokości klatki piersiowej.","Stań w rozkroku na szerokość barków i trzymaj taśmę obiema rękami przed sobą.","Utrzymuj ramiona proste i unieś je na boki, aż będą równoległe do podłogi.","Ściśnij łopatki razem w górnej fazie ruchu.","Powoli opuść ramiona z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 가슴 높이의 고정된 물체에 부착합니다.","발을 어깨너비로 벌리고 서서 양손으로 밴드를 앞에서 잡습니다.","팔을 곧게 펼친 상태로 팔을 옆으로 들어올려 지면과 평행하게 만듭니다.","동작의 꼭짓점에서 견갑골을 함께 짜냅니다.","천천히 팔을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'upper back', '["upper back","trapezius"]', 'delts', 'images/0993-sTfvVsG.jpg', 'videos/0993-sTfvVsG.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0994', 'band reverse wrist curl', 'lower arms', 'lower arms', 'band', '{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca o una sedia con i piedi appoggiati a terra.","Tieni la fascia con una presa prona, i palmi rivolti verso il basso e avvolgila attorno alle dita.","Appoggia gli avambracci sulle cosce, con i polsi che pendono dal bordo.","Piega lentamente i polsi verso l''alto, stringendo gli avambracci.","Fai una pausa per un momento in alto, quindi abbassa lentamente i polsi nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun.","Bandı üstten kavrayarak, avuçlarınız aşağıya bakacak şekilde tutun ve parmaklarınızın etrafına sarın.","Bilekleriniz kenardan sarkacak şekilde ön kollarınızı uyluklarınıza yaslayın.","Bileklerinizi yavaşça yukarı doğru kıvırın, önkollarınızı sıkın.","Tepe noktasında bir an duraklayın, ardından bileklerinizi yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.","Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Возьмите ремешок сверху ладонями вниз и оберните его вокруг пальцев.","Положите предплечья на бедра так, чтобы запястья свисали с краев.","Медленно поднимите запястья вверх, сжимая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳或椅子上，双脚平放在地面上。","正手握住弹力带，手掌朝下，然后将其缠绕在手指上。","将前臂放在大腿上，手腕悬在边缘上。","慢慢向上弯曲手腕，挤压前臂。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","बैंड को ऊपरी पकड़ से पकड़ें, हथेलियाँ नीचे की ओर हों, और इसे अपनी उंगलियों के चारों ओर लपेटें।","अपनी कलाईयों को किनारे से लटकाते हुए अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce lub krześle, stopy płasko na podłodze.","Chwyć taśmę nachwytem, dłonie skierowane w dół, i owiń ją wokół palców.","Oprzyj przedramiona na udach, z nadgarstkami zwisającymi za krawędzią.","Powoli uginaj nadgarstki w górę, ściskając przedramiona.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nadgarstki z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["벤치나 의자에 앉아 발을 바닥에 붙입니다.","손바닥이 아래를 향하도록 오버핸드 그립으로 밴드를 잡고 손가락 주위에 감습니다.","전완을 넓적다리 위에 놓되 손목이 가장자리에서 떨어져 있게 합니다.","천천히 손목을 위로 말아올려 전완 근육을 짜냅니다.","꼭짓점에서 잠깐 멈춘 후 천천히 손목을 시작 자세로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'forearms', 'images/0994-Ezpnw9d.jpg', 'videos/0994-Ezpnw9d.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0996', 'band seated hip internal rotation', 'upper legs', 'upper legs', 'band', '{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una sedia o una panca con la schiena dritta e i piedi appoggiati a terra.","Posiziona una fascia di resistenza attorno alle cosce, appena sopra le ginocchia.","Tieni le ginocchia piegate con un angolo di 90 gradi e i piedi alla larghezza delle spalle.","Coinvolgi i glutei e ruota lentamente le ginocchia verso l''esterno, spingendo contro la resistenza della fascia.","Fare una pausa per un attimo alla fine del movimento, quindi ritornare lentamente alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Sırtınız düz ve ayaklarınız yere düz basacak şekilde bir sandalyeye veya bankta oturun.","Dizlerinizin hemen üstüne, uyluklarınızın çevresine bir direnç bandı yerleştirin.","Dizleriniz 90 derecelik bir açıyla bükülü ve ayaklarınız omuz genişliğinde açık olsun.","Kalça kaslarınızı devreye sokun ve dizlerinizi yavaşça dışarı doğru döndürerek bandın direncine karşı bastırın.","Hareketin sonunda bir süre duraklayın ve ardından yavaşça başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.","Coloca una banda elástica alrededor de los muslos, justo por encima de las rodillas.","Mantén las rodillas flexionadas formando un ángulo de 90 grados y los pies separados a la altura de los hombros.","Activa los glúteos y rota lentamente las rodillas hacia afuera, empujando contra la resistencia de la banda.","Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на стул или скамью, выпрямив спину и поставив ступни на землю.","Оберните ленту сопротивления вокруг бедер, чуть выше колен.","Держите колени согнутыми под углом 90 градусов, а ноги на ширине плеч.","Напрягите ягодицы и медленно разверните колени наружу, преодолевая сопротивление ленты.","Сделайте небольшую паузу в конце движения, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在椅子或长凳上，背部挺直，双脚平放在地面上。","在大腿周围、膝盖上方放置一条阻力带。","保持膝盖弯曲 90 度，双脚分开与肩同宽。","收紧臀肌，慢慢向外旋转膝盖，克服弹力带的阻力。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके कुर्सी या बेंच पर बैठें।","अपने घुटनों के ठीक ऊपर, अपनी जांघों के चारों ओर एक प्रतिरोध बैंड लगाएं।","अपने घुटनों को 90 डिग्री के कोण पर मोड़ें और अपने पैरों को कंधे की चौड़ाई से अलग रखें।","अपने ग्लूट्स को संलग्न करें और बैंड के प्रतिरोध के विरुद्ध दबाव डालते हुए धीरे-धीरे अपने घुटनों को बाहर की ओर घुमाएँ।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na krześle lub ławce, plecy proste, stopy płasko na podłodze.","Umieść taśmę oporową wokół ud, tuż nad kolanami.","Utrzymuj kolana ugięte pod kątem 90 stopni, a stopy w rozkroku na szerokość barków.","Napnij pośladki i powoli rozsuwaj kolana na zewnątrz, pokonując opór taśmy.","Zatrzymaj się na chwilę na końcu ruchu, a następnie powoli wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["의자나 벤치에 앉아 등을 곧게 펼치고 발을 바닥에 붙입니다.","저항 밴드를 넓적다리 주위, 무릎 바로 위에 놓습니다.","무릎을 90도 각도로 구부리되 발은 어깨너비로 벌립니다.","엉덩이 근육에 힘을 주고 천천히 무릎을 바깥쪽으로 회전시키며 밴드의 저항에 밀어냅니다.","동작의 끝에서 잠깐 멈춘 후 천천히 시작 자세로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","quadriceps"]', 'glutes', 'images/0996-9gbyYKk.jpg', 'videos/0996-9gbyYKk.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1011', 'band seated twist', 'waist', 'waist', 'band', '{"en":["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Siediti a terra con le gambe distese davanti a te e la schiena dritta.","Avvolgi la fascia intorno alla vita e tieni le estremità con entrambe le mani.","Contrai gli addominali e ruota lentamente il busto da un lato, mantenendo la schiena dritta e i piedi a terra.","Fare una pausa per un momento alla fine della torsione, quindi tornare lentamente alla posizione di partenza.","Ripeti la torsione dall''altro lato.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Bacaklarınız önünüzde uzatılmış ve sırtınız düz olacak şekilde yere oturun.","Bandı belinizin etrafına sarın ve uçlarını iki elinizle tutun.","Karın kaslarınızı devreye sokun ve sırtınızı düz ve ayaklarınızı yerde tutarak gövdenizi yavaşça bir tarafa doğru çevirin.","Dönüşün sonunda bir süre duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","Bükmeyi diğer tarafa tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Siéntate en el suelo con las piernas extendidas frente a ti y la espalda recta.","Envuelve la banda alrededor de la cintura y sostén los extremos con ambas manos.","Activa el abdomen y gira lentamente el torso hacia un lado, manteniendo la espalda recta y los pies en el suelo.","Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Сядьте на пол, вытянув ноги перед собой и выпрямив спину.","Оберните ленту вокруг талии и возьмитесь за концы обеими руками.","Напрягите пресс и медленно поверните туловище в сторону, сохраняя спину прямой и ноги на земле.","Сделайте небольшую паузу в конце поворота, затем медленно вернитесь в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["坐在地上，双腿向前伸展，背部挺直。","将带子绕在腰上，并用双手握住两端。","收紧腹肌，慢慢将躯干扭向一侧，保持背部挺直，双脚着地。","扭转结束时暂停片刻，然后慢慢回到起始位置。","重复扭转到另一侧。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को अपने सामने फैलाकर और अपनी पीठ को सीधा करके जमीन पर बैठें।","बैंड को अपनी कमर के चारों ओर लपेटें और सिरों को दोनों हाथों से पकड़ें।","अपने पेट को संलग्न करें और धीरे-धीरे अपने धड़ को एक तरफ मोड़ें, अपनी पीठ को सीधा रखें और अपने पैरों को जमीन पर रखें।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ मोड़ को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Usiądź na podłodze z nogami wyciągniętymi przed sobą i prostymi plecami.","Owiń taśmę wokół talii i trzymaj końce obiema rękami.","Napnij mięśnie brzucha i powoli skręć tułów w jedną stronę, utrzymując proste plecy i stopy na podłodze.","Zatrzymaj się na chwilę na końcu skrętu, a następnie powoli wróć do pozycji wyjściowej.","Powtórz skręt w drugą stronę.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["바닥에 앉아 다리를 앞으로 펼치고 등을 곧게 펼칩니다.","밴드를 허리 주위에 감고 양손으로 양쪽 끝을 잡습니다.","복부에 힘을 주고 천천히 상체를 한쪽으로 비틀되 등을 곧게 펼치고 발을 바닥에 붙인 상태를 유지합니다.","비틀림의 끝에서 잠깐 멈춘 후 천천히 시작 자세로 돌아갑니다.","반대쪽으로 비틉니다.","계속 양쪽을 번갈아 원하는 반복 횟수만큼 반복합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/1011-S1JXDAG.jpg', 'videos/1011-S1JXDAG.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0997', 'band shoulder press', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona la fascia sotto i piedi.","Tieni la fascia con i palmi rivolti in avanti e alza le mani all''altezza delle spalle, con i gomiti piegati.","Premi la fascia sopra la testa, estendendo completamente le braccia.","Fermati per un momento in alto, quindi abbassa lentamente la fascia all''altezza delle spalle.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayaklarınızın altına yerleştirin.","Bandı avuçlarınız öne bakacak şekilde tutun ve ellerinizi omuz hizasına kadar kaldırın, dirsekleriniz bükülü olsun.","Kollarınızı tamamen uzatarak bandı başınızın üzerine bastırın.","Üst kısımda bir an duraklayın, ardından bandı yavaşça omuz yüksekliğine indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.","Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ленту ладонями вперед и поднимите руки на высоту плеч, локти согнуты.","Нажмите на ленту над головой, полностью выпрямив руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите ленту обратно на высоту плеч.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在脚下。","手掌朝前握住弹力带，将双手举至肩高，肘部弯曲。","将弹力带压过头顶，充分伸展双臂。","在顶部暂停片刻，然后慢慢将阻力带降低至肩部高度。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को आगे की ओर रखते हुए बैंड को पकड़ें और अपने हाथों को कंधे की ऊंचाई तक उठाएं, कोहनियां मुड़ी हुई हों।","अपनी बाहों को पूरी तरह फैलाते हुए बैंड को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बैंड को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę pod stopami.","Trzymaj taśmę dłońmi skierowanymi do przodu i unieś ręce na wysokość barków, łokcie ugięte.","Wypchnij taśmę nad głowę, w pełni prostując ramiona.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść taśmę z powrotem na wysokość barków.","Powtórz zalecaną liczbę razy."],"ko":["발을 어깨너비로 벌리고 서서 발 아래에 밴드를 놓습니다.","손바닥이 앞을 향하게 하여 밴드를 잡고 손을 어깨 높이로 올려 팔꿈치를 구부립니다.","밴드를 머리 위로 눌러 팔을 완전히 펼칩니다.","꼭짓점에서 잠깐 멈춘 후 천천히 밴드를 어깨 높이로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/0997-peAeMR3.jpg', 'videos/0997-peAeMR3.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1018', 'band shrug', 'back', 'back', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona la fascia sotto i piedi, tenendo le estremità con le mani.","Tieni le braccia tese e rilassate e lascia che la fascia penda davanti alle cosce.","Attacca le tue trappole alzando le spalle verso l''alto, sollevando la fascia il più in alto possibile.","Mantieni la contrazione per un momento, quindi abbassa lentamente le spalle fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayaklarınızın altına yerleştirin, uçlarını ellerinizle tutun.","Kollarınızı düz ve rahat tutun ve bandın uyluklarınızın önünde asılı kalmasına izin verin.","Omuzlarınızı yukarı doğru silkerek ve bandı mümkün olduğu kadar yükseğe kaldırarak tuzaklarınızı devreye sokun.","Bir süre kasılmayı sürdürün, ardından omuzlarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies, sosteniendo los extremos con las manos.","Mantén los brazos rectos y relajados, y deja que la banda cuelgue frente a los muslos.","Activa los trapecios encogiendo los hombros hacia arriba, levantando la banda lo más alto posible.","Mantén la contracción por un momento, luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, расставив ноги на ширине плеч, и поместите ленту под ноги, держа концы руками.","Держите руки прямыми и расслабленными, позвольте ленте свисать перед бедрами.","Задействуйте трапеции, пожимая плечами вверх и поднимая ленту как можно выше.","Удерживайте напряжение на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在脚下，用手握住两端。","保持手臂伸直并放松，让弹力带悬挂在大腿前面。","向上耸肩，尽可能高地举起弹力带，以启动斜方肌。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें, अपने हाथों से सिरों को पकड़ें।","अपनी भुजाओं को सीधा और शिथिल रखें और बैंड को अपनी जांघों के सामने लटका रहने दें।","अपने कंधों को ऊपर की ओर झुकाकर, बैंड को जितना संभव हो उतना ऊपर उठाकर अपने जाल को संलग्न करें।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę pod stopami, trzymając jej końce dłońmi.","Utrzymuj ramiona proste i rozluźnione, pozwalając taśmie zwisać przed udami.","Napnij mięśnie czworoboczne, unosząc barki w górę, jak najwyżej to możliwe.","Utrzymaj napięcie przez chwilę, a następnie powoli opuść barki z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 발 아래에 놓고 양쪽 끝을 손으로 잡습니다.","팔을 곧게 펼친 채로 이완하여 밴드가 넓적다리 앞에 매달리도록 합니다.","어깨를 위로 올려서 승모근을 활성화하여 밴드를 최대한 높이 들어 올립니다.","수축 상태를 잠시 유지한 후, 천천히 어깨를 원래 위치로 내립니다.","원하는 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'traps', 'images/1018-trmte8s.jpg', 'videos/1018-trmte8s.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0998', 'band side triceps extension', 'upper arms', 'upper arms', 'band', '{"en":["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere la fascia con entrambe le mani, i palmi rivolti verso il basso.","Estendi le braccia verso i lati, mantenendole parallele al suolo.","Piega lentamente i gomiti e porta le mani verso le spalle, mantenendo ferma la parte superiore delle braccia.","Fai una pausa per un momento, quindi estendi lentamente le braccia nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı iki elinizle, avuçlarınız aşağıya bakacak şekilde tutun.","Kollarınızı yere paralel olacak şekilde yanlara doğru uzatın.","Dirseklerinizi yavaşça bükün ve üst kollarınızı sabit tutarak ellerinizi omuzlarınıza doğru getirin.","Bir an duraklayın, ardından kollarınızı yavaşça başlangıç ​​pozisyonuna geri uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos, con las palmas hacia abajo.","Extiende los brazos hacia los lados, manteniéndolos paralelos al suelo.","Flexiona lentamente los codos y lleva las manos hacia los hombros, manteniendo quieta la parte superior de los brazos.","Haz una pausa por un momento, luego extiende lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмитесь за ленту обеими руками ладонями вниз.","Вытяните руки прямо в стороны, держа их параллельно земле.","Медленно согните локти и поднесите руки к плечам, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем медленно вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，双手握住弹力带，掌心朝下。","将手臂伸直至两侧，保持与地面平行。","慢慢弯曲肘部，将双手放在肩膀上，保持上臂不动。","暂停片刻，然后慢慢将手臂伸回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी भुजाओं को ज़मीन के समानांतर रखते हुए, भुजाओं तक सीधा फैलाएँ।","धीरे-धीरे अपनी कोहनियों को मोड़ें और अपने हाथों को अपने कंधों की ओर लाएं, अपनी ऊपरी भुजाओं को स्थिर रखें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj taśmę obiema rękami, dłonie skierowane w dół.","Wyprostuj ramiona na boki, równolegle do podłogi.","Powoli uginaj łokcie i przyciągaj dłonie w kierunku barków, utrzymując ramiona nieruchome.","Zatrzymaj się na chwilę, a następnie powoli wyprostuj ramiona z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 두 손으로 밴드를 잡되 손바닥이 아래를 향하도록 합니다.","팔을 옆으로 곧게 뻗어 지면과 평행하게 유지합니다.","천천히 팔꿈치를 구부려 양손을 어깨 쪽으로 가져오면서 위팔은 고정합니다.","잠시 멈춘 후, 천천히 팔을 처음 위치로 뻗어냅니다.","원하는 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0998-obe5LMq.jpg', 'videos/0998-obe5LMq.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0999', 'band single leg calf raise', 'lower legs', 'lower legs', 'band', '{"en":["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."],"it":["Stai con i piedi alla larghezza dei fianchi e posiziona la fascia attorno alla pianta del piede sinistro.","Se necessario, aggrapparsi a un oggetto stabile per mantenere l''equilibrio.","Solleva lentamente il tallone sinistro da terra, sollevando il peso del corpo sulla pianta del piede.","Fai una pausa per un momento in alto, quindi abbassa lentamente il tallone sinistro fino alla posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi passa alla gamba destra."],"tr":["Ayaklarınızı kalça genişliğinde açın ve bandı sol ayağınızın topuğunun etrafına yerleştirin.","Gerekirse denge için sabit bir nesneye tutunun.","Vücut ağırlığınızı ayak parmaklarınızın ucuna vererek sol topuğunuzu yavaşça yerden kaldırın.","Tepe noktasında bir an duraklayın, ardından sol topuğunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından sağ bacağa geçin."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie izquierdo.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta lentamente el talón izquierdo del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón izquierdo de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la pierna derecha."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на подушечку левой стопы.","При необходимости держитесь за устойчивый предмет для равновесия.","Медленно поднимите левую пятку от земли, перенеся вес тела на подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите левую пятку обратно в исходное положение.","Повторите необходимое количество повторений, затем переключитесь на правую ногу."],"zh":["双脚分开站立，与臀部同宽，将弹力带绕在左脚掌上。","如果需要，请抓住一个稳定的物体以保持平衡。","慢慢地将左脚跟抬离地面，将身体重量转移到脚掌上。","在顶部暂停片刻，然后慢慢将左脚跟放回起始位置。","重复所需的重复次数，然后换右腿。"],"hi":["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और बैंड को अपने बाएं पैर की गेंद के चारों ओर रखें।","यदि आवश्यक हो तो संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","धीरे-धीरे अपनी बायीं एड़ी को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैर की गेंद पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बायीं एड़ी को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दाहिने पैर पर स्विच करें।"],"pl":["Stań w rozkroku na szerokość bioder i umieść taśmę wokół podeszwy lewej stopy.","Chwyć się stabilnego obiektu dla równowagi, jeśli to konieczne.","Powoli unieś lewą piętę nad podłogę, przenosząc ciężar ciała na przednią część stopy.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść lewą piętę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień nogę na prawą."],"ko":["엉덩이 너비로 발을 벌리고 서서 밴드를 왼쪽 발 앞부분에 감습니다.","필요하면 안정성을 위해 견고한 물체를 잡습니다.","천천히 왼쪽 발꿈치를 지면에서 들어 발 앞부분에 체중을 올립니다.","맨 위에서 잠시 멈춘 후, 천천히 왼쪽 발꿈치를 원래 위치로 내립니다.","원하는 횟수만큼 반복한 후 오른쪽 다리로 전환합니다."]}', 'ankles', '["ankles","feet"]', 'calves', 'images/0999-9JprnPh.jpg', 'videos/0999-9JprnPh.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1000', 'band single leg reverse calf raise', 'lower legs', 'lower legs', 'band', '{"en":["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."],"it":["Stai con i piedi alla larghezza dei fianchi e posiziona la fascia attorno alla pianta del piede.","Aggrapparsi a un oggetto stabile per mantenere l''equilibrio.","Solleva lentamente il tallone da terra, sollevando il peso del corpo sulla pianta del piede.","Fai una pausa per un momento in alto, quindi abbassa lentamente il tallone fino alla posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi passa all''altra gamba."],"tr":["Ayaklarınızı kalça genişliğinde açın ve bandı ayak parmaklarınızın etrafına yerleştirin.","Denge için sabit bir nesneye tutunun.","Vücut ağırlığınızı ayak parmaklarınızın ucuna vererek topuğunuzu yavaşça yerden kaldırın.","Tepe noktasında bir an duraklayın, ardından topuğunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer bacağa geçin."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.","Sujétate de un objeto estable para mantener el equilibrio.","Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.","Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia a la otra pierna."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на подушечку стопы.","Держитесь за устойчивый предмет для равновесия.","Медленно поднимите пятку от земли, перенеся вес тела на подушечки стопы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятку обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую ногу."],"zh":["双脚分开站立，与臀部同宽，将弹力带放在脚掌周围。","抓住稳定的物体以保持平衡。","慢慢地将脚跟抬离地面，将身体重量转移到脚掌上。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换另一条腿。"],"hi":["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और बैंड को अपने पैर की गेंद के चारों ओर रखें।","संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","धीरे-धीरे अपनी एड़ी को जमीन से ऊपर उठाएं, अपने शरीर का वजन अपने पैर की गेंद पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ी को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ, फिर दूसरे चरण पर जाएँ।"],"pl":["Stań w rozkroku na szerokość bioder i umieść taśmę wokół podeszwy stopy.","Chwyć się stabilnego obiektu dla równowagi.","Powoli unieś piętę nad podłogę, przenosząc ciężar ciała na przednią część stopy.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść piętę z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy, a następnie zmień nogę."],"ko":["엉덩이 너비로 발을 벌리고 서서 밴드를 발 앞부분에 감습니다.","안정성을 위해 견고한 물체를 잡습니다.","천천히 발꿈치를 지면에서 들어 발 앞부분에 체중을 올립니다.","맨 위에서 잠시 멈춘 후, 천천히 발꿈치를 원래 위치로 내립니다.","원하는 횟수만큼 반복한 후 다른 다리로 전환합니다."]}', 'hamstrings', '["hamstrings","glutes"]', 'calves', 'images/1000-QsSQWbf.jpg', 'videos/1000-QsSQWbf.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1001', 'band single leg split squat', 'upper legs', 'upper legs', 'band', '{"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."],"it":["Stare con i piedi alla larghezza dei fianchi e posizionare una fascia di resistenza attorno alle caviglie.","Fai un grande passo avanti con il piede destro e un piccolo passo indietro con il piede sinistro.","Piega le ginocchia e abbassa il corpo finché la coscia destra non è parallela al suolo, mantenendo il ginocchio sinistro leggermente sopra il suolo.","Spingi attraverso il tallone destro per tornare alla posizione di partenza.","Ripeti dall''altra parte."],"tr":["Ayaklarınızı kalça genişliğinde açın ve ayak bileklerinizin etrafına bir direnç bandı yerleştirin.","Sağ ayağınızla ileriye doğru büyük bir adım atın ve sol ayağınızla geriye doğru daha küçük bir adım atın.","Dizlerinizi bükün ve sağ uyluğunuz yere paralel oluncaya kadar vücudunuzu indirin, sol dizinizi yerden biraz yukarıda tutun.","Başlangıç ​​pozisyonuna dönmek için sağ topuğunuzu itin.","Diğer tarafta tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de las caderas y coloca una banda elástica alrededor de los tobillos.","Da un paso grande hacia adelante con el pie derecho y un paso más pequeño hacia atrás con el pie izquierdo.","Flexiona las rodillas y baja el cuerpo hasta que el muslo derecho quede paralelo al suelo, manteniendo la rodilla izquierda ligeramente por encima del suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite del otro lado."],"ru":["Встаньте, ноги на ширине плеч, и наденьте эластичную ленту на лодыжки.","Сделайте большой шаг вперед правой ногой и маленький шаг назад левой ногой.","Согните колени и опустите тело до тех пор, пока правое бедро не станет параллельно земле, сохраняя левое колено немного выше земли.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите с другой стороны."],"zh":["双脚分开站立，与臀部同宽，将阻力带绕在脚踝上。","右脚向前迈一大步，左脚向后退一小步。","弯曲膝盖并降低身体，直到右大腿与地面平行，保持左膝盖略高于地面。","推动右脚跟回到起始位置。","在另一侧重复。"],"hi":["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं और अपनी एड़ियों के चारों ओर एक प्रतिरोध बैंड लगाएं।","अपने दाहिने पैर से एक बड़ा कदम आगे बढ़ाएं और अपने बाएं पैर से एक छोटा कदम पीछे लें।","अपने घुटनों को मोड़ें और अपने शरीर को तब तक नीचे रखें जब तक कि आपकी दाहिनी जांघ जमीन के समानांतर न हो जाए, अपने बाएं घुटने को जमीन से थोड़ा ऊपर रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","दूसरी तरफ दोहराएं।"],"pl":["Stań w rozkroku na szerokość bioder i umieść taśmę oporową wokół kostek.","Zrób duży krok do przodu prawą stopą i mniejszy krok do tyłu lewą stopą.","Ugnij kolana i opuść ciało, aż prawe udo będzie równoległe do podłogi, utrzymując lewe kolano lekko nad podłogą.","Odepchnij się prawą piętą, aby wrócić do pozycji wyjściowej.","Powtórz po drugiej stronie."],"ko":["엉덩이 너비로 발을 벌리고 서서 저항 밴드를 발목 주위에 감습니다.","오른쪽 발로 크게 한 발 앞으로 나가고 왼쪽 발로는 작게 뒤로 물러나갑니다.","무릎을 구부려 몸을 내리면서 오른쪽 넓적다리가 지면과 평행하게 되고 왼쪽 무릎은 약간 지면 위에 있도록 합니다.","오른쪽 발꿈치를 통해 밀어 원래 위치로 돌아옵니다.","다른 쪽에서 반복합니다."]}', 'glutes', '["glutes","hamstrings"]', 'quads', 'images/1001-y8bYM8w.jpg', 'videos/1001-y8bYM8w.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1004', 'band squat', 'upper legs', 'upper legs', 'band', '{"en":["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle, con la fascia posizionata appena sopra le ginocchia.","Mantenendo il petto in alto e il core impegnato, spingi i fianchi indietro e piega le ginocchia per abbassarti in una posizione tozza.","Assicurati che le ginocchia seguano le dita dei piedi e che il peso sia sui talloni.","Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, bant dizlerinizin hemen üzerine gelecek şekilde ayakta durun.","Göğsünüzü yukarıda ve göbek bölgenizi meşgul tutarak kalçalarınızı geriye doğru itin ve dizlerinizi bükerek çömelme pozisyonuna gelin.","Dizlerinizin ayak parmaklarınızın üzerinde olduğundan ve ağırlığınızın topuklarınızda olduğundan emin olun.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con la banda colocada justo por encima de las rodillas.","Manteniendo el pecho arriba y el core activado, lleva las caderas hacia atrás y flexiona las rodillas para bajar a una posición de sentadilla.","Asegúrate de que las rodillas se alineen con los dedos de los pies y de que el peso recaiga en los talones.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч, расположив ленту чуть выше колен.","Удерживая грудь поднятой и напряженным корпус, отведите бедра назад и согните колени, чтобы опуститься в присед.","Убедитесь, что ваши колени касаются пальцев ног, а ваш вес приходится на пятки.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开站立，与肩同宽，弹力带放在膝盖上方。","保持挺胸、核心收紧，将臀部向后推，弯曲膝盖，形成下蹲姿势。","确保膝盖位于脚趾上方，并且重量位于脚后跟。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े रहें और बैंड को अपने घुटनों के ठीक ऊपर रखें।","अपनी छाती को ऊपर और मुख्य भाग को ऊपर रखते हुए, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को मोड़कर स्क्वाट स्थिति में आ जाएँ।","सुनिश्चित करें कि आपके घुटने आपके पैर की उंगलियों पर हों और आपका वजन आपकी एड़ियों पर हो।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z taśmą umieszczoną tuż nad kolanami.","Utrzymując wypiętą klatkę piersiową i napięty brzuch, wypchnij biodra do tyłu i ugnij kolana, opuszczając ciało do pozycji przysiadu.","Upewnij się, że kolana podążają w linii z palcami stóp, a ciężar ciała spoczywa na piętach.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie odepchnij się piętami, aby wrócić do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 무릎 바로 위에 배치합니다.","가슴을 펴고 코어를 활성화하면서 엉덩이를 뒤로 밀고 무릎을 구부려 스쿼트 자세로 내립니다.","무릎이 발가락 위로 정렬되고 체중이 발꿈치에 있는지 확인합니다.","맨 아래에서 잠시 멈춘 후, 발꿈치를 통해 밀어 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/1004-TUZLh71.jpg', 'videos/1004-TUZLh71.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1003', 'band squat row', 'upper legs', 'upper legs', 'band', '{"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio robusto all''altezza della vita.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Tieni le maniglie della fascia con i palmi delle mani uno di fronte all''altro e le braccia distese davanti a te.","Piega le ginocchia e abbassati in posizione tozza, mantenendo la schiena dritta e il petto sollevato.","Dalla posizione tozza, tira le maniglie della fascia verso il tuo corpo, stringendo insieme le scapole.","Fermati per un momento in alto, quindi rilascia lentamente la tensione e torna alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı bel yüksekliğinde sağlam bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde bağlantı noktasına bakacak şekilde durun.","Bandın saplarını avuçlarınız birbirine bakacak ve kollarınız önünüzde uzatılmış şekilde tutun.","Dizlerinizi bükün ve çömelme pozisyonuna alçaltın, sırtınızı düz ve göğsünüzü yukarıda tutun.","Çömelme pozisyonundan, kürek kemiklerinizi birbirine doğru sıkıştırarak bandın saplarını vücudunuza doğru çekin.","Tepe noktasında bir an duraklayın, ardından yavaşça gerilimi bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona las rodillas y baja a una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Desde la posición de sentadilla, tira de las agarraderas de la banda hacia el cuerpo, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Держите ручки лент ладонями друг к другу, а руки вытянуты перед собой.","Согните колени и опуститесь в присед, сохраняя спину прямой и грудь поднятой.","Из положения приседа потяните ручки лент к себе, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将带子固定在腰部高度的坚固锚点上。","面向锚点站立，双脚分开与肩同宽。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","弯曲膝盖并蹲下，保持背部挺直，挺胸。","从蹲姿开始，将弹力带手柄拉向身体，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपने सामने फैलाकर बैंड के हैंडल को पकड़ें।","अपने घुटनों को मोड़ें और स्क्वाट स्थिति में आ जाएं, अपनी पीठ सीधी रखें और छाती ऊपर उठाएं।","स्क्वाट स्थिति से, अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड के हैंडल को अपने शरीर की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości talii.","Stań przodem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Trzymaj uchwyty taśmy dłońmi zwróconymi do siebie, ramiona wyciągnięte przed sobą.","Ugnij kolana i opuść się do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.","Z pozycji przysiadu przyciągnij uchwyty taśmy w kierunku ciała, ściskając łopatki.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli zwolnij napięcie i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 허리 높이의 견고한 고정점에 부착합니다.","고정점을 향해 어깨 너비로 발을 벌리고 서서 밴드를 직면합니다.","밴드 손잡이를 손바닥이 서로 마주 보도록 잡고 팔을 앞으로 쭉 뻗습니다.","무릎을 구부려 스쿼트 자세로 내리면서 등을 곧게 펴고 가슴을 들어 올립니다.","스쿼트 위치에서 밴드 손잡이를 몸 쪽으로 당기며 어깨날을 조입니다.","맨 위에서 잠시 멈춘 후, 천천히 장력을 풀고 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","quadriceps","back"]', 'glutes', 'images/1003-w1NOByi.jpg', 'videos/1003-w1NOByi.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1005', 'band standing crunch', 'waist', 'waist', 'band', '{"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio robusto all''altezza della vita.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Tieni la fascia con entrambe le mani e portala al petto, mantenendo i gomiti piegati e vicini al corpo.","Coinvolgi gli addominali e esegui lentamente uno scricchiolio in avanti, portando il petto verso le ginocchia.","Fermati per un momento al culmine del crunch, quindi torna lentamente alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı bel yüksekliğinde sağlam bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde, bağlantı noktasından uzağa bakacak şekilde durun.","Bandı iki elinizle tutun ve dirseklerinizi bükülü ve vücudunuza yakın tutarak göğsünüze doğru kaldırın.","Karın kaslarınızı devreye sokun ve yavaşça öne doğru çömelerek göğsünüzü dizlerinize doğru getirin.","Çıtırlığın zirvesinde bir an duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje resistente a la altura de la cintura.","Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros.","Sostén la banda con ambas manos y llévala hacia el pecho, manteniendo los codos flexionados y cerca del cuerpo.","Activa el abdomen y flexiona lentamente el torso hacia adelante, llevando el pecho hacia las rodillas.","Haz una pausa por un momento en la parte más alta del movimiento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ремешок к прочной точке крепления на высоте талии.","Встаньте лицом от точки крепления, поставив ноги на ширине плеч.","Возьмите ленту обеими руками и поднесите ее к груди, держа локти согнутыми и близко к телу.","Напрягите пресс и медленно наклонитесь вперед, приближая грудь к коленям.","Сделайте паузу на мгновение в верхней точке скручивания, затем медленно вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将带子固定在腰部高度的坚固锚点上。","背对锚点站立，双脚与肩同宽。","用双手握住弹力带并将其举至胸前，保持肘部弯曲并靠近身体。","收紧腹肌，慢慢向前挺胸，使胸部靠近膝盖。","在卷腹的最高点暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को कमर की ऊंचाई पर एक मजबूत एंकर पॉइंट से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट से दूर की ओर मुंह करके खड़े हो जाएं।","बैंड को दोनों हाथों से पकड़ें और इसे अपनी छाती तक ले आएं, अपनी कोहनियों को मोड़कर अपने शरीर के करीब रखें।","अपने पेट को संलग्न करें और अपनी छाती को अपने घुटनों की ओर लाते हुए धीरे-धीरे आगे की ओर झुकें।","क्रंच के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do stabilnego punktu zaczepienia na wysokości talii.","Stań tyłem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Trzymaj taśmę obiema rękami i przyciągnij ją do klatki piersiowej, utrzymując łokcie ugięte i blisko ciała.","Napnij mięśnie brzucha i powoli wykonaj skłon do przodu, przyciągając klatkę piersiową w kierunku kolan.","Zatrzymaj się na chwilę w górnej fazie skłonu, a następnie powoli wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 허리 높이의 견고한 고정점에 부착합니다.","고정점에서 등을 돌려 어깨 너비로 발을 벌리고 서서 밴드를 직면합니다.","밴드를 양손으로 잡고 가슴 높이로 가져오되 팔꿈치를 구부려 몸에 가깝게 유지합니다.","복근을 활성화하고 천천히 앞으로 구부려 가슴을 무릎 쪽으로 향하게 합니다.","크런치의 최상단에서 잠시 멈춘 후, 천천히 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/1005-Kzg30R7.jpg', 'videos/1005-Kzg30R7.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1022', 'band standing rear delt row', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona la fascia sotto i piedi.","Tieni le maniglie della fascia con i palmi delle mani uno di fronte all''altro e le braccia distese davanti a te.","Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta.","Tira la fascia verso il petto, stringendo insieme le scapole.","Fermati per un momento in alto, quindi rilascia lentamente la tensione e torna alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayaklarınızın altına yerleştirin.","Bandın saplarını avuçlarınız birbirine bakacak ve kollarınız önünüzde uzatılmış şekilde tutun.","Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin.","Bandı göğsünüze doğru çekin, kürek kemiklerinizi birbirine sıkıştırın.","Tepe noktasında bir an duraklayın, ardından yavaşça gerilimi bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Tira de la banda hacia el pecho, juntando los omóplatos.","Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ручки лент ладонями друг к другу, а руки вытянуты перед собой.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Потяните ленту к груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在脚下。","双手握住弹力带手柄，手掌相对，双臂向前伸展。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将弹力带拉向胸部，将肩胛骨挤压在一起。","在最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपने सामने फैलाकर बैंड के हैंडल को पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बैंड को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę pod stopami.","Trzymaj uchwyty taśmy dłońmi zwróconymi do siebie, ramiona wyciągnięte przed sobą.","Ugnij lekko kolana i pochyl się do przodu w biodrach, utrzymując proste plecy.","Przyciągnij taśmę w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli zwolnij napięcie i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 발 아래에 놓습니다.","밴드 손잡이를 손바닥이 서로 마주 보도록 잡고 팔을 앞으로 쭉 뻗습니다.","무릎을 약간 구부리고 허리에서 앞으로 숙이면서 등을 곧게 펩니다.","밴드를 가슴 쪽으로 당기며 어깨날을 조입니다.","맨 위에서 잠시 멈춘 후, 천천히 장력을 풀고 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'trapezius', '["trapezius","rhomboids","biceps"]', 'delts', 'images/1022-tc5dYrf.jpg', 'videos/1022-tc5dYrf.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1007', 'band standing twisting crunch', 'waist', 'waist', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e posizionare la fascia attorno alla parte superiore della schiena, incrociandola davanti al petto.","Tieni le estremità della fascia con le mani, mantenendo i gomiti piegati e vicini ai fianchi.","Contrai gli addominali e ruota il busto da un lato, portando il gomito verso il ginocchio opposto.","Fare una pausa per un momento, quindi tornare alla posizione di partenza.","Ripeti dall''altra parte.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı sırtınızın üst kısmına, göğsünüzün önünden geçecek şekilde yerleştirin.","Bandın uçlarını ellerinizle tutun, dirseklerinizi bükülü ve yanlarınıza yakın tutun.","Karın kaslarınızı devreye sokun ve gövdenizi bir tarafa doğru çevirin, dirseğinizi karşı dizinize doğru getirin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönün.","Diğer tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de la espalda, cruzándola frente al pecho.","Sujeta los extremos de la banda con las manos, manteniendo los codos flexionados y cerca de los costados.","Activa el abdomen y gira el torso hacia un lado, llevando el codo hacia la rodilla opuesta.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite del otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, расставив ноги на ширине плеч, и оберните ленту вокруг верхней части спины, пересекая ее перед грудью.","Возьмите концы ленты руками, держа локти согнутыми и прижатыми к бокам.","Напрягите пресс и поверните туловище в одну сторону, приближая локоть к противоположному колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите с другой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带绕在上背部，穿过胸前。","用手握住带子的末端，保持肘部弯曲并靠近身体两侧。","收紧腹肌并将躯干向一侧扭转，将肘部移向另一侧的膝盖。","暂停片刻，然后回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं और बैंड को अपनी ऊपरी पीठ के चारों ओर रखें, इसे अपनी छाती के सामने पार करें।","बैंड के सिरों को अपने हाथों से पकड़ें, अपनी कोहनियों को मोड़कर अपनी भुजाओं के पास रखें।","अपने पेट को संलग्न करें और अपने धड़ को एक तरफ मोड़ें, अपनी कोहनी को विपरीत घुटने की ओर लाएं।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę na górnej części pleców, krzyżując ją przed klatką piersiową.","Trzymaj końce taśmy dłońmi, utrzymując łokcie ugięte i blisko boków ciała.","Napnij mięśnie brzucha i skręć tułów w jedną stronę, przyciągając łokieć w kierunku przeciwległego kolana.","Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej.","Powtórz po drugiej stronie.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 등 위쪽에 감아 가슴 앞에서 교차하게 합니다.","밴드 끝을 손으로 잡되 팔꿈치를 구부려 몸 옆에 가깝게 유지합니다.","복근을 활성화하고 몸통을 한쪽으로 비틀면서 팔꿈치를 반대쪽 무릎 쪽으로 가져옵니다.","잠시 멈춘 후, 원래 위치로 돌아옵니다.","다른 쪽에서 반복합니다.","양쪽을 번갈아 계속합니다."]}', 'obliques', '["obliques"]', 'abs', 'images/1007-euq4pwp.jpg', 'videos/1007-euq4pwp.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1008', 'band step-up', 'upper legs', 'upper legs', 'band', '{"en":["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."],"it":["Metti una fascia intorno alle cosce, appena sopra le ginocchia.","Mettiti di fronte a un gradino o a una piattaforma con i piedi alla larghezza dei fianchi.","Sali sulla piattaforma con il piede destro, spingendo attraverso il tallone.","Estendi la gamba sinistra dietro di te, mantenendola dritta.","Abbassa di nuovo il piede sinistro a terra.","Ripeti con il piede sinistro salendo sulla piattaforma.","Continua ad alternare le gambe per il numero di ripetizioni desiderato."],"tr":["Bir bandı uyluklarınızın çevresine, dizlerinizin hemen üstüne yerleştirin.","Ayaklarınız kalça genişliğinde açık olacak şekilde bir basamağa veya platforma dönük durun.","Sağ ayağınızla topuğunuzu iterek platforma çıkın.","Sol bacağınızı düz tutarak arkanıza doğru uzatın.","Sol ayağınızı tekrar yere indirin.","Sol ayağınızla platforma adım atarak tekrarlayın.","İstenilen sayıda tekrar için bacakları değiştirerek devam edin."],"es":["Coloca una banda alrededor de los muslos, justo por encima de las rodillas.","Ponte de pie frente a un escalón o plataforma con los pies separados a la altura de las caderas.","Sube a la plataforma con el pie derecho, empujando con el talón.","Extiende la pierna izquierda hacia atrás, manteniéndola recta.","Baja el pie izquierdo de nuevo hasta el suelo.","Repite subiendo a la plataforma con el pie izquierdo.","Continúa alternando las piernas durante el número de repeticiones deseado."],"ru":["Наденьте резинку на бедра, чуть выше колен.","Встаньте лицом к ступеньке или платформе, поставив ноги на ширине плеч.","Встаньте на платформу правой ногой, отталкиваясь пяткой.","Вытяните левую ногу позади себя, сохраняя ее прямой.","Опустите левую ногу обратно на землю.","Повторите то же самое, вставив левую ногу на платформу.","Продолжайте чередовать ноги желаемое количество повторений."],"zh":["将一条带子绕在大腿上，就在膝盖上方。","面向台阶或平台站立，双脚分开与臀部同宽。","用右脚踩上平台，用脚后跟推动。","将左腿伸到身后，保持伸直。","将左脚放回地面。","重复左脚踩上平台的动作。","继续交替双腿达到所需的重复次数。"],"hi":["अपने घुटनों के ठीक ऊपर, अपनी जाँघों के चारों ओर एक बैंड रखें।","अपने पैरों को कूल्हे की चौड़ाई के बराबर दूरी पर रखते हुए किसी सीढ़ी या मंच की ओर मुंह करके खड़े हो जाएं।","अपने दाहिने पैर के साथ मंच पर कदम रखें, अपनी एड़ी को धक्का देते हुए।","अपने बाएँ पैर को सीधा रखते हुए अपने पीछे फैलाएँ।","अपने बाएँ पैर को वापस ज़मीन पर टिकाएँ।","अपने बाएँ पैर को प्लेटफ़ॉर्म पर आगे बढ़ाते हुए दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"],"pl":["Umieść taśmę wokół ud, tuż nad kolanami.","Stań przodem do stopnia lub platformy, stopy w rozkroku na szerokość bioder.","Wejdź na platformę prawą stopą, odpychając się piętą.","Wyprostuj lewą nogę za sobą, utrzymując ją prostą.","Opuść lewą stopę z powrotem na podłogę.","Powtórz, wchodząc na platformę lewą stopą.","Kontynuuj naprzemienne wykonywanie ruchu przez zalecaną liczbę powtórzeń."],"ko":["밴드를 무릎 바로 위 넓적다리 주위에 감습니다.","계단이나 플랫폼을 향해 엉덩이 너비로 발을 벌리고 섭니다.","오른쪽 발로 플랫폼에 올라가면서 발꿈치를 통해 밀어냅니다.","왼쪽 다리를 뒤로 곧게 뻗습니다.","왼쪽 발을 땅에 내립니다.","왼쪽 발로 플랫폼에 올라가도록 반복합니다.","원하는 횟수만큼 다리를 번갈아 계속합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/1008-d5bTEPV.jpg', 'videos/1008-d5bTEPV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1009', 'band stiff leg deadlift', 'upper legs', 'upper legs', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona la fascia attorno alle caviglie.","Tieni la fascia con entrambe le mani davanti alle cosce, con i palmi rivolti verso il corpo.","Tenendo la schiena dritta e il core impegnato, fai perno sui fianchi e abbassa lentamente la parte superiore del corpo verso terra.","Mentre ti abbassi, spingi indietro i fianchi e lascia che le ginocchia si pieghino leggermente.","Abbassa la fascia verso terra, sentendo l''allungamento dei muscoli posteriori della coscia.","Fai una pausa per un momento in fondo, quindi coinvolgi i glutei e i muscoli posteriori della coscia per riportare la parte superiore del corpo alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayak bileklerinizin etrafına yerleştirin.","Bandı iki elinizle uyluklarınızın önünde, avuçlarınız vücudunuza bakacak şekilde tutun.","Sırtınızı düz ve merkez bölgenizi meşgul tutarak kalçalarınıza yaslanın ve üst vücudunuzu yavaşça yere doğru indirin.","Alçalırken kalçalarınızı geriye doğru itin ve dizlerinizin hafifçe bükülmesine izin verin.","Diz arkası kirişlerinizde bir gerginlik hissederek bandı yere doğru indirin.","Altta bir an duraklayın, ardından kalça kaslarınızı ve diz arkası kaslarınızı çalıştırarak üst vücudunuzu başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los tobillos.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y el core activado, flexiona las caderas y baja lentamente la parte superior del cuerpo hacia el suelo.","Mientras bajas, empuja las caderas hacia atrás y deja que las rodillas se flexionen ligeramente.","Baja la banda hacia el suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve en la posición baja, luego activa los glúteos y los isquiotibiales para levantar la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на лодыжки.","Держите ленту обеими руками перед бедрами, ладонями к телу.","Удерживая спину прямой и корпус напряженным, наклонитесь в бедрах и медленно опустите верхнюю часть тела к земле.","Опускаясь, отведите бедра назад и позвольте коленям слегка согнуться.","Опустите ленту к земле, чувствуя растяжение подколенных сухожилий.","Задержитесь на мгновение в нижней точке, затем задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开站立，与肩同宽，将弹力带绕在脚踝上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，核心收紧，铰接臀部，慢慢将上半身降低到地面。","当你降低时，将臀部向后推，并让膝盖稍微弯曲。","将弹力带降低至地面，感受腿筋的拉伸。","在底部暂停片刻，然后启动臀肌和腿筋，将上半身抬回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपनी एड़ियों के चारों ओर रखें।","बैंड को दोनों हाथों से अपनी जाँघों के सामने पकड़ें, हथेलियाँ आपके शरीर की ओर।","अपनी पीठ को सीधा और अपने कोर को व्यस्त रखते हुए, कूल्हों पर टिकाएं और धीरे-धीरे अपने ऊपरी शरीर को जमीन की ओर नीचे लाएं।","जैसे ही आप नीचे आते हैं, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को थोड़ा झुकने दें।","अपनी हैमस्ट्रिंग में खिंचाव महसूस करते हुए बैंड को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने ऊपरी शरीर को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę wokół kostek.","Trzymaj taśmę obiema rękami przed udami, dłonie skierowane do ciała.","Utrzymując proste plecy i napięty brzuch, pochyl się w biodrach i powoli opuść górną część ciała w kierunku podłogi.","Opuszczając się, wypchnij biodra do tyłu i pozwól kolanom lekko się ugiąć.","Opuść taśmę w kierunku podłogi, odczuwając rozciąganie w mięśniach dwugłowych uda.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie napnij pośladki i mięśnie dwugłowe uda, aby unieść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 발목 주위에 감습니다.","밴드를 양손으로 넓적다리 앞에 잡되 손바닥이 몸을 향하도록 합니다.","등을 곧게 펴고 코어를 활성화한 상태에서 허리에서 천천히 앞으로 숙입니다.","내리면서 엉덩이를 뒤로 밀고 무릎을 약간 구부립니다.","밴드를 지면 쪽으로 내리며 햄스트링에서 스트레칭을 느낍니다.","맨 아래에서 잠시 멈춘 후, 둔근과 햄스트링을 활성화하여 몸을 원래 위치로 들어 올립니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/1009-kuMiR2T.jpg', 'videos/1009-kuMiR2T.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1023', 'band straight back stiff leg deadlift', 'upper legs', 'upper legs', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e posizionare la fascia attorno alla parte superiore delle gambe.","Tieni la fascia con entrambe le mani davanti alle cosce, con i palmi rivolti verso il corpo.","Tenendo la schiena dritta e le ginocchia leggermente piegate, fai perno sui fianchi e abbassa la fascia verso terra.","Senti l''allungamento dei muscoli posteriori della coscia mentre abbassi la fascia.","Coinvolgi i glutei e i muscoli posteriori della coscia per riportare il corpo alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı üst bacaklarınızın etrafına yerleştirin.","Bandı iki elinizle uyluklarınızın önünde, avuçlarınız vücudunuza bakacak şekilde tutun.","Sırtınızı dik tutun ve dizlerinizi hafifçe bükün, kalçalarınıza yaslanın ve bandı yere doğru indirin.","Bandı indirirken hamstringlerinizdeki gerginliği hissedin.","Vücudunuzu başlangıç ​​pozisyonuna geri kaldırmak için kalça kaslarınızı ve hamstringlerinizi devreye sokun.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de la parte superior de las piernas.","Sujeta la banda con ambas manos frente a los muslos, con las palmas mirando hacia el cuerpo.","Manteniendo la espalda recta y las rodillas ligeramente flexionadas, flexiona las caderas y baja la banda hacia el suelo.","Siente el estiramiento en los isquiotibiales mientras bajas la banda.","Activa los glúteos y los isquiotibiales para levantar el cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на верхнюю часть ног.","Держите ленту обеими руками перед бедрами, ладонями к телу.","Держа спину прямой и слегка согнутыми в коленях, наклонитесь в бедрах и опустите ленту к земле.","Почувствуйте растяжение подколенных сухожилий, когда опускаете ленту.","Задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять тело обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带绕在大腿上。","用双手将弹力带放在大腿前面，手掌朝向身体。","保持背部挺直，膝盖稍微弯曲，铰接臀部并将弹力带降低到地面。","当你降低弹力带时，感受腿筋的拉伸。","启动臀肌和腿筋，将身体抬回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने ऊपरी पैरों के चारों ओर रखें।","बैंड को दोनों हाथों से अपनी जाँघों के सामने पकड़ें, हथेलियाँ आपके शरीर की ओर।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़कर, कूल्हों पर टिकाएं और बैंड को जमीन की ओर नीचे करें।","जैसे ही आप बैंड को नीचे करते हैं, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","अपने शरीर को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę wokół górnej części nóg.","Trzymaj taśmę obiema rękami przed udami, dłonie skierowane do ciała.","Utrzymując proste plecy i lekko ugięte kolana, pochyl się w biodrach i opuść taśmę w kierunku podłogi.","Poczuj rozciąganie w mięśniach dwugłowych uda podczas opuszczania taśmy.","Napnij pośladki i mięśnie dwugłowe uda, aby unieść ciało z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 넓적다리 위쪽에 감습니다.","밴드를 양손으로 넓적다리 앞에 잡되 손바닥이 몸을 향하도록 합니다.","등을 곧게 펴고 무릎을 약간 구부린 상태에서 허리에서 천천히 앞으로 숙입니다.","내리면서 햄스트링에서 스트레칭을 느낍니다.","둔근과 햄스트링을 활성화하여 몸을 원래 위치로 들어 올립니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/1023-lHeUULr.jpg', 'videos/1023-lHeUULr.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1010', 'band straight leg deadlift', 'back', 'back', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e posizionare la fascia attorno ai piedi.","Tieni la fascia con entrambe le mani, i palmi rivolti verso il corpo e mantieni le braccia dritte.","Coinvolgi il core e mantieni una leggera piegatura delle ginocchia.","Piegati lentamente in avanti sui fianchi, mantenendo la schiena dritta e il petto sollevato.","Abbassa la fascia verso terra mantenendo le gambe dritte.","Fai una pausa per un momento in fondo, quindi contrai i glutei e i muscoli posteriori della coscia per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayaklarınızın etrafına yerleştirin.","Bandı iki elinizle, avuçlarınız vücudunuza bakacak şekilde tutun ve kollarınızı düz tutun.","Merkez bölgenizi devreye sokun ve dizlerinizde hafif bir bükülme sağlayın.","Sırtınızı düz ve göğsünüzü yukarıda tutarak kalçalarınızdan yavaşça öne doğru eğilin.","Bacaklarınızı düz tutarak bandı yere doğru indirin.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için kalça kaslarınızı ve diz arkası kaslarınızı sıkın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda alrededor de los pies.","Sujeta la banda con ambas manos, con las palmas mirando hacia el cuerpo, y mantén los brazos rectos.","Activa el core y mantén una ligera flexión en las rodillas.","Inclínate lentamente hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Baja la banda hacia el suelo manteniendo las piernas rectas.","Haz una pausa breve en la posición baja y luego contrae los glúteos y los isquiotibiales para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и наденьте ленту на ступни.","Держите ленту обеими руками ладонями к телу и держите руки прямыми.","Напрягите корпус и сохраняйте небольшой изгиб в коленях.","Медленно наклонитесь вперед в бедрах, сохраняя спину прямой и грудь поднятой.","Опустите ленту к земле, сохраняя ноги прямыми.","Задержитесь на мгновение в нижней точке, затем сожмите ягодицы и мышцы задней поверхности бедра, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带绕在脚上。","双手握住弹力带，手掌朝向身体，手臂伸直。","收紧核心并保持膝盖轻微弯曲。","慢慢地以臀部为中心向前转动，保持背部挺直，挺胸。","将弹力带降低至地面，同时保持双腿伸直。","在底部暂停片刻，然后挤压臀肌和腿筋，回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के चारों ओर रखें।","बैंड को दोनों हाथों से पकड़ें, हथेलियाँ आपके शरीर की ओर हों, और अपनी भुजाएँ सीधी रखें।","अपने कोर को संलग्न करें और अपने घुटनों को थोड़ा मोड़ें।","अपनी पीठ सीधी और छाती ऊपर उठाते हुए धीरे-धीरे अपने कूल्हों पर आगे की ओर झुकें।","अपने पैरों को सीधा रखते हुए बैंड को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर शुरुआती स्थिति में लौटने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę wokół stóp.","Trzymaj taśmę obiema rękami, dłonie skierowane do ciała, ramiona proste.","Napnij mięśnie brzucha i utrzymuj lekkie ugięcie kolan.","Powoli pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.","Opuść taśmę w kierunku podłogi, utrzymując nogi proste.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie ściśnij pośladki i mięśnie dwugłowe uda, aby wrócić do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 발 주위에 감습니다.","밴드를 양손으로 잡되 손바닥이 몸을 향하고 팔을 곧게 펴서 유지합니다.","코어를 활성화하고 무릎을 약간만 구부려서 유지합니다.","허리에서 천천히 앞으로 숙이되 등을 곧게 펴고 가슴을 든 상태를 유지합니다.","다리를 곧게 펼친 상태로 밴드를 지면 쪽으로 내립니다.","맨 아래에서 잠시 멈춘 후, 둔근과 햄스트링을 조여 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","glutes"]', 'spine', 'images/1010-KUaoUV8.jpg', 'videos/1010-KUaoUV8.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1012', 'band twisting overhead press', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e posiziona la fascia sotto i piedi.","Tieni le maniglie della fascia all''altezza delle spalle con i palmi rivolti in avanti.","Coinvolgi il tuo core e premi la fascia sopra la testa, estendendo completamente le braccia.","Mentre premi, ruota il busto da un lato, mantenendo i fianchi stabili.","Fermati per un momento in alto, quindi torna alla posizione di partenza.","Ripeti la pressa e ruotala sul lato opposto.","Continua ad alternare i lati per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı ayaklarınızın altına yerleştirin.","Avuç içleriniz öne bakacak şekilde bant saplarını omuz yüksekliğinde tutun.","Merkez bölgenizi devreye sokun ve bandı başınızın üzerine bastırarak kollarınızı tamamen uzatın.","Bastırırken kalçalarınızı sabit tutarak gövdenizi bir tarafa çevirin.","Tepe noktasında bir süre duraklayın, ardından başlangıç ​​pozisyonuna dönün.","Baskıyı tekrarlayın ve karşı tarafta çevirin.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.","Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.","Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.","Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.","Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.","Repite el empuje y el giro hacia el lado opuesto.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и поместите ленту под ноги.","Держите ручки лент на уровне плеч ладонями вперед.","Напрягите корпус и нажмите на ленту над головой, полностью выпрямляя руки.","При нажатии поворачивайте туловище в сторону, сохраняя бедра устойчивыми.","Задержитесь на мгновение в верхней точке, затем вернитесь в исходное положение.","Повторите нажатие и поверните на противоположную сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在脚下。","将弹力带手柄保持在与肩同高的位置，手掌朝前。","启动你的核心并将弹力带压过头顶，充分伸展你的手臂。","当你按压时，将你的躯干扭转到一侧，保持臀部稳定。","在顶部暂停片刻，然后回到起始位置。","在另一侧重复按压和扭转。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को अपने पैरों के नीचे रखें।","अपनी हथेलियों को आगे की ओर रखते हुए बैंड के हैंडल को कंधे की ऊंचाई पर पकड़ें।","अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए बैंड को ऊपर की ओर दबाएं।","जैसे ही आप दबाते हैं, अपने कूल्हों को स्थिर रखते हुए अपने धड़ को एक तरफ मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","प्रेस को दोहराएं और विपरीत दिशा में मोड़ें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę pod stopami.","Trzymaj uchwyty taśmy na wysokości barków, dłonie skierowane do przodu.","Napnij mięśnie brzucha i wypchnij taśmę nad głowę, w pełni prostując ramiona.","Wypychając taśmę, skręć tułów w jedną stronę, utrzymując biodra stabilne.","Zatrzymaj się na chwilę w górnej pozycji, a następnie wróć do pozycji wyjściowej.","Powtórz wypchnięcie ze skrętem po przeciwnej stronie.","Kontynuuj naprzemienne wykonywanie ruchu na obie strony przez zalecaną liczbę powtórzeń."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 발 아래에 놓습니다.","밴드 손잡이를 어깨 높이에서 잡되 손바닥이 앞을 향하도록 합니다.","코어를 활성화하고 밴드를 머리 위로 완전히 뻗어냅니다.","누르면서 몸통을 한쪽으로 비틀되 엉덩이는 고정시킵니다.","맨 위에서 잠시 멈춘 후, 원래 위치로 돌아옵니다.","반대쪽에서 누르면서 비틀기를 반복합니다.","원하는 횟수만큼 양쪽을 번갈아 계속합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/1012-u4bAmKp.jpg', 'videos/1012-u4bAmKp.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1369', 'band two legs calf raise - (band under both legs) v. 2', 'lower legs', 'lower legs', 'band', '{"en":["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e posizionare una fascia di resistenza sotto entrambi i piedi.","Tieni le estremità della fascia con le mani per stabilità.","Solleva i talloni da terra il più in alto possibile, usando i polpacci.","Fai una pausa per un momento in alto, quindi abbassa lentamente i talloni nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve her iki ayağınızın altına bir direnç bandı yerleştirin.","Denge için bandın uçlarını ellerinizle tutun.","Baldırlarınızı kullanarak topuklarınızı yerden mümkün olduğunca yükseğe kaldırın.","Tepe noktasında bir an duraklayın, ardından topuklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.","Sujeta los extremos de la banda con las manos para mantener el equilibrio.","Levanta los talones del suelo lo más alto posible, usando las pantorrillas.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч, и поместите эспандер под обе ноги.","Для устойчивости удерживайте концы ленты руками.","Поднимите пятки от земли как можно выше, используя икроножные мышцы.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，并将阻力带放在双脚下方。","用手握住带子的末端以保持稳定。","用小腿将脚跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों पैरों के नीचे एक रेजिस्टेंस बैंड लगाएं।","स्थिरता के लिए बैंड के सिरों को अपने हाथों से पकड़ें।","अपनी पिंडलियों का उपयोग करते हुए अपनी एड़ियों को जमीन से जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i umieść taśmę oporową pod obiema stopami.","Trzymaj końce taśmy dłońmi dla stabilności.","Unieś pięty nad podłogę tak wysoko, jak to możliwe, angażując mięśnie łydek.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść pięty z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 저항 밴드를 양발 아래에 놓습니다.","안정성을 위해 밴드 끝을 손으로 잡습니다.","종아리를 사용하여 발꿈치를 최대한 높이 지면에서 들어 올립니다.","맨 위에서 잠시 멈춘 후, 천천히 발꿈치를 원래 위치로 내립니다.","원하는 횟수만큼 반복합니다."]}', 'ankles', '["ankles","feet"]', 'calves', 'images/1369-jl6uxZV.jpg', 'videos/1369-jl6uxZV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1013', 'band underhand pulldown', 'back', 'back', 'band', '{"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."],"it":["Attacca la fascia a un punto di ancoraggio alto, come una barra per trazioni o una trave robusta.","Stai di fronte al punto di ancoraggio con i piedi alla larghezza delle spalle.","Afferrare la fascia con una presa subdola, con le mani leggermente più larghe della larghezza delle spalle.","Estendi le braccia completamente sopra la testa, mantenendo i gomiti leggermente piegati.","Coinvolgi i dorsali e abbassa la fascia verso il petto, stringendo insieme le scapole.","Fermatevi per un attimo alla fine del movimento, poi rilasciate lentamente la tensione e ritornate alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı, çekme çubuğu veya sağlam kiriş gibi yüksek bir bağlantı noktasına takın.","Ayaklarınız omuz genişliğinde açık olacak şekilde bağlantı noktasına bakacak şekilde durun.","Bandı alttan kavrayın, eller omuz genişliğinden biraz daha açık olsun.","Dirseklerinizi hafifçe bükerek kollarınızı tamamen yukarı doğru uzatın.","Enlemlerinizi devreye alın ve bandı göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Hareketin alt noktasında bir süre duraklayın, ardından yavaşça gerilimi bırakın ve başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Sujeta la banda a un punto de anclaje alto, como una barra de dominadas o una viga resistente.","Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros.","Agarra la banda con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.","Extiende completamente los brazos por encima de la cabeza, manteniendo los codos ligeramente flexionados.","Activa los dorsales y tira de la banda hacia abajo en dirección al pecho, juntando los omóplatos.","Haz una pausa breve en la parte baja del movimiento, luego libera lentamente la tensión y vuelve a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Прикрепите ленту к высокой точке крепления, например к перекладине или прочной балке.","Встаньте лицом к точке крепления, поставив ноги на ширине плеч.","Возьмите ленту обратным хватом снизу, руки на расстоянии чуть шире плеч.","Вытяните руки полностью над головой, слегка согнув локти.","Напрягите широчайшие и потяните ленту вниз к груди, сжимая лопатки вместе.","Сделайте паузу на мгновение в нижней части движения, затем медленно ослабьте напряжение и вернитесь в исходное положение.","Повторите необходимое количество повторений."],"zh":["将弹力带固定在较高的锚点上，例如上拉杆或坚固的横梁。","面向锚点站立，双脚分开与肩同宽。","反手握住弹力带，双手间距略宽于肩宽。","将手臂完全伸过头顶，保持肘部稍微弯曲。","收紧背阔肌，将弹力带向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"],"hi":["बैंड को किसी ऊंचे एंकर बिंदु, जैसे पुल-अप बार या मजबूत बीम से जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए एंकर पॉइंट की ओर मुंह करके खड़े हो जाएं।","बैंड को अंडरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी बाहों को पूरी तरह ऊपर की ओर फैलाएँ।","अपने लैट्स को संलग्न करें और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए बैंड को अपनी छाती की ओर खींचें।","गति के निचले भाग पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Przymocuj taśmę do wysokiego punktu zaczepienia, takiego jak drążek do podciągania lub stabilna belka.","Stań przodem do punktu zaczepienia, stopy w rozkroku na szerokość barków.","Chwyć taśmę podchwytem, dłonie nieco szerzej niż na szerokość barków.","Wyprostuj ramiona w pełni nad głową, utrzymując łokcie lekko ugięte.","Napnij mięśnie najszersze grzbietu i ściągnij taśmę w dół w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę w dolnej fazie ruchu, a następnie powoli zwolnij napięcie i wróć do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["밴드를 풀업 바나 견고한 보(보)와 같은 높은 고정점에 부착합니다.","고정점을 향해 어깨 너비로 발을 벌리고 섭니다.","언더그립으로 밴드를 잡되 손이 어깨보다 약간 더 넓게 벌어지도록 합니다.","팔꿈치를 약간 구부린 상태에서 팔을 머리 위로 완전히 뻗습니다.","광배근을 활성화하여 밴드를 가슴 쪽으로 당기며 어깨날을 조입니다.","동작의 맨 아래에서 잠시 멈춘 후, 천천히 장력을 풀고 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'lats', 'images/1013-k6tUeqS.jpg', 'videos/1013-k6tUeqS.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1014', 'band v-up', 'waist', 'waist', 'band', '{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena con le gambe dritte e le braccia distese sopra la testa, tenendo la fascia.","Coinvolgendo gli addominali, solleva contemporaneamente le gambe e la parte superiore del corpo da terra, portando le mani verso le dita dei piedi.","Fermati per un momento in alto, quindi abbassa lentamente le gambe e la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Bandı tutarak bacaklarınız düz ve kollarınız yukarı doğru uzatılmış şekilde sırt üstü uzanın.","Karın kaslarınızı devreye sokarak bacaklarınızı ve vücudunuzun üst kısmını aynı anda yerden kaldırın, ellerinizi ayak parmaklarınıza doğru uzatın.","Tepe noktasında bir an duraklayın, ardından bacaklarınızı ve üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre tu espalda con las piernas rectas y los brazos extendidos por encima de la cabeza, sosteniendo la banda.","Activando el abdomen, levanta las piernas y la parte superior del cuerpo del suelo al mismo tiempo, llevando las manos hacia los dedos de los pies.","Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas y la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину, выпрямите ноги и вытяните руки над головой, удерживая ленту.","Включив пресс, одновременно поднимите ноги и верхнюю часть тела от земли, потянув руки к пальцам ног.","Задержитесь на мгновение в верхней точке, затем медленно опустите ноги и верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺，双腿伸直，手臂伸过头顶，握住弹力带。","收紧腹肌，同时将双腿和上半身抬离地面，双手伸向脚趾。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को सीधा करके और अपनी बाहों को ऊपर की ओर फैलाकर, बैंड को पकड़कर अपनी पीठ के बल लेट जाएँ।","अपने पेट को शामिल करते हुए, अपने पैरों और शरीर के ऊपरी हिस्से को एक साथ जमीन से ऊपर उठाएं, अपने हाथों को अपने पैर की उंगलियों तक पहुंचाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और शरीर के ऊपरी हिस्से को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach z prostymi nogami i ramionami wyciągniętymi nad głową, trzymając taśmę.","Angażując mięśnie brzucha, unieś nogi oraz górną część ciała jednocześnie, sięgając dłońmi w kierunku palców stóp.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nogi i górną część ciała z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["등을 대고 눕되 다리를 곧게 펴고 팔을 머리 위로 쭉 뻗은 상태에서 밴드를 잡습니다.","복근을 활성화하여 다리와 상체를 동시에 지면에서 들어 올려 손으로 발가락을 향합니다.","맨 위에서 잠시 멈춘 후, 천천히 다리와 상체를 원래 위치로 내립니다.","원하는 횟수만큼 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/1014-H6ETwO9.jpg', 'videos/1014-H6ETwO9.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1015', 'band vertical pallof press', 'waist', 'waist', 'band', '{"en":["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."],"it":["Stare con i piedi alla larghezza delle spalle e avvolgere la fascia attorno a un oggetto robusto all''altezza del petto.","Tieni la fascia con entrambe le mani e allontanati dal punto di ancoraggio, creando tensione nella fascia.","Posizionati perpendicolare al punto di ancoraggio, con il fianco rivolto verso la fascia.","Estendi le braccia davanti a te, mantenendo le mani all''altezza del petto.","Coinvolgi il tuo core e allontana la fascia dal petto, estendendo completamente le braccia.","Mantieni la posizione per qualche secondo, poi riporta lentamente la fascia verso il petto.","Ripeti per il numero di ripetizioni desiderato, quindi cambia lato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı göğüs yüksekliğinde sağlam bir nesnenin etrafına sarın.","Bandı iki elinizle tutun ve bağlantı noktasından uzaklaşarak bantta gerginlik yaratın.","Yan tarafınız banda bakacak şekilde kendinizi bağlantı noktasına dik olarak konumlandırın.","Ellerinizi göğüs hizasında tutarak kollarınızı düz bir şekilde önünüze doğru uzatın.","Merkez bölgenizi devreye sokun ve kollarınızı tamamen uzatarak bandı göğsünüzden uzağa doğru bastırın.","Birkaç saniye bu pozisyonda kalın, ardından bandı yavaşça göğsünüze doğru getirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y enrolla la banda alrededor de un objeto firme a la altura del pecho.","Sujeta la banda con ambas manos y aléjate del punto de anclaje, creando tensión en la banda.","Colócate perpendicular al punto de anclaje, con el costado mirando hacia la banda.","Extiende los brazos rectos hacia delante, manteniendo las manos a la altura del pecho.","Activa el core y empuja la banda alejándola del pecho, extendiendo completamente los brazos.","Mantén la posición durante unos segundos y luego lleva lentamente la banda de vuelta hacia el pecho.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Встаньте, ноги на ширине плеч, и оберните ленту вокруг прочного предмета на уровне груди.","Возьмите ленту обеими руками и отойдите от точки крепления, создавая напряжение в ленте.","Встаньте перпендикулярно точке крепления, боком к ленте.","Вытяните руки прямо перед собой, держа ладони на уровне груди.","Напрягите корпус и отведите ленту от груди, полностью выпрямляя руки.","Удерживайте это положение несколько секунд, затем медленно верните ленту обратно к груди.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["双脚分开与肩同宽站立，将弹力带缠绕在胸部高度的坚固物体上。","用双手握住弹力带并远离锚点，在弹力带中产生张力。","使自己垂直于锚点，一侧面向弹力带。","将双臂伸直在身前，保持双手与胸同高。","收紧核心肌群，将弹力带压离胸部，充分伸展手臂。","保持该姿势几秒钟，然后慢慢将弹力带拉回到胸部。","重复所需的重复次数，然后换边。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बैंड को छाती की ऊंचाई पर किसी मजबूत वस्तु के चारों ओर लपेटें।","बैंड को दोनों हाथों से पकड़ें और एंकर पॉइंट से दूर चले जाएं, जिससे बैंड में तनाव पैदा होगा।","अपने आप को एंकर बिंदु पर लंबवत रखें, आपका पक्ष बैंड की ओर हो।","अपनी बाहों को अपने सामने सीधा फैलाएं, अपने हाथों को छाती की ऊंचाई पर रखें।","अपने कोर को संलग्न करें और अपनी बाहों को पूरी तरह फैलाते हुए बैंड को अपनी छाती से दूर दबाएं।","कुछ सेकंड के लिए इसी स्थिति में रहें, फिर धीरे-धीरे बैंड को वापस अपनी छाती की ओर लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Stań w rozkroku na szerokość barków i owiń taśmę wokół stabilnego obiektu na wysokości klatki piersiowej.","Trzymaj taśmę obiema rękami i odejdź od punktu zaczepienia, tworząc napięcie w taśmie.","Ustaw się prostopadle do punktu zaczepienia, bokiem do taśmy.","Wyciągnij ramiona prosto przed siebie, utrzymując dłonie na wysokości klatki piersiowej.","Napnij mięśnie brzucha i wypchnij taśmę od klatki piersiowej, w pełni prostując ramiona.","Utrzymaj pozycję przez kilka sekund, a następnie powoli przyciągnij taśmę z powrotem w kierunku klatki piersiowej.","Powtórz zalecaną liczbę razy, a następnie zmień stronę."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 가슴 높이의 견고한 물체 주위에 감싸고 고정합니다.","밴드를 양손으로 잡고 고정점에서 멀어지며 밴드에 장력을 만듭니다.","고정점에 수직으로 위치하되 옆이 밴드를 향하도록 합니다.","팔을 앞으로 곧게 뻗되 손이 가슴 높이에 있도록 합니다.","코어를 활성화하고 밴드를 가슴에서 밀어냅니다.","몇 초간 그 자세를 유지한 후, 천천히 밴드를 가슴 쪽으로 당겨옵니다.","원하는 횟수만큼 반복한 후 반대쪽으로 전환합니다."]}', 'obliques', '["obliques","glutes"]', 'abs', 'images/1015-G7PXMlT.jpg', 'videos/1015-G7PXMlT.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1016', 'band wrist curl', 'lower arms', 'lower arms', 'band', '{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca o una sedia con i piedi appoggiati a terra.","Tieni la fascia con entrambe le mani, i palmi rivolti verso l''alto e appoggia gli avambracci sulle cosce.","Piega lentamente i polsi verso l''alto, stringendo gli avambracci.","Fai una pausa per un momento in alto, quindi abbassa lentamente i polsi nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak şekilde bir bankta veya sandalyede oturun.","Bandı iki elinizle, avuçlarınız yukarı bakacak şekilde tutun ve ön kollarınızı uyluklarınıza yaslayın.","Bileklerinizi yavaşça yukarı doğru kıvırın, önkollarınızı sıkın.","Tepe noktasında bir an duraklayın, ardından bileklerinizi yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco o silla con los pies apoyados en el suelo.","Sujeta la banda con ambas manos, con las palmas hacia arriba, y apoya los antebrazos sobre los muslos.","Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.","Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью или стул, поставив ноги на землю.","Держите ленту обеими руками ладонями вверх и положите предплечья на бедра.","Медленно поднимите запястья вверх, сжимая предплечья.","Задержитесь на мгновение в верхней точке, затем медленно опустите запястья обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳或椅子上，双脚平放在地面上。","双手握住弹力带，手掌朝上，前臂放在大腿上。","慢慢向上弯曲手腕，挤压前臂。","在顶部暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","बैंड को दोनों हाथों से पकड़ें, हथेलियाँ ऊपर की ओर हों और अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce lub krześle, stopy płasko na podłodze.","Trzymaj taśmę obiema rękami, dłonie skierowane do góry, i oprzyj przedramiona na udach.","Powoli uginaj nadgarstki w górę, ściskając przedramiona.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść nadgarstki z powrotem do pozycji wyjściowej.","Powtórz zalecaną liczbę razy."],"ko":["벤치나 의자에 앉아 발을 땅에 댑니다.","밴드를 양손으로 손바닥이 위를 향하도록 잡고 팔뚝을 넓적다리에 얹습니다.","천천히 손목을 위로 구부리며 팔뚝을 조입니다.","맨 위에서 잠시 멈춘 후, 천천히 손목을 원래 위치로 내립니다.","원하는 횟수만큼 반복합니다."]}', 'biceps', '["biceps","triceps"]', 'forearms', 'images/1016-vUTfFHw.jpg', 'videos/1016-vUTfFHw.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1017', 'band y-raise', 'shoulders', 'shoulders', 'band', '{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere la fascia davanti alle cosce con i palmi rivolti verso l''interno.","Tieni le braccia tese e sollevale verso l''alto e verso l''esterno, formando una forma a \"Y\" con il tuo corpo.","Stringi le scapole insieme nella parte superiore del movimento.","Abbassa lentamente le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve bandı avuç içleriniz içe bakacak şekilde uyluklarınızın önünde tutun.","Kollarınızı düz tutun ve vücudunuzla ''Y'' şekli oluşturacak şekilde yukarı ve yanlara doğru kaldırın.","Hareketin üst noktasında kürek kemiklerinizi birbirine doğru sıkın.","Kollarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.","Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo.","Junta los omóplatos en la parte superior del movimiento.","Baja lentamente los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч, и держите ленту перед бедрами ладонями внутрь.","Держите руки прямо и поднимите их вверх и в стороны, образуя своим телом букву «Y».","В верхней точке движения сведите лопатки вместе.","Медленно опустите руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，将弹力带放在大腿前面，手掌朝内。","保持双臂伸直，将其向上举至两侧，与身体形成“Y”形。","在动作的最高点将肩胛骨挤压在一起。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी हथेलियों को अंदर की ओर रखते हुए बैंड को अपनी जांघों के सामने पकड़ें।","अपनी भुजाओं को सीधा रखें और उन्हें ऊपर और बाहर की ओर उठाएं, जिससे आपके शरीर का ''Y'' आकार बनता है।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i trzymaj taśmę przed udami, dłońmi skierowanymi do wewnątrz.","Utrzymując ramiona wyprostowane, unieś je w górę i na boki, tworząc ciałem kształt litery „Y”.","Ściśnij łopatki na szczycie ruchu.","Powoli opuść ramiona z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 밴드를 넓적다리 앞에 손바닥이 안쪽을 향하도록 잡습니다.","팔을 곧게 펼치고 옆으로 들어 올려 몸으로 ''Y'' 자 형태를 만듭니다.","동작의 맨 위에서 어깨날을 조입니다.","천천히 팔을 원래 위치로 내립니다.","원하는 횟수만큼 반복합니다."]}', 'traps', '["traps","rhomboids"]', 'delts', 'images/1017-aHDy5O5.jpg', 'videos/1017-aHDy5O5.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0023', 'barbell alternate biceps curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."],"it":["Stai dritto con i piedi alla larghezza delle spalle e tieni un bilanciere in ciascuna mano, con i palmi rivolti in avanti.","Mantieni ferma la parte superiore delle braccia ed espira mentre pieghi i pesi mentre contrai i bicipiti.","Continua a sollevare i bilancieri finché i bicipiti non saranno completamente contratti e i bilancieri saranno all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira mentre inizi lentamente ad abbassare i bilancieri nella posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, alternando le braccia."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde dik durun ve avuç içleriniz öne bakacak şekilde her iki elinizde birer halter tutun.","Üst kollarınızı sabit tutun ve bicepslerinizi kasarken ağırlıkları kıvırırken nefes verin.","Bicepsleriniz tamamen kasılana ve halterler omuz hizasına gelene kadar halterleri kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Halterleri yavaşça başlangıç ​​pozisyonuna indirmeye başlarken nefes alın.","İstenilen sayıda tekrar için kolları değiştirerek tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.","Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.","Repite el número de repeticiones deseado, alternando los brazos."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите в каждую руку по штанге ладонями вперед.","Держите плечи неподвижно и выдыхайте, сгибая штангу и одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе начните медленно опускать штангу обратно в исходное положение.","Повторите желаемое количество повторений, чередуя руки."],"zh":["站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。","保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数，交替手臂。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए सीधे खड़े हो जाएं और प्रत्येक हाथ में एक बारबेल पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ते हुए सांस छोड़ें।","बारबेल्स को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल्स कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","जैसे ही आप धीरे-धीरे बारबेल्स को शुरुआती स्थिति में वापस लाना शुरू करते हैं, श्वास लें।","दोहराव की वांछित संख्या के लिए दोहराएँ, बारी-बारी से हथियार।"],"pl":["Stań prosto, stopy rozstaw na szerokość barków i chwyć sztangielkę w każdą rękę, dłonie skierowane do przodu.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.","Unoś sztangielki, aż biceps będzie w pełni napięty, a sztangielki znajdą się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangielki do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy, na przemian dla obu rąk."],"ko":["똑바로 서서 어깨 너비로 발을 벌리고 각 손에 바벨을 잡되 손바닥이 앞을 향하도록 합니다.","위팔을 고정한 상태에서 숨을 내쉬며 이두근을 수축시키면서 무게를 구부립니다.","바벨을 계속 들어올려 이두근이 완전히 수축되고 바벨이 어깨 높이에 도달할 때까지 들어올립니다.","이두근을 조인 상태에서 잠시 멈춰 수축을 유지합니다.","숨을 들이쉬면서 천천히 바벨을 원래 위치로 내립니다.","원하는 횟수만큼 팔을 번갈아 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0023-Yza7XrQ.jpg', 'videos/0023-Yza7XrQ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0024', 'barbell bench front squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e il bilanciere appoggiato sulla parte superiore del torace, appena sotto la clavicola.","Tieni il bilanciere con una presa prona, mantenendo i gomiti sollevati e la parte superiore delle braccia parallela al suolo.","Abbassa il corpo in una posizione tozza piegando le ginocchia e i fianchi, mantenendo la schiena dritta e il petto in alto.","Fai una pausa per un momento alla fine dello squat, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve halter üst göğsünüzde, köprücük kemiğinizin hemen altında olacak şekilde ayakta durarak başlayın.","Halteri üstten kavrayarak tutun, dirseklerinizi yukarıda ve üst kollarınızı yere paralel tutun.","Sırtınızı düz ve göğsünüzü yukarıda tutarak, dizlerinizi ve kalçalarınızı bükerek vücudunuzu çömelme pozisyonuna indirin.","Çömelmenin alt noktasında bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, justo debajo de la clavícula.","Sujeta la barra con un agarre pronado, manteniendo los codos elevados y los brazos superiores paralelos al suelo.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть груди, чуть ниже ключиц.","Держите штангу хватом сверху, держа локти вверху и плечам параллельно земле.","Опустите тело в присед, сгибая колени и бедра, сохраняя спину прямой и грудь вверх.","Задержитесь на мгновение в нижней части приседа, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。","正手握住杠铃，保持肘部向上，上臂与地面平行。","弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。","在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके कॉलरबोन के ठीक नीचे, आपकी ऊपरी छाती पर टिकी हुई हो।","अपनी कोहनियों को ऊपर और अपनी ऊपरी भुजाओं को ज़मीन के समानांतर रखते हुए, बारबेल को ओवरहैंड ग्रिप से पकड़ें।","घुटनों और कूल्हों पर झुकते हुए, अपनी पीठ को सीधा और अपनी छाती को ऊपर रखते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","स्क्वाट के निचले हिस्से में एक क्षण के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, opierając sztangę na górnej części klatki piersiowej, tuż poniżej obojczyka.","Trzymaj sztangę chwytem nachwytem, utrzymując łokcie uniesione, a ramiona równoległe do podłoża.","Opuść ciało do pozycji przysiadu, zginając kolana i biodra, utrzymując proste plecy i uniesioną klatkę piersiową.","Zatrzymaj się na chwilę w dolnej fazie przysiadu, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨 너비로 발을 벌리고 서서 바벨을 쇄골 바로 아래 상부 가슴에 올려놓으면서 시작합니다.","오버그립으로 바벨을 잡되 팔꿈치를 들어 상완을 지면과 평행하게 유지합니다.","무릎을 구부려 몸을 스쿼트 자세로 내리되 등을 곧게 펴고 가슴을 들어 올립니다.","스쿼트의 맨 아래에서 잠시 멈춘 후, 발꿈치를 통해 밀어 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","glutes","calves"]', 'quads', 'images/0024-Y7YcmIJ.jpg', 'videos/0024-Y7YcmIJ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0025', 'barbell bench press', 'chest', 'chest', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa prona leggermente più larga della larghezza delle spalle.","Solleva il bilanciere dal rack e tienilo direttamente sopra il petto con le braccia completamente distese.","Abbassa lentamente il bilanciere verso il petto, mantenendo i gomiti piegati.","Fai una pausa per un momento quando il bilanciere tocca il tuo petto.","Spingi il bilanciere nella posizione iniziale estendendo le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halteri raftan kaldırın ve kollarınız tamamen uzatılmış halde doğrudan göğsünüzün üzerinde tutun.","Dirseklerinizi içeride tutarak halteri yavaşça göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın.","Kollarınızı uzatarak halteri başlangıç ​​pozisyonuna doğru itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial extendiendo los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, вытянув руки.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","伸展双臂，将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अंदर की ओर रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएँ।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को फैलाकर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę chwytem nachwytem nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.","Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.","Wypchnij sztangę z powrotem do pozycji wyjściowej, prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 눕되 발을 땅에 댑니다.","등을 벤치에 밀착합니다.","어깨 너비보다 약간 더 넓게 오버그립으로 바벨을 잡습니다.","바벨을 랙에서 들어 가슴 위에서 팔을 완전히 뻗은 상태로 잡습니다.","팔꿈치를 안쪽으로 유지하면서 천천히 바벨을 가슴 쪽으로 내립니다.","바벨이 가슴에 닿을 때 잠시 멈춘 후, 팔을 펴서 바벨을 처음 위치로 밀어냅니다.","원하는 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/0025-EIeI8Vf.jpg', 'videos/0025-EIeI8Vf.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0026', 'barbell bench squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Posiziona un bilanciere su uno squat rack all''altezza del petto.","Stai di fronte al rack, con i piedi alla larghezza delle spalle.","Piega le ginocchia e abbassa il corpo in posizione tozza, mantenendo la schiena dritta e il petto in alto.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Solleva il bilanciere dal rack e fai un passo indietro, assicurandoti che i piedi siano ancora alla larghezza delle spalle.","Abbassa il corpo in uno squat, mantenendo le ginocchia in linea con le dita dei piedi.","Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Göğüs yüksekliğinde bir squat rack üzerine halter yerleştirin.","Ayaklarınız omuz genişliğinde açık olacak şekilde raftan uzağa bakacak şekilde durun.","Dizlerinizi bükün ve sırtınızı dik ve göğsünüzü yukarıda tutarak vücudunuzu çömelme pozisyonuna indirin.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halteri raftan kaldırın ve geriye doğru bir adım atın, ayaklarınızın hala omuz genişliğinde olduğundan emin olun.","Dizlerinizi ayak parmaklarınızla aynı hizada tutarak vücudunuzu çömelme pozisyonuna indirin.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca una barra en un soporte de sentadillas a la altura del pecho.","Ponte de pie de espaldas al soporte, con los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y retrocede un paso, asegurándote de que los pies sigan separados a la altura de los hombros.","Baja el cuerpo hacia una sentadilla, manteniendo las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите штангу на стойке для приседаний на уровне груди.","Встаньте лицом от стойки, ноги на ширине плеч.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и отступите назад, убедившись, что ваши ноги по-прежнему находятся на ширине плеч.","Опустите тело в присед, удерживая колени на одной линии с пальцами ног.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["将杠铃放在深蹲架上，与胸部同高。","背对架子站立，双脚与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。","降低身体蹲下，保持膝盖与脚趾在一条线上。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["छाती की ऊंचाई पर स्क्वाट रैक पर बारबेल स्थापित करें।","अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए, रैक से दूर की ओर मुंह करके खड़े हो जाएं।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और पीछे हटें, यह सुनिश्चित करते हुए कि आपके पैर अभी भी कंधे की चौड़ाई से अलग हैं।","अपने घुटनों को अपने पैर की उंगलियों के अनुरूप रखते हुए, अपने शरीर को स्क्वाट में नीचे झुकाएँ।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw sztangę na stojaku na wysokości klatki piersiowej.","Stań tyłem do stojaka, stopy rozstaw na szerokość barków.","Ugnij kolana i opuść ciało do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i zrób krok w tył, upewniając się, że stopy nadal są rozstawione na szerokość barków.","Opuść ciało do pozycji przysiadu, utrzymując kolana w linii ze stopami.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["스쿼트 랙 위에 바벨을 가슴 높이에 설정합니다.","랙에서 등을 돌려 어깨 너비로 발을 벌리고 섭니다.","무릎을 구부려 몸을 스쿼트 자세로 내리되 등을 곧게 펴고 가슴을 들어 올립니다.","오버그립으로 바벨을 잡되 어깨 너비보다 약간 더 넓게 잡습니다.","바벨을 랙에서 들어 한 발 물러나면서 발이 여전히 어깨 너비로 유지되도록 합니다.","무릎이 발가락과 정렬되도록 유지하면서 스쿼트로 내립니다.","맨 아래에서 잠시 멈춘 후, 발꿈치를 통해 밀어 원래 위치로 돌아옵니다.","원하는 횟수만큼 반복합니다."]}', 'glutes', '["glutes","hamstrings","calves"]', 'quads', 'images/0026-W9pFVv1.jpg', 'videos/0026-W9pFVv1.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1316', 'barbell bent arm pullover', 'back', 'back', 'barbell', '{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con la testa da un lato e i piedi sul pavimento.","Tieni un bilanciere con una presa alla larghezza delle spalle ed estendi le braccia direttamente sopra il petto.","Abbassa il bilanciere dietro la testa mantenendo le braccia leggermente piegate.","Fare una pausa per un momento, quindi riportare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız bir ucunda ve ayaklarınız yerde olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinde tutun ve kollarınızı göğsünüzün üzerine düz bir şekilde uzatın.","Kollarınızı hafifçe bükülmüş halde tutarak halteri başınızın arkasına indirin.","Bir süre duraklayın, ardından halteri tekrar başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Возьмите штангу хватом на ширине плеч и вытяните руки прямо над грудью.","Опустите штангу за голову, держа руки слегка согнутыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，头放在一端，双脚放在地板上。","握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。","将杠铃放在脑后，同时保持手臂稍微弯曲。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","कंधे की चौड़ाई की पकड़ के साथ बारबेल को पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएं।","अपनी बाहों को थोड़ा झुकाते हुए बारबेल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, głową na jednym końcu, a stopy oprzyj na podłodze.","Chwyć sztangę uchwytem na szerokość barków i wyprostuj ręce nad klatką piersiową.","Opuść sztangę za głowę, utrzymując ręce lekko ugięte.","Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치 위에 누운 상태로 한쪽 끝에 머리를 두고 발은 바닥에 디딤니다.","어깨넓이의 그립으로 바벨을 잡고 팔을 가슴 위로 펼칩니다.","팔을 약간 구부린 상태로 바벨을 머리 뒤로 내립니다.","잠시 멈춘 후 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","chest"]', 'lats', 'images/1316-cA9FuWG.jpg', 'videos/1316-cA9FuWG.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0027', 'barbell bent over row', 'back', 'back', 'barbell', '{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate.","Piegati in avanti sui fianchi mantenendo la schiena dritta e il petto in alto.","Afferrare il bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Tirare il bilanciere verso la parte inferiore del torace ritraendo le scapole e contraendo i muscoli della schiena.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun.","Sırtınızı düz ve göğsünüzü yukarıda tutarak kalçalarınızdan öne doğru eğin.","Halteri üstten kavrayarak, eller omuz genişliğinden biraz daha geniş olacak şekilde kavrayın.","Kürek kemiklerinizi geri çekerek ve sırt kaslarınızı sıkarak halteri alt göğsünüze doğru çekin.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Наклонитесь вперед в бедрах, сохраняя спину прямой и грудь вверх.","Возьмите штангу хватом сверху, руки на расстоянии чуть шире плеч.","Потяните штангу к нижней части груди, сводя лопатки и напрягая мышцы спины.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","臀部向前弯曲，同时保持背部挺直、挺胸。","正手握住杠铃，双手间距略宽于肩宽。","通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी पीठ की मांसपेशियों को निचोड़कर बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, kolana lekko ugięte.","Pochyl tułów w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.","Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Przyciągnij sztangę w kierunku dolnej części klatki piersiowej, ściągając łopatki i napinając mięśnie grzbietu.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 무릎을 약간 구부린 상태로 섭니다.","허리를 굽혀 상체를 앞으로 숙이면서 등은 곧게 유지하고 가슴을 펼칩니다.","손가락이 앞을 향하는 그립으로 바벨을 잡고 손은 어깨넓이보다 약간 넓게 위치시킵니다.","어깨뼈를 뒤로 당기면서 등 근육을 수축시켜 바벨을 아래 가슴 쪽으로 당깁니다.","맨 위에서 잠시 멈춘 후 천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/0027-eZyBC3j.jpg', 'videos/0027-eZyBC3j.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2407', 'barbell biceps curl (with arm blaster)', 'upper arms', 'upper arms', 'barbell', '{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai dritto con i piedi alla larghezza delle spalle e tieni un bilanciere con una presa subdola, con i palmi rivolti verso l''alto.","Posiziona la parte superiore delle braccia contro l''arm blaster, mantenendo i gomiti vicini al busto.","Mantenendo ferma la parte superiore delle braccia, espira e piega i pesi contraendo i bicipiti.","Continua a sollevare il bilanciere finché i bicipiti non sono completamente contratti e la barra è all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira e inizia lentamente ad abbassare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde dik durun ve halteri avuç içleriniz yukarı bakacak şekilde alttan kavrayarak tutun.","Dirseklerinizi gövdenize yakın tutarak üst kollarınızı kol patlatıcıya yaslayın.","Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın.","Bicepsleriniz tamamen kasılana ve bar omuz hizasına gelinceye kadar halteri kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirmeye başlayın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Прижмите плечи к армбластеру, держа локти близко к туловищу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。","将上臂靠在手臂冲击波上，保持肘部靠近躯干。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हथेलियां ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी कोहनियों को अपने धड़ के पास रखते हुए, अपनी ऊपरी भुजाओं को आर्म ब्लास्टर के सामने रखें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań prosto, stopy rozstaw na szerokość barków, i chwyć sztangę chwytem podchwytem, dłonie skierowane do góry.","Oprzyj ramiona o arm blaster, trzymając łokcie blisko tułowia.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 섭니다. 손가락이 앞을 향하도록 바벨을 잡고 손바닥이 위를 향하게 합니다.","팔뚝을 암 블래스터에 밀착시키고 팔꿈치를 몸 가까이 유지합니다.","상박을 고정한 상태에서 숨을 내쉬면서 이두근을 수축시켜 바벨을 컬합니다.","이두근이 완전히 수축되어 바벨이 어깨 높이에 올 때까지 계속 올립니다.","수축된 상태를 잠시 유지하면서 이두근을 꽉 조입니다.","숨을 들이마시면서 천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/2407-aee2Fcj.jpg', 'videos/2407-aee2Fcj.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0028', 'barbell clean and press', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e il bilanciere sul pavimento di fronte a te.","Piega le ginocchia e fai perno sui fianchi per abbassarti e afferrare il bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Guida attraverso i talloni ed estendi i fianchi e le ginocchia per sollevare il bilanciere dal pavimento, tenendolo vicino al corpo.","Quando il bilanciere raggiunge le cosce, estendi in modo esplosivo i fianchi, alza le spalle e tira il bilanciere verso il petto.","Quando il bilanciere raggiunge l''altezza del petto, abbassati rapidamente sotto di esso e afferralo all''altezza delle spalle, con i gomiti rivolti in avanti e i palmi rivolti verso l''alto.","Dalla posizione di presa, premi il bilanciere sopra la testa estendendo le braccia e spingendo il bilanciere verso l''alto.","Abbassare nuovamente il bilanciere nella posizione iniziale e ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve halter önünüzde yerde olacak şekilde ayakta durun.","Dizlerinizi bükün ve kalçalarınızı menteşeleyerek aşağı indirin ve halteri üstten kavrayarak tutun, eller omuz genişliğinden biraz daha açık olsun.","Topuklarınızın üzerinden geçin ve halterinizi vücudunuza yakın tutarak yerden kaldırmak için kalçalarınızı ve dizlerinizi uzatın.","Halter uyluklarınıza ulaştığında kalçalarınızı patlayıcı bir şekilde uzatın, omuzlarınızı silkin ve halteri göğsünüze doğru çekin.","Halter göğüs yüksekliğine ulaştığında, hızla altına inin ve dirsekleriniz öne ve avuçlarınız yukarıya bakacak şekilde omuz hizasında yakalayın.","Yakalama konumundan, kollarınızı uzatarak ve halteri düz bir şekilde yukarı doğru iterek halterin başının üstüne basın.","Halteri başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.","Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.","Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.","Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на пол перед собой.","Согните ноги в коленях и наклоните бедра, чтобы опуститься и взять штангу хватом сверху, расставив руки чуть шире плеч.","Двигайтесь пятками и выпрямите бедра и колени, чтобы поднять штангу от пола, удерживая ее близко к телу.","Когда штанга достигнет бедер, резко разогните бедра, пожмите плечами и подтяните штангу к груди.","Когда штанга достигнет уровня груди, быстро опуститесь под нее и поймайте ее на уровне плеч, направив локти вперед и ладони вверх.","Из позиции захвата выжмите штангу над головой, вытянув руки и толкнув штангу прямо вверх.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，杠铃放在你面前的地板上。","弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。","通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。","当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。","当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。","从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。","将杠铃放回起始位置，然后重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके सामने फर्श पर हो।","अपने घुटनों को मोड़ें और कूल्हों पर टिकाकर नीचे की ओर झुकें और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी एड़ी के माध्यम से ड्राइव करें और बारबेल को अपने शरीर के करीब रखते हुए, फर्श से उठाने के लिए अपने कूल्हों और घुटनों का विस्तार करें।","जैसे ही बारबेल आपकी जांघों तक पहुंचे, अपने कूल्हों को तेजी से फैलाएं, अपने कंधों को सिकोड़ें और बारबेल को अपनी छाती की ओर ऊपर खींचें।","जैसे ही बारबेल छाती की ऊंचाई तक पहुंचती है, तुरंत इसके नीचे झुकें और इसे कंधे के स्तर पर पकड़ें, आपकी कोहनी आगे की ओर और आपकी हथेलियाँ ऊपर की ओर हों।","पकड़ने की स्थिति से, अपनी बाहों को फैलाकर बारबेल को ऊपर की ओर दबाएं और बारबेल को सीधा ऊपर की ओर धकेलें।","बारबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą leżącą na podłodze przed tobą.","Ugnij kolana i pochyl się w biodrach, aby chwycić sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Odepchnij się od podłoża piętami i wyprostuj biodra i kolana, unosząc sztangę z podłogi blisko ciała.","Gdy sztanga osiągnie wysokość ud, dynamicznie wyprostuj biodra, unieś barki i przyciągnij sztangę w górę w kierunku klatki piersiowej.","Gdy sztanga osiągnie wysokość klatki piersiowej, szybko zejdź pod nią i złap ją na wysokości barków, z łokciami skierowanymi do przodu i dłońmi skierowanymi do góry.","Z pozycji podchwytu wypchnij sztangę nad głowę, prostując ręce i pchając sztangę prosto w górę.","Opuść sztangę z powrotem do pozycji wyjściowej i powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 바벨을 몸 앞 바닥에 놓습니다.","무릎을 굽혀 허리를 숙이면서 손가락이 앞을 향하도록 바벨을 잡고 손은 어깨넓이보다 약간 넓게 위치시킵니다.","발 뒤꿈치로 힘을 주어 바벨을 들어올리면서 몸 가까이 유지하고 허리와 무릎을 펼칩니다.","바벨이 넓적다리에 닿으면 신속하게 허리를 펼치고 어깨를 으쓱하면서 바벨을 가슴 쪽으로 당깁니다.","바벨이 가슴 높이에 도달하면 신속하게 몸 아래로 내려가서 어깨 높이에서 바벨을 받으면서 팔꿈치는 앞으로 향하고 손바닥은 앞을 향하게 합니다.","받은 위치에서 팔을 펼쳐 바벨을 머리 위로 누릅니다.","바벨을 시작 위치로 내리고 원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","glutes","shoulders","triceps"]', 'quads', 'images/0028-SGY8Zui.jpg', 'videos/0028-SGY8Zui.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0029', 'barbell clean-grip front squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e il bilanciere appoggiato sulla parte superiore del torace, con i gomiti rivolti in avanti.","Abbassa il corpo piegando le ginocchia e spingendo indietro i fianchi, come se fossi seduto su una sedia.","Tieni il petto in alto e la schiena dritta mentre ti abbassi, assicurandoti che le ginocchia non superino le dita dei piedi.","Continua ad abbassare finché le cosce non sono parallele al suolo o il più in basso possibile.","Fai una pausa per un momento in fondo, quindi spingi i talloni per rialzarti, estendendo i fianchi e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açarak ve halteri göğsünüzün üst kısmına dayayarak, dirsekleriniz ileriyi gösterecek şekilde ayakta durarak başlayın.","Dizlerinizi bükerek ve sanki bir sandalyeye oturuyormuş gibi kalçalarınızı geriye doğru iterek vücudunuzu indirin.","Aşağı inerken göğsünüzü yukarıda ve sırtınızı düz tutun, dizlerinizin ayak parmaklarınızı geçmediğinden emin olun.","Uyluklarınız yere paralel veya rahatça gidebileceğiniz kadar alçalana kadar alçaltmaya devam edin.","Altta bir an duraklayın, ardından topuklarınızı iterek ayağa kalkın, kalçalarınızı ve dizlerinizi uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada en la parte superior del pecho, con los codos apuntando hacia delante.","Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás, como si te sentaras en una silla.","Mantén el pecho elevado y la espalda recta mientras bajas, asegurándote de que las rodillas no sobrepasen los dedos de los pies.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve en la parte baja y luego empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, положив штангу на верхнюю часть груди, локти направлены вперед.","Опустите тело, согнув колени и отведя бедра назад, как будто вы садитесь на стул.","При опускании держите грудь поднятой, а спину прямой, следя за тем, чтобы колени не выходили за носки ног.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение в нижней точке, затем оттолкнитесь пятками, чтобы снова встать, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"zh":["首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。","弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。","下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई से अलग करके और बारबेल को अपनी ऊपरी छाती पर टिकाकर, अपनी कोहनियों को आगे की ओर रखते हुए खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को नीचे लाएँ, जैसे कि आप किसी कुर्सी पर पीछे बैठे हों।","नीचे उतरते समय अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें, यह सुनिश्चित करें कि आपके घुटने आपके पैर की उंगलियों से आगे न जाएं।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए नीचे रुकें, फिर अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, opierając sztangę na górnej części klatki piersiowej, z łokciami skierowanymi do przodu.","Opuść ciało, uginając kolana i cofając biodra, jakbyś siadał na krześle.","Utrzymuj uniesioną klatkę piersiową i proste plecy podczas opuszczania, upewniając się, że kolana nie wychodzą poza linię palców stóp.","Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 바벨을 가슴 위쪽에 올려놓고 팔꿈치는 앞으로 향하게 합니다.","무릎을 굽혀 의자에 앉는 것처럼 허리를 뒤로 빼면서 몸을 내립니다.","상체를 펴고 등을 곧게 유지하면서 내려가며 무릎이 발끝을 넘지 않도록 합니다.","넓적다리가 바닥과 평행하거나 편안한 범위 내에서 최대한 낮게 내려갑니다.","맨 아래에서 잠시 멈춘 후 발 뒤꿈치로 힘을 주어 일어나면서 허리와 무릎을 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/0029-qi996YS.jpg', 'videos/0029-qi996YS.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0030', 'barbell close-grip bench press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa stretta, leggermente più stretta della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti vicini al corpo.","Fai una pausa per un momento quando il bilanciere tocca il tuo petto.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinden biraz daha dar olacak şekilde yakın bir tutuşla kavrayın.","Halterin askısını açın ve dirseklerinizi vücudunuza yakın tutarak yavaşça göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę wąskim chwytem, nieco węższym niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["벤치 위에 누운 상태로 발을 바닥에 디딤니다.","좁은 그립(어깨넓이보다 좁게)으로 바벨을 잡습니다.","바벨을 받쳐주는 거치대에서 내려놓은 후 천천히 가슴 쪽으로 내립니다. 팔꿈치를 몸 가까이 유지합니다.","바벨이 가슴에 닿으면 잠시 멈춥니다.","팔을 완전히 펴면서 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0030-J6Dx1Mu.jpg', 'videos/0030-J6Dx1Mu.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0031', 'barbell curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai dritto con i piedi alla larghezza delle spalle e tieni un bilanciere con una presa subdola, con i palmi rivolti in avanti.","Tieni i gomiti vicini al busto ed espira mentre pieghi i pesi mentre contrai i bicipiti.","Continua a sollevare la barra finché i bicipiti non sono completamente contratti e la barra è all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira mentre inizi lentamente ad abbassare la barra nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde dik durun ve halteri avuç içleriniz öne bakacak şekilde alttan kavrayarak tutun.","Dirseklerinizi gövdenize yakın tutun ve bicepslerinizi kasarken ağırlıkları kıvırırken nefes verin.","Bicepsleriniz tamamen kasılana ve bar omuz hizasına gelinceye kadar barı kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Çubuğu yavaşça başlangıç ​​pozisyonuna indirmeye başlarken nefes alın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante.","Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вперед.","Держите локти близко к туловищу и выдыхайте, сгибая штангу и одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе начните медленно опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。","保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और हथेलियां आगे की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ते हुए सांस छोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बार कंधे के स्तर पर न आ जाए, तब तक बार को ऊपर उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","जैसे ही आप धीरे-धीरे बार को प्रारंभिक स्थिति में वापस लाना शुरू करते हैं, श्वास लें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań prosto, stopy rozstaw na szerokość barków, i chwyć sztangę chwytem podchwytem, dłonie skierowane do przodu.","Trzymaj łokcie blisko tułowia i wydychaj powietrze, uginając ręce i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 손가락이 앞을 향하도록 바벨을 잡고 손바닥이 앞을 향하게 합니다.","팔꿈치를 몸 가까이 유지하면서 숨을 내쉬고 이두근을 수축시켜 바벨을 컬합니다.","이두근이 완전히 수축되어 바벨이 어깨 높이에 올 때까지 계속 올립니다.","수축된 상태를 잠시 유지하면서 이두근을 꽉 조입니다.","숨을 들이마시면서 천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0031-25GPyDY.jpg', 'videos/0031-25GPyDY.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0032', 'barbell deadlift', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e il bilanciere a terra davanti a te.","Piega le ginocchia e fai perno sui fianchi per abbassare il busto e afferrare il bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Tieni la schiena dritta e il petto sollevato mentre spingi i talloni per sollevare il bilanciere da terra, estendendo i fianchi e le ginocchia.","Mentre stai in piedi, contrai i glutei e mantieni il core impegnato.","Abbassa il bilanciere a terra piegando le anche e le ginocchia, mantenendo la schiena dritta.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve halter önünüzde yerde olacak şekilde ayakta durun.","Dizlerinizi bükün ve kalçalarınızı menteşeleyerek gövdenizi indirin ve halteri üstten kavrayarak, eller omuz genişliğinden biraz daha geniş olacak şekilde kavrayın.","Halteri yerden kaldırmak için topuklarınızın üzerinden geçerken sırtınızı düz ve göğsünüzü yukarıda tutun, kalçalarınızı ve dizlerinizi uzatın.","Dik dururken kalça kaslarınızı sıkın ve merkez bölgenizi meşgul tutun.","Sırtınızı düz tutarak, kalçalarınızı ve dizlerinizi bükerek halteri yere indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.","Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas.","Al ponerte de pie, aprieta los glúteos y mantén el core activado.","Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, положите штангу на землю перед собой.","Согните колени и наклоните бедра, чтобы опустить туловище и взять штангу хватом сверху, руки на расстоянии чуть шире плеч.","Держите спину прямо, а грудь приподнятой, пока вы двигаетесь пятками, чтобы поднять штангу с земли, вытягивая бедра и колени.","Вставая прямо, сожмите ягодицы и держите корпус напряженным.","Опустите штангу обратно на землю, сгибая бедра и колени, сохраняя спину прямой.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，杠铃放在你面前的地面上。","弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。","当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。","当你站直时，挤压你的臀部并保持你的核心参与。","弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपके सामने जमीन पर हो।","अपने घुटनों को मोड़ें और अपने धड़ को नीचे करने के लिए कूल्हों पर टिकाएं और बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","बारबेल को जमीन से ऊपर उठाने के लिए अपनी एड़ी के माध्यम से ड्राइव करते समय अपनी पीठ सीधी और छाती ऊपर रखें, अपने कूल्हों और घुटनों को फैलाएं।","जैसे ही आप सीधे खड़े हों, अपने ग्लूट्स को निचोड़ें और अपने कोर को व्यस्त रखें।","अपनी पीठ को सीधा रखते हुए, कूल्हों और घुटनों पर झुकते हुए बारबेल को वापस ज़मीन पर नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą leżącą na podłodze przed tobą.","Ugnij kolana i pochyl się w biodrach, aby opuścić tułów i chwycić sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Utrzymując proste plecy i uniesioną klatkę piersiową, odepchnij się piętami, unosząc sztangę z podłogi, prostując biodra i kolana.","Gdy staniesz prosto, ściśnij pośladki i utrzymuj napięcie mięśni tułowia.","Opuść sztangę z powrotem na podłogę, uginając biodra i kolana, utrzymując proste plecy.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 바벨을 몸 앞 바닥에 놓습니다.","무릎을 굽혀 허리를 숙이면서 손가락이 앞을 향하도록 바벨을 잡고 손은 어깨넓이보다 약간 넓게 위치시킵니다.","등을 곧게 유지하고 가슴을 펴면서 발 뒤꿈치로 힘을 주어 바벨을 들어올리고 허리와 무릎을 펼칩니다.","서서 일어나면서 둔근을 조이고 복부에 힘을 줍니다.","바벨을 내릴 때는 허리와 무릎을 구부려 바닥으로 낮추면서 등을 곧게 유지합니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0032-ila4NZS.jpg', 'videos/0032-ila4NZS.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0033', 'barbell decline bench press', 'chest', 'chest', 'barbell', '{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con i piedi fissati e la testa più in basso rispetto ai fianchi.","Afferrare il bilanciere con una presa prona leggermente più larga della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti piegati.","Fermati per un momento in basso, quindi riporta il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız sabitlenmiş ve başınız kalçalarınızdan aşağıda olacak şekilde bir iniş bankına uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halterin askısını açın ve dirseklerinizi içeride tutarak yavaşça göğsünüze doğru indirin.","Altta bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу хватом сверху на расстоянии чуть шире плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ी अधिक चौड़ी पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, zabezpieczając stopy, tak aby głowa znajdowała się niżej niż biodra.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie przy ciele.","Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 고정한 하강 벤치에 누운 상태로 머리가 허리보다 아래에 위치하도록 합니다.","손가락이 앞을 향하도록 어깨넓이보다 약간 넓게 바벨을 잡습니다.","바벨을 받쳐주는 거치대에서 내려놓은 후 천천히 가슴 쪽으로 내립니다. 팔꿈치를 안쪽으로 유지합니다.","맨 아래에서 잠시 멈춘 후 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/0033-GrO65fd.jpg', 'videos/0033-GrO65fd.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0034', 'barbell decline bent arm pullover', 'back', 'back', 'barbell', '{"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con la testa più in basso rispetto ai fianchi e i piedi fissati.","Tieni un bilanciere con una presa prona (palmi rivolti lontano da te) ed estendi le braccia direttamente sopra il petto.","Abbassa il bilanciere dietro la testa in modo controllato, mantenendo le braccia leggermente piegate.","Fai una pausa per un momento, quindi riporta il bilanciere nella posizione iniziale contraendo i dorsali.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız kalçalarınızdan aşağıda ve ayaklarınız sağlam olacak şekilde bir iniş bankına uzanın.","Halteri pronasyonlu bir tutuşla tutun (avuç içleriniz sizden uzağa bakacak şekilde) ve kollarınızı düz bir şekilde göğsünüzün üzerine uzatın.","Kollarınızı hafifçe bükerek halteri başınızın arkasına kontrollü bir şekilde indirin.","Bir an duraklayın, ardından latlarınızı kasarak halteri başlangıç ​​pozisyonuna geri kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial contrayendo los dorsales.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Возьмите штангу пронированным хватом (ладонями от себя) и вытяните руки прямо над грудью.","Контролируемо опустите штангу за голову, держа руки слегка согнутыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение, напрягая широчайшие мышцы.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。","有控制地将杠铃降低到头后，保持手臂稍微弯曲。","暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。","重复所需的重复次数。"],"hi":["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेट जाएँ।","एक बारबेल को उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और अपनी भुजाओं को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को थोड़ा मुड़ा हुआ रखते हुए बारबेल को अपने सिर के पीछे नियंत्रित तरीके से नीचे लाएँ।","एक पल के लिए रुकें, फिर अपने लैट्स को सिकोड़कर बारबेल को शुरुआती स्थिति में वापस उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, tak aby głowa znajdowała się niżej niż biodra, a stopy były zabezpieczone.","Chwyć sztangę chwytem pronowanym (dłonie skierowane od siebie) i wyprostuj ręce nad klatką piersiową.","Opuszczaj sztangę za głowę w kontrolowany sposób, utrzymując ręce lekko ugięte.","Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej, napinając mięśnie najszersze grzbietu.","Powtórz odpowiednią liczbę razy."],"ko":["머리가 허리보다 아래에 위치하도록 하강 벤치에 누우면서 발을 고정합니다.","손가락이 뒤를 향하는 그립(정위 그립)으로 바벨을 잡고 팔을 가슴 위로 펼칩니다.","팔을 약간 구부린 상태로 제어된 동작으로 바벨을 머리 뒤로 내립니다.","잠시 멈춘 후 광배근을 수축시키면서 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","chest"]', 'lats', 'images/0034-hMEptv0.jpg', 'videos/0034-hMEptv0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0035', 'barbell decline close grip to skull press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con la testa più bassa dei piedi e tieni un bilanciere con una presa salda.","Abbassa il bilanciere verso la fronte piegando i gomiti e mantenendo ferma la parte superiore delle braccia.","Fai una pausa per un momento, quindi estendi le braccia per riportare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız ayaklarınızdan aşağıda olacak şekilde bir bench sehpasına uzanın ve halteri yakın bir tutuşla tutun.","Dirseklerinizi bükerek, üst kollarınızı sabit tutarak halteri alnınıza doğru indirin.","Bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itmek için kollarınızı uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.","Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, опустив голову ниже ног, и возьмите штангу узким хватом.","Опустите штангу ко лбу, согнув локти, сохраняя плечи неподвижными.","Сделайте паузу на мгновение, затем вытяните руки, чтобы вернуть штангу в исходное положение.","Повторите необходимое количество повторений."],"zh":["躺在下斜长凳上，头低于脚，紧紧握住杠铃。","弯曲肘部，将杠铃向前额降低，保持上臂静止。","暂停片刻，然后伸展双臂将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["अपने सिर को अपने पैरों से नीचे करके एक डिक्लाइन बेंच पर लेटें और बारबेल को कसकर पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर बारबेल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी बाहों को फैलाकर बारबेल को वापस प्रारंभिक स्थिति में दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, głową niżej niż stopy, i chwyć sztangę wąskim chwytem.","Opuść sztangę w kierunku czoła, uginając łokcie i utrzymując ramiona nieruchomo.","Zatrzymaj się na chwilę, a następnie wyprostuj ręce, wypychając sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["머리가 발보다 아래에 위치하도록 하강 벤치에 누워 좁은 그립으로 바벨을 잡습니다.","팔꿈치를 구부려 바벨을 이마 쪽으로 내리면서 상박을 고정된 상태로 유지합니다.","잠시 멈춘 후 팔을 펼쳐 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0035-LMGXZn8.jpg', 'videos/0035-LMGXZn8.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1255', 'barbell decline pullover', 'chest', 'chest', 'barbell', '{"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con la testa più in basso rispetto ai fianchi e i piedi fissati.","Tieni il bilanciere con una presa prona (palmi rivolti lontano da te) e le mani leggermente più larghe della larghezza delle spalle.","Estendi le braccia sopra il petto, mantenendo una leggera piegatura dei gomiti.","Abbassa il bilanciere con un movimento ad arco dietro la testa, sentendo l''allungamento del petto e delle spalle.","Fare una pausa per un momento, quindi riportare il bilanciere nella posizione iniziale invertendo il movimento.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız kalçalarınızdan aşağıda ve ayaklarınız sağlam olacak şekilde bir iniş bankına uzanın.","Halteri pronasyonlu bir tutuşla (avuç içleriniz sizden uzağa bakacak şekilde) ve elleriniz omuz genişliğinden biraz daha açık olacak şekilde tutun.","Dirseklerinizi hafif bükerek kollarınızı göğsünüzün üzerine uzatın.","Göğsünüzde ve omuzlarınızda bir gerginlik hissederek halteri başınızın arkasına bir yay hareketi yaparak indirin.","Bir an duraklayın, ardından hareketi tersine çevirerek halteri başlangıç ​​pozisyonuna getirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.","Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.","Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.","Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Держите штангу пронированным хватом (ладонями от себя), расставив руки чуть шире плеч.","Вытяните руки над грудью, сохраняя небольшой изгиб в локтях.","Опустите штангу по дуге за голову, чувствуя растяжение в груди и плечах.","Сделайте паузу на мгновение, затем верните штангу в исходное положение, изменив движение.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","旋前握住杠铃（手掌背向自己），双手之间的距离略宽于肩宽。","将手臂伸至胸部上方，保持肘部轻微弯曲。","以弧线动作将杠铃降低到头后，感受胸部和肩膀的伸展。","暂停片刻，然后反向动作将杠铃恢复到起始位置。","重复所需的重复次数。"],"hi":["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेट जाएँ।","बारबेल को एक उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और आपके हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर फैलाएँ।","अपनी छाती और कंधों में खिंचाव महसूस करते हुए बारबेल को अपने सिर के पीछे चाप की गति में नीचे करें।","एक पल के लिए रुकें, फिर गति को उलट कर बारबेल को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, tak aby głowa znajdowała się niżej niż biodra, a stopy były zabezpieczone.","Chwyć sztangę chwytem pronowanym (dłonie skierowane od siebie), dłonie nieco szerzej niż szerokość barków.","Wyprostuj ręce nad klatką piersiową, utrzymując lekkie ugięcie w łokciach.","Opuść sztangę ruchem łukowym za głowę, odczuwając rozciąganie klatki piersiowej i barków.","Zatrzymaj się na chwilę, a następnie wróć sztangą do pozycji wyjściowej, wykonując ruch odwrotny.","Powtórz odpowiednią liczbę razy."],"ko":["머리가 허리보다 아래에 위치하도록 하강 벤치에 누우면서 발을 고정합니다.","손가락이 뒤를 향하는 그립으로 바벨을 잡고 손은 어깨넓이보다 약간 넓게 위치시킵니다.","팔을 약간 구부린 상태로 가슴 위로 팔을 펼칩니다.","호 모양으로 바벨을 머리 뒤로 내리면서 가슴과 어깨의 스트레치를 느낍니다.","잠시 멈춘 후 반대 동작으로 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/1255-9sgNE2O.jpg', 'videos/1255-9sgNE2O.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0036', 'barbell decline wide-grip press', 'chest', 'chest', 'barbell', '{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con i piedi fissati e la testa più in basso rispetto ai fianchi.","Afferrare il bilanciere con una presa ampia, leggermente più larga della larghezza delle spalle.","Abbassa il bilanciere sul petto, mantenendo i gomiti ai lati.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız sabitlenmiş ve başınız kalçalarınızdan aşağıda olacak şekilde bir iniş bankına uzanın.","Halteri omuz genişliğinden biraz daha geniş, geniş bir tutuşla kavrayın.","Dirseklerinizi yanlara doğru uzatarak halteri göğsünüze doğru indirin.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos hacia los lados.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу широким хватом, на расстоянии чуть шире ширины плеч.","Опустите штангу к груди, разведя локти в стороны.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","宽握距抓住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部向两侧伸出。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ से पकड़ें।","अपनी कोहनियों को बगल की ओर रखते हुए, बारबेल को अपनी छाती तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, zabezpieczając stopy, tak aby głowa znajdowała się niżej niż biodra.","Chwyć sztangę szerokim chwytem, nieco szerszym niż szerokość barków.","Opuść sztangę do klatki piersiowej, trzymając łokcie skierowane na boki.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["발을 고정한 하강 벤치에 누운 상태로 머리가 허리보다 아래에 위치하도록 합니다.","넓은 그립(어깨넓이보다 넓게)으로 바벨을 잡습니다.","바벨을 가슴 쪽으로 내리면서 팔꿈치를 옆으로 유지합니다.","팔을 완전히 펴면서 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/0036-hl8DUh8.jpg', 'videos/0036-hl8DUh8.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0037', 'barbell decline wide-grip pullover', 'back', 'back', 'barbell', '{"en":["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con la testa più in basso rispetto ai fianchi e i piedi fissati.","Tieni un bilanciere con una presa ampia ed estendi le braccia direttamente sopra il petto.","Abbassa il bilanciere dietro la testa in modo controllato, mantenendo le braccia tese.","Fare una pausa per un momento, quindi riportare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız kalçalarınızdan aşağıda ve ayaklarınız sağlam olacak şekilde bir bench sehpasına uzanın.","Geniş tutuşlu bir halter tutun ve kollarınızı göğsünüzün üzerine düz bir şekilde uzatın.","Kollarınızı düz tutarak halteri başınızın arkasına kontrollü bir şekilde indirin.","Bir süre duraklayın, ardından halteri tekrar başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.","Sujeta una barra con un agarre amplio y extiende los brazos rectos por encima del pecho.","Baja la barra detrás de la cabeza de forma controlada, manteniendo los brazos rectos.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, опустив голову ниже бедер и зафиксировав ступни.","Возьмите штангу широким хватом и вытяните руки прямо над грудью.","Контролируемо опустите штангу за голову, держа руки прямыми.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","宽握距握住杠铃，并将双臂伸直至胸部上方。","有控制地将杠铃降低到头后，保持手臂伸直。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"],"hi":["अपने सिर को अपने कूल्हों से नीचे और अपने पैरों को सुरक्षित रखते हुए एक डिक्लाइन बेंच पर लेटें।","एक बारबेल को चौड़ी पकड़ से पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए बारबेल को अपने सिर के पीछे नियंत्रित तरीके से नीचे लाएँ।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, tak aby głowa znajdowała się niżej niż biodra, a stopy były zabezpieczone.","Chwyć sztangę szerokim chwytem i wyprostuj ręce nad klatką piersiową.","Opuszczaj sztangę za głowę w kontrolowany sposób, utrzymując ręce proste.","Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["머리가 허리보다 아래에 위치하도록 하강 벤치에 누우면서 발을 고정합니다.","넓은 그립으로 바벨을 잡고 팔을 가슴 위로 펼칩니다.","팔을 곧게 유지하면서 제어된 동작으로 바벨을 머리 뒤로 내립니다.","잠시 멈춘 후 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","chest"]', 'lats', 'images/0037-Hj4FOCd.jpg', 'videos/0037-Hj4FOCd.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0038', 'barbell drag curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm''s length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere un bilanciere con una presa subdola, con i palmi rivolti verso l''alto.","Lascia che il bilanciere penda a distanza di un braccio davanti alle cosce.","Tenendo ferma la parte superiore delle braccia, piega il bilanciere verso il petto contraendo i bicipiti.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri avuç içleriniz yukarı bakacak şekilde alttan kavrayarak tutun.","Halterin uyluklarınızın önünde kol uzunluğunda asılı kalmasına izin verin.","Üst kollarınızı sabit tutarak, bicepslerinizi kasarak halteri göğsünüze doğru kıvırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Deja que la barra cuelgue a la longitud del brazo frente a los muslos.","Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обратным хватом ладонями вверх.","Пусть штанга висит на расстоянии вытянутой руки перед бедрами.","Удерживая плечи неподвижно, поднимите штангу к груди, напрягая бицепсы.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。","让杠铃悬挂在大腿前面，与手臂保持一定距离。","保持上臂静止，通过收缩二头肌将杠铃向上卷曲至胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियाँ ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","बारबेल को अपनी जांघों के सामने एक हाथ की दूरी पर लटका रहने दें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर बारबेल को अपनी छाती की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i chwyć sztangę chwytem podchwytem, dłonie skierowane do góry.","Trzymaj sztangę swobodnie opuszczoną na wyciągniętych ramionach przed udami.","Utrzymując ramiona nieruchomo, uginaj sztangę w kierunku klatki piersiowej, napinając biceps.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 손가락이 앞을 향하도록 바벨을 잡고 손바닥이 위를 향하게 합니다.","바벨이 넓적다리 앞에 팔 길이로 내려진 상태에서 시작합니다.","상박을 고정한 상태에서 바벨을 이두근을 수축시켜 가슴 쪽으로 올립니다.","맨 위에서 잠시 멈춘 후 천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0038-IENzBdA.jpg', 'videos/0038-IENzBdA.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1370', 'barbell floor calf raise', 'lower legs', 'lower legs', 'barbell', '{"en":["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Posiziona un bilanciere sul pavimento di fronte a te.","Stai con le punte dei piedi sul bordo del bilanciere, con i talloni pendenti.","Se necessario, aggrapparsi a un oggetto stabile per mantenere l''equilibrio.","Alza i talloni il più in alto possibile, usando i polpacci per sollevare il corpo.","Fai una pausa per un momento in alto, quindi abbassa lentamente i talloni nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Önünüzdeki yere bir halter yerleştirin.","Ayak parmak uçlarınız halterin kenarında olacak şekilde, topuklarınız sarkacak şekilde durun.","Gerekirse denge için sabit bir nesneye tutunun.","Vücudunuzu kaldırmak için baldırlarınızı kullanarak topuklarınızı mümkün olduğunca yükseğe kaldırın.","Tepe noktasında bir an duraklayın, ardından topuklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca una barra en el suelo frente a ti.","Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.","Sujétate de un objeto estable para mantener el equilibrio si es necesario.","Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Положите штангу на пол перед собой.","Встаньте подушечками стоп на край штанги, свесив пятки.","При необходимости держитесь за устойчивый предмет для равновесия.","Поднимите пятки как можно выше, используя икроножные мышцы для подъема тела.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["将杠铃放在您面前的地板上。","站立，脚掌放在杠铃边缘，脚跟悬垂。","如果需要，请抓住一个稳定的物体以保持平衡。","尽可能高地抬高脚后跟，用小腿来抬起身体。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने सामने फर्श पर एक बारबेल रखें।","अपने पैरों की उंगलियों को बारबेल के किनारे पर रखते हुए, अपनी एड़ियों को लटकाकर खड़े रहें।","यदि आवश्यक हो तो संतुलन के लिए किसी स्थिर वस्तु को पकड़ें।","अपने शरीर को ऊपर उठाने के लिए अपनी पिंडलियों का उपयोग करते हुए, अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż sztangę na podłodze przed sobą.","Stań tak, aby palce stóp opierały się na krawędzi sztangi, a pięty zwisały poza nią.","W razie potrzeby przytrzymaj się stabilnego przedmiotu dla równowagi.","Unieś pięty jak najwyżej, wykorzystując mięśnie łydek do uniesienia ciała.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść pięty z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["바벨을 바닥에 놓습니다.","발의 앞부분(발가락 부분)을 바벨의 모서리에 올려놓고 뒷꿈치는 공중에 띄웁니다.","필요하면 균형을 위해 안정적인 물체를 잡습니다.","종아리 힘을 사용하여 뒷꿈치를 가능한 한 높게 올립니다.","맨 위에서 잠시 멈춘 후 천천히 뒷꿈치를 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings"]', 'calves', 'images/1370-2IHEa2T.jpg', 'videos/1370-2IHEa2T.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0039', 'barbell front chest squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni il bilanciere davanti al petto con le mani alla larghezza delle spalle, i gomiti rivolti in avanti.","Coinvolgi il core e mantieni il petto sollevato mentre abbassi il corpo in una posizione tozza, spingendo i fianchi indietro e piegando le ginocchia.","Abbassati finché le cosce non sono parallele al suolo o il più in basso possibile.","Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durmaya başlayın.","Halteri göğsünüzün önünde, elleriniz omuz genişliğinde açık, dirsekleriniz ileriyi gösterecek şekilde tutun.","Vücudunuzu çömelme pozisyonuna indirirken, kalçalarınızı geriye itip dizlerinizi bükerken, merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Uyluklarınız yere paralel veya rahatça gidebildiğiniz kadar alçaltın.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente al pecho con las manos separadas a la altura de los hombros, los codos apuntando hacia delante.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Для начала встаньте, поставив ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу перед грудью, руки на ширине плеч, локти направлены вперед.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在胸前，双手与肩同宽，肘部向前。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","अपने हाथों को कंधे की चौड़ाई पर, कोहनियों को आगे की ओर रखते हुए, बारबेल को अपनी छाती के सामने पकड़ें।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट स्थिति में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę przed klatką piersiową, dłonie na szerokość barków, łokcie skierowane do przodu.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, opuszczając ciało do pozycji przysiadu, cofając biodra i uginając kolana.","Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 가슴 앞에 올려놓고 손을 어깨넓이로 벌려 팔꿈치는 앞으로 향하게 합니다.","복부에 힘을 주고 가슴을 펼친 상태를 유지하면서 몸을 내립니다. 허리를 뒤로 빼고 무릎을 구부려 스쿼트 위치에 들어갑니다.","넓적다리가 바닥과 평행하거나 편안한 범위 내에서 최대한 낮게 내려갑니다.","맨 아래에서 잠시 멈춘 후 발 뒤꿈치로 힘을 주어 시작 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/0039-IeTIEqg.jpg', 'videos/0039-IeTIEqg.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0041', 'barbell front raise', 'shoulders', 'shoulders', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere un bilanciere davanti alle cosce con una presa prona.","Tieni le braccia tese e solleva il bilanciere in avanti e verso l''alto fino a raggiungere il livello delle spalle.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri üstten kavrayarak uyluklarınızın önünde tutun.","Kollarınızı düz tutun ve halteri omuz hizasına gelene kadar ileri ve yukarı doğru kaldırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, удерживайте штангу перед бедрами хватом сверху.","Держите руки прямо и поднимите штангу вперед и вверх, пока она не достигнет уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。","保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने एक बारबेल को ज़ोर से पकड़ें।","अपनी भुजाओं को सीधा रखें और बारबेल को कंधे के स्तर तक पहुंचने तक आगे और ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i chwyć sztangę przed udami chwytem nachwytem.","Utrzymując ręce proste, unieś sztangę do przodu i w górę, aż osiągnie wysokość barków.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 섭니다.","손가락이 앞을 향하도록 어깨높이 앞에 바벨을 잡습니다.","팔을 곧게 펼친 상태를 유지하면서 바벨을 앞으로 위쪽으로 들어올려 어깨 높이에 도달하게 합니다.","맨 위에서 잠시 멈춘 후 천천히 바벨을 시작 위치로 내립니다. 원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","triceps"]', 'delts', 'images/0041-b2Uoz54.jpg', 'videos/0041-b2Uoz54.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0040', 'barbell front raise and pullover', 'chest', 'chest', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere un bilanciere con una presa prona, i palmi rivolti verso il basso.","Tieni le braccia tese e solleva il bilanciere davanti a te fino a raggiungere l''altezza delle spalle.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Successivamente, abbassa il bilanciere dietro la testa, mantenendo le braccia dritte.","Fermati per un momento in basso, quindi solleva il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri avuç içleriniz aşağıya bakacak şekilde üstten kavrayarak tutun.","Kollarınızı düz tutun ve halteri omuz yüksekliğine ulaşıncaya kadar önünüzde kaldırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","Daha sonra kollarınızı düz tutarak halteri başınızın arkasına indirin.","Altta bir an duraklayın, ardından halteri tekrar başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos rectos y levanta la barra frente a ti hasta que alcance la altura de los hombros.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","A continuación, baja la barra detrás de la cabeza, manteniendo los brazos rectos.","Haz una pausa breve en la parte baja y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Держите руки прямо и поднимите штангу перед собой до уровня плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Затем опустите штангу за голову, держа руки прямыми.","Сделайте небольшую паузу в нижней точке, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。","保持双臂伸直，将杠铃举至身前，直至达到肩膀高度。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","接下来，将杠铃放低到头后，保持手臂伸直。","在底部停顿片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियां नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी भुजाएं सीधी रखें और बारबेल को अपने सामने तब तक उठाएं जब तक यह कंधे की ऊंचाई तक न पहुंच जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","इसके बाद, अपनी बाहों को सीधा रखते हुए बारबेल को अपने सिर के पीछे नीचे करें।","नीचे एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.","Utrzymując ręce proste, unieś sztangę przed sobą, aż osiągnie wysokość barków.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Następnie opuść sztangę za głowę, utrzymując ręce proste.","Zatrzymaj się na chwilę na dole, a następnie unieś sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 서서 손가락이 아래를 향하도록 바벨을 잡습니다.","팔을 곧게 펼친 상태를 유지하면서 바벨을 앞으로 들어올려 어깨 높이에 도달하게 합니다.","맨 위에서 잠시 멈춘 후 천천히 바벨을 시작 위치로 내립니다.","다음으로 팔을 곧게 유지하면서 바벨을 머리 뒤로 내립니다.","맨 아래에서 잠시 멈춘 후 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'deltoids', '["deltoids","triceps"]', 'pectorals', 'images/0040-33AzZeV.jpg', 'videos/0040-33AzZeV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0042', 'barbell front squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni il bilanciere davanti alle spalle, appoggiandolo sulla clavicola e sulle spalle.","Coinvolgi il core e mantieni il petto sollevato mentre abbassi il corpo in una posizione tozza, spingendo i fianchi indietro e piegando le ginocchia.","Abbassati finché le cosce non sono parallele al suolo o il più in basso possibile.","Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durmaya başlayın.","Halteri omuzlarınızın önünde tutun, köprücük kemiğinize ve omuzlarınıza yaslayın.","Vücudunuzu çömelme pozisyonuna indirirken, kalçalarınızı geriye itip dizlerinizi bükerken, merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Uyluklarınız yere paralel veya rahatça gidebildiğiniz kadar alçaltın.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Для начала встаньте, поставив ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу перед плечами, положив ее на ключицы и плечи.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在肩膀前面，将其放在锁骨和肩膀上。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े होकर शुरुआत करें, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपने कंधों के सामने पकड़ें, इसे अपने कॉलरबोन और कंधों पर टिकाएं।","अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें क्योंकि आप अपने शरीर को स्क्वाट स्थिति में नीचे लाते हैं, अपने कूल्हों को पीछे धकेलते हैं और अपने घुटनों को मोड़ते हैं।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę przed barkami, opierając ją na obojczyku i barkach.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, opuszczając ciało do pozycji przysiadu, cofając biodra i uginając kolana.","Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 어깨 앞에 올려놓으면서 빗장뼈와 어깨에 걸쳐놓습니다.","복부에 힘을 주고 가슴을 펼친 상태를 유지하면서 몸을 내립니다. 허리를 뒤로 빼고 무릎을 구부려 스쿼트 위치에 들어갑니다.","넓적다리가 바닥과 평행하거나 편안한 범위 내에서 최대한 낮게 내려갑니다.","맨 아래에서 잠시 멈춘 후 발 뒤꿈치로 힘을 주어 시작 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/0042-zG0zs85.jpg', 'videos/0042-zG0zs85.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0043', 'barbell full squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni il bilanciere sulla parte superiore della schiena, appoggiandolo sulle trappole o sui deltoidi posteriori.","Coinvolgi il tuo core e mantieni il petto sollevato mentre inizi ad abbassare il corpo.","Piega le ginocchia e i fianchi, spingendo i fianchi indietro e in basso come se fossi seduto su una sedia.","Abbassati finché le cosce non sono parallele al suolo o leggermente più in basso.","Tieni le ginocchia in linea con le dita dei piedi e il peso sui talloni.","Spingi i talloni per rialzarti, estendendo i fianchi e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halterinizi sırtınızın üst kısmında tutun ve trapezlerinize veya arka deltalarınıza dayayın.","Vücudunuzu aşağı indirmeye başladığınızda merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Dizlerinizi ve kalçalarınızı bükün, sanki bir sandalyeye oturuyormuş gibi kalçalarınızı geriye ve aşağı doğru itin.","Uyluklarınız yere paralel veya biraz aşağıda oluncaya kadar kendinizi indirin.","Dizlerinizi ayak parmaklarınızla aynı hizada ve ağırlığınızı topuklarınızda tutun.","Kalçalarınızı ve dizlerinizi uzatarak ayağa kalkmak için topuklarınızı kullanın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","放低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने आप को तब तक नीचे रखें जब तक आपकी जांघें ज़मीन के समानांतर या थोड़ा नीचे न हो जाएं।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, rozpoczynając opuszczanie ciała.","Ugnij kolana i biodra, cofając biodra w dół, jakbyś siadał na krześle.","Opuszczaj się, aż uda będą równoległe do podłoża lub nieco niżej.","Utrzymuj kolana w linii ze stopami, a ciężar ciała w piętach.","Wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 상체 뒤쪽에 올려놓으면서 승모근이나 후삼각근에 걸쳐놓습니다.","복부에 힘을 주고 가슴을 펼친 상태를 유지하면서 몸을 내리기 시작합니다.","무릎과 허리를 구부려 의자에 앉는 것처럼 허리를 뒤로 내립니다.","넓적다리가 바닥과 평행하거나 약간 아래까지 내려갑니다.","무릎이 발가락과 일직선상에 있고 체중은 발 뒤꿈치에 있는지 확인합니다.","발 뒤꿈치로 힘을 주어 일어나면서 허리와 무릎을 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/0043-qXTaZnJ.jpg', 'videos/0043-qXTaZnJ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1461', 'barbell full squat (back pov)', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni il bilanciere sulla parte superiore della schiena, appoggiandolo sulle trappole o sui deltoidi posteriori.","Coinvolgi il tuo core e mantieni il petto sollevato mentre inizi ad abbassare il corpo.","Piega le ginocchia e i fianchi, spingendo i fianchi indietro e in basso come se fossi seduto su una sedia.","Abbassa il corpo finché le cosce non sono parallele al suolo o leggermente al di sotto.","Tieni le ginocchia in linea con le dita dei piedi e il peso sui talloni.","Spingi i talloni per rialzarti, estendendo i fianchi e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halterinizi sırtınızın üst kısmında tutun ve trapezlerinize veya arka deltalarınıza dayayın.","Vücudunuzu aşağı indirmeye başladığınızda merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Dizlerinizi ve kalçalarınızı bükün, sanki bir sandalyeye oturuyormuş gibi kalçalarınızı geriye ve aşağı doğru itin.","Uyluklarınız yere paralel veya biraz aşağıda oluncaya kadar vücudunuzu indirin.","Dizlerinizi ayak parmaklarınızla aynı hizada ve ağırlığınızı topuklarınızda tutun.","Kalçalarınızı ve dizlerinizi uzatarak ayağa kalkmak için topuklarınızı kullanın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","降低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, rozpoczynając opuszczanie ciała.","Ugnij kolana i biodra, cofając biodra w dół, jakbyś siadał na krześle.","Opuszczaj ciało, aż uda będą równoległe do podłoża lub nieco niżej.","Utrzymuj kolana w linii ze stopami, a ciężar ciała w piętach.","Wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 상체 뒤쪽에 올려놓으면서 승모근이나 후삼각근에 걸쳐놓습니다.","복부에 힘을 주고 가슴을 펼친 상태를 유지하면서 몸을 내리기 시작합니다.","무릎과 허리를 구부려 의자에 앉는 것처럼 허리를 뒤로 내립니다.","몸을 내려서 넓적다리가 바닥과 평행하거나 약간 아래까지 내려갑니다.","무릎이 발가락과 일직선상에 있고 체중은 발 뒤꿈치에 있는지 확인합니다.","발 뒤꿈치로 힘을 주어 일어나면서 허리와 무릎을 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/1461-DhMl549.jpg', 'videos/1461-DhMl549.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1462', 'barbell full squat (side pov)', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni il bilanciere sulla parte superiore della schiena, appoggiandolo sulle trappole o sui deltoidi posteriori.","Coinvolgi il tuo core e mantieni il petto sollevato mentre inizi ad abbassare il corpo.","Piega le ginocchia e i fianchi, spingendo i fianchi indietro e in basso come se fossi seduto su una sedia.","Abbassa il corpo finché le cosce non sono parallele al suolo o leggermente al di sotto.","Tieni le ginocchia in linea con le dita dei piedi e il peso sui talloni.","Spingi i talloni per rialzarti, estendendo i fianchi e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halterinizi sırtınızın üst kısmında tutun ve trapezlerinize veya arka deltalarınıza dayayın.","Vücudunuzu aşağı indirmeye başladığınızda merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Dizlerinizi ve kalçalarınızı bükün, sanki bir sandalyeye oturuyormuş gibi kalçalarınızı geriye ve aşağı doğru itin.","Uyluklarınız yere paralel veya biraz aşağıda oluncaya kadar vücudunuzu indirin.","Dizlerinizi ayak parmaklarınızla aynı hizada ve ağırlığınızı topuklarınızda tutun.","Kalçalarınızı ve dizlerinizi uzatarak ayağa kalkmak için topuklarınızı kullanın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo.","Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla.","Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, когда начинаете опускать тело вниз.","Согните колени и бедра, отводя бедра назад и вниз, как будто вы сидите на стуле.","Опускайте тело до тех пор, пока бедра не станут параллельны земле или немного ниже.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","降低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","जब आप अपने शरीर को नीचे करना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें।","घुटनों और कूल्हों पर झुकें, अपने कूल्हों को पीछे और नीचे धकेलें जैसे कि कुर्सी पर बैठे हों।","अपने शरीर को तब तक नीचे झुकाएँ जब तक कि आपकी जाँघें ज़मीन के समानांतर या थोड़ा नीचे न आ जाएँ।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, rozpoczynając opuszczanie ciała.","Ugnij kolana i biodra, cofając biodra w dół, jakbyś siadał na krześle.","Opuszczaj ciało, aż uda będą równoległe do podłoża lub nieco niżej.","Utrzymuj kolana w linii ze stopami, a ciężar ciała w piętach.","Wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 상체 뒤쪽에 올려놓으면서 승모근이나 후삼각근에 걸쳐놓습니다.","복부에 힘을 주고 가슴을 펼친 상태를 유지하면서 몸을 내리기 시작합니다.","무릎과 허리를 구부려 의자에 앉는 것처럼 허리를 뒤로 내립니다.","몸을 내려서 넓적다리가 바닥과 평행하거나 약간 아래까지 내려갑니다.","무릎이 발가락과 일직선상에 있고 체중은 발 뒤꿈치에 있는지 확인합니다.","발 뒤꿈치로 힘을 주어 일어나면서 허리와 무릎을 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/1462-iYzB0Cz.jpg', 'videos/1462-iYzB0Cz.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1545', 'barbell full zercher squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere nell''incavo dei gomiti, con le mani che afferrano il bilanciere per stabilità.","Coinvolgi il core e mantieni il petto sollevato mentre abbassi i fianchi indietro e in basso in una posizione tozza.","Tieni le ginocchia in linea con le dita dei piedi e il peso sui talloni.","Abbassati finché le cosce non sono parallele al suolo o il più in basso possibile.","Spingi i talloni per rialzarti, contraendo i glutei nella parte superiore del movimento.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halterinizi dirseklerinizin kıvrımlarında tutun ve ellerinizle denge sağlamak için halteri kavrayın.","Kalçalarınızı geriye ve aşağıya doğru çömelme pozisyonuna indirirken, merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Dizlerinizi ayak parmaklarınızla aynı hizada ve ağırlığınızı topuklarınızda tutun.","Uyluklarınız yere paralel veya rahatça gidebildiğiniz kadar alçaltın.","Hareketin en üst noktasında kalça kaslarınızı sıkarak ayağa kalkmak için topuklarınızın üzerinden geçin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra en el pliegue de los codos, agarrándola con las manos para mantener la estabilidad.","Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla.","Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, apretando los glúteos en la parte alta del movimiento.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу на сгибах локтей, удерживая ее руками для устойчивости.","Напрягите корпус и держите грудь поднятой, опуская бедра назад и вниз в положение приседа.","Держите колени на одной линии с пальцами ног, а вес тела перенесите на пятки.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Проведите пятками, чтобы встать обратно, сжимая ягодицы в верхней части движения.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。","当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在动作的最高点挤压臀部。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","स्थिरता के लिए बारबेल को अपनी कोहनियों के मोड़ से पकड़ें, अपने हाथों से बारबेल को पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों को पीछे की ओर झुकाते हुए स्क्वाट स्थिति में आते समय अपनी छाती को ऊपर उठाएं।","अपने घुटनों को अपने पंजों की सीध में रखें और अपना वजन अपनी एड़ियों पर रखें।","तब तक नीचे जाएँ जब तक आपकी जाँघें ज़मीन के समानांतर न हो जाएँ, या जितना नीचे आप आराम से जा सकें।","वापस खड़े होने के लिए अपनी एड़ियों के माध्यम से ड्राइव करें, आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę w zgięciach łokci, chwytając ją dłońmi dla stabilności.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, opuszczając biodra w dół do pozycji przysiadu.","Utrzymuj kolana w linii ze stopami, a ciężar ciała w piętach.","Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Wypchnij się przez pięty, wracając do pozycji stojącej, ściskając pośladki na szczycie ruchu.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨넓이로 벌리고 발가락을 약간 바깥쪽으로 향하게 섭니다.","바벨을 팔꿈치 안쪽에 걸쳐놓고 바벨을 잡아 안정성을 유지합니다.","복부에 힘을 주고 가슴을 들어올린 상태를 유지하면서 허리를 뒤로 내리고 스쿼트 위치로 내려갑니다.","무릎이 발가락과 일직선상에 있고 체중은 발 뒤꿈치에 있는지 확인합니다.","넓적다리가 바닥과 평행하거나 편안한 범위 내에서 최대한 낮게 내려갑니다.","발 뒤꿈치로 힘을 주어 일어나면서 둔근을 조이고 움직임의 최상단에서 조입니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/1545-vR1vold.jpg', 'videos/1545-vR1vold.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1409', 'barbell glute bridge', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia sdraiandoti sulla schiena a terra con le ginocchia piegate e i piedi appoggiati sul pavimento.","Posiziona un bilanciere sui fianchi, tenendolo saldamente con entrambe le mani.","Coinvolgi i glutei e i muscoli centrali, quindi solleva i fianchi da terra finché il tuo corpo non forma una linea retta dalle ginocchia alle spalle.","Fermati un attimo in alto, contraendo i glutei.","Abbassa lentamente i fianchi fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülmüş ve ayaklarınız yere düz basacak şekilde yere sırt üstü uzanarak başlayın.","Kalçalarınızın üzerine bir halter yerleştirin ve iki elinizle güvenli bir şekilde tutun.","Kalça kaslarınızı ve göbek kaslarınızı çalıştırın, ardından vücudunuz dizlerinizden omuzlarınıza kadar düz bir çizgi oluşturana kadar kalçalarınızı yerden kaldırın.","Kalça kaslarınızı sıkarak tepede bir an duraklayın.","Kalçalarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что лягте на спину на землю, согните колени и поставьте ступни на пол.","Положите штангу на бедра, крепко удерживая ее обеими руками.","Задействуйте ягодицы и мышцы корпуса, затем поднимите бедра от земли, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, напрягая ягодицы.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先平躺在地上，膝盖弯曲，双脚平放在地板上。","将杠铃放在臀部上，用双手牢牢握住它。","锻炼臀部和核心肌肉，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，挤压臀部。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट रखते हुए, अपनी पीठ के बल जमीन पर लेटकर शुरुआत करें।","अपने कूल्हों पर एक बारबेल रखें, इसे दोनों हाथों से सुरक्षित रूप से पकड़ें।","अपने ग्लूट्स और कोर की मांसपेशियों को शामिल करें, फिर अपने कूल्हों को ज़मीन से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach na podłodze, kolana ugięte, a stopy oparte płasko na podłodze.","Umieść sztangę na biodrach, trzymając ją pewnie obiema rękami.","Napnij pośladki i mięśnie tułowia, a następnie unieś biodra z podłogi, aż ciało utworzy prostą linię od kolan do barków.","Zatrzymaj się na chwilę na górze, ściskając pośladki.","Powoli opuść biodra z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["바닥에 누워 무릎을 구부리고 발을 바닥에 디딤니다.","바벨을 허리에 걸쳐놓고 양손으로 안정적으로 잡습니다.","둔근과 복부에 힘을 주고 바닥에서 허리를 들어올려 몸이 무릎부터 어깨까지 일직선을 이루도록 합니다.","맨 위에서 잠시 멈춘 후 둔근을 꽉 조입니다.","천천히 허리를 바닥으로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/1409-qKBpF7I.jpg', 'videos/1409-qKBpF7I.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3562', 'barbell glute bridge two legs on bench (male)', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia sedendoti sul bordo di una panca con la parte superiore della schiena appoggiata contro di essa e i piedi appoggiati a terra, alla larghezza dei fianchi.","Posiziona un bilanciere sui fianchi, tenendolo saldamente con entrambe le mani.","Coinvolgi i glutei e i muscoli centrali, quindi premi i talloni per sollevare i fianchi dalla panca, creando una linea retta dalle ginocchia alle spalle.","Fermati un attimo in alto, contraendo i glutei.","Abbassa lentamente i fianchi fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Sırtınızın üst kısmı ona dayalı ve ayaklarınız yere düz basacak şekilde, kalça genişliğinde olacak şekilde bir bankın kenarına oturarak başlayın.","Kalçalarınızın üzerine bir halter yerleştirin ve iki elinizle güvenli bir şekilde tutun.","Kalça kaslarınızı ve göbek kaslarınızı çalıştırın, ardından kalçalarınızı benchten kaldırmak için topuklarınıza basın, dizlerinizden omuzlarınıza kadar düz bir çizgi oluşturun.","Kalça kaslarınızı sıkarak tepede bir an duraklayın.","Kalçalarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza sentado en el borde de un banco con la parte superior de la espalda apoyada contra él y los pies planos sobre el suelo, separados a la altura de las caderas.","Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos.","Activa los glúteos y el core, luego empuja con los talones para levantar las caderas del banco, creando una línea recta desde las rodillas hasta los hombros.","Haz una pausa breve en la parte alta, apretando los glúteos.","Baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что сядьте на край скамьи, прислонившись к ней верхней частью спины, а ступни поставьте на землю, на ширине плеч.","Положите штангу на бедра, крепко удерживая ее обеими руками.","Задействуйте ягодицы и мышцы корпуса, затем надавите на пятки, чтобы поднять бедра со скамьи, создавая прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, напрягая ягодицы.","Медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先坐在长凳边缘，上背部靠在长凳上，双脚平放在地面上，与臀部同宽。","将杠铃放在臀部上，用双手牢牢握住它。","锻炼臀肌和核心肌肉，然后用脚后跟将臀部抬离长凳，形成从膝盖到肩膀的一条直线。","在顶部暂停片刻，挤压臀部。","慢慢地将臀部放回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच के किनारे पर अपनी ऊपरी पीठ को टिकाकर और अपने पैरों को ज़मीन पर सपाट, कूल्हे की चौड़ाई के बराबर दूरी पर रखकर शुरुआत करें।","अपने कूल्हों पर एक बारबेल रखें, इसे दोनों हाथों से सुरक्षित रूप से पकड़ें।","अपने ग्लूट्स और कोर की मांसपेशियों को शामिल करें, फिर अपने कूल्हों को बेंच से ऊपर उठाने के लिए अपनी एड़ी पर दबाव डालें, जिससे आपके घुटनों से लेकर आपके कंधों तक एक सीधी रेखा बन जाए।","शीर्ष पर एक पल के लिए रुकें, अपने ग्लूट्स को निचोड़ें।","धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na krawędzi ławki, opierając górną część pleców o nią, a stopy ustaw płasko na podłodze na szerokość bioder.","Umieść sztangę na biodrach, trzymając ją pewnie obiema rękami.","Napnij pośladki i mięśnie tułowia, a następnie odepchnij się piętami, unosząc biodra z ławki, tworząc prostą linię od kolan do barków.","Zatrzymaj się na chwilę na górze, ściskając pośladki.","Powoli opuść biodra z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치의 가장자리에 앉아 상부 등을 벤치에 붙이고 양발을 어깨너비로 벌려 바닥에 놓습니다.","바벨을 엉덩이에 올리고 양손으로 안전하게 잡습니다.","둔근과 복부 근육을 긴장시킨 후 발꿈치를 통해 힘을 주어 엉덩이를 벤치에서 들어올려 무릎부터 어깨까지 일직선을 만듭니다.","맨 위에서 잠깐 멈추어 둔근을 조입니다.","천천히 엉덩이를 처음 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","core"]', 'glutes', 'images/3562-qg2PGl6.jpg', 'videos/3562-qg2PGl6.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0044', 'barbell good morning', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e il bilanciere appoggiato sulla parte superiore della schiena.","Mantenendo la schiena dritta e il core impegnato, fai perno in avanti sui fianchi, spingendo indietro i glutei come se stessi cercando di toccare il muro dietro di te con i glutei.","Abbassa il busto finché non è parallelo al suolo, avvertendo un allungamento nei muscoli posteriori della coscia.","Fai una pausa per un momento, quindi torna alla posizione di partenza contraendo i glutei e spingendo i fianchi in avanti.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve halter sırtınızın üst kısmına dayanacak şekilde ayakta durarak başlayın.","Sırtınızı düz ve merkez bölgenizi meşgul tutarak, kalçalarınızı öne doğru menteşeleyin, sanki arkanızdaki duvara kalça kaslarınızla dokunmaya çalışıyormuşsunuz gibi kalçalarınızı geriye doğru itin.","Diz arkası kirişlerinizde bir gerginlik hissederek gövdenizi yere paralel hale gelinceye kadar indirin.","Bir an duraklayın, ardından kalça kaslarınızı sıkarak ve kalçalarınızı öne doğru iterek başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo la espalda recta y el core activado, flexiona las caderas hacia delante, empujando los glúteos hacia atrás como si intentaras tocar la pared detrás de ti con ellos.","Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales.","Haz una pausa breve y luego vuelve a la posición inicial apretando los glúteos y empujando las caderas hacia delante.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Удерживая спину прямой и напряженным корпус, наклонитесь вперед в бедрах, отводя ягодицы назад, как будто вы пытаетесь коснуться ягодицами стены позади себя.","Опускайте туловище до тех пор, пока оно не станет параллельно земле, чувствуя растяжение подколенных сухожилий.","Сделайте паузу на мгновение, затем вернитесь в исходное положение, сжимая ягодицы и толкая бедра вперед.","Повторите необходимое количество повторений."],"zh":["首先站立，双脚分开与肩同宽，将杠铃放在上背部。","保持背部挺直，核心肌群参与，臀部向前转动，将臀部向后推，就好像你试图用臀部触碰身后的墙壁一样。","降低躯干直到与地面平行，感觉腿筋被拉伸。","暂停片刻，然后通过挤压臀部并将臀部向前推回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए, कूल्हों पर आगे की ओर झुकें, अपने नितंबों को पीछे धकेलें जैसे कि आप अपने ग्लूट्स से अपने पीछे की दीवार को छूने की कोशिश कर रहे हों।","अपने धड़ को तब तक नीचे करें जब तक वह ज़मीन के समानांतर न हो जाए, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","एक पल के लिए रुकें, फिर अपने ग्लूट्स को निचोड़ते हुए और अपने कूल्हों को आगे की ओर धकेलते हुए प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.","Utrzymując proste plecy i napięte mięśnie tułowia, pochyl się w biodrach, cofając pośladki, jakbyś próbował dotknąć nimi ściany za sobą.","Opuszczaj tułów, aż będzie równoległy do podłoża, odczuwając rozciąganie mięśni dwugłowych uda.","Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej, ściskając pośladki i pchając biodra do przodu.","Powtórz odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 서서 바벨을 상부 등 위에 올립니다.","등을 곧게 펴고 복부에 력을 주면서 엉덩이를 뒤로 밀어 힌지 동작을 합니다.","몸통이 바닥과 평행할 때까지 내려가며 햄스트링의 스트레칭을 느낍니다.","잠깐 멈춘 후 둔근을 조이고 엉덩이를 앞으로 밀어 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'lower back', '["lower back"]', 'hamstrings', 'images/0044-XlZ4lAC.jpg', 'videos/0044-XlZ4lAC.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0045', 'barbell guillotine bench press', 'chest', 'chest', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Abbassa lentamente il bilanciere verso il collo, mantenendo i gomiti rivolti verso l''esterno.","Fai una pausa per un momento quando il bilanciere è appena sopra il collo.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Dirseklerinizi dışarı doğru bakacak şekilde halterinizi yavaşça boynunuza doğru indirin.","Halter boynunuzun hemen üstüne gelince bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.","Haz una pausa breve cuando la barra esté justo encima del cuello.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Медленно опустите штангу к шее, держа локти направленными наружу.","Сделайте паузу на мгновение, когда штанга окажется чуть выше вашей шеи.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","慢慢地将杠铃降低到颈部，保持肘部朝外。","当杠铃位于颈部上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी कोहनियों को बाहर की ओर रखते हुए बारबेल को धीरे-धीरे अपनी गर्दन की ओर नीचे लाएं।","जब बारबेल आपकी गर्दन के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Powoli opuszczaj sztangę w kierunku szyi, trzymając łokcie skierowane na zewnątrz.","Zatrzymaj się na chwilę, gdy sztanga znajdzie się tuż nad szyją.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 등을 벤치에 붙입니다.","바벨을 어깨너비보다 약간 넓은 너비로 오버핸드 그립으로 잡습니다.","바벨을 천천히 목 방향으로 내리면서 팔꿈치를 바깥쪽으로 향하게 합니다.","바벨이 목 바로 위에 올 때 잠깐 멈춥니다.","바벨을 처음 위치로 밀어 올려 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","triceps"]', 'pectorals', 'images/0045-GXoaSgn.jpg', 'videos/0045-GXoaSgn.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0046', 'barbell hack squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere dietro le gambe, appoggiandolo sulla parte superiore delle cosce.","Abbassa il corpo piegando le ginocchia e i fianchi, mantenendo la schiena dritta e il petto in alto.","Continua ad abbassare finché le cosce non sono parallele al suolo o il più in basso possibile.","Fai una pausa per un momento, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durmaya başlayın.","Halteri bacaklarınızın arkasında tutun ve üst uyluklarınıza yaslayın.","Sırtınızı düz ve göğsünüzü yukarıda tutarak dizlerinizi ve kalçalarınızı bükerek vücudunuzu indirin.","Uyluklarınız yere paralel veya rahatça gidebileceğiniz kadar alçalana kadar alçaltmaya devam edin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos.","Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.","Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу за ногами, положив ее на верхнюю часть бедер.","Опустите тело, согнув колени и бедра, держа спину прямо и грудь вверх.","Продолжайте опускаться до тех пор, пока ваши бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在腿后面，将其放在大腿上部。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और अपने पैर की उंगलियों को थोड़ा बाहर की ओर करके खड़े होकर शुरुआत करें।","बारबेल को अपने पैरों के पीछे पकड़ें, इसे अपनी ऊपरी जांघों पर टिकाएं।","घुटनों और कूल्हों को मोड़कर अपने शरीर को नीचे लाएँ, अपनी पीठ सीधी रखें और अपनी छाती ऊपर रखें।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę za nogami, opierając ją na górnej części ud.","Opuść ciało, uginając kolana i biodra, utrzymując proste plecy i uniesioną klatkę piersiową.","Kontynuuj opuszczanie, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Zatrzymaj się na chwilę, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 발가락을 약간 바깥쪽으로 향하게 하여 섭니다.","바벨을 양다리 뒤쪽으로 잡아 상부 넓적다리에 올립니다.","무릎과 엉덩이를 굽히면서 등을 곧게 펴고 가슴을 들어올린 상태로 몸을 내립니다.","넓적다리가 바닥과 평행해질 때까지 또는 편안한 범위 내에서 최대한 내립니다.","잠깐 멈춘 후 발꿈치를 통해 힘을 주어 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0046-5VCj6iH.jpg', 'videos/0046-5VCj6iH.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1436', 'barbell high bar squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle, le dita leggermente rivolte verso l''esterno.","Posiziona il bilanciere sulla parte superiore della schiena, appoggiandolo sulle trappole.","Coinvolgi il core e mantieni il petto sollevato mentre inizi ad accovacciarti, spingendo indietro i fianchi e piegando le ginocchia.","Abbassati finché le cosce non sono parallele al suolo o il più in basso possibile.","Spingi i talloni per rialzarti, estendendo i fianchi e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halteri sırtınızın üst kısmına yerleştirin ve trapezlerinize dayayın.","Çömelmeye, kalçalarınızı geriye doğru itmeye ve dizlerinizi bükmeye başladığınızda merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Uyluklarınız yere paralel veya rahatça gidebildiğiniz kadar alçaltıncaya kadar kendinizi indirin.","Kalçalarınızı ve dizlerinizi uzatarak ayağa kalkmak için topuklarınızı kullanın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera.","Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas.","Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente.","Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, носки слегка развернуты наружу.","Положите штангу на верхнюю часть спины, положив ее на трапеции.","Напрягите корпус и держите грудь поднятой, когда начинаете приседать, отводя бедра назад и сгибая колени.","Опускайтесь до тех пор, пока бедра не станут параллельны земле или настолько низко, насколько вам будет удобно.","Протолкните пятки, чтобы встать обратно, выпрямляя бедра и колени.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，放在斜方肌上。","当你开始蹲下时，启动你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。","放低身体，直到大腿与地面平行，或者尽可能低到您能舒服的高度。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर निकली हुई हों।","बारबेल को अपनी ऊपरी पीठ पर रखें, इसे अपने जाल पर टिकाएं।","जब आप बैठना शुरू करें तो अपने कोर को संलग्न करें और अपनी छाती को ऊपर रखें, अपने कूल्हों को पीछे धकेलें और अपने घुटनों को मोड़ें।","अपने आप को तब तक नीचे करें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या जितना नीचे आप आराम से जा सकें।","अपने कूल्हों और घुटनों को फैलाते हुए वापस खड़े होने के लिए अपनी एड़ी से ड्राइव करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Umieść sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, rozpoczynając przysiad, cofając biodra i uginając kolana.","Opuszczaj się, aż uda będą równoległe do podłoża, lub tak nisko, jak pozwala ci na to komfort.","Wypchnij się przez pięty, wracając do pozycji stojącej, prostując biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 발가락을 약간 바깥쪽으로 향하게 하여 섭니다.","바벨을 상부 등에 올려 승모근 위에 두고 안정적으로 잡습니다.","복부에 력을 주고 가슴을 들어올린 상태에서 스쿼트를 시작하면서 엉덩이를 뒤로 밀고 무릎을 굽힙니다.","넓적다리가 바닥과 평행해질 때까지 또는 편안한 범위 내에서 최대한 내립니다.","발꿈치를 통해 힘을 주어 일어나면서 엉덩이와 무릎을 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves","core"]', 'glutes', 'images/1436-Gnfo4FM.jpg', 'videos/1436-Gnfo4FM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0047', 'barbell incline bench press', 'chest', 'chest', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati sulla panca con i piedi appoggiati a terra.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti ad un angolo di 45 gradi.","Fermati per un momento in basso, quindi riporta il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Ayaklarınız yere düz basacak şekilde bankta uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halterin askısını açın ve dirseklerinizi 45 derecelik bir açıda tutarak yavaşça göğsünüze doğru indirin.","Altta bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos a un ángulo de 45 grados.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу и медленно опустите ее к груди, держа локти под углом 45 градусов.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को 45 डिग्री के कोण पर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się na ławce, stopy oprzyj płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, utrzymując łokcie pod kątem 45 stopni.","Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도로 설정합니다.","벤치에 누워 양발을 바닥에 놓습니다.","바벨을 어깨너비보다 약간 넓은 너비로 오버핸드 그립으로 잡습니다.","바벨을 랙에서 꺼내 천천히 가슴 쪽으로 내리면서 팔꿈치를 45도 각도로 유지합니다.","하단에서 잠깐 멈춘 후 바벨을 처음 위치로 밀어 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","triceps"]', 'pectorals', 'images/0047-3TZduzM.jpg', 'videos/0047-3TZduzM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1719', 'barbell incline close grip bench press', 'upper arms', 'upper arms', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati sulla panca con i piedi appoggiati a terra.","Afferrare il bilanciere con una presa stretta, leggermente più stretta della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti vicini al corpo.","Fai una pausa per un momento quando il bilanciere tocca il tuo petto.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Ayaklarınız yere düz basacak şekilde bankta uzanın.","Halteri omuz genişliğinden biraz daha dar olacak şekilde yakın bir tutuşla kavrayın.","Halterin askısını açın ve dirseklerinizi vücudunuza yakın tutarak yavaşça göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу узким хватом, на расстоянии чуть уже ширины плеч.","Снимите штангу и медленно опустите ее к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक संकीर्ण पकड़ के साथ पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się na ławce, stopy oprzyj płasko na podłodze.","Chwyć sztangę wąskim chwytem, nieco węższym niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도로 설정합니다.","벤치에 누워 양발을 바닥에 놓습니다.","바벨을 어깨너비보다 약간 좁은 너비의 클로즈 그립으로 잡습니다.","바벨을 랙에서 꺼내 천천히 가슴 쪽으로 내리면서 팔꿈치를 몸에 가깝게 붙입니다.","바벨이 가슴에 닿을 때 잠깐 멈춥니다.","바벨을 처음 위치로 밀어 올려 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/1719-gx7s7uF.jpg', 'videos/1719-gx7s7uF.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0048', 'barbell incline reverse-grip press', 'upper arms', 'upper arms', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati sulla panca e afferra il bilanciere con una presa inversa, le mani leggermente più larghe della larghezza delle spalle.","Togli il bilanciere e abbassalo verso la parte superiore del torace, mantenendo i gomiti piegati.","Fermati per un momento in basso, quindi riporta il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Sehpaya arkanıza yaslanın ve halteri ters tutuşla kavrayın, eller omuz genişliğinden biraz daha açık olsun.","Halterin askısını açın ve dirseklerinizi içeride tutarak üst göğsünüze doğru indirin.","Altta bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Recuéstate en el banco y agarra la barra con un agarre invertido, con las manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala hacia la parte superior del pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью и возьмите штангу обратным хватом, руки чуть шире плеч.","Снимите штангу и опустите ее к верхней части груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。","松开杠铃并将其向上胸部降低，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर पीठ के बल लेट जाएं और बारबेल को उल्टी पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे अपनी ऊपरी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się na ławce i chwyć sztangę chwytem odwrotnym, dłonie nieco szerzej niż szerokość barków.","Zdejmij sztangę ze stojaka i opuszczaj ją w kierunku górnej części klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도로 설정합니다.","벤치에 누워 바벨을 리버스 그립으로 어깨너비보다 약간 넓은 너비로 잡습니다.","바벨을 랙에서 꺼내 상부 가슴 쪽으로 내리면서 팔꿈치를 구부려 모아둡니다.","하단에서 잠깐 멈춘 후 바벨을 처음 위치로 밀어 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0048-641mIfk.jpg', 'videos/0048-641mIfk.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0049', 'barbell incline row', 'back', 'back', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati a faccia in giù sulla panca con il petto contro il cuscino e i piedi appoggiati a terra.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Tieni la schiena dritta e il core impegnato.","Tirare il bilanciere verso il petto, stringendo insieme le scapole.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Göğsünüz yastığa dayalı ve ayaklarınız yere düz basacak şekilde bankta yüz üstü uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Sırtınızı düz ve merkez bölgenizi meşgul tutun.","Halteri göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho apoyado en el respaldo y los pies planos sobre el suelo.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью лицом вниз, прижавшись грудью к подушке, а ступни поставьте на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Держите спину прямо, а корпус напряженным.","Подтяните штангу к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपनी छाती को पैड से सटाकर और अपने पैरों को ज़मीन पर सपाट रखते हुए बेंच पर मुँह के बल लेट जाएँ।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się twarzą w dół na ławce, opierając klatkę piersiową o poduszkę, a stopy ustaw płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Utrzymuj proste plecy i napięte mięśnie tułowia.","Przyciągnij sztangę w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도로 설정합니다.","벤치에 엎드려 가슴이 패드에 닿게 하고 양발을 바닥에 놓습니다.","바벨을 어깨너비보다 약간 넓은 너비로 오버핸드 그립으로 잡습니다.","등을 곧게 펴고 복부에 력을 줍니다.","바벨을 가슴 쪽으로 당기면서 어깨 날개뼈를 모아줍니다.","맨 위에서 잠깐 멈춘 후 바벨을 천천히 처음 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/0049-dmgMp3n.jpg', 'videos/0049-dmgMp3n.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0050', 'barbell incline shoulder raise', 'chest', 'chest', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Siediti sulla panca con la schiena appoggiata al cuscino e i piedi appoggiati a terra.","Tieni un bilanciere con una presa prona, leggermente più largo della larghezza delle spalle.","Sollevare il bilanciere all''altezza delle spalle, mantenendo i gomiti leggermente piegati.","Solleva lentamente il bilanciere sopra la testa, estendendo completamente le braccia.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere all''altezza delle spalle.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Sırtınız yastığa dayalı ve ayaklarınız yere düz basacak şekilde bankta oturun.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten tutuşla tutun.","Dirseklerinizi hafifçe bükerek halteri omuz yüksekliğine kadar kaldırın.","Kollarınızı tamamen uzatarak halteri başınızın üzerine yavaşça kaldırın.","Tepe noktasında bir an duraklayın, ardından halteri yavaşça omuz yüksekliğine indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.","Levanta lentamente la barra por encima de la cabeza, extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью, прислонившись спиной к подушке, а ступни поставьте на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Поднимите штангу до уровня плеч, слегка согнув локти.","Медленно поднимите штангу над головой, полностью выпрямляя руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно на высоту плеч.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","坐在长凳上，背部靠在垫子上，双脚平放在地面上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃举至肩膀高度，保持肘部稍微弯曲。","慢慢地将杠铃举过头顶，充分伸展双臂。","在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपनी पीठ पैड से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ के साथ पकड़ें।","अपनी कोहनियों को थोड़ा मोड़ते हुए बारबेल को कंधे की ऊंचाई तक उठाएं।","अपनी भुजाओं को पूरी तरह फैलाते हुए धीरे-धीरे बारबेल को ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस कंधे की ऊंचाई तक नीचे लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Usiądź na ławce, opierając plecy o poduszkę, a stopy ustaw płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Unieś sztangę do wysokości barków, utrzymując łokcie lekko ugięte.","Powoli unieś sztangę nad głowę, w pełni prostując ręce.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do wysokości barków.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도로 설정합니다.","벤치에 앉아 등을 패드에 붙이고 양발을 바닥에 놓습니다.","바벨을 어깨너비보다 약간 넓은 너비로 오버핸드 그립으로 잡습니다.","바벨을 어깨 높이까지 올리면서 팔꿈치를 약간 굽힌 상태로 유지합니다.","바벨을 천천히 머리 위로 들어올리며 팔을 완전히 펼칩니다.","맨 위에서 잠깐 멈춘 후 바벨을 천천히 어깨 높이로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'deltoids', '["deltoids","trapezius"]', 'serratus anterior', 'images/0050-xi0yckC.jpg', 'videos/0050-xi0yckC.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0051', 'barbell jefferson squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."],"it":["Stai con i piedi alla larghezza delle spalle e le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere con una presa prona, appoggiandolo sulla parte anteriore del corpo, appena sotto la vita.","Porta il piede sinistro in avanti e il piede destro indietro, mantenendo i piedi alla larghezza delle spalle.","Piega le ginocchia e abbassa il corpo in posizione tozza, mantenendo la schiena dritta e il petto in alto.","Spingi i talloni per tornare alla posizione di partenza.","Ripeti il ​​movimento, alternando il piede avanti e quello posteriore ad ogni ripetizione."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halteri üstten kavrayarak vücudunuzun ön kısmına, belinizin hemen altına dayayın.","Ayaklarınızı omuz genişliğinde açarak sol ayağınızı öne ve sağ ayağınızı geriye doğru adım atın.","Dizlerinizi bükün ve sırtınızı dik ve göğsünüzü yukarıda tutarak vücudunuzu çömelme pozisyonuna indirin.","Başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","Her tekrarda ileri ve geri ayağınızı değiştirerek hareketi tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, apoyándola en la parte delantera del cuerpo, justo debajo de la cintura.","Da un paso con el pie izquierdo hacia delante y el pie derecho hacia atrás, manteniendo los pies separados a la altura de los hombros.","Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Empuja con los talones para volver a ponerte de pie en la posición inicial.","Repite el movimiento, alternando el pie delantero y el trasero en cada repetición."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Держите штангу хватом сверху, положив ее на переднюю часть тела, чуть ниже талии.","Сделайте шаг левой ногой вперед, а правой назад, держа ноги на ширине плеч.","Согните ноги в коленях и опустите тело в положение приседа, держа спину прямо и грудь вверх.","Оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите движение, чередуя переднюю и заднюю ногу при каждом повторении."],"zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","正手握住杠铃，将其放在身体前部、腰部下方。","左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","脚后跟用力，站回起始位置。","重复该动作，每次重复时交替使用前脚和后脚。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","बारबेल को ऊपरी पकड़ से पकड़ें, इसे अपने शरीर के सामने, अपनी कमर के ठीक नीचे रखें।","अपने बाएं पैर को आगे और अपने दाहिने पैर को पीछे ले जाएं, अपने पैरों को कंधे की चौड़ाई से अलग रखें।","अपने घुटनों को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","प्रारंभिक स्थिति में वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें।","प्रत्येक दोहराव के साथ अपने आगे और पीछे के पैर को बारी-बारी से दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, z lekko rozstawionymi na zewnątrz palcami stóp.","Trzymaj sztangę chwytem nachwytem, opierając ją z przodu ciała, tuż poniżej talii.","Zrób krok lewą stopą do przodu, a prawą stopą do tyłu, utrzymując stopy rozstawione na szerokość barków.","Ugnij kolana i opuść ciało do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.","Wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz ruch, zmieniając przednią i tylną stopę przy każdym powtórzeniu."],"ko":["양발을 어깨너비로 벌리고 발가락을 약간 바깥쪽으로 향하게 하여 섭니다.","바벨을 오버핸드 그립으로 잡아 몸 앞쪽에 올리며 허리 아래에 둡니다.","왼쪽 발은 앞으로, 오른쪽 발은 뒤로 발을 내딛으면서 양발의 거리를 어깨너비로 유지합니다.","무릎을 굽히고 등을 곧게 펴며 가슴을 들어올린 상태로 스쿼트 자세로 내려갑니다.","발꿈치를 통해 힘을 주어 처음 위치로 일어서옵니다.","각 반복마다 앞뒤 발을 바꾸어 가며 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0051-pkSoCW9.jpg', 'videos/0051-pkSoCW9.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0052', 'barbell jm bench press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Abbassa il bilanciere sul petto, mantenendo i gomiti piegati vicino al corpo.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Dirseklerinizi vücudunuza yakın tutarak halteri göğsünüze doğru indirin.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Опустите штангу к груди, держа локти близко к телу.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部靠近身体。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Opuść sztangę do klatki piersiowej, trzymając łokcie blisko ciała.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 등을 벤치에 붙입니다.","바벨을 어깨너비보다 약간 넓은 너비로 오버핸드 그립으로 잡습니다.","바벨을 가슴 쪽으로 내리면서 팔꿈치를 몸 가까이 붙입니다.","바벨을 처음 위치로 밀어 올려 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0052-ZsiqXYa.jpg', 'videos/0052-ZsiqXYa.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0053', 'barbell jump squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle, tenendo un bilanciere sulla parte superiore della schiena.","Abbassa il corpo in una posizione tozza piegando le ginocchia e spingendo indietro i fianchi.","Una volta raggiunto il fondo dello squat, esplodi verso l''alto saltando da terra.","Mentre salti, estendi i fianchi, le ginocchia e le caviglie, spingendo attraverso le dita dei piedi.","Atterra dolcemente nella posizione tozza e ripeti immediatamente il movimento per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açarak, sırtınızın üst kısmında bir halter tutarak başlayın.","Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu çömelme pozisyonuna indirin.","Squat''ın en altına ulaştığınızda yerden atlayarak yukarıya doğru patlayın.","Zıplarken kalçalarınızı, dizlerinizi ve ayak bileklerinizi ayak parmaklarınızın arasından iterek uzatın.","Yavaşça çömelme pozisyonuna inin ve hareketi istenen sayıda tekrar için hemen tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás.","Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo.","Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies.","Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч, удерживая штангу на верхней части спины.","Опустите тело в присед, согнув колени и отведя бедра назад.","Как только вы достигнете нижней точки приседа, взорвитесь вверх, отпрыгнув от земли.","Во время прыжка вытягивайте бедра, колени и лодыжки, толкая пальцы ног.","Мягко приземлитесь обратно в положение приседа и сразу же повторите движение желаемое количество повторений."],"zh":["首先，双脚分开与肩同宽站立，将杠铃放在上背部。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","一旦到达深蹲底部，就从地面跳起向上爆发。","跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。","轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़कर खड़े होकर शुरुआत करें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","एक बार जब आप स्क्वाट के निचले भाग पर पहुंच जाएं, तो जमीन से कूदकर ऊपर की ओर विस्फोट करें।","जैसे ही आप कूदते हैं, अपने पैर की उंगलियों से धक्का देते हुए अपने कूल्हों, घुटनों और टखनों को फैलाएं।","धीरे से वापस स्क्वाट स्थिति में आ जाएँ और वांछित संख्या में दोहराव के लिए तुरंत इस क्रिया को दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.","Opuść ciało do pozycji przysiadu, uginając kolana i cofając biodra.","Gdy osiągniesz dolną fazę przysiadu, eksplozywnie wybij się w górę, wyskakując z podłoża.","Podczas wyskoku wyprostuj biodra, kolana i kostki, odpychając się przez palce stóp.","Wyląduj miękko w pozycji przysiadu i natychmiast powtórz ruch odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올립니다.","무릎을 굽히고 엉덩이를 뒤로 밀어 스쿼트 자세로 내려갑니다.","스쿼트의 최하단에 도달하면 즉시 지면을 밀어내며 힘껏 점프합니다.","점프하면서 엉덩이, 무릎, 발목을 펼치고 발가락을 통해 힘을 줍니다.","가볍게 스쿼트 자세로 착지한 후 즉시 다음 반복을 진행합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0053-1gFNTZV.jpg', 'videos/0053-1gFNTZV.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1410', 'barbell lateral lunge', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."],"it":["Stai con i piedi alla larghezza delle spalle, tenendo un bilanciere sulla parte superiore della schiena.","Fai un grande passo laterale con il piede destro, mantenendo il piede sinistro ben piantato.","Piega il ginocchio destro e abbassa il corpo in una posizione di affondo, mantenendo la gamba sinistra dritta.","Spingi con il piede destro e torna alla posizione di partenza.","Ripeti dall''altro lato, facendo un passo con il piede sinistro."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun ve halterinizi sırtınızın üst kısmına doğru tutun.","Sol ayağınızı dik tutarak sağ ayağınızla yana doğru büyük bir adım atın.","Sağ dizinizi bükün ve sol bacağınızı düz tutarak vücudunuzu hamle pozisyonuna indirin.","Sağ ayağınızla itin ve başlangıç ​​pozisyonuna dönün.","Sol ayağınızla adım atarak diğer tarafta tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta.","Empuja con el pie derecho y vuelve a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу на верхней части спины.","Сделайте большой шаг в сторону правой ногой, удерживая левую ногу на месте.","Согните правое колено и опустите тело в положение выпада, сохраняя левую ногу прямой.","Оттолкнитесь правой ногой и вернитесь в исходное положение.","Повторите то же самое в другую сторону, наступая левой ногой."],"zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体降低到弓步位置，保持左腿伸直。","用右脚推出并返回到起始位置。","在另一侧重复，用左脚迈步。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने दाहिने पैर को बगल में रखते हुए एक बड़ा कदम उठाएं, अपने बाएं पैर को सीधा रखें।","अपने दाहिने घुटने को मोड़ें और अपने शरीर को नीचे झुकाकर स्थिति में लाएँ, अपने बाएँ पैर को सीधा रखें।","अपने दाहिने पैर से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","अपने बाएं पैर से कदम बढ़ाते हुए दूसरी तरफ भी दोहराएं।"],"pl":["Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.","Zrób szeroki krok w bok prawą stopą, utrzymując lewą stopę w miejscu.","Ugnij prawe kolano i opuść ciało do pozycji wykroku bocznego, utrzymując lewą nogę prostą.","Odepchnij się prawą stopą i wróć do pozycji wyjściowej.","Powtórz po drugiej stronie, wykonując krok lewą stopą."],"ko":["양발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올립니다.","오른쪽 발로 옆으로 큰 발걸음을 내딛으면서 왼쪽 발은 제자리에 둡니다.","오른쪽 무릎을 굽혀 런지 자세로 내려가면서 왼쪽 다리는 곧게 펼친 상태를 유지합니다.","오른쪽 발을 밀어내며 처음 위치로 돌아옵니다.","반대쪽도 동일하게 진행하며 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/1410-py1HSzx.jpg', 'videos/1410-py1HSzx.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1435', 'barbell low bar squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e il bilanciere appoggiato sulla parte superiore della schiena.","Mantenendo il petto in alto e il core impegnato, abbassa lentamente il corpo piegando le ginocchia e spingendo indietro i fianchi.","Continua ad abbassarti finché le cosce non sono parallele al suolo o leggermente più in basso.","Fai una pausa per un momento, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve halter sırtınızın üst kısmına dayanacak şekilde ayakta durun.","Göğsünüzü yukarıda ve göbek bölgenizi meşgul tutarak, dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu yavaşça indirin.","Uyluklarınız yere paralel veya biraz altına gelinceye kadar alçaltmaya devam edin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda.","Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, а штанга положитесь на верхнюю часть спины.","Удерживая грудь поднятой и напряженным корпус, медленно опустите тело, сгибая колени и отводя бедра назад.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，杠铃放在上背部。","保持挺胸，核心收紧，弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और बारबेल आपकी पीठ के ऊपरी हिस्से पर टिका हो।","अपनी छाती को ऊपर और कोर को व्यस्त रखते हुए, अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाएँ।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.","Utrzymując uniesioną klatkę piersiową i napięte mięśnie tułowia, powoli opuszczaj ciało, uginając kolana i cofając biodra.","Kontynuuj opuszczanie, aż uda będą równoległe do podłoża lub nieco niżej.","Zatrzymaj się na chwilę, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올립니다.","가슴을 들어올리고 복부에 력을 주면서 천천히 무릎을 굽히고 엉덩이를 뒤로 밀어 내려갑니다.","넓적다리가 바닥과 평행해지거나 더 낮아질 때까지 내립니다.","잠깐 멈춘 후 발꿈치를 통해 힘을 주어 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/1435-bTpEUcm.jpg', 'videos/1435-bTpEUcm.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0054', 'barbell lunge', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e un bilanciere appoggiato sulla parte superiore della schiena.","Fai un passo avanti con il piede destro, mantenendo il busto eretto.","Abbassa il corpo piegando il ginocchio destro finché la coscia non è parallela al suolo.","Spingi attraverso il tallone destro per tornare alla posizione di partenza.","Ripeti con la gamba sinistra, alternando le gambe per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açarak ve sırtınızın üst kısmına bir halter koyarak başlayın.","Gövdenizi dik tutarak sağ ayağınızla öne doğru bir adım atın.","Sağ dizinizi uyluğunuz yere paralel oluncaya kadar bükerek vücudunuzu indirin.","Başlangıç ​​pozisyonuna dönmek için sağ topuğunuzu itin.","İstenilen sayıda tekrar için sol bacağınızla, bacak değiştirerek tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia delante con el pie derecho, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo.","Empuja con el talón derecho para regresar a la posición inicial.","Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Сделайте шаг вперед правой ногой, удерживая туловище в вертикальном положении.","Опустите тело, согнув правое колено, пока бедро не станет параллельно земле.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое с левой ногой, чередуя ноги необходимое количество повторений."],"zh":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向前迈出一步，保持躯干直立。","弯曲右膝降低身体，直到大腿与地面平行。","推动右脚跟回到起始位置。","用左腿重复上述动作，交替腿进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और एक बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपने धड़ को सीधा रखते हुए अपने दाहिने पैर से एक कदम आगे बढ़ाएं।","अपने दाहिने घुटने को मोड़कर अपने शरीर को नीचे करें जब तक कि आपकी जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","वांछित संख्या में दोहराव के लिए पैरों को बारी-बारी से अपने बाएं पैर से दोहराएं।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.","Zrób krok do przodu prawą stopą, utrzymując tułów wyprostowany.","Opuść ciało, uginając prawe kolano, aż udo będzie równoległe do podłoża.","Odepchnij się przez prawą piętę, wracając do pozycji wyjściowej.","Powtórz lewą nogą, wykonując wykroki naprzemiennie odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 서서 바벨을 상부 등에 올립니다.","오른쪽 발로 앞으로 발을 내딛으면서 몸통을 곧게 유지합니다.","오른쪽 무릎을 굽혀 넓적다리가 바닥과 평행해질 때까지 몸을 내립니다.","오른쪽 발꿈치를 통해 힘을 주어 처음 위치로 돌아옵니다.","왼쪽 발로도 동일하게 진행하며 발을 교대로 하여 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0054-t8iSghb.jpg', 'videos/0054-t8iSghb.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1720', 'barbell lying back of the head tricep extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Tieni un bilanciere con una presa prona, le mani alla larghezza delle spalle ed estendi le braccia verso l''alto sul petto.","Tenendo ferma la parte superiore delle braccia, abbassa lentamente il bilanciere dietro la testa piegando i gomiti.","Fai una pausa per un momento, quindi allunga le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın ve kollarınızı göğsünüzün üzerine doğru uzatın.","Üst kollarınızı sabit tutarak, dirseklerinizi bükerek halteri yavaşça başınızın arkasına indirin.","Bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу за голову, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.","Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę za głowę, uginając łokcie.","Zatrzymaj się na chwilę, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 머리가 벤치의 끝에 오도록 합니다.","바벨을 오버핸드 그립으로 어깨너비로 잡고 가슴 위로 팔을 완전히 펼쳐 올립니다.","상부 팔을 고정하면서 팔꿈치를 굽혀 바벨을 천천히 머리 뒤로 내립니다.","잠깐 멈춘 후 팔을 펼쳐 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/1720-yg8Totb.jpg', 'videos/1720-yg8Totb.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0055', 'barbell lying close-grip press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa salda, le mani alla larghezza delle spalle, i palmi rivolti verso i piedi.","Solleva il bilanciere dal rack e tienilo direttamente sopra il petto con le braccia completamente distese.","Abbassa lentamente il bilanciere verso il petto, mantenendo i gomiti vicini al corpo.","Fai una pausa per un momento quando il bilanciere tocca il petto, quindi spingilo nuovamente nella posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri sıkı bir kavrama ile kavrayın, eller omuz genişliğinde açık, avuç içleri ayaklarınıza doğru baksın.","Halteri raftan kaldırın ve kollarınız tamamen uzatılmış halde doğrudan göğsünüzün üzerinde tutun.","Dirseklerinizi vücudunuza yakın tutarak halteri yavaşça göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın, ardından başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas mirando hacia los pies.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу узким хватом, руки на ширине плеч, ладони обращены к ногам.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга коснется груди, затем поднимите ее обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","बारबेल को ज़ोर से पकड़ें, हाथ कंधे की चौड़ाई पर अलग हों, हथेलियाँ आपके पैरों की ओर हों।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","जब बारबेल आपकी छाती को छू ले तो एक पल के लिए रुकें, फिर उसे वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę wąskim chwytem, dłonie na szerokość barków, dłonie skierowane w stronę stóp.","Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.","Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej, a następnie wypchnij ją z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 등을 벤치에 붙입니다.","바벨을 클로즈 그립(어깨너비)으로 잡고 손바닥이 발 방향을 향하게 합니다.","바벨을 랙에서 꺼내 가슴 위로 팔을 완전히 펼쳐 올립니다.","바벨을 천천히 가슴 쪽으로 내리면서 팔꿈치를 몸 가까이 붙입니다.","바벨이 가슴에 닿을 때 잠깐 멈춘 후 처음 위치로 밀어 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0055-EcaV7aL.jpg', 'videos/0055-EcaV7aL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0056', 'barbell lying close-grip triceps extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Afferrare il bilanciere con una presa salda, le mani alla larghezza delle spalle, i palmi rivolti verso l''alto.","Estendi completamente le braccia, sollevando il bilanciere sopra il petto.","Mantenendo ferma la parte superiore delle braccia, abbassare lentamente il bilanciere verso la fronte piegando i gomiti.","Fai una pausa per un momento in basso, quindi estendi le braccia nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri sıkı bir tutuşla kavrayın, eller omuz genişliğinde açık, avuç içleri yukarıya baksın.","Halteri göğsünüzün üzerine kaldırarak kollarınızı tamamen uzatın.","Üst kollarınızı sabit tutarak, dirseklerinizi bükerek halteri yavaşça alnınıza doğru indirin.","Altta bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna geri uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.","Extiende completamente los brazos, levantando la barra por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу узким хватом, руки на ширине плеч, ладонями вверх.","Полностью выпрямите руки, подняв штангу над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","紧握杠铃，双手与肩同宽，掌心向上。","充分伸展双臂，将杠铃举至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","在底部停顿片刻，然后将手臂伸展回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को कसकर पकड़ें, हाथ कंधे की चौड़ाई पर अलग हों, हथेलियाँ ऊपर की ओर हों।","अपनी बाहों को पूरी तरह फैलाएं, बारबेल को अपनी छाती से ऊपर उठाएं।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę wąskim chwytem, dłonie na szerokość barków, dłonie skierowane do góry.","Wyprostuj ręce w pełni, unosząc sztangę nad klatką piersiową.","Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.","Zatrzymaj się na chwilę na dole, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 머리가 벤치의 끝에 오도록 합니다.","바벨을 클로즈 그립(어깨너비)으로 잡고 손바닥이 위를 향하게 합니다.","팔을 완전히 펼쳐 바벨을 가슴 위로 올립니다.","상부 팔을 고정하면서 팔꿈치를 굽혀 바벨을 천천히 이마 쪽으로 내립니다.","하단에서 잠깐 멈춘 후 팔을 펼쳐 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0056-HJ63mSO.jpg', 'videos/0056-HJ63mSO.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0057', 'barbell lying extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Tieni il bilanciere con una presa prona, le mani alla larghezza delle spalle ed estendi le braccia verso l''alto sul petto.","Mantenendo ferma la parte superiore delle braccia, abbassare lentamente il bilanciere verso la fronte piegando i gomiti.","Fai una pausa per un momento, quindi allunga le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın ve kollarınızı göğsünüzün üzerine doğru uzatın.","Üst kollarınızı sabit tutarak, dirseklerinizi bükerek halteri yavaşça alnınıza doğru indirin.","Bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.","Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.","Zatrzymaj się na chwilę, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 머리가 벤치의 끝에 오도록 합니다.","바벨을 오버핸드 그립으로 어깨너비로 잡고 가슴 위로 팔을 완전히 펼쳐 올립니다.","상부 팔을 고정하면서 팔꿈치를 굽혀 바벨을 천천히 이마 쪽으로 내립니다.","잠깐 멈춘 후 팔을 펼쳐 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0057-EMpUwRI.jpg', 'videos/0057-EMpUwRI.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0058', 'barbell lying lifting (on hip)', 'upper legs', 'upper legs', 'barbell', '{"en":["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena su una panca con i piedi appoggiati a terra e le ginocchia piegate.","Tieni il bilanciere con una presa prona e posizionalo sui fianchi.","Coinvolgendo i glutei, solleva i fianchi dalla panca finché il tuo corpo non forma una linea retta dalle ginocchia alle spalle.","Fai una pausa per un momento in alto, quindi abbassa lentamente i fianchi fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve dizleriniz bükülmüş olacak şekilde bir bankta sırt üstü uzanın.","Halteri üstten kavrayarak tutun ve kalçalarınızın üzerine konumlandırın.","Kalça kaslarınızı devreye sokarak, vücudunuz dizlerinizden omuzlarınıza kadar düz bir çizgi oluşturana kadar kalçalarınızı benchten kaldırın.","Tepe noktasında bir an duraklayın, ardından kalçalarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta la barra con un agarre pronado y colócala sobre las caderas.","Activando los glúteos, levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.","Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину на скамью, поставьте ступни на землю и согните колени.","Возьмите штангу хватом сверху и расположите ее на бедрах.","Задействуя ягодицы, поднимите бедра со скамьи, пока ваше тело не образует прямую линию от колен до плеч.","Задержитесь на мгновение в верхней точке, затем медленно опустите бедра обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["仰卧在长凳上，双脚平放在地上，膝盖弯曲。","正手握住杠铃并将其放在臀部上。","收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपनी पीठ के बल लेट जाएं और आपके पैर जमीन पर सपाट हों और आपके घुटने मुड़े हुए हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें और इसे अपने कूल्हों पर रखें।","अपने ग्लूट्स को जोड़ते हुए, अपने कूल्हों को बेंच से ऊपर उठाएं जब तक कि आपका शरीर आपके घुटनों से आपके कंधों तक एक सीधी रेखा न बना ले।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach na ławce, stopy oprzyj płasko na podłodze, a kolana ugnij.","Chwyć sztangę chwytem nachwytem i umieść ją na biodrach.","Napinając pośladki, unieś biodra z ławki, aż ciało utworzy prostą linię od kolan do barków.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść biodra z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 등을 대고 누워 양발을 바닥에 놓고 무릎을 굽힙니다.","바벨을 오버핸드 그립으로 잡아 엉덩이에 올립니다.","둔근을 조이면서 엉덩이를 벤치에서 들어올려 무릎부터 어깨까지 일직선을 만듭니다.","맨 위에서 잠깐 멈춘 후 천천히 엉덩이를 처음 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","quadriceps"]', 'glutes', 'images/0058-SNFfUff.jpg', 'videos/0058-SNFfUff.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0059', 'barbell lying preacher curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca da predicatore con il petto contro il cuscino e le braccia distese oltre il bordo, tenendo un bilanciere con una presa subdola.","Mantenendo ferma la parte superiore delle braccia, espira e piega i pesi contraendo i bicipiti.","Continua a sollevare la barra finché i bicipiti non sono completamente contratti e la barra è all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira e inizia lentamente ad abbassare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Göğsünüz yastığa dayalı ve kollarınız kenardan uzatılmış şekilde bir vaiz bankına oturun, halteri alttan kavrayarak tutun.","Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın.","Bicepsleriniz tamamen kasılana ve bar omuz hizasına gelinceye kadar barı kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirmeye başlayın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руки через край, держа штангу обратным хватом.","Удерживая плечи неподвижно, выдохните и согните гантели, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर और अपनी बाहों को किनारे पर फैलाकर, एक बारबेल को अंडरहैंड ग्रिप से पकड़कर बैठें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बार कंधे के स्तर पर न आ जाए, तब तक बार को ऊपर उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce Scotta, opierając klatkę piersiową o poduszkę, a ręce wyprostuj nad jej krawędzią, trzymając sztangę chwytem podchwytem.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["프리처 벤치에 앉아 가슴이 패드에 붙고 팔이 가장자리 위로 펼쳐지도록 합니다.","바벨을 언더핸드 그립으로 잡습니다.","상부 팔을 고정하면서 호흡을 내쉬며 이두근을 수축시키면서 바벨을 말아올립니다.","바벨을 어깨 높이까지 올려 이두근이 완전히 수축될 때까지 계속 올립니다.","이두근을 조이며 짧게 멈춘 후 호흡을 들이쉬며 천천히 바벨을 처음 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0059-SYJ4Bkt.jpg', 'videos/0059-SYJ4Bkt.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0061', 'barbell lying triceps extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Tieni il bilanciere con una presa prona, le mani alla larghezza delle spalle ed estendi le braccia verso l''alto sul petto.","Mantenendo ferma la parte superiore delle braccia, abbassare lentamente il bilanciere verso la fronte piegando i gomiti.","Fai una pausa per un momento in basso, quindi allunga le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın ve kollarınızı göğsünüzün üzerine doğru uzatın.","Üst kollarınızı sabit tutarak, dirseklerinizi bükerek halteri yavaşça alnınıza doğru indirin.","Altta bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.","Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.","Zatrzymaj się na chwilę na dole, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 머리가 벤치의 끝에 오도록 합니다.","바벨을 오버핸드 그립으로 어깨너비로 잡고 가슴 위로 팔을 완전히 펼쳐 올립니다.","상부 팔을 고정하면서 팔꿈치를 굽혀 바벨을 천천히 이마 쪽으로 내립니다.","하단에서 잠깐 멈춘 후 팔을 펼쳐 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0061-iZop9xO.jpg', 'videos/0061-iZop9xO.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0060', 'barbell lying triceps extension skull crusher', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Tieni il bilanciere con una presa prona, le mani alla larghezza delle spalle ed estendi le braccia verso l''alto sul petto.","Mantenendo ferma la parte superiore delle braccia, abbassare lentamente il bilanciere verso la fronte piegando i gomiti.","Fai una pausa per un momento quando il bilanciere è appena sopra la fronte, quindi estendi le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın ve kollarınızı göğsünüzün üzerine doğru uzatın.","Üst kollarınızı sabit tutarak, dirseklerinizi bükerek halteri yavaşça alnınıza doğru indirin.","Halter alnınızın hemen üzerindeyken bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.","Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Возьмите штангу хватом сверху, руки на ширине плеч, вытяните руки вверх над грудью.","Удерживая плечи неподвижно, медленно опустите штангу ко лбу, сгибая локти.","Сделайте паузу на мгновение, когда штанга окажется прямо над лбом, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें, और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे करें।","जब बारबेल आपके माथे के ठीक ऊपर हो तो एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków, i wyprostuj ręce nad klatką piersiową.","Utrzymując ramiona nieruchomo, powoli opuszczaj sztangę w kierunku czoła, uginając łokcie.","Zatrzymaj się na chwilę, gdy sztanga znajdzie się tuż nad czołem, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 양발을 바닥에 놓고 머리가 벤치의 끝에 오도록 합니다.","바벨을 오버핸드 그립으로 어깨너비로 잡고 가슴 위로 팔을 완전히 펼쳐 올립니다.","상부 팔을 고정하면서 팔꿈치를 굽혀 바벨을 천천히 이마 쪽으로 내립니다.","바벨이 이마 바로 위에 올 때 잠깐 멈춘 후 팔을 펼쳐 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0060-h8LFzo9.jpg', 'videos/0060-h8LFzo9.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0063', 'barbell narrow stance squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere sulla parte superiore della schiena, appoggiandolo sulle trappole o sui deltoidi posteriori.","Coinvolgi il core e mantieni il petto sollevato mentre abbassi lentamente il corpo piegando le ginocchia e spingendo indietro i fianchi.","Continua ad abbassarti finché le cosce non sono parallele al suolo o leggermente più in basso.","Fai una pausa per un momento, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun.","Halterinizi sırtınızın üst kısmında tutun ve trapezlerinize veya arka deltalarınıza dayayın.","Dizlerinizi bükerek ve kalçalarınızı geriye doğru iterek vücudunuzu yavaşça indirirken çekirdeğinizi devreye sokun ve göğsünüzü yukarıda tutun.","Uyluklarınız yere paralel veya biraz altına gelinceye kadar alçaltmaya devam edin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores.","Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás.","Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo.","Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Держите штангу на верхней части спины, опираясь на трапеции или задние дельты.","Напрягите корпус и держите грудь поднятой, медленно опуская тело, сгибая колени и отводя бедра назад.","Продолжайте опускаться до тех пор, пока бедра не станут параллельны земле или немного ниже.","Сделайте паузу на мгновение, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पैरों की उंगलियों को थोड़ा बाहर की ओर करके खड़े रहें।","बारबेल को अपनी ऊपरी पीठ पर पकड़ें, इसे अपने जाल या पीछे के डेल्टा पर टिकाएं।","अपने कोर को संलग्न करें और अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए धीरे-धीरे अपने शरीर को नीचे लाते हुए अपनी छाती को ऊपर रखें।","जब तक आपकी जांघें जमीन के समानांतर या थोड़ा नीचे न हो जाएं तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.","Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych lub tylnych aktonach barków.","Napnij mięśnie tułowia i utrzymuj uniesioną klatkę piersiową, powoli opuszczając ciało, uginając kolana i cofając biodra.","Kontynuuj opuszczanie, aż uda będą równoległe do podłoża lub nieco niżej.","Zatrzymaj się na chwilę, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["양발을 어깨너비로 벌리고 발가락을 약간 바깥쪽으로 향하게 하여 섭니다.","바벨을 상부 등에 올려 승모근이나 후방 삼각근 위에 두고 잡습니다.","복부에 력을 주고 가슴을 들어올린 상태에서 무릎을 굽히고 엉덩이를 뒤로 밀어 천천히 내려갑니다.","넓적다리가 바닥과 평행해지거나 더 아래로 내려갑니다.","잠깐 멈춘 후 발꿈치를 통해 힘을 주어 처음 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0063-elhhVgj.jpg', 'videos/0063-elhhVgj.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0064', 'barbell one arm bent over row', 'back', 'back', 'barbell', '{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."],"it":["Stare con i piedi alla larghezza delle spalle, le ginocchia leggermente piegate e tenere un bilanciere con una mano utilizzando una presa prona.","Piegati in avanti sui fianchi, mantenendo la schiena dritta e la testa in posizione neutra.","Tira il bilanciere verso il petto, tenendo il gomito vicino al corpo e unendo le scapole.","Abbassare nuovamente il bilanciere nella posizione iniziale in modo controllato.","Ripeti per il numero di ripetizioni desiderato, quindi passa all''altro braccio."],"tr":["Ayaklarınız omuz genişliğinde açık, dizleriniz hafifçe bükülü olarak ayakta durun ve halteri bir elinizle üstten kavrayarak tutun.","Sırtınızı düz ve başınızı nötr pozisyonda tutarak kalçalarınızdan öne doğru eğin.","Halterinizi göğsünüze doğru çekin, dirseğinizi vücudunuza yakın tutun ve kürek kemiklerinizi birbirine doğru sıkıştırın.","Halteri kontrollü bir şekilde başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından diğer kola geçin."],"es":["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral.","Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia al otro brazo."],"ru":["Встаньте, ноги на ширине плеч, колени слегка согнуты, возьмите штангу одной рукой хватом сверху.","Наклонитесь вперед в бедрах, сохраняя спину прямой и голову в нейтральном положении.","Подтяните штангу к груди, держа локоть близко к телу и сжимая лопатки вместе.","Контролируемым образом опустите штангу обратно в исходное положение.","Повторите желаемое количество повторений, затем переключитесь на другую руку."],"zh":["双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。","臀部向前弯曲，保持背部挺直，头部处于中立位置。","将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","以受控的方式将杠铃降低回起始位置。","重复所需的重复次数，然后换到另一只手臂。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और ओवरहैंड ग्रिप का उपयोग करके एक हाथ से बारबेल को पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने सिर को तटस्थ स्थिति में रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी कोहनी को अपने शरीर के पास रखते हुए और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","नियंत्रित तरीके से बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"],"pl":["Stań w rozkroku na szerokość barków, kolana lekko ugięte, i chwyć sztangę jedną ręką chwytem nachwytem.","Pochyl się do przodu w biodrach, utrzymując proste plecy i głowę w pozycji neutralnej.","Przyciągnij sztangę w kierunku klatki piersiowej, trzymając łokieć blisko ciała i ściskając łopatki.","Opuść sztangę z powrotem do pozycji wyjściowej w kontrolowany sposób.","Powtórz odpowiednią liczbę razy, a następnie zmień rękę."],"ko":["어깨너비로 발을 벌리고 무릎을 약간 구부린 후 한손으로 바벨을 오버그립으로 잡습니다.","엉덩이에서 구부려 앞으로 숙인 후 등을 곧게 펴고 머리는 중립 위치에 둡니다.","바벨을 가슴 방향으로 당기되, 팔꿈치를 몸 가까이 유지하고 어깨뼈를 모으면서 짜냅니다.","통제된 방식으로 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복한 후 다른 팔로 전환합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/0064-Jsgsc27.jpg', 'videos/0064-Jsgsc27.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0065', 'barbell one arm floor press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."],"it":["Sdraiati sulla schiena sul pavimento con le ginocchia piegate e i piedi appoggiati a terra.","Tieni il bilanciere con una mano, con il palmo rivolto verso l''alto, ed estendi il braccio verso l''alto sopra il petto.","Abbassa lentamente il bilanciere verso il petto, mantenendo il gomito vicino al corpo.","Fermati per un momento in basso, quindi riporta il bilanciere nella posizione iniziale.","Ripeti per il numero di ripetizioni desiderato, quindi cambia braccio."],"tr":["Dizleriniz bükülü ve ayaklarınız yere düz basacak şekilde yere sırt üstü yatın.","Halteri bir elinizle, avuç içi yukarı bakacak şekilde tutun ve kolunuzu göğsünüzün üzerine doğru uzatın.","Dirseğinizi vücudunuza yakın tutarak halteri yavaşça göğsünüze doğru indirin.","Altta bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin."],"es":["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.","Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de brazo."],"ru":["Лягте на спину на пол, согните колени и поставьте ступни на землю.","Держите штангу одной рукой ладонью вверх и вытяните руку прямо над грудью.","Медленно опустите штангу к груди, держа локоть близко к телу.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"zh":["仰卧在地板上，膝盖弯曲，双脚平放在地面上。","用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数，然后换臂。"],"hi":["अपने घुटनों को मोड़कर और पैरों को जमीन पर सपाट रखते हुए फर्श पर अपनी पीठ के बल लेट जाएं।","एक हाथ से बारबेल को पकड़ें, हथेली ऊपर की ओर रखें और अपने हाथ को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी कोहनी को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"],"pl":["Połóż się płasko na plecach na podłodze, kolana ugięte, a stopy oparte płasko na podłodze.","Chwyć sztangę jedną ręką, dłonią skierowaną w górę, i wyprostuj rękę nad klatką piersiową.","Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokieć blisko ciała.","Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy, a następnie zmień rękę."],"ko":["바닥에 누워 무릎을 구부리고 발을 바닥에 평평하게 붙입니다.","한손으로 바벨을 언더그립으로 잡고 팔을 가슴 위로 곧게 펼칩니다.","바벨을 가슴 방향으로 천천히 내리되, 팔꿈치를 몸 가까이 유지합니다.","아래에서 잠깐 멈춘 후 바벨을 시작 위치로 밀어올립니다.","원하는 반복 횟수만큼 반복한 후 팔을 바꿉니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/0065-vtusOWT.jpg', 'videos/0065-vtusOWT.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0066', 'barbell one arm side deadlift', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"it":["Stare con i piedi alla larghezza delle spalle, tenendo un bilanciere in una mano con una presa prona.","Tieni la schiena dritta e il core impegnato.","Piegati sui fianchi e abbassa il bilanciere verso l''esterno della gamba, mantenendo il braccio dritto e il petto in alto.","Abbassa il bilanciere il più possibile mantenendo una buona forma.","Fai una pausa per un momento, quindi torna lentamente alla posizione di partenza.","Ripeti per il numero di ripetizioni desiderato, quindi cambia lato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun, bir elinizde halteri üstten kavrayarak tutun.","Sırtınızı düz ve merkez bölgenizi meşgul tutun.","Kalçalarınızı bükün ve kolunuzu düz ve göğsünüzü yukarıda tutarak halteri bacağınızın dışına doğru indirin.","İyi formunuzu koruyarak halteri mümkün olduğu kadar indirin.","Bir an duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado.","Mantén la espalda recta y el core activado.","Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado.","Baja la barra tanto como puedas manteniendo una buena forma.","Haz una pausa por un momento, luego regresa lentamente a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Встаньте, ноги на ширине плеч, держите штангу в одной руке хватом сверху.","Держите спину прямо, а корпус напряженным.","Согнитесь в бедрах и опустите штангу к внешней стороне ноги, держа руку прямо и грудь вверх.","Опустите штангу как можно ниже, сохраняя при этом хорошую форму.","Сделайте паузу на мгновение, затем медленно вернитесь в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["双脚分开与肩同宽站立，一只手握住杠铃，正握。","保持背部挺直，核心肌群参与。","臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。","尽可能降低杠铃，同时保持良好的姿势。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में बारबेल को ओवरहैंड पकड़ के साथ पकड़ लें।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","कूल्हों पर झुकें और बारबेल को अपने पैर के बाहर की ओर नीचे करें, अपनी बांह सीधी रखें और अपनी छाती ऊपर रखें।","अच्छी फॉर्म बनाए रखते हुए बारबेल को जितना हो सके उतना नीचे करें।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Stań w rozkroku na szerokość barków, trzymając sztangę jedną ręką chwytem nachwytem.","Utrzymuj proste plecy i napięte mięśnie tułowia.","Pochyl się w biodrach i opuść sztangę wzdłuż zewnętrznej strony nogi, utrzymując rękę prostą, a klatkę piersiową uniesioną.","Opuszczaj sztangę tak nisko, jak pozwala ci na to zachowanie prawidłowej techniki.","Zatrzymaj się na chwilę, a następnie powoli wróć do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy, a następnie zmień stronę."],"ko":["어깨너비로 발을 벌리고 한손으로 바벨을 오버그립으로 잡습니다.","등을 곧게 펴고 코어에 힘을 넣습니다.","엉덩이에서 구부려 바벨을 다리 바깥쪽으로 내리되, 팔은 곧게 펴고 가슴은 위로 향하게 합니다.","좋은 자세를 유지하면서 바벨을 최대한 내립니다.","잠깐 멈춘 후 천천히 시작 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복한 후 반대쪽으로 전환합니다."]}', 'hamstrings', '["hamstrings","quadriceps","lower back"]', 'glutes', 'images/0066-2DxtqHL.jpg', 'videos/0066-2DxtqHL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0067', 'barbell one arm snatch', 'shoulders', 'shoulders', 'barbell', '{"en":["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."],"it":["Stare con i piedi alla larghezza delle spalle, le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Piega le ginocchia e abbassa i fianchi in una posizione tozza, mantenendo la schiena dritta e il petto in alto.","Estendi in modo esplosivo anche, ginocchia e caviglie, spingendo il bilanciere verso l''alto.","Quando il bilanciere raggiunge l''altezza del petto, tiralo verso l''alto con il braccio, tenendolo vicino al corpo.","Ruota il gomito sotto il bilanciere ed estendi il braccio completamente sopra la testa, bloccando il gomito.","Abbassare nuovamente il bilanciere nella posizione iniziale in modo controllato.","Ripeti per il numero di ripetizioni desiderato, quindi cambia braccio."],"tr":["Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun.","Halteri üstten kavrayarak tutun, eller omuz genişliğinden biraz daha açık olsun.","Dizlerinizi bükün ve kalçalarınızı çömelme pozisyonuna indirin, sırtınızı düz ve göğsünüzü yukarıda tutun.","Halteri yukarı doğru hareket ettirerek kalçalarınızı, dizlerinizi ve ayak bileklerinizi patlayıcı bir şekilde uzatın.","Halter göğüs hizasına ulaştığında, vücudunuza yakın tutarak kolunuzla yukarı doğru çekin.","Dirseğinizi halterin altında döndürün ve kolunuzu tamamen yukarı doğru uzatarak dirseğinizi kilitleyin.","Halteri kontrollü bir şekilde başlangıç ​​pozisyonuna indirin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından kolları değiştirin."],"es":["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.","Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.","Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.","Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.","Baja la barra de vuelta a la posición inicial de forma controlada.","Repite el número de repeticiones deseado, luego cambia de brazo."],"ru":["Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Возьмите штангу хватом сверху, расставив руки чуть шире плеч.","Согните ноги в коленях и опустите бедра в положение приседа, держа спину прямо и грудь вверх.","Взрывно выпрямите бедра, колени и лодыжки, поднимая штангу вверх.","Когда штанга достигнет уровня груди, потяните ее рукой вверх, держа ее близко к телу.","Поверните локоть под штангу и вытяните руку полностью над головой, блокируя локоть.","Контролируемым образом опустите штангу обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте руки."],"zh":["双脚分开与肩同宽站立，脚趾稍微向外。","正手握住杠铃，双手分开略宽于肩宽。","弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。","爆发性伸展臀部、膝盖和脚踝，将杠铃向上推。","当杠铃到达胸部水平时，用手臂将其向上拉，使其靠近身体。","将肘部旋转到杠铃下方，并将手臂完全伸过头顶，锁定肘部。","以受控的方式将杠铃降低回起始位置。","重复所需的重复次数，然后换臂。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपने घुटनों को मोड़ें और अपने कूल्हों को स्क्वाट स्थिति में लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएं, बारबेल को ऊपर की ओर ले जाएं।","जैसे ही बारबेल छाती के स्तर पर पहुंचे, इसे अपने शरीर के करीब रखते हुए अपनी बांह से ऊपर की ओर खींचें।","अपनी कोहनी को बारबेल के नीचे घुमाएं और अपनी कोहनी को लॉक करते हुए अपने हाथ को पूरी तरह ऊपर की ओर फैलाएं।","नियंत्रित तरीके से बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"],"pl":["Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.","Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Ugnij kolana i opuść biodra do pozycji przysiadu, utrzymując proste plecy i uniesioną klatkę piersiową.","Eksplozywnie wyprostuj biodra, kolana i kostki, napędzając sztangę do góry.","Gdy sztanga osiągnie wysokość klatki piersiowej, pociągnij ją w górę ręką, trzymając blisko ciała.","Obróć łokieć pod sztangą i wyprostuj rękę w pełni nad głową, blokując łokieć.","Opuść sztangę z powrotem do pozycji wyjściowej w kontrolowany sposób.","Powtórz odpowiednią liczbę razy, a następnie zmień rękę."],"ko":["어깨너비로 발을 벌리고 발끝은 약간 바깥쪽을 향하게 합니다.","오버그립으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","무릎을 구부려 스쿼트 위치로 엉덩이를 내리되, 등을 곧게 펴고 가슴은 위로 향하게 합니다.","엉덩이, 무릎, 발목을 폭발적으로 펴면서 바벨을 위로 드라이브합니다.","바벨이 가슴 높이에 도달하면 팔로 바벨을 위로 당기되, 몸 가까이 유지합니다.","팔꿈치를 바벨 아래로 회전시키고 팔을 머리 위로 완전히 펼친 후 팔꿈치를 잠금합니다.","바벨을 통제된 방식으로 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복한 후 팔을 바꿉니다."]}', 'traps', '["traps","forearms","core"]', 'delts', 'images/0067-xHKN2s8.jpg', 'videos/0067-xHKN2s8.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0068', 'barbell one leg squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."],"it":["Stai con i piedi alla larghezza delle spalle e tieni un bilanciere sulla parte superiore della schiena.","Sollevare un piede da terra ed estenderlo in avanti, mantenendolo parallelo al suolo.","Piega la gamba in piedi e abbassa il corpo come se fossi seduto su una sedia, mantenendo il petto sollevato e la schiena dritta.","Abbassati finché la coscia non è parallela al suolo, quindi spingi il tallone per tornare alla posizione di partenza.","Ripeti per il numero di ripetizioni desiderato, quindi cambia gamba e ripeti."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri sırtınızın üst kısmına doğru tutun.","Bir ayağınızı yerden kaldırın ve yere paralel tutarak ileri doğru uzatın.","Ayakta duran bacağınızı bükün ve sanki bir sandalyeye oturuyormuş gibi vücudunuzu aşağıya doğru indirin, göğsünüzü yukarıda ve sırtınızı dik tutun.","Uyluğunuz yere paralel oluncaya kadar kendinizi indirin, ardından başlangıç ​​pozisyonuna dönmek için topuğunuzu itin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından bacak değiştirin ve tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo.","Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta.","Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial.","Repite el número de repeticiones deseado y luego cambia de pierna y repite."],"ru":["Встаньте, ноги на ширине плеч, держите штангу на верхней части спины.","Поднимите одну ногу от земли и вытяните ее вперед, удерживая параллельно земле.","Согните стоящую ногу и опустите тело вниз, как будто садитесь на стул, держа грудь поднятой, а спину прямой.","Опускайтесь до тех пор, пока бедро не станет параллельно земле, затем оттолкнитесь пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу и повторите."],"zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","将一只脚抬离地面并向前伸展，保持与地面平行。","弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。","降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数，然后换腿并重复。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","एक पैर को जमीन से ऊपर उठाएं और इसे जमीन के समानांतर रखते हुए आगे की ओर फैलाएं।","अपने खड़े पैर को मोड़ें और अपने शरीर को नीचे नीचे करें जैसे कि आप कुर्सी पर बैठे हों, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","जब तक आपकी जांघ जमीन के समानांतर न हो जाए, तब तक अपने आप को नीचे रखें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"],"pl":["Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.","Unieś jedną stopę z podłogi i wyciągnij ją do przodu, utrzymując równolegle do podłoża.","Ugnij nogę podporową i opuść ciało, jakbyś siadał na krześle, utrzymując uniesioną klatkę piersiową i proste plecy.","Opuszczaj się, aż udo będzie równoległe do podłoża, a następnie odepchnij się przez piętę, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy, a następnie zmień nogę i powtórz."],"ko":["어깨너비로 발을 벌리고 바벨을 상부 등에 걸칩니다.","한발을 들어올려 지면과 평행하게 앞으로 펼칩니다.","서 있는 다리를 구부려 의자에 앉는 것처럼 몸을 내리되, 가슴은 위로 향하게 하고 등은 곧게 펴고 유지합니다.","허벅지가 지면과 평행할 때까지 내린 후 발뒤꿈치로 밀어 시작 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복한 후 다리를 바꿉니다."]}', 'glutes', '["glutes","hamstrings","calves"]', 'quads', 'images/0068-uKyN64F.jpg', 'videos/0068-uKyN64F.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0069', 'barbell overhead squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e le dita dei piedi leggermente rivolte verso l''esterno.","Tieni il bilanciere con una presa ampia, posizionandolo sopra la testa con le braccia completamente distese.","Coinvolgi il core e abbassa il corpo in una posizione tozza, mantenendo il petto sollevato e le ginocchia che seguono le dita dei piedi.","Fai una pausa per un momento in fondo, quindi spingi i talloni per tornare alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız hafifçe dışa dönük olacak şekilde ayakta durun.","Halteri geniş bir kavrama ile tutun ve kollarınız tamamen uzatılmış halde başınızın üzerine konumlandırın.","Merkez bölgenizi devreye sokun ve vücudunuzu çömelme pozisyonuna indirin, göğsünüzü yukarıda ve dizlerinizin ayak parmaklarınızın üzerinde olmasını sağlayın.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera.","Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos.","Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка развернув пальцы ног.","Возьмите штангу широким хватом, расположив ее над головой, полностью выпрямив руки.","Напрягите корпус и опустите тело в положение приседа, удерживая грудь поднятой, а колени касаясь пальцев ног.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾稍微外翻。","宽握距握住杠铃，将其置于头顶，双臂完全伸展。","收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और पंजों को थोड़ा बाहर की ओर करके खड़े हो जाएं।","बारबेल को चौड़ी पकड़ से पकड़ें, अपनी भुजाओं को पूरी तरह फैलाकर इसे सिर के ऊपर रखें।","अपने कोर को संलग्न करें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएं, अपनी छाती को ऊपर रखें और घुटनों को अपने पैर की उंगलियों पर रखें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.","Chwyć sztangę szerokim chwytem, ustawiając ją nad głową przy w pełni wyprostowanych rękach.","Napnij mięśnie tułowia i opuść ciało do pozycji przysiadu, utrzymując uniesioną klatkę piersiową, a kolana w linii ze stopami.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨너비로 발을 벌리고 발끝은 약간 바깥쪽을 향하게 합니다.","넓은 그립으로 바벨을 잡고 머리 위에 위치시켜 팔을 완전히 펼칩니다.","코어에 힘을 넣고 몸을 스쿼트 위치로 내리되, 가슴은 위로 향하게 하고 무릎은 발 위에 정렬되도록 합니다.","아래에서 잠깐 멈춘 후 발뒤꿈치로 밀어 시작 위치로 돌아옵니다.","원하는 반복 횟수만큼 반복합니다."]}', 'glutes', '["glutes","hamstrings","calves","core"]', 'quads', 'images/0069-gfk9kD4.jpg', 'videos/0069-gfk9kD4.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1411', 'barbell palms down wrist curl over a bench', 'lower arms', 'lower arms', 'barbell', '{"en":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con i piedi appoggiati a terra e gli avambracci appoggiati sulle cosce, con i palmi rivolti verso il basso.","Tieni un bilanciere con una presa prona, le mani alla larghezza delle spalle.","Abbassa il bilanciere verso terra flettendo i polsi e mantenendo gli avambracci fermi.","Fai una pausa per un momento in basso, quindi solleva lentamente il bilanciere estendendo i polsi.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve önkollarınız uyluklarınızın üzerinde olacak şekilde, avuçlarınız aşağıya bakacak şekilde bir bankta oturun.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın.","Ön kollarınızı sabit tutarak bileklerinizi esneterek halteri yere doğru indirin.","Altta bir an duraklayın, ardından bileklerinizi uzatarak halteri yavaşça yukarı kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.","Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.","Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ступни на землю, положите предплечья на бедра ладонями вниз.","Возьмите штангу хватом сверху, руки на ширине плеч.","Опустите штангу к земле, сгибая запястья, сохраняя предплечья неподвижными.","Задержитесь на мгновение в нижней точке, затем медленно поднимите штангу вверх, вытягивая запястья.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地上，前臂放在大腿上，手掌朝下。","正手握住杠铃，双手与肩同宽。","弯曲手腕，将杠铃降低到地面，保持前臂静止。","在底部停顿片刻，然后通过伸展手腕慢慢将杠铃举起。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके और अपने अग्रभागों को अपनी जाँघों पर टिकाकर, हथेलियाँ नीचे की ओर रखते हुए एक बेंच पर बैठें।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी कलाइयों को मोड़कर, अपने अग्रबाहुओं को स्थिर रखते हुए, बारबेल को ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को फैलाकर बारबेल को वापस ऊपर उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, a przedramiona oprzyj na udach, dłonie skierowane w dół.","Chwyć sztangę chwytem nachwytem, dłonie na szerokość barków.","Opuść sztangę w kierunku podłogi, zginając nadgarstki, utrzymując przedramiona nieruchomo.","Zatrzymaj się na chwilę na dole, a następnie powoli unieś sztangę z powrotem, prostując nadgarstki.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발을 바닥에 평평하게 놓고 팔뚝을 허벅지에 올려놓되, 손바닥은 아래를 향하게 합니다.","오버그립으로 바벨을 잡되, 손은 어깨너비로 벌립니다.","손목을 구부려 바벨을 땅 방향으로 내리되, 팔뚝은 움직이지 않게 고정합니다.","아래에서 잠깐 멈춘 후 손목을 펼쳐 바벨을 천천히 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","brachialis"]', 'forearms', 'images/1411-yzYH9pI.jpg', 'videos/1411-yzYH9pI.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1412', 'barbell palms up wrist curl over a bench', 'lower arms', 'lower arms', 'barbell', '{"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Sedersi su una panca con i piedi appoggiati a terra e tenere un bilanciere con una presa subdola, con i palmi rivolti verso l''alto.","Appoggia gli avambracci sulla panca, lasciando che i polsi pendano dal bordo.","Mantenendo gli avambracci fermi, espira e piega i polsi verso l''alto il più possibile.","Mantieni la posizione contratta per una breve pausa, quindi inspira e riporta lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak şekilde bir bankta oturun ve halteri avuç içleriniz yukarı bakacak şekilde alttan kavrayarak tutun.","Önkollarınızı bankın üzerine yaslayın, bileklerinizin kenardan sarkmasına izin verin.","Önkollarınızı sabit tutarak nefes verin ve bileklerinizi mümkün olduğunca yukarı doğru kıvırın.","Kısa bir süre kasılmış pozisyonda kalın, ardından nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.","Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ступни на землю и возьмите штангу обратным хватом ладонями вверх.","Положите предплечья на скамью так, чтобы запястья свисали с края.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。","将前臂放在长凳上，让手腕悬在长凳边缘。","保持前臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को जमीन पर सपाट करके एक बेंच पर बैठें और हथेलियाँ ऊपर की ओर रखते हुए बारबेल को हाथ से पकड़ें।","अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं।","अपने अग्रबाहुओं को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, i chwyć sztangę chwytem podchwytem, dłonie skierowane do góry.","Oprzyj przedramiona na ławce, pozwalając nadgarstkom zwisać za jej krawędzią.","Utrzymując przedramiona nieruchomo, wydychaj powietrze i zginaj nadgarstki w górę, jak najdalej to możliwe.","Zatrzymaj się na chwilę w pozycji szczytowej, a następnie wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발을 바닥에 평평하게 놓고 언더그립으로 바벨을 잡되, 손바닥은 위를 향하게 합니다.","팔뚝을 벤치에 올려놓되, 손목이 가장자리에서 내려오도록 합니다.","팔뚝은 움직이지 않게 고정하고 숨을 내쉬면서 손목을 최대한 위로 구부립니다.","수축된 위치에서 잠깐 멈춘 후 숨을 들이쉬면서 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","shoulders"]', 'forearms', 'images/1412-SJAA2IQ.jpg', 'videos/1412-SJAA2IQ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('3017', 'barbell pendlay row', 'back', 'back', 'barbell', '{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate.","Piegati in avanti sui fianchi, mantenendo la schiena dritta e il petto in alto.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Tirare il bilanciere verso la parte superiore dell''addome, stringendo insieme le scapole.","Abbassare nuovamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun.","Sırtınızı düz ve göğsünüzü yukarıda tutarak kalçalarınızdan öne doğru eğin.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halteri üst karnınıza doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Halteri tekrar başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч и слегка согнув колени.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Потяните штангу к верхней части живота, сжимая лопатки вместе.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，膝盖稍微弯曲。","臀部向前弯曲，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","将杠铃降低回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपने ऊपरी पेट की ओर खींचें।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, kolana lekko ugięte.","Pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Przyciągnij sztangę w kierunku górnej części brzucha, ściskając łopatki.","Opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨너비로 발을 벌리고 무릎을 약간 구부립니다.","엉덩이에서 구부려 앞으로 숙이되, 등을 곧게 펴고 가슴은 위로 향하게 합니다.","오버그립으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","바벨을 상부 복부 방향으로 당기면서 어깨뼈를 모으고 짜냅니다.","바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/3017-r0z6xzQ.jpg', 'videos/3017-r0z6xzQ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1751', 'barbell pin presses', 'upper arms', 'upper arms', 'barbell', '{"en":["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Posiziona un bilanciere su un power rack all''altezza del petto.","Mettiti di fronte al bilanciere e posizionati sotto di esso, con i piedi alla larghezza delle spalle.","Afferra il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Solleva il bilanciere dal rack e tienilo direttamente sopra il petto, con le braccia completamente distese.","Abbassa il bilanciere verso il petto, mantenendo i gomiti piegati vicino al corpo.","Fai una pausa per un momento quando il bilanciere tocca il tuo petto.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Göğüs yüksekliğinde bir güç rafına bir halter yerleştirin.","Halterin karşısında durun ve ayaklarınız omuz genişliğinde açık olacak şekilde kendinizi onun altına konumlandırın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Halteri raftan kaldırın ve kollarınız tamamen uzatılmış halde doğrudan göğsünüzün üzerinde tutun.","Dirseklerinizi vücudunuza yakın tutarak halteri göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca una barra en un rack de potencia a la altura del pecho.","Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Установите штангу на силовую стойку на уровне груди.","Встаньте лицом к штанге и расположитесь под ней, поставив ноги на ширине плеч.","Возьмите штангу хватом сверху, на расстоянии чуть шире ширины плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Опустите штангу к груди, держа локти прижатыми к телу.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["将杠铃放在与胸部同高的力量架上。","面向杠铃站立，将自己置于杠铃下方，双脚分开与肩同宽。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其保持在胸部正上方，双臂完全伸展。","将杠铃向胸部方向降低，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["छाती की ऊंचाई पर पावर रैक पर बारबेल स्थापित करें।","बारबेल की ओर मुंह करके खड़े हो जाएं और अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए खुद को इसके नीचे रखें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े ओवरहैंड ग्रिप से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर रखें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, बारबेल को अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw sztangę na stojaku (power rack) na wysokości klatki piersiowej.","Stań przed sztangą i ustaw się pod nią, stopy rozstaw na szerokość barków.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.","Opuść sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["파워 랙에서 바벨을 가슴 높이로 설정합니다.","바벨을 마주보고 서서 그 아래 위치하되, 발은 어깨너비로 벌립니다.","오버그립으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","바벨을 랙에서 들어올려 가슴 위에 바로 잡고 팔을 완전히 펼칩니다.","바벨을 가슴 방향으로 내리되, 팔꿈치를 몸에 가깝게 유지합니다.","바벨이 가슴에 닿을 때 잠깐 멈춥니다.","바벨을 시작 위치로 밀어올려 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/1751-bndCa3Q.jpg', 'videos/1751-bndCa3Q.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0070', 'barbell preacher curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca da predicatore con la parte superiore delle braccia appoggiata sul cuscino e il petto contro il supporto.","Afferrare il bilanciere con una presa subdola, leggermente più larga della larghezza delle spalle.","Mantenendo ferma la parte superiore delle braccia, espira e porta il bilanciere verso le spalle.","Fermati un attimo in alto, contraendo i bicipiti.","Inspira e abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Üst kollarınız yastığa ve göğsünüz desteğe dayanacak şekilde bir vaiz bankına oturun.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde alttan kavrayın.","Üst kollarınızı sabit tutarak nefes verin ve halteri omuzlarınıza doğru kıvırın.","Bicepslerinizi sıkarak tepede bir an duraklayın.","Nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.","Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.","Haz una pausa breve en la parte alta, apretando los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью для проповедника, положив плечи на подушку и грудь на опору.","Возьмите штангу хватом снизу, на расстоянии чуть шире ширины плеч.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам.","Задержитесь на мгновение в верхней точке, напрягая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。","反手握住杠铃，握距略宽于肩宽。","保持上臂静止，呼气并将杠铃向上弯向肩膀。","在顶部暂停片刻，挤压你的二头肌。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपनी ऊपरी बांहों को पैड पर और अपनी छाती को सहारे पर टिकाकर एक उपदेशक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए सांस छोड़ें और बारबेल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce Scotta, opierając ramiona na poduszce, a klatkę piersiową o podparcie.","Chwyć sztangę chwytem podchwytem, nieco szerszym niż szerokość barków.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w kierunku barków.","Zatrzymaj się na chwilę na górze, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["프리처 벤치에 앉아 상완이 패드에 올려지고 가슴이 지지대에 닿도록 합니다.","언더그립으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","상완을 움직이지 않게 고정하고 숨을 내쉬면서 바벨을 어깨 방향으로 구부립니다.","위에서 잠깐 멈춘 후 이두근을 짜냅니다.","숨을 들이쉬면서 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0070-qOgPVf6.jpg', 'videos/0070-qOgPVf6.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0071', 'barbell press sit-up', 'waist', 'waist', 'barbell', '{"en":["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati sulla schiena su un tappetino con le ginocchia piegate e i piedi appoggiati a terra.","Tieni il bilanciere con una presa prona, appoggiandolo sul petto.","Coinvolgendo gli addominali, solleva lentamente la parte superiore del corpo da terra, piegandoti in avanti finché il busto non forma un angolo di 45 gradi.","Fermati per un momento in alto, quindi abbassa lentamente la parte superiore del corpo fino alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Dizleriniz bükülmüş ve ayaklarınız yere düz basacak şekilde bir matın üzerine sırt üstü uzanın.","Halteri üstten kavrayarak göğsünüzün üzerine yaslayın.","Karın kaslarınızı devreye sokarak üst bedeninizi yavaşça yerden kaldırın ve gövdeniz 45 derecelik bir açıya gelene kadar öne doğru kıvrılın.","Tepe noktasında bir an duraklayın, ardından üst vücudunuzu yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, apoyándola sobre el pecho.","Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados.","Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на спину на коврик, согните колени и поставьте ступни на землю.","Возьмите штангу хватом сверху, положив ее на грудь.","Включив пресс, медленно поднимите верхнюю часть тела от земли, наклоняясь вперед, пока туловище не окажется под углом 45 градусов.","Задержитесь на мгновение в верхней точке, затем медленно опустите верхнюю часть тела обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在垫子上，膝盖弯曲，双脚平放在地上。","正手握住杠铃，将其放在胸前。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"],"hi":["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए एक चटाई पर अपनी पीठ के बल लेट जाएँ।","बारबेल को अपनी छाती पर टिकाकर, ऊपरी पकड़ से पकड़ें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na plecach na macie, kolana ugięte, a stopy oparte płasko na podłodze.","Chwyć sztangę chwytem nachwytem, opierając ją na klatce piersiowej.","Napinając mięśnie brzucha, powoli unieś górną część ciała z podłogi, zwijając się do przodu, aż tułów znajdzie się pod kątem 45 stopni.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść górną część ciała z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["매트 위에 누워 무릎을 구부리고 발을 바닥에 평평하게 놓습니다.","오버그립으로 바벨을 잡아 가슴에 올려놓습니다.","복부에 힘을 주고 상체를 천천히 들어올려 몸통이 45도 각도가 될 때까지 앞으로 구부립니다.","위에서 잠깐 멈춘 후 상체를 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","chest"]', 'abs', 'images/0071-wnEscH8.jpg', 'videos/0071-wnEscH8.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0072', 'barbell prone incline curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati a faccia in giù sulla panca con il petto e lo stomaco appoggiati contro di essa.","Tieni un bilanciere con una presa subdola, alla larghezza delle spalle.","Estendi completamente le braccia, lasciando che il bilanciere penda verso il pavimento.","Mantenendo ferma la parte superiore delle braccia, espira e piega i pesi contraendo i bicipiti.","Continua a sollevare il bilanciere finché i bicipiti non sono completamente contratti e la barra è all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira e inizia lentamente ad abbassare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Göğsünüz ve karnınız ona yaslanacak şekilde bankta yüzüstü uzanın.","Halterinizi omuz genişliğinde açık olacak şekilde alttan tutuşla tutun.","Halterin yere doğru sarkmasına izin vererek kollarınızı tamamen uzatın.","Üst kollarınızı sabit tutarak, bicepslerinizi kasarken ağırlıkları nefes verin ve kıvırın.","Bicepsleriniz tamamen kasılana ve bar omuz hizasına gelinceye kadar halteri kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirmeye başlayın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.","Sujeta una barra con un agarre supino, separado a la altura de los hombros.","Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.","Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте лицом вниз на скамью, прижавшись к ней грудью и животом.","Возьмите штангу хватом снизу на ширине плеч.","Полностью выпрямите руки, позволяя штанге свисать к полу.","Удерживая плечи неподвижно, выдохните и согните гири, одновременно сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно начните опускать штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部和腹部靠在长凳上。","反手握住杠铃，距离与肩同宽。","充分伸展双臂，让杠铃垂向地板。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपनी छाती और पेट को बेंच पर टिकाकर चेहरे के बल लेट जाएँ।","बारबेल को कंधे की चौड़ाई की दूरी पर हाथ की पकड़ से पकड़ें।","अपनी बाहों को पूरी तरह फैलाएं, जिससे बारबेल नीचे फर्श की ओर लटक जाए।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się twarzą w dół na ławce, opierając o nią klatkę piersiową i brzuch.","Chwyć sztangę chwytem podchwytem, na szerokość barków.","Wyprostuj ręce w pełni, pozwalając sztandze zwisać w kierunku podłogi.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając ręce i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도 각도로 설정합니다.","벤치에 얼굴을 아래로 하여 누워 가슴과 배가 벤치에 닿도록 합니다.","언더그립으로 바벨을 어깨너비로 잡습니다.","팔을 완전히 펼쳐 바벨이 바닥 방향으로 내려오도록 합니다.","상완을 움직이지 않게 고정하고 숨을 내쉬면서 이두근을 수축시키며 바벨을 구부립니다.","바벨을 이두근이 완전히 수축되고 바벨이 어깨 높이가 될 때까지 계속 올립니다.","이두근을 짜내며 수축된 위치에서 잠깐 멈춥니다.","숨을 들이쉬면서 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0072-WLvTAv5.jpg', 'videos/0072-WLvTAv5.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0073', 'barbell pullover', 'back', 'back', 'barbell', '{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con la testa da un lato e i piedi sul pavimento.","Tieni un bilanciere con una presa alla larghezza delle spalle ed estendi le braccia direttamente sopra il petto.","Tenendo le braccia tese, abbassa il bilanciere dietro la testa in modo controllato finché non senti un allungamento nei dorsali.","Fare una pausa per un momento, quindi riportare il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız bir ucunda ve ayaklarınız yerde olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri omuz genişliğinde tutun ve kollarınızı göğsünüzün üzerine düz bir şekilde uzatın.","Kollarınızı düz tutarak halteri başınızın arkasına kontrollü bir şekilde, enlemlerinizde bir gerginlik hissedene kadar indirin.","Bir süre duraklayın, ardından halteri tekrar başlangıç ​​pozisyonuna kaldırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.","Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на пол.","Возьмите штангу хватом на ширине плеч и вытяните руки прямо над грудью.","Держа руки прямыми, контролируемо опустите штангу за голову, пока не почувствуете растяжение в широчайших.","Сделайте паузу на мгновение, затем поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，头放在一端，双脚放在地板上。","握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。","保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","कंधे की चौड़ाई की पकड़ के साथ बारबेल को पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएं।","अपनी भुजाओं को सीधा रखते हुए, बारबेल को अपने सिर के पीछे नियंत्रित तरीके से तब तक नीचे करें जब तक आपको अपनी जांघों में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, głową na jednym końcu, a stopy oprzyj na podłodze.","Chwyć sztangę uchwytem na szerokość barków i wyprostuj ręce nad klatką piersiową.","Utrzymując ręce proste, opuszczaj sztangę za głowę w kontrolowany sposób, aż poczujesz rozciąganie mięśni najszerszych grzbietu.","Zatrzymaj się na chwilę, a następnie unieś sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치 위에 누워 머리는 한쪽 끝에 발은 바닥에 놓습니다.","어깨너비 그립으로 바벨을 잡고 팔을 가슴 위로 곧게 펼칩니다.","팔을 곧게 펴면서 바벨을 통제된 방식으로 머리 뒤로 내리되, 등근육에서 스트레칭을 느낄 때까지 내립니다.","잠깐 멈춘 후 바벨을 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","triceps"]', 'lats', 'images/0073-i6LWjok.jpg', 'videos/0073-i6LWjok.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0022', 'barbell pullover to press', 'back', 'back', 'barbell', '{"en":["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con la testa da un lato e i piedi a terra.","Tieni il bilanciere con una presa prona (palmi rivolti lontano da te) ed estendi le braccia direttamente sopra il petto.","Tenendo le braccia tese, abbassa il bilanciere dietro la testa con un movimento ad arco finché non senti un allungamento nei dorsali.","Fai una pausa per un momento, quindi inverti il ​​movimento e riporta il bilanciere nella posizione iniziale sopra il petto.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Başınız bir ucunda ve ayaklarınız yerde olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri pronasyonlu bir tutuşla tutun (avuç içleriniz sizden uzağa bakacak şekilde) ve kollarınızı düz bir şekilde göğsünüzün üzerine uzatın.","Kollarınızı düz tutarak, halterinizi başınızın arkasına yay benzeri bir hareketle, enlemlerinizde bir gerginlik hissedene kadar indirin.","Bir an duraklayın, ardından hareketi tersine çevirin ve halteri göğsünüzün üzerindeki başlangıç ​​pozisyonuna doğru bastırın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.","Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho.","Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales.","Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив голову на один конец и поставив ноги на землю.","Возьмите штангу пронированным хватом (ладонями от себя) и вытяните руки прямо над грудью.","Держа руки прямыми, опустите штангу за голову дугообразными движениями, пока не почувствуете растяжение широчайших мышц.","Сделайте паузу на мгновение, затем поменяйте направление движения и верните штангу в исходное положение над грудью.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，头朝一端，双脚着地。","旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。","保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。","暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को ज़मीन पर रखकर सीधे लेट जाएँ।","बारबेल को उभरी हुई पकड़ से पकड़ें (हथेलियाँ आपसे दूर की ओर हों) और अपनी भुजाओं को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, बारबेल को अपने सिर के पीछे एक चाप जैसी गति में तब तक नीचे करें जब तक आपको अपनी जांघों में खिंचाव महसूस न हो जाए।","एक पल के लिए रुकें, फिर गति को उल्टा करें और बारबेल को वापस अपनी छाती के ऊपर प्रारंभिक स्थिति में दबाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, głową na jednym końcu, a stopy oprzyj na podłodze.","Chwyć sztangę chwytem pronowanym (dłonie skierowane od siebie) i wyprostuj ręce nad klatką piersiową.","Utrzymując ręce proste, opuszczaj sztangę za głowę ruchem łukowym, aż poczujesz rozciąganie mięśni najszerszych grzbietu.","Zatrzymaj się na chwilę, a następnie wykonaj ruch odwrotny, wypychając sztangę z powrotem do pozycji wyjściowej nad klatką piersiową.","Powtórz odpowiednią liczbę razy."],"ko":["벤치 위에 누워 머리는 한쪽 끝에 발은 바닥에 놓습니다.","프로네이티드 그립(손바닥이 몸에서 멀어지도록)으로 바벨을 잡고 팔을 가슴 위로 곧게 펼칩니다.","팔을 곧게 펴면서 바벨을 호 모양으로 머리 뒤로 내리되, 등근육에서 스트레칭을 느낄 때까지 내립니다.","잠깐 멈춘 후 동작을 역으로 하여 바벨을 가슴 위의 시작 위치로 밀어올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","chest","shoulders"]', 'lats', 'images/0022-znLogoF.jpg', 'videos/0022-znLogoF.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0074', 'barbell rack pull', 'upper legs', 'upper legs', 'barbell', '{"en":["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."],"it":["Posiziona un bilanciere su una rastrelliera all''altezza del ginocchio.","Stare con i piedi alla larghezza delle spalle, le dita dei piedi leggermente rivolte verso l''esterno.","Piegati sui fianchi e sulle ginocchia per abbassarti e afferra il bilanciere con una presa prona, con le mani alla larghezza delle spalle.","Coinvolgi il core e solleva il bilanciere estendendo le anche e le ginocchia, tirando indietro le spalle e contraendo i glutei in alto.","Abbassare il bilanciere nella posizione iniziale piegando le anche e le ginocchia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Diz yüksekliğinde bir rafa halter yerleştirin.","Ayaklarınız omuz genişliğinde açık, ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun.","Kendinizi aşağı indirmek için kalçalarınızı ve dizlerinizi bükün ve halteri üstten kavrayarak, ellerinizi omuz genişliğinde açın.","Merkez bölgenizi devreye sokun ve kalçalarınızı ve dizlerinizi uzatarak, omuzlarınızı geriye çekerek ve üst kısımda kalça kaslarınızı sıkarak halteri kaldırın.","Kalçalarınızı ve dizlerinizi bükerek halteri tekrar başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca una barra en un soporte a la altura de la rodilla.","Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.","Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros.","Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta.","Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas.","Repite el número de repeticiones deseado."],"ru":["Установите штангу на стойку на уровне колен.","Встаньте, ноги на ширине плеч, носки слегка направлены наружу.","Согните бедра и колени, чтобы опуститься вниз, и возьмите штангу хватом сверху, руки на ширине плеч.","Напрягите корпус и поднимите штангу, вытягивая бедра и колени, отводя плечи назад и сжимая ягодицы в верхней точке.","Опустите штангу обратно в исходное положение, сгибая бедра и колени.","Повторите необходимое количество повторений."],"zh":["将杠铃放在膝盖高度的架子上。","双脚分开与肩同宽站立，脚趾稍微向外。","弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。","通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。","弯曲臀部和膝盖，将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["घुटने की ऊंचाई पर एक रैक पर बारबेल स्थापित करें।","अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपने आप को नीचे लाने के लिए कूल्हों और घुटनों पर झुकें और हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपने कोर को संलग्न करें और अपने कूल्हों और घुटनों को फैलाकर, अपने कंधों को पीछे खींचकर और शीर्ष पर अपने ग्लूट्स को निचोड़कर बारबेल को ऊपर उठाएं।","कूल्हों और घुटनों पर झुकते हुए बारबेल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw sztangę na stojaku na wysokości kolan.","Stań w rozkroku na szerokość barków, palce stóp skierowane lekko na zewnątrz.","Ugnij biodra i kolana, aby opuścić się i chwycić sztangę chwytem nachwytem, dłonie na szerokość barków.","Napnij mięśnie tułowia i unieś sztangę, prostując biodra i kolana, odciągając barki do tyłu i ściskając pośladki na górze.","Opuść sztangę z powrotem do pozycji wyjściowej, uginając biodra i kolana.","Powtórz odpowiednią liczbę razy."],"ko":["바벨을 랙에 무릎 높이로 설정합니다.","어깨너비로 발을 벌리고 발끝은 약간 바깥쪽을 향하게 합니다.","엉덩이와 무릎에서 구부려 아래로 내려 오버그립으로 바벨을 어깨너비로 잡습니다.","코어에 힘을 주고 엉덩이와 무릎을 펼치면서 바벨을 들어올리고, 어깨를 뒤로 당기며 위에서 둔근을 짜냅니다.","엉덩이와 무릎에서 구부려 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0074-za9Ni4z.jpg', 'videos/0074-za9Ni4z.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0075', 'barbell rear delt raise', 'shoulders', 'shoulders', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stare con i piedi alla larghezza delle spalle e tenere un bilanciere con una presa prona, i palmi rivolti verso il basso.","Piega leggermente le ginocchia e fai perno in avanti sui fianchi, mantenendo la schiena dritta.","Sollevare il bilanciere lateralmente, mantenendo le braccia tese, finché non saranno parallele al suolo.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri avuç içleriniz aşağıya bakacak şekilde üstten kavrayarak tutun.","Dizlerinizi hafifçe bükün ve sırtınızı düz tutarak kalçalarınızdan öne doğru eğilin.","Halteri yanlara doğru kaldırın, kollarınızı yere paralel olana kadar düz tutun.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.","Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Слегка согните колени и наклонитесь вперед в бедрах, сохраняя спину прямой.","Поднимите штангу в стороны, держа руки прямыми, пока они не станут параллельны земле.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और हथेलियां नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को सीधा रखते हुए बारबेल को बगल की ओर उठाएं, जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.","Ugnij lekko kolana i pochyl się do przodu w biodrach, utrzymując proste plecy.","Unieś sztangę na boki, utrzymując ręce proste, aż będą równoległe do podłoża.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨너비로 발을 벌리고 오버그립(손바닥이 아래)으로 바벨을 잡습니다.","무릎을 약간 구부리고 엉덩이에서 구부려 앞으로 숙인 후 등을 곧게 펴고 유지합니다.","팔을 곧게 펴면서 바벨을 옆으로 들어올려 지면과 평행할 때까지 올립니다.","위에서 잠깐 멈춘 후 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'traps', '["traps","rhomboids"]', 'delts', 'images/0075-Ln9iTbU.jpg', 'videos/0075-Ln9iTbU.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0076', 'barbell rear delt row', 'shoulders', 'shoulders', 'barbell', '{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate.","Tieni un bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Piegati in avanti sui fianchi, mantenendo la schiena dritta e il petto in alto.","Tirare il bilanciere verso il petto, stringendo insieme le scapole.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun.","Halteri üstten kavrayarak tutun, eller omuz genişliğinden biraz daha geniş olsun.","Sırtınızı dik ve göğsünüzü yukarıda tutarak kalçalarınızdan öne doğru eğin.","Halteri göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Tira de la barra hacia el pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Подтяните штангу к груди, сведя лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, kolana lekko ugięte.","Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową.","Przyciągnij sztangę w kierunku klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨너비로 발을 벌리고 무릎을 약간 구부립니다.","오버그립으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","엉덩이에서 구부려 앞으로 숙이되, 등을 곧게 펴고 가슴은 위로 향하게 합니다.","바벨을 가슴 방향으로 당기면서 어깨뼈를 모으고 짜냅니다.","위에서 잠깐 멈춘 후 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'trapezius', '["trapezius","rhomboids","biceps"]', 'delts', 'images/0076-S9zHIvU.jpg', 'videos/0076-S9zHIvU.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0078', 'barbell rear lunge', 'upper legs', 'upper legs', 'barbell', '{"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"it":["Inizia stando in piedi con i piedi alla larghezza delle spalle e un bilanciere appoggiato sulla parte superiore della schiena.","Fai un passo indietro con il piede destro, atterrando sulla pianta del piede.","Piega entrambe le ginocchia per abbassare il corpo finché la coscia sinistra non è parallela al suolo.","Spingi attraverso il tallone sinistro per tornare alla posizione di partenza.","Ripeti con l''altra gamba."],"tr":["Ayaklarınızı omuz genişliğinde açarak ve sırtınızın üst kısmına bir halter koyarak başlayın.","Sağ ayağınızla geriye doğru bir adım atın ve ayak parmaklarınızın ucuna inin.","Sol uyluğunuz yere paralel oluncaya kadar vücudunuzu indirmek için her iki dizinizi de bükün.","Başlangıç ​​pozisyonuna dönmek için sol topuğunuzu itin.","Diğer bacakla tekrarlayın."],"es":["Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."],"ru":["Начните с того, что встаньте, поставив ноги на ширине плеч и положив штангу на верхнюю часть спины.","Сделайте шаг назад правой ногой, приземлившись на подушечку стопы.","Согните оба колена и опустите тело до тех пор, пока левое бедро не станет параллельно земле.","Оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите с другой ногой."],"zh":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और एक बारबेल को अपनी पीठ के ऊपरी हिस्से पर टिकाकर खड़े होकर शुरुआत करें।","अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने पैर की गेंद पर उतरें।","अपने शरीर को नीचे करने के लिए दोनों घुटनों को मोड़ें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी को धक्का दें।","दूसरे पैर से दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, ze sztangą opartą na górnej części pleców.","Zrób krok w tył prawą stopą, lądując na palcach stopy.","Ugnij oba kolana, opuszczając ciało, aż lewe udo będzie równoległe do podłoża.","Odepchnij się przez lewą piętę, wracając do pozycji wyjściowej.","Powtórz drugą nogą."],"ko":["어깨너비로 발을 벌리고 바벨을 상부 등에 올려놓은 상태에서 시작합니다.","오른발로 뒤로 한발을 내디디며 발의 공 부분에 착지합니다.","양쪽 무릎을 구부려 왼쪽 허벅지가 지면과 평행할 때까지 몸을 내립니다.","왼쪽 발뒤꿈치로 밀어 시작 위치로 돌아옵니다.","반대쪽 다리로 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0078-VaP75jl.jpg', 'videos/0078-VaP75jl.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0077', 'barbell rear lunge v. 2', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."],"it":["Stai con i piedi alla larghezza delle spalle e tieni un bilanciere sulla parte superiore della schiena.","Fai un passo indietro con il piede destro, atterrando sulla pianta del piede.","Piega entrambe le ginocchia per abbassare il corpo finché la coscia sinistra non è parallela al suolo.","Spingi attraverso il tallone sinistro per tornare alla posizione di partenza.","Ripeti con l''altra gamba."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri sırtınızın üst kısmına doğru tutun.","Sağ ayağınızla geriye doğru bir adım atın ve ayak parmaklarınızın ucuna inin.","Sol uyluğunuz yere paralel oluncaya kadar vücudunuzu indirmek için her iki dizinizi de bükün.","Başlangıç ​​pozisyonuna dönmek için sol topuğunuzu itin.","Diğer bacakla tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.","Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie.","Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo.","Empuja con el talón izquierdo para volver a la posición inicial.","Repite con la otra pierna."],"ru":["Встаньте, ноги на ширине плеч, держите штангу на верхней части спины.","Сделайте шаг назад правой ногой, приземлившись на подушечку стопы.","Согните оба колена и опустите тело до тех пор, пока левое бедро не станет параллельно земле.","Оттолкнитесь левой пяткой, чтобы вернуться в исходное положение.","Повторите с другой ногой."],"zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने पैर की गेंद पर उतरें।","अपने शरीर को नीचे करने के लिए दोनों घुटनों को मोड़ें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी को धक्का दें।","दूसरे पैर से दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, trzymając sztangę na górnej części pleców.","Zrób krok w tył prawą stopą, lądując na palcach stopy.","Ugnij oba kolana, opuszczając ciało, aż lewe udo będzie równoległe do podłoża.","Odepchnij się przez lewą piętę, wracając do pozycji wyjściowej.","Powtórz drugą nogą."],"ko":["어깨너비로 발을 벌리고 바벨을 상부 등에 걸칩니다.","오른발로 뒤로 한발을 내디디며 발의 공 부분에 착지합니다.","양쪽 무릎을 구부려 왼쪽 허벅지가 지면과 평행할 때까지 몸을 내립니다.","왼쪽 발뒤꿈치로 밀어 시작 위치로 돌아옵니다.","반대쪽 다리로 반복합니다."]}', 'quadriceps', '["quadriceps","hamstrings","calves"]', 'glutes', 'images/0077-62Nw60O.jpg', 'videos/0077-62Nw60O.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0079', 'barbell revers wrist curl v. 2', 'lower arms', 'lower arms', 'barbell', '{"en":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panchina con i piedi appoggiati a terra e le ginocchia piegate.","Tieni un bilanciere con una presa prona, i palmi rivolti verso il basso e le mani alla larghezza delle spalle.","Appoggia gli avambracci sulle cosce, lasciando che i polsi pendano dal bordo.","Mantenendo gli avambracci fermi, espira e piega i polsi verso l''alto il più possibile.","Mantieni la posizione contratta per una breve pausa, quindi inspira e riporta lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve dizleriniz bükülü olacak şekilde bir bankta oturun.","Halteri üstten kavrayarak, avuç içleriniz aşağıya bakacak şekilde ve elleriniz omuz genişliğinde açık olacak şekilde tutun.","Ön kollarınızı uyluklarınıza yaslayın, bileklerinizin kenardan sarkmasına izin verin.","Ön kollarınızı sabit tutarak nefes verin ve bileklerinizi mümkün olduğunca yukarı doğru kıvırın.","Kısa bir süre kasılmış pozisyonda kalın, ardından nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ноги на землю и согните колени.","Возьмите штангу хватом сверху, ладонями вниз, руки на ширине плеч.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Удерживая предплечья неподвижно, выдохните и согните запястья вверх как можно дальше.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地上，膝盖弯曲。","正手握住杠铃，手掌朝下，双手与肩同宽。","将前臂放在大腿上，让手腕悬在边缘。","保持前臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक बेंच पर बैठें।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","अपनी बांहों को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस शुरुआती स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, a kolana ugnij.","Chwyć sztangę chwytem nachwytem, dłonie skierowane w dół, na szerokość barków.","Oprzyj przedramiona na udach, pozwalając nadgarstkom zwisać za krawędzią.","Utrzymując przedramiona nieruchomo, wydychaj powietrze i zginaj nadgarstki w górę, jak najdalej to możliwe.","Zatrzymaj się na chwilę w pozycji szczytowej, a następnie wdychaj powietrze, powoli opuszczając sztangę do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발을 바닥에 평평하게 놓고 무릎을 구부립니다.","오버그립(손바닥이 아래)으로 바벨을 잡되, 손은 어깨너비로 벌립니다.","팔뚝을 허벅지에 올려놓고 손목이 가장자리에서 내려오도록 합니다.","팔뚝은 움직이지 않게 고정하고 숨을 내쉬면서 손목을 최대한 위로 구부립니다.","수축된 위치에서 잠깐 멈춘 후 숨을 들이쉬면서 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","brachialis"]', 'forearms', 'images/0079-qDnGfDb.jpg', 'videos/0079-qDnGfDb.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2187', 'barbell reverse close-grip bench press', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la schiena premuta contro la panca.","Afferrare il bilanciere con una presa inversa, con le mani alla larghezza delle spalle.","Solleva il bilanciere dal rack e tienilo direttamente sopra il petto con le braccia completamente distese.","Abbassa lentamente il bilanciere verso il petto, mantenendo i gomiti vicini al corpo.","Fai una pausa per un momento quando il bilanciere è appena sopra il petto.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve sırtınız banka yaslanacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri ters tutuşla kavrayın, eller omuz genişliğinde açık olsun.","Halteri raftan kaldırın ve kollarınız tamamen uzatılmış halde doğrudan göğsünüzün üzerinde tutun.","Dirseklerinizi vücudunuza yakın tutarak halteri yavaşça göğsünüze doğru indirin.","Halter göğsünüzün hemen üstüne gelince bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.","Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.","Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.","Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.","Haz una pausa breve cuando la barra esté justo encima del pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, поставьте ступни на землю и прижмите спину к скамье.","Возьмите штангу обратным хватом, руки на ширине плеч.","Снимите штангу со стойки и держите ее прямо над грудью, полностью вытянув руки.","Медленно опустите штангу к груди, держа локти близко к телу.","Сделайте паузу на мгновение, когда штанга окажется чуть выше груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","反握抓住杠铃，双手与肩同宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃向胸部降低，保持肘部靠近身体。","当杠铃位于胸部正上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को उल्टी पकड़ से पकड़ें।","बारबेल को रैक से उठाएं और अपनी बाहों को पूरी तरह फैलाकर सीधे अपनी छाती के ऊपर पकड़ें।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए बारबेल को धीरे-धीरे अपनी छाती की ओर नीचे लाएं।","जब बारबेल आपकी छाती के ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a plecy przyciśnij do ławki.","Chwyć sztangę chwytem odwrotnym, dłonie na szerokość barków.","Zdejmij sztangę ze stojaka i utrzymuj ją bezpośrednio nad klatką piersiową przy w pełni wyprostowanych rękach.","Powoli opuszczaj sztangę w kierunku klatki piersiowej, trzymając łokcie blisko ciała.","Zatrzymaj się na chwilę, gdy sztanga znajdzie się tuż nad klatką piersiową.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["벤치 위에 누워 발을 바닥에 평평하게 놓고 등을 벤치에 밀착시킵니다.","리버스 그립(손바닥이 몸 방향)으로 바벨을 어깨너비로 잡습니다.","바벨을 랙에서 들어올려 팔을 완전히 펼친 상태에서 가슴 위에 잡습니다.","바벨을 천천히 가슴 방향으로 내리되, 팔꿈치를 몸에 가깝게 유지합니다.","바벨이 가슴 바로 위에 있을 때 잠깐 멈춥니다.","바벨을 시작 위치로 밀어올려 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'chest', '["chest","shoulders"]', 'triceps', 'images/2187-YqJw82s.jpg', 'videos/2187-YqJw82s.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0080', 'barbell reverse curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."],"it":["Stai dritto con i piedi alla larghezza delle spalle e tieni un bilanciere con una presa prona, i palmi rivolti verso il basso.","Mantieni ferma la parte superiore delle braccia ed espira mentre pieghi il bilanciere verso l''alto, contraendo i bicipiti.","Continua a sollevare il bilanciere finché i bicipiti non saranno completamente contratti e il bilanciere sarà all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira mentre abbassi lentamente il bilanciere nella posizione iniziale, mantenendo ferma la parte superiore delle braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde dik durun ve halteri avuçlarınız aşağıya bakacak şekilde üstten kavrayarak tutun.","Üst kollarınızı sabit tutun ve halteri yukarı doğru kıvırırken bicepslerinizi kasarken nefes verin.","Bicepsleriniz tamamen kasılana ve halter omuz hizasına gelene kadar halteri kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Üst kollarınızı sabit tutarak halteri yavaşça başlangıç ​​pozisyonuna indirirken nefes alın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos.","Repite el número de repeticiones deseado."],"ru":["Встаньте прямо, ноги на ширине плеч, возьмите штангу хватом сверху ладонями вниз.","Держите плечи неподвижно и на выдохе поднимайте штангу вверх, сокращая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","На вдохе медленно опускайте штангу обратно в исходное положение, сохраняя плечи неподвижными.","Повторите необходимое количество повторений."],"zh":["站直，双脚分开与肩同宽，正手握住杠铃，手掌朝下。","保持上臂静止，向上弯举杠铃时呼气，收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将杠铃放回起始位置，保持上臂静止。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखते हुए सीधे खड़े हो जाएं और हथेलियों को नीचे की ओर रखते हुए बारबेल को ओवरहैंड ग्रिप से पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को ऊपर की ओर मोड़ते हुए सांस छोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","सांस लेते हुए धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में लाएं, अपनी ऊपरी भुजाओं को स्थिर रखें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań prosto, stopy rozstaw na szerokość barków, i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w górę i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej, utrzymując ramiona nieruchomo.","Powtórz odpowiednią liczbę razy."],"ko":["발을 어깨너비로 벌리고 곧게 선 후 오버그립(손바닥이 아래)으로 바벨을 잡습니다.","상완을 움직이지 않게 고정하고 숨을 내쉬면서 바벨을 위로 구부려 이두근을 수축합니다.","바벨을 이두근이 완전히 수축되고 바벨이 어깨 높이가 될 때까지 계속 올립니다.","이두근을 짜내며 수축된 위치에서 잠깐 멈춥니다.","숨을 들이쉬면서 상완을 고정하고 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0080-xNrS20v.jpg', 'videos/0080-xNrS20v.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0118', 'barbell reverse grip bent over row', 'back', 'back', 'barbell', '{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai in piedi con i piedi alla larghezza delle spalle e le ginocchia leggermente piegate.","Tieni un bilanciere con una presa prona, i palmi rivolti verso il basso e le mani leggermente più larghe della larghezza delle spalle.","Piegati in avanti all''altezza dei fianchi, mantenendo la schiena dritta e il petto in alto, finché il busto non sarà quasi parallelo al pavimento.","Tirare il bilanciere verso la parte inferiore del torace, stringendo insieme le scapole.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve dizleriniz hafifçe bükülü şekilde ayakta durun.","Halteri üstten kavrayarak, avuç içleriniz aşağıya bakacak şekilde ve elleriniz omuz genişliğinden biraz daha geniş olacak şekilde tutun.","Gövdeniz neredeyse yere paralel oluncaya kadar sırtınızı düz ve göğsünüzü yukarıda tutarak kalçalarınızı öne doğru eğin.","Halterinizi alt göğsünüze doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.","Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros.","Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo.","Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч и слегка согнуты в коленях.","Держите штангу хватом сверху, ладонями вниз, руки на расстоянии чуть шире плеч.","Наклонитесь вперед в бедрах, держа спину прямо и грудь вверх, пока туловище не станет почти параллельно полу.","Потяните штангу к нижней части груди, сжимая лопатки вместе.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，手掌朝下，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी पीठ सीधी और छाती ऊपर रखते हुए कूल्हों के बल आगे की ओर झुकें, जब तक कि आपका धड़ लगभग फर्श के समानांतर न हो जाए।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी निचली छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, kolana lekko ugięte.","Chwyć sztangę chwytem nachwytem, dłonie skierowane w dół, nieco szerzej niż szerokość barków.","Pochyl się do przodu w biodrach, utrzymując proste plecy i uniesioną klatkę piersiową, aż tułów będzie niemal równoległy do podłogi.","Przyciągnij sztangę w kierunku dolnej części klatki piersiowej, ściskając łopatki.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["어깨너비로 발을 벌리고 무릎을 약간 구부립니다.","오버그립(손바닥이 아래)으로 바벨을 잡되, 손은 어깨너비보다 약간 넓게 벌립니다.","엉덩이에서 구부려 앞으로 숙이되, 등을 곧게 펴고 가슴은 위로 향하게 하여 몸통이 거의 지면과 평행할 때까지 합니다.","바벨을 하부 가슴 방향으로 당기면서 어깨뼈를 모으고 짜냅니다.","위에서 잠깐 멈춘 후 바벨을 천천히 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/0118-SzX3uzM.jpg', 'videos/0118-SzX3uzM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1256', 'barbell reverse grip decline bench press', 'chest', 'chest', 'barbell', '{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca declinata con i piedi fissati e la testa più in basso rispetto ai fianchi.","Afferrare il bilanciere con una presa inversa, leggermente più largo della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti piegati.","Fermati per un momento in basso, quindi riporta il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız sabitlenmiş ve başınız kalçalarınızdan aşağıda olacak şekilde bir iniş bankına uzanın.","Halteri ters tutuşla, omuz genişliğinden biraz daha geniş olacak şekilde kavrayın.","Halterin askısını açın ve dirseklerinizi içeride tutarak yavaşça göğsünüze doğru indirin.","Altta bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.","Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на наклонную скамью, зафиксировав ноги и опустив голову ниже бедер.","Возьмите штангу обратным хватом, на расстоянии чуть шире ширины плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте небольшую паузу в нижней точке, затем верните штангу в исходное положение.","Повторите необходимое количество повторений."],"zh":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","反握抓住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","बारबेल को कंधे की चौड़ाई से थोड़ा चौड़ा करके उल्टी पकड़ से पकड़ें।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się na ławce skośnej ujemnej, zabezpieczając stopy, tak aby głowa znajdowała się niżej niż biodra.","Chwyć sztangę chwytem odwrotnym, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie przy ciele.","Zatrzymaj się na chwilę na dole, a następnie wypchnij sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["디클라인 벤치에 누워 발이 고정되고 머리가 엉덩이보다 낮도록 합니다.","리버스 그립으로 바벨을 어깨너비보다 약간 넓게 잡습니다.","바벨을 벗어나게 들어올려 천천히 가슴 방향으로 낮추되, 팔꿈치를 안쪽으로 유지합니다.","아래에서 잠깐 멈춘 후 바벨을 시작 위치로 밀어올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/1256-DotAgEF.jpg', 'videos/1256-DotAgEF.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1257', 'barbell reverse grip incline bench press', 'chest', 'chest', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sdraiati sulla panca con i piedi appoggiati a terra.","Afferrare il bilanciere con una presa inversa, le mani leggermente più larghe della larghezza delle spalle.","Togli il bilanciere e abbassalo lentamente verso il petto, mantenendo i gomiti piegati.","Fai una pausa per un momento quando il bilanciere tocca il tuo petto.","Spingi nuovamente il bilanciere nella posizione iniziale, estendendo completamente le braccia.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Ayaklarınız yere düz basacak şekilde bankta uzanın.","Halteri ters tutuşla kavrayın, eller omuz genişliğinden biraz daha açık olsun.","Halterin askısını açın ve dirseklerinizi içeride tutarak yavaşça göğsünüze doğru indirin.","Halter göğsünüze dokunduğunda bir an duraklayın.","Kollarınızı tamamen uzatarak halteri başlangıç ​​pozisyonuna geri itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Túmbate en el banco con los pies planos sobre el suelo.","Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.","Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.","Haz una pausa breve cuando la barra toque el pecho.","Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Лягте на скамью, положив ноги на землю.","Возьмите штангу обратным хватом, руки чуть шире плеч.","Ослабьте штангу и медленно опустите ее к груди, держа локти прижатыми.","Сделайте паузу на мгновение, когда штанга коснется вашей груди.","Верните штангу в исходное положение, полностью выпрямив руки.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","反握抓住杠铃，双手分开略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपने पैरों को ज़मीन पर सपाट करके बेंच पर लेट जाएँ।","बारबेल को उल्टी पकड़ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","बारबेल को खोलें और अपनी कोहनियों को अंदर की ओर रखते हुए इसे धीरे-धीरे अपनी छाती की ओर नीचे करें।","जब बारबेल आपकी छाती को छूए तो एक पल के लिए रुकें।","अपनी भुजाओं को पूरी तरह फैलाते हुए बारबेल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Połóż się na ławce, stopy oprzyj płasko na podłodze.","Chwyć sztangę chwytem odwrotnym, dłonie nieco szerzej niż szerokość barków.","Zdejmij sztangę ze stojaka i powoli opuszczaj ją w kierunku klatki piersiowej, trzymając łokcie przy ciele.","Zatrzymaj się na chwilę, gdy sztanga dotknie klatki piersiowej.","Wypchnij sztangę z powrotem do pozycji wyjściowej, w pełni prostując ręce.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도 각도로 세웁니다.","벤치에 누워 발은 바닥에 편하게 놓습니다.","역그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","바벨을 랙에서 꺼내 천천히 가슴을 향해 내리며 팔꿈치는 몸 옆으로 유지합니다.","바벨이 가슴에 닿을 때 잠시 멈춉니다.","바벨을 시작 위치로 밀어 올리며 팔을 완전히 펼칩니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","shoulders"]', 'pectorals', 'images/1257-DU7I633.jpg', 'videos/1257-DU7I633.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1317', 'barbell reverse grip incline bench row', 'back', 'back', 'barbell', '{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Installa una panca inclinata con un angolo di 45 gradi.","Sedersi sulla panca di fronte allo schienale con il petto appoggiato ad esso.","Afferra il bilanciere con una presa inversa (palmi rivolti verso il basso) e le mani leggermente più larghe della larghezza delle spalle.","Tieni la schiena dritta e il core impegnato.","Tirare il bilanciere verso la parte superiore dell''addome, stringendo insieme le scapole.","Fermati un attimo nella parte superiore del movimento.","Abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["45 derecelik bir açıyla eğimli bir tezgah kurun.","Göğsünüz sırtlığa dönük olacak şekilde bankta oturun.","Halteri ters bir tutuşla (avuç içleri aşağıya bakacak şekilde) ve ellerinizi omuz genişliğinden biraz daha açık olacak şekilde tutun.","Sırtınızı düz ve merkez bölgenizi meşgul tutun.","Halteri üst karnınıza doğru çekin, kürek kemiklerinizi birbirine doğru sıkıştırın.","Hareketin zirvesinde bir an duraklayın.","Halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Coloca un banco inclinado a un ángulo de 45 grados.","Siéntate en el banco frente al respaldo con el pecho apoyado contra él.","Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros.","Mantén la espalda recta y el core activado.","Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos.","Haz una pausa breve en la parte alta del movimiento.","Baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Установите наклонную скамью под углом 45 градусов.","Сядьте на скамью лицом к спинке, прижавшись к ней грудью.","Возьмите штангу обратным хватом (ладонями вниз) и расставьте руки чуть шире плеч.","Держите спину прямо и напрягите корпус.","Потяните штангу к верхней части живота, сжимая лопатки вместе.","Сделайте паузу на мгновение в верхней точке движения.","Медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["设置一个 45 度角的上斜凳。","坐在长凳上，面向靠背，胸部靠在靠背上。","反握（手掌朝下）抓住杠铃，双手距离略宽于肩宽。","保持背部挺直，核心参与。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢地将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर बैकरेस्ट की ओर मुंह करके अपनी छाती को टिकाकर बैठें।","बारबेल को उल्टी पकड़ (हथेलियाँ नीचे की ओर) से पकड़ें और हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ सीधी और कोर व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपने ऊपरी पेट की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें।","बारबेल को धीरे-धीरे प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Ustaw ławkę skośną (dodatnią) pod kątem 45 stopni.","Usiądź na ławce twarzą do oparcia, opierając o nie klatkę piersiową.","Chwyć sztangę chwytem odwrotnym (dłonie skierowane w dół), dłonie nieco szerzej niż szerokość barków.","Utrzymuj proste plecy i napięte mięśnie tułowia.","Przyciągnij sztangę w kierunku górnej części brzucha, ściskając łopatki.","Zatrzymaj się na chwilę na szczycie ruchu.","Powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["인클라인 벤치를 45도 각도로 세웁니다.","벤치에 앉아 등받이에 등을 붙인 채로 앉습니다.","역그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","등을 곧게 펴고 코어에 힘을 줍니다.","바벨을 상복부를 향해 당기며 어깨 날개뼈를 꽉 조입니다.","동작 상단에서 잠시 멈춥니다.","천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'biceps', '["biceps","forearms"]', 'upper back', 'images/1317-8d8qJQI.jpg', 'videos/1317-8d8qJQI.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1721', 'barbell reverse grip skullcrusher', 'upper arms', 'upper arms', 'barbell', '{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Sdraiati su una panca con i piedi appoggiati a terra e la testa all''estremità della panca.","Tieni il bilanciere con una presa inversa, i palmi rivolti verso il viso e le mani alla larghezza delle spalle.","Estendi le braccia verso l''alto sul petto, mantenendo i gomiti e i polsi dritti.","Abbassa lentamente il bilanciere verso la fronte piegando i gomiti e mantenendo ferma la parte superiore delle braccia.","Fai una pausa per un momento in basso, quindi allunga le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve başınız sehpanın ucunda olacak şekilde bir bankın üzerine düz bir şekilde uzanın.","Halteri ters tutuşla, avuçlarınız yüzünüze bakacak şekilde ve elleriniz omuz genişliğinde açık olacak şekilde tutun.","Kollarınızı göğsünüzün üzerine doğru uzatın, dirseklerinizi içeride ve bileklerinizi düz tutun.","Dirseklerinizi bükerek, üst kollarınızı sabit tutarak halteri yavaşça alnınıza doğru indirin.","Altta bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.","Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.","Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.","Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.","Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Лягте на скамью, положив ноги на землю, а голову на край скамьи.","Держите штангу обратным хватом ладонями к лицу, руки на ширине плеч.","Вытяните руки прямо вверх над грудью, сохраняя локти и запястья прямыми.","Медленно опустите штангу ко лбу, сгибая локти, сохраняя плечи неподвижными.","Задержитесь на мгновение в нижней точке, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","反握握住杠铃，手掌朝向脸部，双手与肩同宽。","将手臂伸直越过胸部，保持肘部内收和手腕伸直。","弯曲肘部，慢慢将杠铃降低到前额，保持上臂静止。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数。"],"hi":["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","बारबेल को उल्टी पकड़ से पकड़ें, हथेलियाँ आपके चेहरे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएं, अपनी कोहनियों को अंदर और अपनी कलाइयों को सीधा रखें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे बारबेल को अपने माथे की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Połóż się płasko na ławce, stopy oprzyj płasko na podłodze, a głowę umieść na końcu ławki.","Chwyć sztangę chwytem odwrotnym, dłonie skierowane w stronę twarzy, na szerokość barków.","Wyprostuj ręce nad klatką piersiową, utrzymując łokcie przy sobie, a nadgarstki proste.","Powoli opuszczaj sztangę w kierunku czoła, uginając łokcie, utrzymując ramiona nieruchomo.","Zatrzymaj się na chwilę na dole, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 누워 발은 바닥에 편하게 놓고 머리는 벤치 끝에 위치합니다.","역그립으로 바벨을 잡으며 손은 어깨 너비 정도 벌립니다.","팔을 가슴 위로 쭉 펼치며 팔꿈치는 안쪽으로 향하게 유지합니다.","팔꿈치를 구부려 천천히 바벨을 이마를 향해 내립니다.","하단에서 잠시 멈춘 후 팔을 다시 펼쳐 시작 위치로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'triceps', 'images/1721-yRLPCLu.jpg', 'videos/1721-yRLPCLu.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0081', 'barbell reverse preacher curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca da predicatore con il petto contro il cuscino e le braccia distese verso il basso, tenendo un bilanciere con una presa prona.","Mantenendo ferma la parte superiore delle braccia, espira e piega il bilanciere verso l''alto contraendo i bicipiti.","Continua a sollevare il bilanciere finché i bicipiti non saranno completamente contratti e il bilanciere sarà all''altezza delle spalle.","Mantieni la posizione contratta per una breve pausa mentre contrai i bicipiti.","Inspira e abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Göğsünüz yastığa dayalı ve kollarınız düz bir şekilde aşağıya doğru uzatılmış şekilde bir vaiz bankına oturun, halteri üstten kavrayarak tutun.","Üst kollarınızı sabit tutarak nefes verin ve bicepslerinizi kasarken halteri yukarı doğru kıvırın.","Bicepsleriniz tamamen kasılana ve halter omuz hizasına gelene kadar halteri kaldırmaya devam edin.","Bicepslerinizi sıkarken kasılmış pozisyonu kısa bir süre koruyun.","Nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.","Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.","Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.","Inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью для проповедника, прижав грудь к подушке и вытянув руки вниз, держа штангу хватом сверху.","Удерживая плечи неподвижно, выдохните и поднимите штангу вверх, одновременно напрягая бицепсы.","Продолжайте поднимать штангу до тех пор, пока ваши бицепсы полностью не сократятся и штанга не окажется на уровне плеч.","Задержитесь в сокращенном положении на короткую паузу, одновременно сжимая бицепсы.","Вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。","保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर बैठें और आपकी भुजाएँ सीधी नीचे की ओर फैली हुई हों, एक बारबेल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को ऊपर की ओर मोड़ें।","बारबेल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और बारबेल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे बारबेल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce Scotta, opierając klatkę piersiową o poduszkę, a ręce wyprostuj prosto w dół, trzymając sztangę chwytem nachwytem.","Utrzymując ramiona nieruchomo, wydychaj powietrze, uginając sztangę w górę i napinając biceps.","Unoś sztangę, aż biceps będzie w pełni napięty, a sztanga znajdzie się na wysokości barków.","Zatrzymaj się na chwilę w pozycji szczytowej, mocno napinając biceps.","Wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["프리처 벤치에 앉아 가슴을 패드에 붙이고 팔을 곧게 내린 채 바벨을 오버핸드 그립으로 잡습니다.","상팔은 고정된 상태를 유지하며 숨을 내쉬며 바벨을 위로 컬링하고 이두근을 수축합니다.","바벨이 어깨 높이에 도달할 때까지 계속 올립니다.","이두근을 완전히 수축한 상태를 잠시 유지하며 조입니다.","숨을 들이쉬며 천천히 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0081-4LIG9xr.jpg', 'videos/0081-4LIG9xr.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0082', 'barbell reverse wrist curl', 'lower arms', 'lower arms', 'barbell', '{"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sedersi su una panca con i piedi appoggiati a terra e tenere un bilanciere con una presa prona, i palmi rivolti verso il basso.","Appoggia gli avambracci sulle cosce, lasciando che i polsi pendano dal bordo.","Piega lentamente i polsi verso l''alto, portando il bilanciere verso il tuo corpo.","Fermati per un momento in alto, quindi abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak şekilde bir bankta oturun ve halteri avuç içleriniz aşağıya bakacak şekilde üstten kavrayarak tutun.","Ön kollarınızı uyluklarınıza yaslayın, bileklerinizin kenardan sarkmasına izin verin.","Bileklerinizi yavaşça yukarı doğru kıvırarak halteri vücudunuza doğru getirin.","Tepe noktasında bir süre duraklayın, ardından halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo.","Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.","Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ноги на землю и возьмите штангу хватом сверху ладонями вниз.","Положите предплечья на бедра, позволяя запястьям свисать с края.","Медленно поднимите запястья вверх, приближая штангу к телу.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地上，正手握住杠铃，手掌朝下。","将前臂放在大腿上，让手腕悬在边缘。","慢慢向上弯曲手腕，将杠铃拉向身体。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और हथेलियाँ नीचे की ओर रखते हुए बारबेल को ज़ोर से पकड़ें।","अपने अग्रबाहुओं को अपनी जाँघों पर टिकाएँ, जिससे आपकी कलाइयाँ किनारे से लटक जाएँ।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, बारबेल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, i chwyć sztangę chwytem nachwytem, dłonie skierowane w dół.","Oprzyj przedramiona na udach, pozwalając nadgarstkom zwisać za krawędzią.","Powoli zginaj nadgarstki w górę, przyciągając sztangę w kierunku ciała.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발은 바닥에 놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 아래를 향합니다.","전완을 허벅지 위에 올리고 손목은 벤치 끝에서 튀어나온 상태로 유지합니다.","손목을 천천히 위로 컬링하며 바벨을 몸 방향으로 올립니다.","상단에서 잠시 멈춘 후 천천히 바벨을 시작 위치로 내립니다."]}', 'biceps', '["biceps","brachialis"]', 'forearms', 'images/0082-LsZkfU6.jpg', 'videos/0082-LsZkfU6.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0084', 'barbell rollerout', 'waist', 'waist', 'barbell', '{"en":["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."],"it":["Inginocchiarsi sul pavimento e tenere un bilanciere con entrambe le mani, alla larghezza delle spalle.","Fai rotolare il bilanciere in avanti, estendendo le braccia e mantenendo il core impegnato.","Continua a rotolare in avanti finché il corpo non è completamente esteso e le braccia sono sopra la testa.","Fai una pausa per un momento, quindi ruota lentamente il bilanciere verso le ginocchia, mantenendo il controllo.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Yere diz çökün ve halteri iki elinizle omuz genişliğinde tutun.","Halteri ileri doğru yuvarlayın, kollarınızı uzatın ve merkez bölgenizi meşgul tutun.","Vücudunuz tamamen uzayıncaya ve kollarınız başınızın üstünde oluncaya kadar ileri doğru yuvarlanmaya devam edin.","Bir an duraklayın, ardından kontrolü koruyarak halteri yavaşça dizlerinize doğru döndürün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros.","Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado.","Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control.","Repite el número de repeticiones deseado."],"ru":["Встаньте на колени и возьмите штангу обеими руками на ширине плеч.","Перекатите штангу вперед, вытягивая руки и сохраняя корпус напряженным.","Продолжайте перекатываться вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Сделайте паузу на мгновение, затем медленно перекатите штангу обратно к коленям, сохраняя контроль.","Повторите необходимое количество повторений."],"zh":["跪在地板上，双手握住杠铃，距离与肩同宽。","向前滚动杠铃，伸展手臂并保持核心收紧。","继续向前滚动，直到身体完全伸展并且手臂举过头顶。","暂停片刻，然后慢慢将杠铃向膝盖方向滚动，保持控制。","重复所需的重复次数。"],"hi":["फर्श पर घुटने टेकें और दोनों हाथों से कंधे की चौड़ाई की दूरी पर बारबेल पकड़ें।","अपनी बाहों को फैलाते हुए और अपने कोर को व्यस्त रखते हुए, बारबेल को आगे की ओर घुमाएँ।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं, तब तक आगे की ओर लुढ़कना जारी रखें।","एक पल के लिए रुकें, फिर नियंत्रण बनाए रखते हुए धीरे-धीरे बारबेल को अपने घुटनों की ओर वापस घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Uklęknij na podłodze i chwyć sztangę oburącz, na szerokość barków.","Toczy sztangę do przodu, prostując ręce i napinając mięśnie tułowia.","Kontynuuj toczenie do przodu, aż ciało będzie w pełni wyprostowane, a ręce nad głową.","Zatrzymaj się na chwilę, a następnie powoli tocz sztangę z powrotem w kierunku kolan, zachowując kontrolę.","Powtórz odpowiednią liczbę razy."],"ko":["바닥에 무릎을 꿇고 바벨을 어깨 너비로 양손으로 잡습니다.","바벨을 앞으로 굴리며 팔을 펼치고 코어에 힘을 줍니다.","팔이 머리 위로 가도록 몸 전체가 완전히 펼쳐질 때까지 계속 굴립니다.","잠시 멈춘 후 천천히 바벨을 무릎 방향으로 다시 굴려 제어를 유지합니다.","원하는 반복 횟수만큼 반복합니다."]}', 'lower back', '["lower back"]', 'abs', 'images/0084-7M66AVi.jpg', 'videos/0084-7M66AVi.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0083', 'barbell rollerout from bench', 'waist', 'waist', 'barbell', '{"en":["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."],"it":["Inizia in ginocchio sul pavimento con un bilanciere posizionato su una panca di fronte a te.","Afferrare il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Mantenendo il core impegnato e la schiena dritta, fai rotolare lentamente il bilanciere in avanti, estendendo le braccia davanti a te.","Continua a far rotolare il bilanciere in avanti finché il tuo corpo non è completamente esteso e le tue braccia sono sopra la testa.","Fermati per un momento nella posizione completamente estesa, quindi ruota lentamente il bilanciere verso il tuo corpo, tornando alla posizione di partenza.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Önünüzdeki bir bankın üzerine yerleştirilmiş bir halterle yere diz çökerek başlayın.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayın.","Merkez bölgenizi meşgul ve sırtınızı dik tutarak halteri yavaşça ileri doğru yuvarlayın ve kollarınızı önünüze doğru uzatın.","Vücudunuz tamamen uzayıncaya ve kollarınız başınızın üstünde oluncaya kadar halteri ileri doğru yuvarlamaya devam edin.","Tamamen uzatılmış pozisyonda bir an duraklayın, ardından halteri yavaşça vücudunuza doğru döndürerek başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti.","Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.","Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti.","Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza.","Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Начните с того, что встанете на колени на пол, положив штангу на скамью перед собой.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Удерживая корпус напряженным и спину прямой, медленно перекатывайте штангу вперед, вытягивая руки перед собой.","Продолжайте перекатывать штангу вперед до тех пор, пока ваше тело не будет полностью выпрямлено, а руки не окажутся над головой.","Задержитесь на мгновение в полностью выпрямленном положении, затем медленно перекатите штангу обратно к телу, возвращаясь в исходное положение.","Повторите необходимое количество повторений."],"zh":["首先跪在地板上，将杠铃放在你面前的长凳上。","正手握住杠铃，握距略宽于肩宽。","保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。","继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。","在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。","重复所需的重复次数。"],"hi":["अपने सामने एक बेंच पर बारबेल रखकर फर्श पर घुटने टेककर शुरुआत करें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","अपने कोर को व्यस्त रखते हुए और अपनी पीठ को सीधा रखते हुए, अपनी बाहों को अपने सामने फैलाते हुए धीरे-धीरे बारबेल को आगे की ओर घुमाएँ।","जब तक आपका शरीर पूरी तरह से विस्तारित न हो जाए और आपकी भुजाएं ऊपर न आ जाएं, तब तक बारबेल को आगे की ओर घुमाते रहें।","पूरी तरह से विस्तारित स्थिति में एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को अपने शरीर की ओर घुमाएं, प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Uklęknij na podłodze ze sztangą umieszczoną na ławce przed sobą.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Utrzymując napięte mięśnie tułowia i proste plecy, powoli tocz sztangę do przodu, wyciągając ręce przed siebie.","Kontynuuj toczenie sztangi do przodu, aż ciało będzie w pełni wyprostowane, a ręce nad głową.","Zatrzymaj się na chwilę w pozycji pełnego wyprostu, a następnie powoli tocz sztangę z powrotem w kierunku ciała, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["바닥에 무릎을 꿇은 상태로 앞의 벤치 위에 바벨을 올려놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","코어에 힘을 주고 등을 곧게 펴며 천천히 바벨을 앞으로 굴립니다.","팔을 펼쳐 신체가 완전히 확장되고 팔이 머리 위로 갈 때까지 계속 굴립니다.","완전히 펼친 위치에서 잠시 멈춘 후 천천히 바벨을 몸으로 다시 굴려 시작 위치로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders","triceps"]', 'abs', 'images/0083-Gxg9lDc.jpg', 'videos/0083-Gxg9lDc.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0085', 'barbell romanian deadlift', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e le dita dei piedi rivolte in avanti.","Tieni il bilanciere con una presa prona, con le mani leggermente più larghe della larghezza delle spalle.","Piegati sui fianchi, mantenendo la schiena dritta e le ginocchia leggermente piegate.","Abbassa il bilanciere verso terra, tenendolo vicino al corpo.","Senti l''allungamento dei muscoli posteriori della coscia mentre abbassi il bilanciere.","Una volta che senti un allungamento nei muscoli posteriori della coscia, spingi i fianchi in avanti e stai dritto.","Contrai i glutei nella parte superiore del movimento.","Abbassare nuovamente il bilanciere nella posizione iniziale e ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız omuz genişliğinde açık ve ayak parmaklarınız ileriyi gösterecek şekilde ayakta durun.","Halteri üstten kavrayarak tutun, eller omuz genişliğinden biraz daha açık olsun.","Kalçalarınızı bükün, sırtınızı düz tutun ve dizlerinizi hafifçe bükün.","Halteri vücudunuza yakın tutarak yere doğru indirin.","Halteri indirirken diz arkası kaslarınızın gerginliğini hissedin.","Diz arkası kaslarınızın gerildiğini hissettiğinizde kalçalarınızı öne doğru itin ve dik durun.","Hareketin üst noktasında kalçalarınızı sıkın.","Halteri başlangıç ​​pozisyonuna indirin ve istenilen sayıda tekrar yapın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.","Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.","Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo.","Siente el estiramiento en los isquiotibiales mientras bajas la barra.","Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie.","Aprieta los glúteos en la parte alta del movimiento.","Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги на ширине плеч, носки ног направлены вперед.","Возьмите штангу хватом сверху, руки чуть шире плеч.","Согните бедра, сохраняя спину прямой и слегка согнутыми в коленях.","Опустите штангу к земле, держа ее близко к телу.","Почувствуйте растяжение подколенных сухожилий, когда опускаете штангу.","Как только вы почувствуете растяжение подколенных сухожилий, выдвиньте бедра вперед и встаньте прямо.","Напрягите ягодицы в верхней точке движения.","Опустите штангу обратно в исходное положение и повторите желаемое количество повторений."],"zh":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，保持背部挺直，膝盖稍微弯曲。","将杠铃向地面降低，使其靠近身体。","当你降低杠铃时，感受腿筋的拉伸。","一旦感觉到腿筋拉伸，就将臀部向前推并站直。","在动作的最高点挤压臀部。","将杠铃放回起始位置，然后重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके पैर की उंगलियां आगे की ओर हों।","बारबेल को ओवरहैंड ग्रिप से पकड़ें, हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखें।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़ते हुए, कूल्हों पर झुकें।","बारबेल को अपने शरीर के करीब रखते हुए जमीन की ओर नीचे करें।","जैसे ही आप बारबेल को नीचे करते हैं, अपनी हैमस्ट्रिंग में खिंचाव महसूस करें।","एक बार जब आप अपनी हैमस्ट्रिंग में खिंचाव महसूस करें, तो अपने कूल्हों को आगे की ओर धकेलें और सीधे खड़े हो जाएं।","आंदोलन के शीर्ष पर अपने ग्लूट्स को निचोड़ें।","बारबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"],"pl":["Stań w rozkroku na szerokość barków, palce stóp skierowane do przodu.","Chwyć sztangę chwytem nachwytem, dłonie nieco szerzej niż szerokość barków.","Pochyl się w biodrach, utrzymując proste plecy i lekko ugięte kolana.","Opuszczaj sztangę w kierunku podłogi, trzymając ją blisko ciała.","Poczuj rozciąganie mięśni dwugłowych uda podczas opuszczania sztangi.","Gdy poczujesz rozciąganie w tych mięśniach, wypchnij biodra do przodu i wyprostuj się.","Ściśnij pośladki na szczycie ruchu.","Opuść sztangę z powrotem do pozycji wyjściowej i powtórz odpowiednią liczbę razy."],"ko":["발을 어깨 너비로 벌리고 발끝은 앞을 향하도록 섭니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","허리에서 굽히며 등은 곧게 유지하고 무릎은 약간만 구부립니다.","바벨을 몸 가까이 유지하며 천천히 땅을 향해 내립니다.","햄스트링에 스트레칭 감각이 들 때까지 내립니다.","햄스트링에 스트레칭이 감지되면 엉덩이를 앞으로 밀어 일어섭니다.","동작 상단에서 글루트를 조입니다.","바벨을 시작 위치로 다시 내립니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0085-wQ2c4XD.jpg', 'videos/0085-wQ2c4XD.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0086', 'barbell seated behind head military press', 'shoulders', 'shoulders', 'barbell', '{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con la schiena dritta e i piedi appoggiati a terra.","Tieni il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Solleva il bilanciere dal rack e abbassalo all''altezza delle spalle, dietro la testa.","Spingi il bilanciere verso l''alto finché le braccia non sono completamente distese.","Abbassare nuovamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak tutun.","Halteri raftan kaldırın ve başınızın arkasında omuz hizasına kadar indirin.","Kollarınız tamamen uzayana kadar halteri yukarıya doğru bastırın.","Halteri tekrar başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza.","Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.","Baja la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и опустите ее на уровень плеч за голову.","Нажмите штангу вверх, пока руки полностью не выпрямятся.","Опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，然后将其降至与肩同高，位于头后。","向上推杠铃，直到手臂完全伸展。","将杠铃降低回到起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और इसे अपने सिर के पीछे, कंधे के स्तर तक नीचे लाएं।","बारबेल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","बारबेल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, plecy wyprostuj, a stopy oprzyj płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Zdejmij sztangę ze stojaka i opuść ją do wysokości barków, za głową.","Wyciśnij sztangę w górę, aż ręce będą w pełni wyprostowane.","Opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 등을 곧게 펴고 발은 바닥에 놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","바벨을 랙에서 꺼내 어깨 높이로 내려 머리 뒤로 위치합니다.","바벨을 위로 밀어 올리며 팔을 완전히 펼칩니다.","바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/0086-ngPpyRS.jpg', 'videos/0086-ngPpyRS.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0087', 'barbell seated bradford rocky press', 'shoulders', 'shoulders', 'barbell', '{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."],"it":["Siediti su una panca con la schiena dritta e i piedi appoggiati a terra.","Tieni il bilanciere con una presa prona, leggermente più larga della larghezza delle spalle.","Sollevare il bilanciere all''altezza delle spalle, mantenendo i gomiti leggermente piegati e rivolti in avanti.","Premi il bilanciere sopra la testa, estendendo completamente le braccia.","Abbassare il bilanciere all''altezza delle spalle e ripetere per il numero di ripetizioni desiderato."],"tr":["Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak tutun.","Halteri omuz yüksekliğine kadar kaldırın, dirseklerinizi hafifçe bükülü ve ileriye dönük tutun.","Kollarınızı tamamen uzatarak halteri başınızın üzerine bastırın.","Halteri tekrar omuz yüksekliğine indirin ve istediğiniz sayıda tekrar yapın."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.","Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.","Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Поднимите штангу на высоту плеч, держа локти слегка согнутыми и направленными вперед.","Жмите штангу над головой, полностью выпрямляя руки.","Опустите штангу обратно на высоту плеч и повторите необходимое количество повторений."],"zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को कंधे की ऊंचाई तक उठाएं, अपनी कोहनियों को थोड़ा मोड़कर आगे की ओर रखें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","बारबेल को वापस कंधे की ऊंचाई तक कम करें और वांछित संख्या में दोहराव के लिए दोहराएं।"],"pl":["Usiądź na ławce, plecy wyprostuj, a stopy oprzyj płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerszym niż szerokość barków.","Unieś sztangę do wysokości barków, utrzymując łokcie lekko ugięte i skierowane do przodu.","Wyciśnij sztangę nad głowę, w pełni prostując ręce.","Opuść sztangę z powrotem do wysokości barków i powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 등을 곧게 펴고 발은 바닥에 놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","바벨을 어깨 높이로 올리며 팔꿈치는 약간 구부리고 앞을 향하게 합니다.","바벨을 위로 밀어 올리며 팔을 완전히 펼칩니다.","바벨을 어깨 높이로 내려 원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/0087-0dCyly0.jpg', 'videos/0087-0dCyly0.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0088', 'barbell seated calf raise', 'lower legs', 'lower legs', 'barbell', '{"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con i piedi appoggiati sul pavimento e un bilanciere appoggiato sulle cosce.","Posiziona le punte dei piedi su una piattaforma rialzata, come un blocco o un gradino.","Posiziona il bilanciere sulle cosce e tienilo saldamente con le mani.","Tenendo la schiena dritta e il core impegnato, solleva i talloni da terra estendendo le caviglie.","Fai una pausa per un momento in alto, quindi abbassa lentamente i talloni nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve halter kalçalarınızın üzerinde olacak şekilde bir bankta oturun.","Ayak parmaklarınızın toplarını blok veya basamak gibi yükseltilmiş bir platform üzerine yerleştirin.","Halteri uyluklarınızın üzerine konumlandırın ve ellerinizle güvenli bir şekilde tutun.","Sırtınızı düz ve merkez bölgenizi meşgul tutarak, ayak bileklerinizi uzatarak topuklarınızı yerden kaldırın.","Tepe noktasında bir an duraklayın, ardından topuklarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Coloca la barra sobre los muslos y sujétala con firmeza con las manos.","Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos.","Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ступни на пол и положите штангу на бедра.","Поставьте подушечки стоп на приподнятую платформу, например, на блок или ступеньку.","Расположите штангу на бедрах и надежно удерживайте ее руками.","Удерживая спину прямой и напрягая корпус, поднимите пятки от земли, вытянув лодыжки.","Задержитесь на мгновение в верхней точке, затем медленно опустите пятки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。","将脚掌放在升高的平台上，例如木块或台阶。","将杠铃放在大腿上，并用手牢牢握住它。","保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को फर्श पर सपाट करके और एक बारबेल को अपनी जांघों पर टिकाकर एक बेंच पर बैठें।","अपने पैरों की उंगलियों को किसी ऊंचे मंच पर रखें, जैसे ब्लॉक या सीढ़ी।","बारबेल को अपनी जांघों पर रखें और इसे अपने हाथों से सुरक्षित रूप से पकड़ें।","अपनी पीठ सीधी और अपने कोर को व्यस्त रखते हुए, अपनी एड़ियों को फैलाकर अपनी एड़ियों को जमीन से ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, a sztangę oprzyj na udach.","Ustaw palce stóp na podwyższonej platformie, na przykład klocku lub stopniu.","Umieść sztangę na udach i trzymaj ją pewnie rękami.","Utrzymując proste plecy i napięte mięśnie tułowia, unieś pięty z podłogi, prostując kostki.","Zatrzymaj się na chwilę na górze, a następnie powoli opuść pięty z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발은 바닥에 놓고 바벨을 허벅지 위에 올립니다.","발의 앞부분(발가락 부분)을 블록이나 스텝과 같은 높은 플랫폼에 올립니다.","바벨을 허벅지 위에 가로질러 놓고 양손으로 단단히 잡습니다.","등을 곧게 펴고 코어에 힘을 줍니다.","발뒤꿈치를 들어 올리며 발목을 펼쳐 확장합니다.","상단에서 잠시 멈춘 후 천천히 발뒤꿈치를 시작 위치로 내립니다."]}', 'hamstrings', '["hamstrings","quadriceps"]', 'calves', 'images/0088-ktsFQAZ.jpg', 'videos/0088-ktsFQAZ.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1371', 'barbell seated calf raise', 'lower legs', 'lower legs', 'barbell', '{"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con i piedi appoggiati sul pavimento e un bilanciere appoggiato sulle cosce.","Posiziona le punte dei piedi su una piattaforma rialzata, come un blocco o un gradino.","Abbassa i talloni il più possibile, avvertendo un allungamento nei polpacci.","Alza i talloni il più in alto possibile, contraendo i polpacci.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak ve halter kalçalarınızın üzerinde olacak şekilde bir bankta oturun.","Ayak parmaklarınızın toplarını blok veya basamak gibi yükseltilmiş bir platform üzerine yerleştirin.","Baldırlarınızda bir gerginlik hissederek topuklarınızı mümkün olduğu kadar indirin.","Topuklarınızı mümkün olduğu kadar yükseğe kaldırın, baldırlarınızı kasın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos.","Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.","Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas.","Levanta los talones lo más alto posible, contrayendo las pantorrillas.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ступни на пол и положите штангу на бедра.","Поставьте подушечки стоп на приподнятую платформу, например, на блок или ступеньку.","Опустите пятки как можно ниже, чувствуя растяжение в икрах.","Поднимите пятки как можно выше, напрягая икроножные мышцы.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。","将脚掌放在升高的平台上，例如木块或台阶。","尽可能降低脚后跟，感受小腿的拉伸。","尽可能高地抬高脚后跟，收缩小腿。","重复所需的重复次数。"],"hi":["अपने पैरों को फर्श पर सपाट करके और एक बारबेल को अपनी जांघों पर टिकाकर एक बेंच पर बैठें।","अपने पैरों की उंगलियों को किसी ऊंचे मंच पर रखें, जैसे ब्लॉक या सीढ़ी।","जहां तक ​​संभव हो अपनी एड़ियों को नीचे करें, अपनी पिंडलियों में खिंचाव महसूस करें।","अपनी पिंडलियों को सिकोड़ते हुए अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, a sztangę oprzyj na udach.","Ustaw palce stóp na podwyższonej platformie, na przykład klocku lub stopniu.","Opuść pięty jak najniżej, odczuwając rozciąganie łydek.","Unieś pięty jak najwyżej, napinając łydki.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발은 바닥에 놓고 바벨을 허벅지 위에 올립니다.","발의 앞부분(발가락 부분)을 블록이나 스텝과 같은 높은 플랫폼에 올립니다.","발뒤꿈치를 최대한 내려 종아리에 스트레칭을 느낍니다.","발뒤꿈치를 최대한 높이 올려 종아리를 수축합니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings"]', 'calves', 'images/1371-ipvgBnC.jpg', 'videos/1371-ipvgBnC.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1718', 'barbell seated close grip behind neck triceps extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con la schiena dritta e i piedi appoggiati a terra.","Tieni il bilanciere con una presa salda dietro il collo, con i palmi rivolti in avanti.","Tieni i gomiti vicini alla testa e abbassa lentamente il bilanciere verso la parte posteriore della testa.","Fai una pausa per un momento, quindi allunga le braccia fino alla posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun.","Halteri boynunuzun arkasında, avuçlarınız öne bakacak şekilde sıkı bir tutuşla tutun.","Dirseklerinizi başınıza yakın tutun ve halteri yavaşça başınızın arkasına doğru indirin.","Bir an duraklayın, ardından kollarınızı başlangıç ​​pozisyonuna kadar uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.","Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.","Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Держите штангу узким хватом за шеей ладонями вперед.","Держите локти близко к голове и медленно опустите штангу к затылку.","Сделайте паузу на мгновение, затем вытяните руки обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，背部挺直，双脚平放在地上。","紧紧抓住颈后的杠铃，手掌朝前。","保持肘部靠近头部，慢慢将杠铃放低至脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को अपनी गर्दन के पीछे कसकर पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को अपने सिर के पास रखें और बारबेल को धीरे-धीरे अपने सिर के पीछे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, plecy wyprostuj, a stopy oprzyj płasko na podłodze.","Chwyć sztangę wąskim chwytem za głową, dłonie skierowane do przodu.","Trzymaj łokcie blisko głowy i powoli opuszczaj sztangę w kierunku tyłu głowy.","Zatrzymaj się na chwilę, a następnie wyprostuj ręce z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 등을 곧게 펴고 발은 바닥에 놓습니다.","목 뒤에 클로즈그립으로 바벨을 잡으며 손은 앞을 향합니다.","팔꿈치는 머리 가까이 유지하며 천천히 바벨을 머리 뒤로 내립니다.","잠시 멈춘 후 팔을 펼쳐 시작 위치로 올립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/1718-4CBIBOM.jpg', 'videos/1718-4CBIBOM.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0089', 'barbell seated close-grip concentration curl', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Sedersi su una panca con i piedi appoggiati sul pavimento e tenere un bilanciere con una presa subdola, con le mani alla larghezza delle spalle.","Appoggia la parte superiore delle braccia contro l''interno delle cosce, appena sopra le ginocchia, e lascia che il bilanciere penda davanti a te.","Mantenendo ferma la parte superiore delle braccia, espira e porta il bilanciere verso le spalle, contraendo i bicipiti.","Mantieni la posizione contratta per una breve pausa, quindi inspira e abbassa lentamente il bilanciere nella posizione iniziale.","Ripetere per il numero di ripetizioni desiderato."],"tr":["Ayaklarınız yere düz basacak şekilde bir bankta oturun ve ellerinizi omuz genişliğinde açarak halteri alttan kavrayarak tutun.","Üst kollarınızı dizlerinizin hemen üzerinde uyluklarınızın iç kısmına yaslayın ve halterin önünüze sarkmasına izin verin.","Üst kollarınızı sabit tutarak nefes verin ve halteri omuzlarınıza doğru kıvırarak bicepslerinizi kasın.","Kısa bir süre kasılmış pozisyonda kalın, ardından nefes alın ve halteri yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.","Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.","Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.","Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставьте ноги на пол и возьмите штангу обратным хватом, руки на ширине плеч.","Положите плечи на внутреннюю поверхность бедер, чуть выше колен, и позвольте штанге свисать перед вами.","Удерживая плечи неподвижно, выдохните и поднимите штангу к плечам, напрягая бицепсы.","Удерживайте сокращенное положение на короткую паузу, затем вдохните и медленно опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地板上，反手握住杠铃，双手与肩同宽。","将你的上臂靠在大腿内侧，就在膝盖上方，让杠铃垂在你面前。","保持上臂静止，呼气并将杠铃向上卷曲至肩膀，收缩二头肌。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को फर्श पर सपाट करके एक बेंच पर बैठें और हाथों को कंधे की चौड़ाई से अलग रखते हुए बारबेल को हाथ से पकड़ें।","अपनी ऊपरी भुजाओं को अपने घुटनों के ठीक ऊपर, अपनी भीतरी जाँघों पर टिकाएँ, और बारबेल को अपने सामने नीचे लटकने दें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए बारबेल को अपने कंधों की ओर मोड़ें।","थोड़ी देर के लिए सिकुड़ी हुई स्थिति में बने रहें, फिर सांस लें और धीरे-धीरे बारबेल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, i chwyć sztangę chwytem podchwytem, dłonie na szerokość barków.","Oprzyj ramiona o wewnętrzną stronę ud, tuż nad kolanami, i pozwól sztandze zwisać przed sobą.","Utrzymując ramiona nieruchomo, wydychaj powietrze i uginaj sztangę w kierunku barków, napinając biceps.","Zatrzymaj się na chwilę w pozycji szczytowej, a następnie wdychaj powietrze, powoli opuszczając sztangę z powrotem do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발은 바닥에 놓고 언더핸드 그립으로 바벨을 잡으며 손은 어깨 너비입니다.","상팔을 허벅지 내측에 얹고 바벨을 몸 앞에 매달린 상태로 유지합니다.","상팔은 고정된 상태를 유지하며 숨을 내쉬며 바벨을 어깨를 향해 컬링하고 이두근을 수축합니다.","수축된 위치를 잠시 유지하며 조입니다.","숨을 들이쉬며 천천히 바벨을 시작 위치로 내립니다."]}', 'forearms', '["forearms"]', 'biceps', 'images/0089-1V1gj1u.jpg', 'videos/0089-1V1gj1u.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0090', 'barbell seated good morning', 'upper legs', 'upper legs', 'barbell', '{"en":["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panca con i piedi piatti a terra e un bilanciere appoggiato sulla parte alta della schiena.","Tieni la schiena dritta e il petto sollevato.","Inclinati lentamente in avanti ai fianchi, abbassando il busto verso terra.","Fermati un attimo in fondo, poi spingi attraverso i talloni per tornare alla posizione di partenza.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Ayaklarınız yere düz basacak ve halter sırtınızın üst kısmına dayanacak şekilde bir bankta oturun.","Sırtınızı dik ve göğsünüzü dik tutun.","Kalçalarınızdan yavaşça öne doğru eğilerek gövdenizi yere doğru indirin.","Altta bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için topuklarınızı itin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda.","Mantén la espalda recta y el pecho elevado.","Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo.","Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, поставив ноги на землю, а штангу положите на верхнюю часть спины.","Держите спину прямо и грудь вверх.","Медленно наклонитесь вперед в бедрах, опуская туловище к земле.","Задержитесь на мгновение внизу, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，双脚平放在地上，上背部放一个杠铃。","保持背部挺直，挺胸。","慢慢地向前转动臀部，将躯干降低到地面。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक बारबेल आपकी पीठ के ऊपरी हिस्से पर टिका हुआ हो।","अपनी पीठ सीधी और छाती ऊपर रखें।","अपने धड़ को जमीन की ओर नीचे करते हुए धीरे-धीरे कूल्हों पर आगे की ओर झुकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, stopy oprzyj płasko na podłodze, a sztangę oprzyj na górnej części pleców.","Utrzymuj proste plecy i uniesioną klatkę piersiową.","Powoli pochylaj się do przodu w biodrach, opuszczając tułów w kierunku podłogi.","Zatrzymaj się na chwilę na dole, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz odpowiednią liczbę razy."],"ko":["벤치에 앉아 발은 바닥에 놓고 바벨을 상등에 올려놓습니다.","등을 곧게 펴고 가슴을 올립니다.","천천히 허리에서 굽혀 몸을 땅을 향해 내립니다.","하단에서 잠시 멈춘 후 발뒤꿈치를 통해 밀어 시작 위치로 돌아갑니다.","원하는 반복 횟수만큼 반복합니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/0090-d960PgE.jpg', 'videos/0090-d960PgE.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0091', 'barbell seated overhead press', 'shoulders', 'shoulders', 'barbell', '{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."],"it":["Siediti su una panchina con la schiena dritta e i piedi piatti a terra.","Tieni il bilanciere con una presa sopra la mano, leggermente più larga della larghezza delle spalle.","Solleva il bilanciere dal portapacchi e portalo all''altezza delle spalle, con i gomiti piegati e i palmi rivolti in avanti.","Premi il bilanciere sopra la testa estendendo completamente le braccia.","Fermati un attimo in cima, poi abbassa lentamente il bilanciere all''altezza delle spalle.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun.","Halteri omuz genişliğinden biraz daha geniş olacak şekilde üstten kavrayarak tutun.","Halteri raftan kaldırın ve dirsekleriniz bükülü ve avuç içleriniz öne bakacak şekilde omuz hizasına getirin.","Kollarınızı tamamen uzatarak halteri başınızın üzerine doğru bastırın.","Tepe noktasında bir an duraklayın, ardından halteri yavaşça omuz hizasına indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.","Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.","Empuja la barra por encima de la cabeza extendiendo completamente los brazos.","Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, на расстоянии чуть шире плеч.","Снимите штангу со стойки и поднимите ее на уровень плеч, согнув локти и повернув ладони вперед.","Выжмите штангу над головой, полностью выпрямив руки.","Задержитесь на мгновение в верхней точке, затем медленно опустите штангу обратно на уровень плеч.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","充分伸展双臂，将杠铃压过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़े हाथ से पकड़ें।","बारबेल को रैक से उठाएं और कंधे के स्तर पर लाएं, अपनी कोहनियां मुड़ी हुई और हथेलियां आगे की ओर रहें।","अपनी बाहों को पूरी तरह फैलाकर बारबेल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे बारबेल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, trzymając plecy proste, a stopy płasko na podłodze.","Chwyć sztangę chwytem nachwytem, nieco szerzej niż na szerokość barków.","Zdejmij sztangę ze stojaka i unieś ją na wysokość barków, zginając łokcie i kierując dłonie do przodu.","Wypchnij sztangę nad głowę, w pełni prostując ramiona.","Zatrzymaj się na chwilę w górnej pozycji, a następnie powoli opuść sztangę z powrotem na wysokość barków.","Powtórz zadaną liczbę powtórzeń."],"ko":["벤치에 앉아 등을 곧게 펴고 발은 바닥에 놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비보다 약간 넓게 합니다.","바벨을 랙에서 꺼내 어깨 높이로 올리며 팔꿈치는 구부리고 손은 앞을 향합니다.","팔을 펼쳐 바벨을 위로 밀어 올립니다.","상단에서 잠시 멈춘 후 천천히 바벨을 어깨 높이로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","upper back"]', 'delts', 'images/0091-kTbSH9h.jpg', 'videos/0091-kTbSH9h.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0092', 'barbell seated overhead triceps extension', 'upper arms', 'upper arms', 'barbell', '{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."],"it":["Siediti su una panchina con la schiena dritta e i piedi piatti a terra.","Tieni un bilanciere con una presa sopra la testa, mani alla larghezza delle spalle, e sollevalo sopra la testa.","Abbassa il bilanciere dietro la testa piegando i gomiti, tenendo le braccia superiori vicine alla testa.","Fermati un attimo, poi estendi le braccia per sollevare il bilanciere fino alla posizione iniziale.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Sırtınız dik ve ayaklarınız yere düz basacak şekilde bir bankta oturun.","Halteri üstten kavrayarak tutun, ellerinizi omuz genişliğinde açın ve başınızın üzerine kaldırın.","Dirseklerinizi bükerek, üst kollarınızı başınıza yakın tutarak halteri başınızın arkasına indirin.","Bir an duraklayın, ardından halteri başlangıç ​​pozisyonuna geri kaldırmak için kollarınızı uzatın.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.","Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.","Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.","Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Сядьте на скамью, выпрямив спину и поставив ноги на землю.","Возьмите штангу хватом сверху, руки на ширине плеч, и поднимите ее над головой.","Опустите штангу за голову, согнув локти и держа плечи близко к голове.","Сделайте паузу на мгновение, затем вытяните руки и поднимите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，双手与肩同宽，并将其举过头顶。","弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。","暂停片刻，然后伸展双臂将杠铃举回起始位置。","重复所需的重复次数。"],"hi":["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","बारबेल को ऊपरी पकड़ से पकड़ें, हाथों को कंधे की चौड़ाई से अलग रखें और इसे ऊपर उठाएं।","अपनी कोहनियों को मोड़कर बारबेल को अपने सिर के पीछे नीचे करें, अपनी ऊपरी भुजाओं को अपने सिर के पास रखें।","एक पल के लिए रुकें, फिर बारबेल को शुरुआती स्थिति में वापस उठाने के लिए अपनी बाहों को फैलाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Usiądź na ławce, trzymając plecy proste, a stopy płasko na podłodze.","Chwyć sztangę chwytem nachwytem, z dłońmi rozstawionymi na szerokość barków, i unieś ją nad głowę.","Opuść sztangę za głowę, zginając łokcie i trzymając ramiona blisko głowy.","Zatrzymaj się na chwilę, a następnie wyprostuj ramiona, wracając ze sztangą do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń."],"ko":["벤치에 앉아 등을 곧게 펴고 발은 바닥에 놓습니다.","오버핸드 그립으로 바벨을 잡으며 손은 어깨 너비입니다.","바벨을 머리 위로 올립니다.","팔꿈치를 구부려 바벨을 머리 뒤로 천천히 내립니다.","잠시 멈춘 후 팔을 펼쳐 바벨을 시작 위치로 올립니다."]}', 'shoulders', '["shoulders"]', 'triceps', 'images/0092-5uFK1xr.jpg', 'videos/0092-5uFK1xr.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0094', 'barbell seated twist', 'waist', 'waist', 'barbell', '{"en":["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."],"it":["Siediti su una panchina piatta con i piedi piatti a terra e le ginocchia piegate.","Tieni un bilanciere con entrambe le mani davanti al petto, tenendo i gomiti leggermente piegati.","Attiva il core e ruota lentamente il busto da un lato, mantenendo la schiena dritta.","Fermati un attimo alla fine della torsione, poi ruota lentamente tornando alla posizione iniziale.","Ripeti la torsione dall''altro lato.","Continua ad alternare i lati per il numero desiderato di ripetizioni."],"tr":["Ayaklarınız yere düz basacak ve dizleriniz bükülü olacak şekilde düz bir bankta oturun.","Dirseklerinizi hafifçe bükerek halteri iki elinizle göğsünüzün önünde tutun.","Merkez bölgenizi devreye sokun ve sırtınızı düz tutarak gövdenizi yavaşça bir tarafa doğru çevirin.","Bükülmenin sonunda bir an duraklayın, ardından yavaşça başlangıç ​​pozisyonuna dönün.","Bükmeyi diğer tarafa tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas.","Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados.","Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta.","Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial.","Repite el giro hacia el otro lado.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Сядьте на плоскую скамью, поставьте ступни на землю и согните колени.","Держите штангу обеими руками перед грудью, слегка согнув локти.","Напрягите корпус и медленно поверните туловище в сторону, сохраняя спину прямой.","Сделайте паузу на мгновение в конце поворота, затем медленно поверните обратно в исходное положение.","Повторите поворот в другую сторону.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。","双手握住杠铃于胸前，保持肘部稍微弯曲。","启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。","扭转结束时暂停片刻，然后慢慢旋转回到起始位置。","重复扭转到另一侧。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक सपाट बेंच पर बैठें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी छाती के सामने दोनों हाथों से बारबेल को पकड़ें।","अपने कोर को संलग्न करें और अपनी पीठ को सीधा रखते हुए धीरे-धीरे अपने धड़ को एक तरफ मोड़ें।","मोड़ के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में वापस आएँ।","दूसरी तरफ मोड़ को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Usiądź na płaskiej ławce, trzymając stopy płasko na podłodze, a kolana ugięte.","Trzymaj sztangę obiema rękami przed klatką piersiową, z lekko ugiętymi łokciami.","Napnij mięśnie brzucha i powoli skręć tułów w jedną stronę, trzymając plecy proste.","Zatrzymaj się na chwilę na końcu skrętu, a następnie powoli wróć do pozycji wyjściowej.","Powtórz skręt w drugą stronę.","Kontynuuj naprzemienne skręty przez zadaną liczbę powtórzeń."],"ko":["플랫 벤치에 앉아 발은 바닥에 놓고 무릎은 구부립니다.","바벨을 양손으로 가슴 앞에 들고 팔꿈치는 약간 구부립니다.","코어에 힘을 주고 몸 한쪽 방향으로 천천히 트위스트하며 등은 곧게 펴집니다.","트위스트 끝에서 잠시 멈춘 후 천천히 시작 위치로 돌아갑니다.","다른 쪽으로 트위스트합니다.","원하는 반복 횟수만큼 좌우를 번갈아 반복합니다."]}', 'obliques', '["obliques","lower back"]', 'abs', 'images/0094-dFSNDOA.jpg', 'videos/0094-dFSNDOA.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0095', 'barbell shrug', 'back', 'back', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi alla larghezza delle spalle e tieni un bilanciere davanti a te con una presa sopra la testa.","Mantieni le braccia dritte e la schiena dritta durante tutto l''esercizio.","Alza le spalle verso le orecchie il più possibile, stringendo i trapezi in alto.","Tieni per un momento, poi abbassa lentamente le spalle fino alla posizione iniziale.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri üstten kavrayarak önünüzde tutun.","Egzersiz boyunca kollarınızı düz ve sırtınızı düz tutun.","Omuzlarınızı mümkün olduğu kadar kulaklarınıza doğru kaldırın, trapezlerinizi üst kısımda sıkıştırın.","Bir süre bekleyin, ardından omuzlarınızı yavaşça başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado.","Mantén los brazos rectos y la espalda recta durante todo el ejercicio.","Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta.","Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, и держите штангу перед собой хватом сверху.","На протяжении всего упражнения держите руки прямыми и спину прямой.","Поднимите плечи к ушам как можно выше, сжимая трапеции вверху.","Задержитесь на мгновение, затем медленно опустите плечи обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，正手握住杠铃。","在整个练习过程中保持手臂伸直和背部挺直。","将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。","保持一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने सामने एक बारबेल को ज़ोर से पकड़ें।","पूरे अभ्यास के दौरान अपनी भुजाएँ सीधी और अपनी पीठ सीधी रखें।","अपने कंधों को अपने कानों की ओर जितना संभव हो उतना ऊपर उठाएं, अपने जालों को शीर्ष पर निचोड़ें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań ze stopami na szerokość barków, trzymając sztangę przed sobą chwytem nachwytem.","Trzymaj ramiona proste, a plecy proste przez cały czas trwania ćwiczenia.","Unieś barki jak najwyżej w kierunku uszu, mocno napinając mięsień czworoboczny w górnej pozycji.","Przytrzymaj przez chwilę, a następnie powoli opuść barki z powrotem do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń."],"ko":["어깨넓이로 발을 벌리고 서서 바벨을 양손으로 오버그립으로 몸 앞에 들고 있습니다.","운동 내내 팔과 등을 곧게 펴진 상태로 유지합니다.","어깨를 귀 쪽으로 최대한 높이 들어올리면서 사다리근을 최상단에서 꼬집습니다.","순간 멈춘 후 어깨를 천천히 시작 위치로 낮춥니다.","원하는 횟수만큼 반복합니다."]}', 'shoulders', '["shoulders"]', 'traps', 'images/0095-dG7tG5y.jpg', 'videos/0095-dG7tG5y.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0096', 'barbell side bent v. 2', 'waist', 'waist', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."],"it":["Stai con i piedi a larghezza delle spalle e tieni un bilanciere con entrambe le mani, palmi rivolti verso il basso.","Mantieni la schiena dritta e il core impegnato durante tutto l''esercizio.","Piega lentamente il busto verso il lato destro, abbassando il bilanciere verso il ginocchio destro.","Fermati un attimo, poi torna alla posizione iniziale.","Ripeti il movimento sul lato sinistro.","Continua ad alternare i lati per il numero desiderato di ripetizioni."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri iki elinizle, avuçlarınız aşağıya bakacak şekilde tutun.","Egzersiz boyunca sırtınızı düz ve göbek bölgenizi meşgul tutun.","Gövdenizi yavaşça sağ tarafa doğru eğin ve halteri sağ dizinize doğru indirin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönün.","Hareketi sol tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo.","Mantén la espalda recta y el core activado durante todo el ejercicio.","Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha.","Haz una pausa breve y luego vuelve a la posición inicial.","Repite el movimiento hacia el lado izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, возьмите штангу обеими руками ладонями вниз.","На протяжении всего упражнения держите спину прямой и напряженным корпус.","Медленно наклоните туловище в правую сторону, опуская штангу к правому колену.","Сделайте паузу на мгновение, затем вернитесь в исходное положение.","Повторите движение с левой стороны.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。","在整个练习过程中保持背部挺直并保持核心参与。","慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。","暂停片刻，然后回到起始位置。","在左侧重复该动作。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों से बारबेल पकड़ें, हथेलियां नीचे की ओर हों।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और मुख्य भाग को व्यस्त रखें।","धीरे-धीरे अपने धड़ को दाहिनी ओर झुकाएं, बारबेल को अपने दाहिने घुटने की ओर नीचे करें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","बायीं ओर भी यही क्रिया दोहरायें।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań ze stopami na szerokość barków, trzymając sztangę obiema rękami, dłońmi skierowanymi w dół.","Trzymaj plecy proste, a mięśnie brzucha napięte przez cały czas trwania ćwiczenia.","Powoli pochyl tułów w prawą stronę, opuszczając sztangę w kierunku prawego kolana.","Zatrzymaj się na chwilę, a następnie wróć do pozycji wyjściowej.","Powtórz ruch w lewą stronę.","Kontynuuj naprzemienne pochylenia przez zadaną liczbę powtórzeń."],"ko":["발을 어깨 너비로 벌리고 양손으로 바벨을 들며 손은 아래를 향합니다.","등을 곧게 펴고 코어에 힘을 줍니다.","천천히 몸을 오른쪽으로 굽혀 바벨을 오른쪽 무릎을 향해 내립니다.","잠시 멈춘 후 시작 위치로 돌아갑니다.","왼쪽으로 같은 동작을 반복합니다.","원하는 반복 횟수만큼 좌우를 번갈아 반복합니다."]}', 'obliques', '["obliques","lower back"]', 'abs', 'images/0096-i4JkUaL.jpg', 'videos/0096-i4JkUaL.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0098', 'barbell side split squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai in piedi con i piedi più larghi delle spalle, le dita leggermente rivolte verso l''esterno.","Tieni un bilanciere sulla parte alta della schiena, appoggiandolo sui trapezi.","Attiva il core e tieni il petto sollevato mentre abbassi il corpo in posizione accovacciata, piegando ginocchia e fianchi.","Mentre ti abbassi, spingi le ginocchia verso i lati e tieni il peso sui talloni.","Abbassa finché le cosce non sono parallele al suolo, poi spingi attraverso i talloni per tornare alla posizione di partenza.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Ayaklarınız omuz genişliğinden daha geniş, ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun.","Sırtınızın üst kısmına bir halter tutun ve onu trapezlerinize dayayın.","Vücudunuzu çömelme pozisyonuna indirirken, dizlerinizi ve kalçalarınızı bükerken, merkez bölgenizi devreye sokun ve göğsünüzü yukarıda tutun.","Alçalırken dizlerinizi yanlara doğru itin ve ağırlığınızı topuklarınıza verin.","Uyluklarınız yere paralel oluncaya kadar alçaltın, ardından topuklarınızı iterek başlangıç ​​pozisyonuna dönün.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios.","Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas.","Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones.","Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги шире плеч, носки слегка направлены наружу.","Держите штангу на верхней части спины, положив ее на трапеции.","Напрягите корпус и держите грудь поднятой, опуская тело в присед, сгибая колени и бедра.","Опускаясь, разведите колени в стороны и перенесите вес тела на пятки.","Опускайтесь до тех пор, пока бедра не станут параллельны земле, затем оттолкнитесь пятками, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений."],"zh":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌上。","当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。","当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。","降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने जाल पर टिकाएं।","अपने कोर को संलग्न करें और घुटनों और कूल्हों पर झुकते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाते समय अपनी छाती को ऊपर रखें।","जैसे ही आप नीचे आते हैं, अपने घुटनों को बगल की ओर धकेलें और अपना वजन अपनी एड़ियों पर रखें।","जब तक आपकी जांघें जमीन के समानांतर न हो जाएं, तब तक नीचे झुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań ze stopami rozstawionymi szerzej niż barki, ze stopami skierowanymi lekko na zewnątrz.","Trzymaj sztangę na górnej części pleców, opierając ją na mięśniach czworobocznych.","Napnij mięśnie brzucha i trzymaj klatkę piersiową uniesioną, opuszczając ciało w przysiad, uginając kolana i biodra.","Podczas schodzenia w dół kieruj kolana na zewnątrz i trzymaj ciężar na piętach.","Zejdź, aż uda będą równoległe do podłoża, a następnie wypchnij się przez pięty, wracając do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń."],"ko":["발을 어깨 너비보다 넓게 벌리고 발끝은 약간 바깥쪽을 향합니다.","바벨을 상등에 올려 트랩 위에 올립니다.","코어에 힘을 주고 가슴을 올린 채로 스쿼트 자세로 몸을 낮춥니다.","무릎과 엉덩이를 구부립니다.","내려가며 무릎을 옆으로 밀고 체중은 발뒤꿈치에 유지합니다.","허벅지가 땅과 평행할 때까지 내린 후 발뒤꿈치를 통해 밀어 시작 위치로 돌아갑니다."]}', 'glutes', '["glutes","hamstrings","calves"]', 'quads', 'images/0098-W31mMjd.jpg', 'videos/0098-W31mMjd.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0097', 'barbell side split squat v. 2', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."],"it":["Stai in piedi con i piedi più larghi delle spalle, con le dita leggermente rivolte verso l''esterno.","Tieni un bilanciere sulla parte alta della schiena, appoggiandolo sulle spalle.","Fai un grande passo di lato con il piede destro, mantenendo il sinistro piantato.","Flette il ginocchio destro e abbassa il corpo in posizione accovacciata, mantenendo il petto sollevato e la schiena dritta.","Spingi attraverso il tallone destro per tornare alla posizione di partenza.","Ripeti dall''altro lato, facendo un passo avanti con il piede sinistro.","Continua ad alternare i lati per il numero desiderato di ripetizioni."],"tr":["Ayaklarınız omuz genişliğinden daha geniş, ayak parmaklarınız hafifçe dışarı bakacak şekilde ayakta durun.","Sırtınızın üst kısmına bir halter tutun ve omuzlarınıza yaslayın.","Sol ayağınızı dik tutarak sağ ayağınızla yana doğru büyük bir adım atın.","Sağ dizinizi bükün ve göğsünüzü yukarıda ve sırtınızı düz tutarak vücudunuzu çömelme pozisyonuna indirin.","Başlangıç ​​pozisyonuna dönmek için sağ topuğunuzu itin.","Sol ayağınızla dışarı çıkarak diğer tarafta tekrarlayın.","İstenilen tekrar sayısı için alternatif taraflara devam edin."],"es":["Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera.","Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros.","Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo.","Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta.","Empuja con el talón derecho para regresar a la posición inicial.","Repite hacia el otro lado, dando el paso con el pie izquierdo.","Continúa alternando lados durante el número de repeticiones deseado."],"ru":["Встаньте, поставив ноги шире плеч, носки слегка направлены наружу.","Держите штангу через верхнюю часть спины, положив ее на плечи.","Сделайте большой шаг в сторону правой ногой, удерживая левую ногу на месте.","Согните правое колено и опустите тело в положение приседа, удерживая грудь поднятой, а спину прямой.","Оттолкнитесь правой пяткой, чтобы вернуться в исходное положение.","Повторите то же самое с другой стороны, выставив левую ногу.","Продолжайте чередовать стороны желаемое количество повторений."],"zh":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在肩膀上。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。","推动右脚跟回到起始位置。","在另一侧重复，左脚迈出。","继续交替进行所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई से अधिक चौड़ा करके खड़े रहें, पैर की उंगलियां थोड़ी बाहर की ओर हों।","अपनी ऊपरी पीठ पर एक बारबेल पकड़ें, इसे अपने कंधों पर टिकाएं।","अपने दाहिने पैर को बगल में रखते हुए एक बड़ा कदम उठाएं, अपने बाएं पैर को सीधा रखें।","अपने दाहिने घुटने को मोड़ें और अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ, अपनी छाती को ऊपर और अपनी पीठ को सीधा रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","अपने बाएं पैर से बाहर निकलते हुए दूसरी तरफ भी दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"],"pl":["Stań ze stopami rozstawionymi szerzej niż barki, ze stopami skierowanymi lekko na zewnątrz.","Trzymaj sztangę na górnej części pleców, opierając ją na barkach.","Zrób duży krok w bok prawą stopą, trzymając lewą stopę nieruchomo na podłożu.","Ugnij prawe kolano i opuść ciało w przysiad, trzymając klatkę piersiową uniesioną, a plecy proste.","Wypchnij się przez prawą piętę, wracając do pozycji wyjściowej.","Powtórz w drugą stronę, wykonując krok lewą stopą.","Kontynuuj naprzemienne strony przez zadaną liczbę powtórzeń."],"ko":["발을 어깨 너비보다 넓게 벌리고 발끝은 약간 바깥쪽을 향합니다.","바벨을 상등에 올려 어깨에 올립니다.","오른발로 옆으로 한 발을 크게 디딥니다.","오른쪽 무릎을 구부려 스쿼트 자세로 몸을 내립니다.","가슴을 올리고 등을 곧게 유지합니다.","오른쪽 발뒤꿈치를 통해 밀어 시작 위치로 돌아갑니다.","원하는 반복 횟수만큼 좌우를 번갈아 반복합니다."]}', 'glutes', '["glutes","hamstrings","calves"]', 'quads', 'images/0097-HUEqZ1y.jpg', 'videos/0097-HUEqZ1y.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('1756', 'barbell single leg deadlift', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."],"it":["Stai con i piedi larghi i fianchi, tenendo un bilanciere davanti alle cosce con una presa sopra la testa.","Sposta il peso sul piede sinistro e solleva leggermente il piede destro da terra.","Piega in avanti ai fianchi, mantenendo la schiena dritta e la gamba destra estesa dietro di te per mantenere l''equilibrio.","Abbassa il bilanciere verso terra, tenendolo vicino al corpo e la gamba sinistra leggermente piegata.","Fermati un attimo in basso, poi attiva glutei e muscoli posteriori femorale per sollevare il busto fino alla posizione iniziale.","Ripeti per il numero desiderato di ripetizioni, poi cambia lato."],"tr":["Ayaklarınızı kalça genişliğinde açın ve halteri üstten kavrayarak uyluklarınızın önünde tutun.","Ağırlığınızı sol ayağınıza verin ve sağ ayağınızı yerden hafifçe kaldırın.","Kalçalarınızdan öne doğru eğilin, sırtınızı düz tutun ve denge için sağ bacağınızı arkanızda uzatın.","Halteri vücudunuza yakın tutarak ve sol bacağınızı hafifçe bükerek yere doğru indirin.","Altta bir an duraklayın, ardından kalça kaslarınızı ve diz arkası kaslarınızı çalıştırarak gövdenizi başlangıç ​​pozisyonuna kaldırın.","İstenilen tekrar sayısı kadar tekrarlayın, ardından taraf değiştirin."],"es":["Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono.","Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo.","Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio.","Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.","Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de lado."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу перед бедрами хватом сверху.","Перенесите вес тела на левую ногу и слегка поднимите правую ногу от земли.","Наклонитесь вперед в бедрах, сохраняя спину прямой и вытянув правую ногу позади себя для равновесия.","Опустите штангу к земле, держа ее близко к телу и слегка согнув левую ногу.","Задержитесь на мгновение в нижней точке, затем задействуйте ягодицы и мышцы задней поверхности бедра, чтобы поднять туловище обратно в исходное положение.","Повторите желаемое количество повторений, затем поменяйте сторону."],"zh":["站立，双脚分开与臀部同宽，正手握住杠铃在大腿前面。","将重心转移到左脚上，并将右脚稍微抬离地面。","臀部向前转动，保持背部挺直，右腿向后伸展以保持平衡。","将杠铃向地面降低，使其靠近身体，左腿稍微弯曲。","在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。","重复所需的重复次数，然后换边。"],"hi":["अपने पैरों को कूल्हे-चौड़ाई से अलग करके खड़े हो जाएं, एक बारबेल को अपनी जांघों के सामने एक ओवरहैंड पकड़ के साथ पकड़ें।","अपना वजन अपने बाएं पैर पर डालें और अपने दाहिने पैर को जमीन से थोड़ा ऊपर उठाएं।","कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और संतुलन के लिए अपना दाहिना पैर अपने पीछे फैलाएँ।","बारबेल को अपने शरीर के पास रखते हुए और अपने बाएँ पैर को थोड़ा मोड़कर ज़मीन की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने धड़ को शुरुआती स्थिति में वापस उठाने के लिए अपने ग्लूट्स और हैमस्ट्रिंग को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"],"pl":["Stań ze stopami na szerokość bioder, trzymając sztangę przed udami chwytem nachwytem.","Przenieś ciężar ciała na lewą stopę i unieś prawą stopę lekko nad podłogę.","Pochyl tułów do przodu w biodrach, trzymając plecy proste, a prawą nogę wyprostowaną z tyłu dla utrzymania równowagi.","Opuść sztangę w kierunku podłogi, trzymając ją blisko ciała, a lewą nogę lekko ugiętą.","Zatrzymaj się na chwilę w dolnej pozycji, a następnie napnij pośladki i mięśnie dwugłowe uda, unosząc tułów z powrotem do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń, a następnie zmień stronę."],"ko":["발을 엉덩이 너비로 벌리고 오버핸드 그립으로 바벨을 넓적다리 앞에 들고 섭니다.","왼발에 체중을 옮기고 오른발을 약간 들어 올립니다.","허리에서 굽혀 등은 곧게 펴고 오른다리는 균형을 위해 뒤로 펼칩니다.","바벨을 땅을 향해 내리며 바벨은 몸 가까이 유지하고 왼다리는 약간 구부립니다.","하단에서 잠시 멈춘 후 글루트와 햄스트링으로 밀어 몸을 다시 일으킵니다.","원하는 반복 횟수만큼 반복한 후 옆발을 바꿉니다."]}', 'hamstrings', '["hamstrings","lower back"]', 'glutes', 'images/1756-gEyURal.jpg', 'videos/1756-gEyURal.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0099', 'barbell single leg split squat', 'upper legs', 'upper legs', 'barbell', '{"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."],"it":["Stai con i piedi divaricati alla larghezza delle spalle, tenendo una barra sulla parte alta della schiena.","Fai un grande passo avanti con una gamba, mantenendo il busto dritto.","Abbassa il corpo piegando il ginocchio anteriore e il fianco, mantenendo la gamba posteriore dritta.","Continua ad abbassare finché la coscia anteriore non è parallela al suolo.","Fermati un attimo, poi spingi attraverso il tallone anteriore per tornare alla posizione di partenza.","Ripeti per il numero desiderato di ripetizioni, poi cambia gamba."],"tr":["Ayaklarınız omuz genişliğinde açık olacak şekilde ayakta durun ve halterinizi sırtınızın üst kısmına doğru tutun.","Gövdenizi dik tutarak tek ayağınızla ileriye doğru büyük bir adım atın.","Arka bacağınızı düz tutarken ön dizinizi ve kalçanızı bükerek vücudunuzu indirin.","Ön uyluğunuz yere paralel oluncaya kadar indirmeye devam edin.","Bir an duraklayın, ardından başlangıç ​​pozisyonuna dönmek için ön topuğunuzu itin.","İstenilen tekrar sayısı kadar tekrarlayın, ardından bacakları değiştirin."],"es":["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda.","Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido.","Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta.","Continúa bajando hasta que el muslo delantero quede paralelo al suelo.","Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial.","Repite el número de repeticiones deseado, luego cambia de pierna."],"ru":["Встаньте, ноги на ширине плеч, удерживая штангу на верхней части спины.","Сделайте большой шаг вперед одной ногой, сохраняя туловище в вертикальном положении.","Опустите тело, согнув переднее колено и бедро, сохраняя при этом заднюю ногу прямой.","Продолжайте опускаться до тех пор, пока переднее бедро не станет параллельно земле.","Сделайте паузу на мгновение, затем оттолкнитесь передней пяткой, чтобы вернуться в исходное положение.","Повторите необходимое количество повторений, затем поменяйте ногу."],"zh":["双脚分开与肩同宽站立，将杠铃放在上背部。","单腿向前迈出一大步，保持躯干直立。","弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。","继续降低，直到大腿前侧与地面平行。","暂停片刻，然后推动前脚跟回到起始位置。","重复所需的重复次数，然后换腿。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी पीठ के ऊपरी हिस्से पर एक बारबेल पकड़ें।","अपने धड़ को सीधा रखते हुए एक पैर से एक बड़ा कदम आगे बढ़ाएं।","अपने पिछले पैर को सीधा रखते हुए, अपने सामने के घुटने और कूल्हे को मोड़कर अपने शरीर को नीचे लाएँ।","जब तक आपकी अगली जांघ ज़मीन के समानांतर न हो जाए, तब तक नीचे करना जारी रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी सामने की एड़ी से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदल लें।"],"pl":["Stań ze stopami na szerokość barków, trzymając sztangę na górnej części pleców.","Zrób duży krok do przodu jedną nogą, trzymając tułów w pionie.","Opuść ciało, uginając przednie kolano i biodro, trzymając tylną nogę wyprostowaną.","Kontynuuj opuszczanie, aż przednie udo będzie równoległe do podłoża.","Zatrzymaj się na chwilę, a następnie wypchnij się przez przednią piętę, wracając do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń, a następnie zmień nogę."],"ko":["발을 어깨 너비로 벌리고 바벨을 상등에 올립니다.","한 다리로 크게 앞으로 발을 내밀며 몸을 곧게 유지합니다.","앞다리의 무릎과 엉덩이를 구부려 몸을 내립니다.","뒷다리는 곧게 펼친 상태를 유지합니다.","허벅지가 땅과 평행할 때까지 계속 내립니다.","잠시 멈춘 후 앞발의 발뒤꿈치를 통해 밀어 시작 위치로 돌아갑니다."]}', 'glutes', '["glutes","hamstrings","calves"]', 'quads', 'images/0099-gGNQmVt.jpg', 'videos/0099-gGNQmVt.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2799', 'barbell sitted alternate leg raise', 'waist', 'waist', 'barbell', '{"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"it":["Siediti su una panca con la schiena dritta e tieni un bilanciere sopra le cosce.","Tieni le gambe dritte, solleva una gamba il più in alto possibile mentre tieni l''altra a terra.","Abbassa di nuovo la gamba sollevata e ripeti con l''altra gamba.","Continua ad alternare le gambe per il numero desiderato di ripetizioni."],"tr":["Sırtınız dik olacak şekilde bir bankta oturun ve halteri uyluklarınızın üzerinde tutun.","Bacaklarınızı düz tutarak bir bacağınızı mümkün olduğu kadar yukarı kaldırın, diğer bacağınızı ise yerde tutun.","Yükseltilmiş bacağınızı geriye doğru indirin ve hareketi diğer bacakla tekrarlayın.","İstenilen sayıda tekrar için bacakları değiştirerek devam edin."],"es":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo.","Baja la pierna elevada y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"ru":["Сядьте на скамью с прямой спиной и держите штангу на бедрах.","Держа ноги прямыми, поднимите одну ногу как можно выше, удерживая другую ногу на земле.","Опустите поднятую ногу обратно вниз и повторите то же самое с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"zh":["坐在长凳上，背部挺直，将杠铃放在大腿上。","保持双腿伸直，将一条腿尽可能高地抬起，同时将另一条腿放在地上。","将抬起的腿放回原位，然后换另一条腿重复上述步骤。","继续交替双腿达到所需的重复次数。"],"hi":["अपनी पीठ सीधी करके एक बेंच पर बैठें और अपनी जांघों पर एक बारबेल पकड़ें।","अपने पैरों को सीधा रखते हुए एक पैर को जितना हो सके ऊपर उठाएं और दूसरे पैर को जमीन पर रखें।","उठे हुए पैर को वापस नीचे लाएँ और दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"],"pl":["Usiądź na ławce, trzymając plecy proste, i trzymaj sztangę na udach.","Trzymając nogi wyprostowane, unieś jedną nogę jak najwyżej, trzymając drugą nogę na podłodze.","Opuść uniesioną nogę i powtórz drugą nogą.","Kontynuuj naprzemienne unoszenie nóg przez zadaną liczbę powtórzeń."],"ko":["벤치에 앉아 등을 곧게 펴고 바벨을 허벅지 위에 올립니다.","다리를 곧게 펼친 상태로 유지하며 한 다리를 최대한 높이 올립니다.","올린 다리를 내려 다른 다리로 같은 동작을 합니다.","원하는 반복 횟수만큼 좌우를 번갈아 반복합니다."]}', 'hip flexors', '["hip flexors"]', 'abs', 'images/2799-G7xoEzr.jpg', 'videos/2799-G7xoEzr.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('2800', 'barbell sitted alternate leg raise (female)', 'waist', 'waist', 'barbell', '{"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."],"it":["Siediti su una panca con la schiena dritta e tieni un bilanciere sopra le cosce.","Appoggia le mani ai lati della panca per sostenerti.","Tenendo le gambe dritte, solleva una gamba il più in alto possibile mantenendola parallela al suolo.","Abbassa di nuovo la gamba e ripeti con l''altra gamba.","Continua ad alternare le gambe per il numero desiderato di ripetizioni."],"tr":["Sırtınız dik olacak şekilde bir bankta oturun ve halteri uyluklarınızın üzerinde tutun.","Destek için ellerinizi sehpanın yanlarına koyun.","Bacaklarınızı düz tutarak bir bacağınızı yere paralel tutarak mümkün olduğunca yukarı kaldırın.","Bacağınızı geriye doğru indirin ve hareketi diğer bacakla tekrarlayın.","İstenilen sayıda tekrar için bacakları değiştirerek devam edin."],"es":["Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos.","Coloca las manos a los lados del banco para apoyarte.","Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo.","Baja la pierna y repite con la otra pierna.","Continúa alternando las piernas durante el número de repeticiones deseado."],"ru":["Сядьте на скамью с прямой спиной и держите штангу на бедрах.","Положите руки по бокам скамьи для поддержки.","Держа ноги прямыми, поднимите одну ногу как можно выше, удерживая ее параллельно земле.","Опустите ногу обратно и повторите то же самое с другой ногой.","Продолжайте чередовать ноги желаемое количество повторений."],"zh":["坐在长凳上，背部挺直，将杠铃放在大腿上。","将双手放在长凳两侧以获得支撑。","保持双腿伸直，将一条腿尽可能抬高，同时保持与地面平行。","将腿放回原位，然后换另一条腿重复此动作。","继续交替双腿达到所需的重复次数。"],"hi":["अपनी पीठ सीधी करके एक बेंच पर बैठें और अपनी जांघों पर एक बारबेल पकड़ें।","समर्थन के लिए अपने हाथों को बेंच के किनारों पर रखें।","अपने पैरों को सीधा रखते हुए, एक पैर को जमीन के समानांतर रखते हुए जितना संभव हो उतना ऊपर उठाएं।","पैर को वापस नीचे लाएँ और दूसरे पैर से दोहराएँ।","पुनरावृत्ति की वांछित संख्या के लिए पैरों को बारी-बारी से जारी रखें।"],"pl":["Usiądź na ławce, trzymając plecy proste, i trzymaj sztangę na udach.","Oprzyj dłonie po bokach ławki dla podparcia.","Trzymając nogi wyprostowane, unieś jedną nogę jak najwyżej, utrzymując ją równolegle do podłoża.","Opuść nogę i powtórz drugą nogą.","Kontynuuj naprzemienne unoszenie nóg przez zadaną liczbę powtórzeń."],"ko":["벤치에 앉아 등을 펴고 바벨을 다리 위에 가로질러 올려놓습니다.","양손을 벤치 옆에 놓아 지탱합니다.","다리를 펴서 지면과 평행하게 유지하면서 한쪽 다리를 최대한 높이 들어올립니다.","다리를 내린 후 반대쪽 다리로 반복합니다.","원하는 반복 횟수만큼 다리를 교대로 반복합니다."]}', 'hip flexors', '["hip flexors","quadriceps"]', 'abs', 'images/2800-BCs0G2F.jpg', 'videos/2800-BCs0G2F.gif');
INSERT INTO "ejercicios" ("id", "name", "category", "bodyPart", "equipment", "instructionSteps", "muscleGroup", "secondaryMuscles", "target", "image", "gifUrl") VALUES ('0100', 'barbell skier', 'shoulders', 'shoulders', 'barbell', '{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."],"it":["Stai con i piedi a larghezza delle spalle e tieni un bilanciere davanti alle cosce con una presa sopra la mano.","Flette leggermente le ginocchia e piega in avanti sui fianchi, mantenendo la schiena dritta e il petto sollevato.","Contemporaneamente solleva il bilanciere verso le spalle saltando leggermente da terra.","Quando raggiungi la parte alta del movimento, inverti rapidamente il movimento e abbassa il bilanciere fino alla posizione iniziale.","Ripeti per il numero desiderato di ripetizioni."],"tr":["Ayaklarınızı omuz genişliğinde açın ve halteri üstten kavrayarak uyluklarınızın önünde tutun.","Dizlerinizi hafifçe bükün ve kalçalarınızdan öne doğru eğilin, sırtınızı düz ve göğsünüzü yukarıda tutun.","Aynı anda yerden hafifçe zıplarken halteri omuzlarınıza doğru kaldırın.","Hareketin tepesine ulaştığınızda, hareketi hızla tersine çevirin ve halteri tekrar başlangıç ​​pozisyonuna indirin.","İstenilen sayıda tekrar için tekrarlayın."],"es":["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.","Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.","Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.","Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.","Repite el número de repeticiones deseado."],"ru":["Встаньте, ноги на ширине плеч, удерживайте штангу перед бедрами хватом сверху.","Слегка согните колени и наклонитесь вперед в бедрах, держа спину прямо и грудь вверх.","Одновременно поднимите штангу к плечам, слегка подпрыгнув от земли.","Достигнув верхней точки движения, быстро поменяйте направление движения и опустите штангу обратно в исходное положение.","Повторите необходимое количество повторений."],"zh":["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","同时将杠铃举向肩膀，同时稍微离开地面。","当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。","重复所需的重复次数。"],"hi":["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपनी जांघों के सामने एक बारबेल को ज़ोर से पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","इसके साथ ही जमीन से थोड़ा ऊपर उछलते हुए बारबेल को अपने कंधों की ओर ऊपर उठाएं।","जैसे ही आप गति के शीर्ष पर पहुँचते हैं, गति को तुरंत उलट दें और बारबेल को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"],"pl":["Stań ze stopami na szerokość barków, trzymając sztangę przed udami chwytem nachwytem.","Ugnij lekko kolana i pochyl tułów do przodu w biodrach, trzymając plecy proste, a klatkę piersiową uniesioną.","Jednocześnie unieś sztangę w kierunku barków, lekko podskakując.","Gdy osiągniesz szczyt ruchu, szybko odwróć kierunek i opuść sztangę z powrotem do pozycji wyjściowej.","Powtórz zadaną liczbę powtórzeń."],"ko":["발을 어깨 너비로 벌리고 바벨을 엎질러 잡아 다리 앞에서 들고 섭니다.","무릎을 살짝 굽히고 엉덩이를 뒤로 밀면서 골반에서 몸을 굽힙니다.","동시에 바벨을 어깨로 들어올리면서 살짝 점프합니다.","가장 높은 지점에 도달하면 빠르게 반대 동작을 하며 바벨을 시작 위치로 내립니다.","원하는 반복 횟수만큼 반복합니다."]}', 'triceps', '["triceps","core"]', 'delts', 'images/0100-4Leypho.jpg', 'videos/0100-4Leypho.gif');
